package com.grahambartley.runelite.voiced.dialogue.profile;

import com.grahambartley.runelite.voiced.dialogue.VoicedDialogueConfig;
import com.grahambartley.runelite.voiced.dialogue.speaker.LearnedNpcStore;
import com.grahambartley.runelite.voiced.dialogue.speaker.NpcAttributes;
import com.grahambartley.runelite.voiced.dialogue.speaker.NpcDemographicAnalyzer;
import com.grahambartley.runelite.voiced.dialogue.speaker.NpcFinder;
import com.grahambartley.runelite.voiced.dialogue.speaker.NpcGender;
import com.grahambartley.runelite.voiced.dialogue.speaker.wiki.NpcLearningService;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.NPC;

@Slf4j
public class VoiceManager {

  public enum PlayerVoice {
    TYPE_A(NpcGender.MALE, "Type A"),
    TYPE_B(NpcGender.FEMALE, "Type B");

    private final NpcGender gender;
    private final String label;

    PlayerVoice(NpcGender gender, String label) {
      this.gender = gender;
      this.label = label;
    }

    public NpcGender getGender() {
      return gender;
    }

    @Override
    public String toString() {
      return label;
    }
  }

  private final VoicedDialogueConfig config;
  private final NpcDemographicAnalyzer demographicAnalyzer;
  private final NpcProfileTable profileTable;
  private final NpcIdentityResolver identityResolver;
  private final NpcVoiceResolver npcVoiceResolver;

  private NpcLearningService learningService;

  public static VoiceManager create(VoicedDialogueConfig config, Client client) {
    NpcDemographicAnalyzer demographicAnalyzer = new NpcDemographicAnalyzer();
    demographicAnalyzer.initialize();
    NpcProfileTable profileTable = new NpcProfileTable();
    profileTable.initialize();
    return new VoiceManager(config, client, demographicAnalyzer, profileTable);
  }

  public VoiceManager(
      VoicedDialogueConfig config,
      Client client,
      NpcDemographicAnalyzer demographicAnalyzer,
      NpcProfileTable profileTable) {
    this.config = config;
    this.demographicAnalyzer = demographicAnalyzer;
    this.profileTable = profileTable;
    this.identityResolver =
        new NpcIdentityResolver(new NpcFinder(client), demographicAnalyzer, profileTable);
    this.npcVoiceResolver = new NpcVoiceResolver(config);
  }

  public boolean isVoiced(int npcId) {
    return demographicAnalyzer.isVoiced(npcId);
  }

  public void offerToLearning(String menuOption, NPC npc) {
    if (learningService == null
        || npc == null
        || !learningService.isEnabled()
        || !learningService.startsConversation(menuOption)) {
      return;
    }
    NpcAttributes attributes = demographicAnalyzer.analyzeNPC(npc);
    if (attributes != null) {
      learningService.considerLearning(attributes.getNpcId(), npc.getName());
    }
  }

  public void enableLearning(LearnedNpcStore store, NpcLearningService service) {
    this.learningService = service;
    this.demographicAnalyzer.setLearnedStore(store);
    this.npcVoiceResolver.setLearningService(service);
  }

  public ResolvedSpeaker resolve(Speaker speaker, String npcName) {
    if (speaker == Speaker.PLAYER) {
      return new ResolvedSpeaker(playerVoice(), playerProfile());
    }

    return npcSpeaker(npcName, identityResolver.resolve(npcName));
  }

  public ResolvedSpeaker resolveNpc(NPC npc) {
    return npcSpeaker(npc.getName(), identityResolver.resolve(npc));
  }

  private ResolvedSpeaker npcSpeaker(String npcName, NpcIdentity identity) {
    VoiceSpec voice = npcVoiceResolver.resolve(npcName, identity);
    return new ResolvedSpeaker(voice, npcProfile(npcName, identity));
  }

  public ResolvedSpeaker resolveNarrator() {
    return new ResolvedSpeaker(VoiceSpec.NARRATOR, profileTable.resolveNarrator());
  }

  private VoiceSpec playerVoice() {
    NpcGender gender = config.playerVoice().getGender();
    if (config.debugMode()) {
      log.info(VoiceTraceFormatter.buildPlayerTrace(gender));
    }
    return VoiceSpec.player(gender);
  }

  private CharacterProfile playerProfile() {
    CharacterProfile profile =
        profileTable.resolvePlayer(
            config.playerAccent(), config.playerPersona(), config.playerPace());
    if (config.debugMode()) {
      log.info("[TTS profile] player -> '{}' accent='{}'", profile.name(), profile.accent());
    }
    return profile;
  }

  private CharacterProfile npcProfile(String npcName, NpcIdentity identity) {
    Integer npcId = identity.worldId();
    String race = null;
    String ethnicity = null;
    NpcAttributes attributes = identity.attributes();
    if (attributes != null) {
      race = attributes.getRace();
      ethnicity = attributes.getEthnicity();
      npcId = attributes.getNpcId();
    }

    NpcProfileTable.Resolution resolution =
        profileTable.resolveNpc(npcId, identity.nameMatch(), race, ethnicity);
    if (config.debugMode()) {
      log.info(
          "[TTS profile] npc='{}' id={} race={} ethnicity={} -> '{}' (source={}, accent='{}')",
          npcName,
          npcId == null ? "MISS" : npcId,
          race == null ? "UNKNOWN" : race,
          ethnicity == null ? "-" : ethnicity,
          resolution.profile().name(),
          resolution.source(),
          resolution.profile().accent());
    }
    return resolution.profile();
  }
}

package com.grahambartley.runelite.voiced.dialogue.profile;

import java.util.regex.Pattern;

public final class DirectionSanitizer {

  static final int MAX_FIELD_LENGTH = 1000;

  private static final Pattern CONTROL = Pattern.compile("[\\u0000-\\u001F\\u007F]+");

  private static final Pattern MARKERS =
      Pattern.compile(
          "(?i)(#+\\s*transcript|transcript\\s*####|audio\\s*profile|director'?s\\s*notes)");

  private static final Pattern WHITESPACE = Pattern.compile("\\s+");

  private final ProfanityFilter profanityFilter;

  public DirectionSanitizer(ProfanityFilter profanityFilter) {
    this.profanityFilter = profanityFilter;
  }

  public String sanitize(String field) {
    if (field == null) {
      return null;
    }
    String flattened = CONTROL.matcher(field).replaceAll(" ");
    String demarked = MARKERS.matcher(flattened).replaceAll(" ");
    String collapsed = WHITESPACE.matcher(demarked).replaceAll(" ").trim();
    if (collapsed.length() > MAX_FIELD_LENGTH) {
      collapsed = collapsed.substring(0, MAX_FIELD_LENGTH).trim();
    }
    return profanityFilter.mask(collapsed);
  }
}

package com.grahambartley.runelite.voiced.dialogue.profile;

import lombok.EqualsAndHashCode;
import lombok.Getter;
import lombok.ToString;
import lombok.experimental.Accessors;

@Getter
@Accessors(fluent = true)
@EqualsAndHashCode
@ToString
public final class CharacterProfile {

  private final String name;
  private final String accent;
  private final String style;
  private final String pace;

  static final String TRANSCRIPT_DIVIDER = "#### TRANSCRIPT";

  static final String GUARD =
      "VOICE ONLY THE TRANSCRIPT BELOW THE DIVIDER, WORD FOR WORD. ADD NO WORDS OF YOUR OWN.";

  public CharacterProfile(String name, String accent, String style, String pace) {
    this.name = stripTrailingOrNull(name);
    this.accent = stripTrailingOrNull(accent);
    this.style = stripTrailingOrNull(style);
    this.pace = stripTrailingOrNull(pace);
  }

  private static String stripTrailingOrNull(String field) {
    return field == null ? null : field.stripTrailing();
  }

  public String renderPromptBlock() {
    return GUARD
        + "\n\n"
        + "AUDIO PROFILE: "
        + name
        + "\n\nDIRECTOR'S NOTES:\n- Style: "
        + style
        + "\n- Accent: "
        + accent
        + "\n- Pace: "
        + pace
        + "\n\n"
        + TRANSCRIPT_DIVIDER
        + "\n";
  }

  public String cacheKey() {
    String joined = name + '' + accent + '' + style + '' + pace;
    return Integer.toHexString(joined.hashCode());
  }
}

package com.grahambartley.runelite.voiced.dialogue.profile;

import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import lombok.extern.slf4j.Slf4j;

@Slf4j
public class ExpressionEmotionTable {

  private static final String DOC_KEY_PREFIX = "_";

  static final String TABLE_RESOURCE = "/expression-emotions.json";

  private final Map<Integer, Emotion> table;

  private ExpressionEmotionTable(Map<Integer, Emotion> table) {
    this.table = table;
  }

  public static ExpressionEmotionTable load() {
    try (InputStream stream = ExpressionEmotionTable.class.getResourceAsStream(TABLE_RESOURCE)) {
      if (stream == null) {
        log.warn(
            "Expression-emotion table {} not found - all expressions resolve to NEUTRAL",
            TABLE_RESOURCE);
        return new ExpressionEmotionTable(Collections.emptyMap());
      }
      JsonObject root =
          new JsonParser()
              .parse(new InputStreamReader(stream, StandardCharsets.UTF_8))
              .getAsJsonObject();
      return new ExpressionEmotionTable(parse(root));
    } catch (Exception e) {
      log.warn(
          "Failed to load expression-emotion table {} - all expressions resolve to NEUTRAL: {}",
          TABLE_RESOURCE,
          e.getMessage());
      return new ExpressionEmotionTable(Collections.emptyMap());
    }
  }

  static Map<Integer, Emotion> parse(JsonObject root) {
    Map<Integer, Emotion> parsed = new HashMap<>();
    for (Map.Entry<String, JsonElement> entry : root.entrySet()) {
      String key = entry.getKey();
      if (key.startsWith(DOC_KEY_PREFIX)) {
        continue;
      }
      int animationId;
      try {
        animationId = Integer.parseInt(key);
      } catch (NumberFormatException e) {
        throw new IllegalArgumentException(
            "expression-emotions.json key is not an integer animation id: " + key, e);
      }
      String emotionName = entry.getValue().getAsString();
      Emotion emotion;
      try {
        emotion = Emotion.valueOf(emotionName);
      } catch (IllegalArgumentException e) {
        throw new IllegalArgumentException(
            "expression-emotions.json value for id "
                + animationId
                + " is not a valid Emotion: "
                + emotionName,
            e);
      }
      parsed.put(animationId, emotion);
    }
    return Collections.unmodifiableMap(parsed);
  }

  public Emotion resolve(int animationId) {
    if (animationId < 0) {
      return Emotion.NEUTRAL;
    }
    return table.getOrDefault(animationId, Emotion.NEUTRAL);
  }
}

package com.grahambartley.runelite.voiced.dialogue.profile;

import java.util.Collections;
import java.util.List;
import java.util.Map;
import lombok.Value;
import lombok.experimental.Accessors;

@Value
@Accessors(fluent = true)
class NpcProfileLayers {

  static final CharacterProfile BUILTIN_DEFAULT =
      new CharacterProfile(
          "Gielinor Commoner",
          "British English, Received Pronunciation, as heard in southern England.",
          "A grounded medieval fantasy townsperson; plain, sincere, and natural.",
          "Steady and conversational.");

  static final NpcProfileLayers EMPTY =
      new NpcProfileLayers(
          BUILTIN_DEFAULT,
          null,
          null,
          Collections.emptyMap(),
          Collections.emptyMap(),
          Collections.emptyList(),
          Collections.emptyMap());

  @Value
  @Accessors(fluent = true)
  static class Layer {
    String name;
    String accent;
    String style;
    String pace;
  }

  @Value
  @Accessors(fluent = true)
  static class CategoryRule {
    String id;
    List<String> keywords;
    Layer layer;
    boolean child;
  }

  CharacterProfile defaultProfile;
  Layer playerLayer;
  Layer narratorLayer;
  Map<String, Layer> byRace;
  Map<String, Layer> byEthnicity;
  List<CategoryRule> byCategory;
  Map<Integer, Layer> byId;
}

package com.grahambartley.runelite.voiced.dialogue.profile;

import java.io.BufferedReader;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.Locale;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import lombok.extern.slf4j.Slf4j;

@Slf4j
public final class ProfanityFilter {

  private static final String WORDLIST_RESOURCE = "/profanity.txt";

  private static final Pattern TOKEN =
      Pattern.compile("[\\p{L}\\p{N}@$](?:[\\p{L}\\p{N}._*@$-]*[\\p{L}\\p{N}@$])?");

  private static final char[] LEET_FROM = {'0', '1', '3', '4', '5', '7', '@', '$'};

  private static final char[] LEET_TO = {'o', 'i', 'e', 'a', 's', 't', 'a', 's'};

  private static final Set<String> ALLOWLIST =
      Collections.unmodifiableSet(
          new HashSet<>(
              Arrays.asList(
                  "scunthorpe",
                  "assassin",
                  "assassinate",
                  "assassination",
                  "assess",
                  "assassins",
                  "sussex",
                  "penistone",
                  "class",
                  "pass",
                  "bass",
                  "grass",
                  "compass",
                  "cockle",
                  "shitake",
                  "dickens")));

  private final Set<String> blocklist;

  public ProfanityFilter() {
    this.blocklist = loadBundled();
  }

  private Set<String> loadBundled() {
    Set<String> words = new HashSet<>();
    try (InputStream stream = getClass().getResourceAsStream(WORDLIST_RESOURCE)) {
      if (stream == null) {
        log.warn(
            "Profanity wordlist {} not found - profanity masking is a no-op this session",
            WORDLIST_RESOURCE);
        return Collections.emptySet();
      }
      try (BufferedReader reader =
          new BufferedReader(new InputStreamReader(stream, StandardCharsets.UTF_8))) {
        String line;
        while ((line = reader.readLine()) != null) {
          String entry = line.trim();
          if (entry.isEmpty() || entry.charAt(0) == '#') {
            continue;
          }
          String normalized = normalize(entry);
          if (!normalized.isEmpty()) {
            words.add(normalized);
          }
        }
      }
    } catch (Exception e) {
      log.error("Failed to load profanity wordlist {}: {}", WORDLIST_RESOURCE, e.getMessage());
      return Collections.emptySet();
    }
    return Collections.unmodifiableSet(words);
  }

  static String normalize(String text) {
    StringBuilder out = new StringBuilder(text.length());
    String lower = text.toLowerCase(Locale.ROOT);
    for (int i = 0; i < lower.length(); i++) {
      char c = lower.charAt(i);
      char mapped = leet(c);
      if (mapped >= 'a' && mapped <= 'z') {
        out.append(mapped);
      }
    }
    return out.toString();
  }

  private static char leet(char c) {
    for (int i = 0; i < LEET_FROM.length; i++) {
      if (LEET_FROM[i] == c) {
        return LEET_TO[i];
      }
    }
    return c;
  }

  public String mask(String text) {
    if (text == null || text.isEmpty() || blocklist.isEmpty()) {
      return text;
    }
    Matcher matcher = TOKEN.matcher(text);
    StringBuilder out = null;
    int last = 0;
    while (matcher.find()) {
      String token = matcher.group();
      String normalized = normalize(token);
      if (normalized.isEmpty()
          || ALLOWLIST.contains(normalized)
          || !blocklist.contains(normalized)) {
        continue;
      }
      if (out == null) {
        out = new StringBuilder(text.length());
      }
      out.append(text, last, matcher.start());
      for (int i = matcher.start(); i < matcher.end(); i++) {
        out.append('*');
      }
      last = matcher.end();
    }
    if (out == null) {
      return text;
    }
    out.append(text, last, text.length());
    return out.toString();
  }
}

package com.grahambartley.runelite.voiced.dialogue.profile;

import com.google.gson.JsonObject;
import com.grahambartley.runelite.voiced.dialogue.profile.NpcProfileLayers.CategoryRule;
import com.grahambartley.runelite.voiced.dialogue.profile.NpcProfileLayers.Layer;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import lombok.Value;
import lombok.experimental.Accessors;
import lombok.extern.slf4j.Slf4j;

@Slf4j
public final class NpcProfileTable {

  private static final String TABLE_RESOURCE = "/npc-voices.json";

  @Value
  @Accessors(fluent = true)
  public static class Resolution {
    CharacterProfile profile;
    String source;
  }

  public static final class NameMatch {

    static final NameMatch NONE = new NameMatch(Collections.emptyList());

    private final List<CategoryRule> rules;

    NameMatch(List<CategoryRule> rules) {
      this.rules = rules;
    }

    public boolean child() {
      for (CategoryRule rule : rules) {
        if (rule.child()) {
          return true;
        }
      }
      return false;
    }
  }

  private static final class MatchedLayer {
    private final Layer layer;
    private final String source;

    MatchedLayer(Layer layer, String source) {
      this.layer = layer;
      this.source = source;
    }
  }

  private final DirectionSanitizer directionSanitizer;

  private NpcProfileLayers layers = NpcProfileLayers.EMPTY;
  private boolean loaded = false;

  public NpcProfileTable() {
    this(new DirectionSanitizer(new ProfanityFilter()));
  }

  public NpcProfileTable(DirectionSanitizer directionSanitizer) {
    this.directionSanitizer = directionSanitizer;
  }

  public void initialize() {
    NpcProfileLayers parsed = NpcProfileParser.loadResource(TABLE_RESOURCE);
    if (parsed == null) {
      return;
    }
    this.layers = parsed;
    this.loaded = true;
    log.info(
        "NPC profiles loaded: {} race, {} ethnicity, {} keyword categories, {} bespoke NPC"
            + " overrides",
        layers.byRace().size(),
        layers.byEthnicity().size(),
        layers.byCategory().size(),
        layers.byId().size());
  }

  static NpcProfileTable fromProfilesJson(JsonObject profiles) {
    NpcProfileTable table = new NpcProfileTable();
    table.layers = NpcProfileParser.parse(profiles);
    table.loaded = true;
    return table;
  }

  public NameMatch matchName(String npcName) {
    if (npcName == null || npcName.isEmpty()) {
      return NameMatch.NONE;
    }
    String lower = npcName.toLowerCase(Locale.ROOT);
    List<CategoryRule> matches = new ArrayList<>();
    for (CategoryRule rule : layers.byCategory()) {
      for (String keyword : rule.keywords()) {
        if (wordContains(lower, keyword)) {
          matches.add(rule);
          break;
        }
      }
    }
    return new NameMatch(matches);
  }

  public Resolution resolveNpc(Integer npcId, NameMatch nameMatch, String race, String ethnicity) {
    return mergeLayers(collectLayers(npcId, nameMatch, race, ethnicity));
  }

  private List<MatchedLayer> collectLayers(
      Integer npcId, NameMatch nameMatch, String race, String ethnicity) {
    List<MatchedLayer> matched = new ArrayList<>();

    Layer raceLayer = race == null ? null : layers.byRace().get(race.toLowerCase(Locale.ROOT));
    if (raceLayer != null) {
      matched.add(new MatchedLayer(raceLayer, "race:" + race));
    }
    boolean plainRace =
        race == null || race.equalsIgnoreCase("Human") || race.equalsIgnoreCase("Unknown");
    Layer ethnicityLayer =
        (ethnicity == null || !plainRace)
            ? null
            : layers.byEthnicity().get(ethnicity.toLowerCase(Locale.ROOT));
    if (ethnicityLayer != null) {
      matched.add(new MatchedLayer(ethnicityLayer, "ethnicity:" + ethnicity));
    }
    for (CategoryRule rule : nameMatch.rules) {
      matched.add(new MatchedLayer(rule.layer(), "keyword:" + rule.id()));
    }
    Layer idLayer = npcId == null ? null : layers.byId().get(npcId);
    if (idLayer != null) {
      matched.add(new MatchedLayer(idLayer, "id:" + npcId));
    }
    return matched;
  }

  private Resolution mergeLayers(List<MatchedLayer> matched) {
    CharacterProfile defaultProfile = layers.defaultProfile();
    String name = defaultProfile.name();
    String accent = defaultProfile.accent();
    String pace = defaultProfile.pace();
    List<String> styleParts = new ArrayList<>();
    List<String> sources = new ArrayList<>();
    for (MatchedLayer entry : matched) {
      Layer layer = entry.layer;
      if (layer.name() != null) {
        name = layer.name();
      }
      if (layer.accent() != null) {
        accent = layer.accent();
      }
      if (layer.pace() != null) {
        pace = layer.pace();
      }
      if (layer.style() != null) {
        styleParts.add(layer.style());
      }
      sources.add(entry.source);
    }
    String style = styleParts.isEmpty() ? defaultProfile.style() : String.join(" ", styleParts);
    String source = sources.isEmpty() ? "default" : String.join("+", sources);

    return new Resolution(new CharacterProfile(name, accent, style, pace), source);
  }

  public CharacterProfile resolvePlayer(String accent, String style, String pace) {
    CharacterProfile base = apply(layers.defaultProfile(), layers.playerLayer());
    return new CharacterProfile(
        base.name(),
        sanitizedOr(accent, base.accent()),
        sanitizedOr(style, base.style()),
        sanitizedOr(pace, base.pace()));
  }

  public CharacterProfile resolveNarrator() {
    return apply(layers.defaultProfile(), layers.narratorLayer());
  }

  private String sanitizedOr(String configured, String fallback) {
    if (isBlank(configured)) {
      return fallback;
    }
    String sanitized = directionSanitizer.sanitize(configured);
    return isBlank(sanitized) ? fallback : sanitized;
  }

  public boolean isLoaded() {
    return loaded;
  }

  static boolean wordContains(String haystack, String needle) {
    if (needle.isEmpty()) {
      return false;
    }
    int idx = haystack.indexOf(needle);
    while (idx >= 0) {
      boolean leftOk = idx == 0 || !Character.isLetter(haystack.charAt(idx - 1));
      int end = idx + needle.length();
      boolean rightOk = end == haystack.length() || !Character.isLetter(haystack.charAt(end));
      if (leftOk && rightOk) {
        return true;
      }
      idx = haystack.indexOf(needle, idx + 1);
    }
    return false;
  }

  private static CharacterProfile apply(CharacterProfile base, Layer layer) {
    if (layer == null) {
      return base;
    }
    return new CharacterProfile(
        layer.name() != null ? layer.name() : base.name(),
        layer.accent() != null ? layer.accent() : base.accent(),
        layer.style() != null ? layer.style() : base.style(),
        layer.pace() != null ? layer.pace() : base.pace());
  }

  private static boolean isBlank(String value) {
    return value == null || value.trim().isEmpty();
  }
}

package com.grahambartley.runelite.voiced.dialogue.profile;

import com.grahambartley.runelite.voiced.dialogue.speaker.NpcGender;
import com.grahambartley.runelite.voiced.dialogue.speaker.NpcRace;
import lombok.Value;
import lombok.experimental.Accessors;

@Value
@Accessors(fluent = true)
public class VoiceSpec {

  public static final int UNSPECIFIED_SEED = -1;

  public static final VoiceSpec NARRATOR =
      new VoiceSpec(false, NpcRace.HUMAN, NpcGender.MALE, UNSPECIFIED_SEED, false, true);

  boolean player;
  NpcRace race;
  NpcGender gender;
  int voiceSeed;
  boolean child;
  boolean narrator;

  public static VoiceSpec player(NpcGender gender) {
    return new VoiceSpec(true, NpcRace.HUMAN, gender, UNSPECIFIED_SEED, false, false);
  }

  public static VoiceSpec npc(NpcRace race, NpcGender gender) {
    return new VoiceSpec(false, race, gender, UNSPECIFIED_SEED, false, false);
  }

  public static VoiceSpec npc(NpcRace race, NpcGender gender, int seed) {
    return new VoiceSpec(false, race, gender, seed < 0 ? UNSPECIFIED_SEED : seed, false, false);
  }

  public static VoiceSpec npc(NpcRace race, NpcGender gender, int seed, boolean child) {
    return new VoiceSpec(false, race, gender, seed < 0 ? UNSPECIFIED_SEED : seed, child, false);
  }

  public boolean hasVoiceSeed() {
    return voiceSeed >= 0;
  }

  public String key() {
    if (narrator) {
      return "narrator";
    }
    return player ? "player:" + gender : "npc:" + race + ":" + gender;
  }

  @Override
  public String toString() {
    return key();
  }
}

package com.grahambartley.runelite.voiced.dialogue.profile;

import com.grahambartley.runelite.voiced.dialogue.speaker.NpcAttributes;
import lombok.Value;
import lombok.experimental.Accessors;

@Value
@Accessors(fluent = true)
class NpcIdentity {

  Integer worldId;

  NpcAttributes attributes;

  NpcProfileTable.NameMatch nameMatch;
}

