import com.grahambartley.runelite.voiced.dialogue.VoicedDialogueConfig;
import com.grahambartley.runelite.voiced.dialogue.speaker.AttributeSource;
import com.grahambartley.runelite.voiced.dialogue.speaker.NameNormalizer;
import com.grahambartley.runelite.voiced.dialogue.speaker.NpcAttributes;
import com.grahambartley.runelite.voiced.dialogue.speaker.NpcDemographicParser;
import com.grahambartley.runelite.voiced.dialogue.speaker.NpcGender;
import com.grahambartley.runelite.voiced.dialogue.speaker.NpcRace;
import com.grahambartley.runelite.voiced.dialogue.speaker.wiki.NpcLearningService;
import lombok.extern.slf4j.Slf4j;

@Slf4j
final class NpcVoiceResolver {

  private final VoicedDialogueConfig config;

  private NpcLearningService learningService;

  NpcVoiceResolver(VoicedDialogueConfig config) {
    this.config = config;
  }

  void setLearningService(NpcLearningService learningService) {
    this.learningService = learningService;
  }

  VoiceSpec resolve(String npcName, NpcIdentity identity) {
    if (npcName == null || npcName.isEmpty()) {
      return defaultVoice(npcName, null, identity, "blank-name");
    }
    if (identity.worldId() == null) {
      return defaultVoice(npcName, null, identity, "not-in-world");
    }
    NpcAttributes attributes = identity.attributes();
    if (attributes == null) {
      return defaultVoice(npcName, identity.worldId(), identity, "analysis-failed");
    }

    NpcRace race = NpcDemographicParser.toRace(attributes.getRace());
    NpcGender gender = NpcDemographicParser.toGender(attributes.getGender());
    String source =
        AttributeSource.STATIC_TABLE.equals(attributes.getSource()) ? "table-hit" : "table-miss";

    if (learningService != null) {
      learningService.considerLearning(attributes.getNpcId(), npcName);
    }

    NpcRace voiceRace = race == NpcRace.UNKNOWN ? NpcRace.HUMAN : race;
    NpcGender voiceGender = NpcDemographicParser.toVoiceGender(gender);
    boolean child = attributes.isChild() || identity.nameMatch().child();
    int seed = voiceSeed(identity.worldId(), npcName);
    if (config.debugMode()) {
      log.info(
          VoiceTraceFormatter.buildNpcTrace(
              npcName, identity.worldId(), race, gender, child, source, seed));
    }
    return VoiceSpec.npc(voiceRace, voiceGender, seed, child);
  }

  private VoiceSpec defaultVoice(
      String npcName, Integer npcId, NpcIdentity identity, String source) {
    boolean child = identity.nameMatch().child();
    int seed = voiceSeed(npcId, npcName);
    if (config.debugMode()) {
      log.info(
          VoiceTraceFormatter.buildNpcTrace(
              npcName, npcId, NpcRace.UNKNOWN, NpcGender.UNKNOWN, child, source, seed));
    }
    return VoiceSpec.npc(NpcRace.HUMAN, NpcGender.MALE, seed, child);
  }

  private static int voiceSeed(Integer npcId, String npcName) {
    int hash =
        npcId != null ? Integer.hashCode(npcId) : NameNormalizer.normalize(npcName).hashCode();
    return hash & Integer.MAX_VALUE;
  }
}

package com.grahambartley.runelite.voiced.dialogue.profile;

import com.grahambartley.runelite.voiced.dialogue.speaker.NpcGender;
import com.grahambartley.runelite.voiced.dialogue.speaker.NpcRace;

public final class VoiceTraceFormatter {

  private static final String NOT_APPLICABLE = "-";

  private VoiceTraceFormatter() {}

  static String buildNpcTrace(
      String npcName,
      Integer npcId,
      NpcRace race,
      NpcGender gender,
      boolean child,
      String source,
      int seed) {
    return String.format(
        "[TTS voice] npc='%s' world=%s race=%s gender=%s lifeStage=%s source=%s -> seed=%d",
        npcName,
        npcId == null ? "MISS" : "HIT(id=" + npcId + ")",
        race,
        gender,
        child ? "child" : "adult",
        source,
        seed);
  }

  public static String buildResolvedLine(
      String backendId, VoiceSpec voice, String npcName, String emotion, CharacterProfile profile) {
    boolean character = !voice.narrator();
    return String.format(
        "[TTS line] backend=%s kind=%s name=%s emotion=%s race=%s gender=%s lifeStage=%s seed=%s"
            + " profile=%s accent=%s",
        backendId,
        kindOf(voice),
        voice.player() || voice.narrator() ? "-" : "'" + npcName + "'",
        emotion,
        character ? voice.race() : NOT_APPLICABLE,
        character ? voice.gender() : NOT_APPLICABLE,
        character ? (voice.child() ? "child" : "adult") : NOT_APPLICABLE,
        voice.hasVoiceSeed() ? Integer.toString(voice.voiceSeed()) : NOT_APPLICABLE,
        "'" + profile.name() + "'",
        "'" + profile.accent() + "'");
  }

  private static String kindOf(VoiceSpec voice) {
    if (voice.narrator()) {
      return "narrator";
    }
    return voice.player() ? "player" : "npc";
  }

  static String buildPlayerTrace(NpcGender gender) {
    return String.format("[TTS voice] player -> gender=%s", gender);
  }
}

package com.grahambartley.runelite.voiced.dialogue.profile;

import com.grahambartley.runelite.voiced.dialogue.speaker.NpcDemographicAnalyzer;
import com.grahambartley.runelite.voiced.dialogue.speaker.NpcFinder;
import net.runelite.api.NPC;

final class NpcIdentityResolver {

  private final NpcFinder npcFinder;
  private final NpcDemographicAnalyzer demographicAnalyzer;
  private final NpcProfileTable profileTable;

  NpcIdentityResolver(
      NpcFinder npcFinder,
      NpcDemographicAnalyzer demographicAnalyzer,
      NpcProfileTable profileTable) {
    this.npcFinder = npcFinder;
    this.demographicAnalyzer = demographicAnalyzer;
    this.profileTable = profileTable;
  }

  NpcIdentity resolve(String npcName) {
    NpcProfileTable.NameMatch nameMatch = profileTable.matchName(npcName);
    NPC npc = npcFinder.findByName(npcName);
    if (npc == null) {
      return new NpcIdentity(null, null, nameMatch);
    }
    return new NpcIdentity(npc.getId(), demographicAnalyzer.analyzeNPC(npc), nameMatch);
  }

  NpcIdentity resolve(NPC npc) {
    return new NpcIdentity(
        npc.getId(), demographicAnalyzer.analyzeNPC(npc), profileTable.matchName(npc.getName()));
  }
}

