@Slf4j
@PluginDescriptor(name = "Voiced Dialogue")
public class VoicedDialoguePlugin extends Plugin {

  private static final int CACHE_SIZE = 64;

  private static final int QUEUE_CAPACITY = 4;

  private static final long WIKI_CALL_INTERVAL_MILLIS = 500;

  @Inject private Client client;

  @Inject private VoicedDialogueConfig config;

  @Inject private OkHttpClient okHttpClient;

  @Inject private Gson gson;

  @Inject private ConfigManager configManager;

  @Inject private ClientThread clientThread;

  @Inject private ChatMessageManager chatMessageManager;

  private BackendProvider backendProvider;

  private DialogueAudioService audioService;

  private ExecutorService wikiExecutor;

  private VoiceManager voiceManager;

  private ChatNoticeManager noticeManager;

  private DialogueWatcher dialogueWatcher;
  private ExamineSpeaker examineSpeaker;

  private PublicChatSpeaker publicChatSpeaker;

  private AmbientChatterWatcher ambientChatterWatcher;

  private SpendTracker spendTracker;

  private OpenRouterUsageClient usageClient;

  private OpenRouterCreditMeter creditMeter;

  private ExecutorService spendExecutor;

  private NpcLearningService learningService;

  private final AtomicLong spendEpoch = new AtomicLong();

  @Override
  protected void startUp() {
    pinProviderWhenOnlyOpenRouterKeyed();
    voiceManager = VoiceManager.create(config, client);

    Path ttsDir = RuneLite.RUNELITE_DIR.toPath().resolve("voiced-dialogue");
    try {
      LearnedNpcStore learnedStore = new LearnedNpcStore(ttsDir.resolve("learned-npcs.json"), gson);
      wikiExecutor =
          Executors.newSingleThreadExecutor(
              r -> {
                Thread t = new Thread(r, "tts-wiki-learn");
                t.setDaemon(true);
                return t;
              });
      learningService =
          new NpcLearningService(
              new WikiNpcClient(okHttpClient),
              learnedStore,
              wikiExecutor,
              config::autoLearnNewNpcs,
              voiceManager::isVoiced,
              new WikiCallThrottle(WIKI_CALL_INTERVAL_MILLIS));
      voiceManager.enableLearning(learnedStore, learningService);
    } catch (RuntimeException | LinkageError e) {
      log.warn("Auto-learn is unavailable: {}", e.getMessage());
    }

    noticeManager = new ChatNoticeManager(client, configManager, clientThread, chatMessageManager);

    spendTracker = new SpendTracker();
    usageClient = new OpenRouterUsageClient(okHttpClient, gson);
    creditMeter = new OpenRouterCreditMeter();
    spendExecutor =
        Executors.newSingleThreadExecutor(
            r -> {
              Thread t = new Thread(r, "tts-spend");
              t.setDaemon(true);
              return t;
            });
    captureOpenRouterBaseline();

    OpenRouterTtsBackend openRouterBackend = new OpenRouterTtsBackend(okHttpClient, config, gson);
    openRouterBackend.setNotice(noticeManager::notifyFromBackendThread);
    openRouterBackend.setSpendTracker(spendTracker);
    AiStudioTtsBackend aiStudioBackend = new AiStudioTtsBackend(okHttpClient, config, gson);
    aiStudioBackend.setNotice(noticeManager::notifyFromBackendThread);
    aiStudioBackend.setSpendTracker(spendTracker);
    backendProvider = new BackendProvider(openRouterBackend, aiStudioBackend, config::ttsProvider);
    DiskAudioCache diskCache =
        new DiskAudioCache(
            ttsDir.resolve("cache"), () -> config.cacheSizeLimitMiB() * 1024L * 1024);
    audioService =
        new DialogueAudioService(
            backendProvider,
            new StreamingAudioPlayer(),
            StreamingAudioPlayer::new,
            diskCache,
            CACHE_SIZE,
            QUEUE_CAPACITY,
            config::volume);
    audioService.prewarm(backendProvider::warmUpActive);
    DialoguePrefetcher prefetcher =
        new DialoguePrefetcher(audioService::prefetch, audioService::cancelPrefetch);

    DialogueTextCleaner textCleaner = new DialogueTextCleaner(new ProfanityFilter());
    CaveEchoPolicy caveEchoPolicy = new CaveEchoPolicy(client, config);
    SynthesisDispatcher synthesisDispatcher =
        new SynthesisDispatcher(
            voiceManager,
            new EmotionResolver(),
            caveEchoPolicy,
            config,
            backendProvider,
            audioService);
    DialoguePrefetchCoordinator prefetchCoordinator =
        new DialoguePrefetchCoordinator(
            voiceManager, textCleaner, prefetcher, backendProvider, config);
    dialogueWatcher =
        new DialogueWatcher(
            client,
            textCleaner,
            new DialogueWidgetReader(client),
            synthesisDispatcher,
            prefetchCoordinator,
            audioService,
            new NarrationWatcher(client, textCleaner, synthesisDispatcher, config::voiceNarration));
    publicChatSpeaker =
        new PublicChatSpeaker(client, textCleaner, synthesisDispatcher, config::voicePublicChat);
    examineSpeaker =
        new ExamineSpeaker(
            textCleaner,
            synthesisDispatcher,
            config::voiceExamineText,
            dialogueWatcher::isDialogueOpen,
            clientThread::invokeLater);
    ambientChatterWatcher =
        new AmbientChatterWatcher(
            client,
            textCleaner,
            synthesisDispatcher,
            config::voiceAmbientChatter,
            dialogueWatcher::isConversationOnScreen,
            config::volume);

    log.info("VoicedDialogue started");
  }

  @Override
  protected void shutDown() {
    if (learningService != null) {
      learningService.close();
      learningService = null;
    }
    noticeManager = null;
    spendTracker = null;
    usageClient = null;
    creditMeter = null;
    spendEpoch.incrementAndGet();
    if (spendExecutor != null) {
      spendExecutor.shutdown();
      spendExecutor = null;
    }
    dialogueWatcher = null;
    publicChatSpeaker = null;
    examineSpeaker = null;
    ambientChatterWatcher = null;
    if (audioService != null) {
      audioService.close();
      audioService = null;
    }
    if (backendProvider != null) {
      backendProvider.close();
      backendProvider = null;
    }
    voiceManager = null;
    if (wikiExecutor != null) {
      wikiExecutor.shutdown();
      wikiExecutor = null;
    }
    log.info("VoicedDialogue stopped");
  }

  @Subscribe
  public void onGameTick(final GameTick tick) {
    if (noticeManager == null
        || backendProvider == null
        || dialogueWatcher == null
        || audioService == null) {
      return;
    }
    noticeManager.maybeShowOnboarding();
    noticeManager.maybeWarnMissingCloudKey(backendProvider.active());
    dialogueWatcher.tick();
    audioService.refreshAmbientVolumes();
  }

  @Subscribe
  public void onChatMessage(ChatMessage event) {
    if (publicChatSpeaker != null) {
      publicChatSpeaker.onChatMessage(event);
    }
    if (examineSpeaker != null) {
      examineSpeaker.onChatMessage(event);
    }
  }

  @Subscribe
  public void onMenuOptionClicked(MenuOptionClicked event) {
    if (voiceManager != null) {
      voiceManager.offerToLearning(event.getMenuOption(), event.getMenuEntry().getNpc());
    }
  }

  @Subscribe
  public void onOverheadTextChanged(OverheadTextChanged event) {
    if (ambientChatterWatcher != null) {
      ambientChatterWatcher.onOverheadTextChanged(event);
    }
  }

  @Subscribe
  public void onCommandExecuted(CommandExecuted event) {
    if (!SpendReport.matches(event.getCommand())
        || spendTracker == null
        || noticeManager == null
        || usageClient == null
        || creditMeter == null) {
      return;
    }
    List<SpendTracker.ProviderSpend> snapshot = spendTracker.snapshot();
    String key = config.openRouterApiKey();
    OpenRouterUsageClient reader = usageClient;
    OpenRouterCreditMeter meter = creditMeter;
    log.debug(
        "[TTS spend] ::{} received, {} provider(s) used", SpendReport.COMMAND, snapshot.size());
    submitSpendTask(
        () -> {
          try {
            Double spent = meter.spentSince(key, reader.fetchUsage(key));
            ChatNoticeManager notices = noticeManager;
            if (notices == null) {
              return;
            }
            List<String> lines = SpendReport.lines(snapshot, spent);
            for (String line : lines) {
              notices.postCommandResponse(line);
            }
            log.debug("[TTS spend] queued {} readout line(s), billedUsd={}", lines.size(), spent);
          } catch (RuntimeException e) {
            log.warn("[TTS spend] could not build the spend readout", e);
          }
        });
  }

  private void captureOpenRouterBaseline() {
    String key = config.openRouterApiKey();
    OpenRouterUsageClient reader = usageClient;
    OpenRouterCreditMeter meter = creditMeter;
    if (reader == null || meter == null || meter.hasBaselineFor(key)) {
      return;
    }
    submitSpendTask(() -> meter.recordBaseline(key, reader.fetchUsage(key)));
  }

  private void submitSpendTask(Runnable task) {
    ExecutorService executor = spendExecutor;
    if (executor == null) {
      return;
    }
    long mine = spendEpoch.get();
    try {
      executor.execute(
          () -> {
            if (spendEpoch.get() == mine) {
              task.run();
            }
          });
    } catch (RejectedExecutionException ignored) {
    }
  }

  void pinProviderWhenOnlyOpenRouterKeyed() {
    String stored =
        configManager.getConfiguration(
            VoicedDialogueConfig.GROUP, VoicedDialogueConfig.PROVIDER_KEY);
    if (!ProviderDefaultPolicy.shouldPinToOpenRouter(stored, config.openRouterApiKey())) {
      return;
    }
    configManager.setConfiguration(
        VoicedDialogueConfig.GROUP,
        VoicedDialogueConfig.PROVIDER_KEY,
        VoicedDialogueConfig.TtsProvider.OPENROUTER);
    log.info("Pinned this profile to OpenRouter, the provider it holds a key for");
  }

  @Subscribe
  public void onConfigChanged(ConfigChanged event) {
    if (VoicedDialogueConfig.GROUP.equals(event.getGroup())
        && VoicedDialogueConfig.OPENROUTER_API_KEY.equals(event.getKey())
        && creditMeter != null) {
      creditMeter.reset();
      captureOpenRouterBaseline();
    }
    if (!BackendWarmUpPolicy.affectsBackendWarmUp(event.getGroup(), event.getKey())) {
      return;
    }
    if (audioService == null || backendProvider == null) {
      return;
    }
    backendProvider.clearRateLimits();
    audioService.prewarm(backendProvider::warmUpActive);
  }

  @Provides
  VoicedDialogueConfig provideConfig(ConfigManager configManager) {
    return configManager.getConfig(VoicedDialogueConfig.class);
  }
}

package com.grahambartley.runelite.voiced.dialogue.cache;

import com.grahambartley.runelite.voiced.dialogue.audio.Pcm;
import com.grahambartley.runelite.voiced.dialogue.profile.Emotion;
import java.io.IOException;
import java.nio.ByteBuffer;
import java.nio.ByteOrder;
import java.nio.charset.StandardCharsets;
import java.nio.file.DirectoryStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.nio.file.attribute.BasicFileAttributes;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.function.LongSupplier;
import lombok.extern.slf4j.Slf4j;

@Slf4j
public class DiskAudioCache {

  private static final int MAGIC = 0x54_44_43_31;

  private static final int HEADER_BYTES = 16;

  public static final long DEFAULT_MAX_BYTES = 256L * 1024 * 1024;

  public static final long UNLIMITED = 0;

  private final Path dir;
  private final LongSupplier maxBytes;

  private volatile boolean disabled;

  public DiskAudioCache(Path dir) {
    this(dir, DEFAULT_MAX_BYTES);
  }

  public DiskAudioCache(Path dir, long maxBytes) {
    this(dir, () -> maxBytes);
  }

  public DiskAudioCache(Path dir, LongSupplier maxBytes) {
    this.dir = dir;
    this.maxBytes = maxBytes;
  }

  public Pcm get(String backendId, String voiceKey, Emotion emotion, String text) {
    if (disabled) {
      return null;
    }
    Path file;
    try {
      file = fileFor(backendId, voiceKey, emotion, text);
    } catch (RuntimeException e) {
      return null;
    }
    if (!Files.isRegularFile(file)) {
      return null;
    }
    try {
      Pcm pcm = decode(Files.readAllBytes(file));
      if (pcm == null) {
        deleteQuietly(file);
        return null;
      }
      return pcm;
    } catch (IOException | RuntimeException e) {
      log.debug("Disk cache read failed for {}; treating as miss", file.getFileName(), e);
      deleteQuietly(file);
      return null;
    }
  }

  public void put(String backendId, String voiceKey, Emotion emotion, String text, Pcm pcm) {
    if (disabled || pcm == null || pcm.getSamples() == null) {
      return;
    }
    Path file;
    try {
      ensureDir();
      file = fileFor(backendId, voiceKey, emotion, text);
    } catch (IOException | RuntimeException e) {
      log.debug("Disk cache unavailable; disabling on-disk caching", e);
      disabled = true;
      return;
    }
    Path tmp = null;
    try {
      tmp = Files.createTempFile(dir, file.getFileName().toString(), ".tmp");
      Files.write(tmp, encode(pcm));
      try {
        Files.move(tmp, file, StandardCopyOption.ATOMIC_MOVE, StandardCopyOption.REPLACE_EXISTING);
      } catch (IOException atomicUnsupported) {
        Files.move(tmp, file, StandardCopyOption.REPLACE_EXISTING);
      }
      tmp = null;
      enforceSizeCap();
    } catch (IOException | RuntimeException e) {
      log.debug("Disk cache write failed for {}; skipping", file.getFileName(), e);
    } finally {
      if (tmp != null) {
        deleteQuietly(tmp);
      }
    }
  }

  private Path fileFor(String backendId, String voiceKey, Emotion emotion, String text) {
    return dir.resolve(hashKey(backendId, voiceKey, emotion, text) + ".tdc");
  }

  private static String hashKey(String backendId, String voiceKey, Emotion emotion, String text) {
    try {
      MessageDigest md = MessageDigest.getInstance("SHA-256");
      feed(md, backendId);
      feed(md, voiceKey);
      feed(md, emotion == null ? "null" : emotion.name());
      feed(md, text);
      byte[] digest = md.digest();
      StringBuilder sb = new StringBuilder(digest.length * 2);
      for (byte b : digest) {
        sb.append(Character.forDigit((b >> 4) & 0xF, 16));
        sb.append(Character.forDigit(b & 0xF, 16));
      }
      return sb.toString();
    } catch (NoSuchAlgorithmException e) {
      throw new IllegalStateException("SHA-256 unavailable", e);
    }
  }

  private static void feed(MessageDigest md, String field) {
    byte[] bytes = field == null ? new byte[0] : field.getBytes(StandardCharsets.UTF_8);
    ByteBuffer len = ByteBuffer.allocate(4).order(ByteOrder.LITTLE_ENDIAN).putInt(bytes.length);
    md.update(len.array());
    md.update(bytes);
  }

  private static byte[] encode(Pcm pcm) {
    float[] samples = pcm.getSamples();
    ByteBuffer buf =
        ByteBuffer.allocate(HEADER_BYTES + samples.length * 4).order(ByteOrder.LITTLE_ENDIAN);
    buf.putInt(MAGIC);
    buf.putInt(pcm.getSampleRate());
    buf.putInt(samples.length);
    buf.putInt(0);
    buf.asFloatBuffer().put(samples);
    return buf.array();
  }

  private static Pcm decode(byte[] bytes) {
    if (bytes.length < HEADER_BYTES) {
      return null;
    }
    ByteBuffer buf = ByteBuffer.wrap(bytes).order(ByteOrder.LITTLE_ENDIAN);
    if (buf.getInt() != MAGIC) {
      return null;
    }
    int sampleRate = buf.getInt();
    int sampleCount = buf.getInt();
    buf.getInt();
    if (sampleRate <= 0 || sampleCount < 0) {
      return null;
    }
    if (bytes.length != HEADER_BYTES + (long) sampleCount * 4) {
      return null;
    }
    float[] samples = new float[sampleCount];
    buf.asFloatBuffer().get(samples);
    return new Pcm(samples, sampleRate);
  }

  private void ensureDir() throws IOException {
    if (!Files.isDirectory(dir)) {
      Files.createDirectories(dir);
    }
  }

  private static void deleteQuietly(Path file) {
    try {
      Files.deleteIfExists(file);
    } catch (IOException ignored) {
    }
  }

  private void enforceSizeCap() {
    long cap = maxBytes.getAsLong();
    if (cap <= UNLIMITED) {
      return;
    }
    List<Entry> entries = new ArrayList<>();
    long total = 0;
    try (DirectoryStream<Path> stream = Files.newDirectoryStream(dir, "*.tdc")) {
      for (Path p : stream) {
        try {
          BasicFileAttributes attrs = Files.readAttributes(p, BasicFileAttributes.class);
          if (attrs.isRegularFile()) {
            entries.add(new Entry(p, attrs.size(), attrs.lastModifiedTime().toMillis()));
            total += attrs.size();
          }
        } catch (IOException ignored) {
        }
      }
    } catch (IOException e) {
      log.debug("Disk cache size scan failed; skipping eviction this round", e);
      return;
    }
    if (total <= cap) {
      return;
    }
    entries.sort(Comparator.comparingLong(e -> e.mtime));
    for (Entry e : entries) {
      if (total <= cap) {
        break;
      }
      deleteQuietly(e.path);
      total -= e.size;
    }
  }

  private static final class Entry {
    final Path path;
    final long size;
    final long mtime;

    Entry(Path path, long size, long mtime) {
      this.path = path;
      this.size = size;
      this.mtime = mtime;
    }
  }
}

package com.grahambartley.runelite.voiced.dialogue.cache;

import java.util.LinkedHashMap;
import java.util.Map;

public final class LruCache<K, V> {

  private final int maxSize;
  private final LinkedHashMap<K, V> map;

  public LruCache(int maxSize) {
    if (maxSize < 1) {
      throw new IllegalArgumentException("maxSize must be at least 1");
    }
    this.maxSize = maxSize;
    this.map =
        new LinkedHashMap<K, V>(16, 0.75f, true) {
          @Override
          protected boolean removeEldestEntry(Map.Entry<K, V> eldest) {
            return size() > LruCache.this.maxSize;
          }
        };
  }

  public synchronized V get(K key) {
    return map.get(key);
  }

  public synchronized void put(K key, V value) {
    map.put(key, value);
  }

  public synchronized boolean containsKey(K key) {
    return map.containsKey(key);
  }

  public synchronized int size() {
    return map.size();
  }
}

package com.grahambartley.runelite.voiced.dialogue.cache;

import com.grahambartley.runelite.voiced.dialogue.audio.Pcm;
import com.grahambartley.runelite.voiced.dialogue.profile.Emotion;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ConcurrentHashMap;
import java.util.function.Supplier;
import lombok.Value;
import lombok.experimental.Accessors;
import lombok.extern.slf4j.Slf4j;

@Slf4j
public final class TieredSynthesisCache {

  private static final int LOG_TEXT_PREVIEW_LENGTH = 40;

  @Value
  @Accessors(fluent = true)
  public static class CacheKey {
    String backendId;
    String voiceKey;
    Emotion emotion;
    String text;

    public String textPreview() {
      return text.length() <= LOG_TEXT_PREVIEW_LENGTH
          ? text
          : text.substring(0, LOG_TEXT_PREVIEW_LENGTH) + "...";
    }
  }

  public final LruCache<CacheKey, Pcm> memory;
  private final DiskAudioCache disk;
  public final ConcurrentHashMap<CacheKey, CompletableFuture<Pcm>> inFlight =
      new ConcurrentHashMap<>();

  public TieredSynthesisCache(int maxEntries, DiskAudioCache disk) {
    this.memory = new LruCache<>(maxEntries);
    this.disk = disk;
  }

  public Pcm memoryHit(CacheKey key) {
    return memory.get(key);
  }

  public Pcm lookup(CacheKey key) {
    long start = System.nanoTime();
    Pcm pcm = memory.get(key);
    if (pcm != null) {
      log.debug(
          "[TTS cache] hit tier=memory lookupMs={} ({}/{}) \"{}\"",
          elapsedMs(start),
          key.backendId(),
          key.voiceKey(),
          key.textPreview());
      return pcm;
    }
    if (disk != null) {
      pcm = disk.get(key.backendId(), key.voiceKey(), key.emotion(), key.text());
      if (pcm != null) {
        memory.put(key, pcm);
        log.debug(
            "[TTS cache] hit tier=disk lookupMs={} ({}/{}) \"{}\"",
            elapsedMs(start),
            key.backendId(),
            key.voiceKey(),
            key.textPreview());
      }
    }
    return pcm;
  }

  public Pcm withInFlight(CacheKey key, Supplier<Pcm> synth, Runnable onDeduped) {
    CompletableFuture<Pcm> own = new CompletableFuture<>();
    CompletableFuture<Pcm> running = inFlight.putIfAbsent(key, own);
    if (running != null) {
      onDeduped.run();
      return await(running);
    }
    Pcm pcm = null;
    try {
      pcm = synth.get();
      if (pcm != null) {
        writeThrough(key, pcm);
      }
    } finally {
      own.complete(pcm);
      inFlight.remove(key, own);
    }
    return pcm;
  }

  private void writeThrough(CacheKey key, Pcm pcm) {
    memory.put(key, pcm);
    if (disk != null) {
      disk.put(key.backendId(), key.voiceKey(), key.emotion(), key.text(), pcm);
    }
  }

  private static Pcm await(CompletableFuture<Pcm> future) {
    try {
      return future.join();
    } catch (RuntimeException e) {
      return null;
    }
  }

  private static long elapsedMs(long startNanos) {
    return (System.nanoTime() - startNanos) / 1_000_000L;
  }
}

package com.grahambartley.runelite.voiced.dialogue.speaker;

import lombok.extern.slf4j.Slf4j;

@Slf4j
public final class NpcDemographicParser {

  static final NpcGender DEFAULT_GENDER = NpcGender.MALE;

  private NpcDemographicParser() {}

  public static NpcRace toRace(String race) {
    if (race == null || race.isEmpty()) {
      return NpcRace.UNKNOWN;
    }

    try {
      return NpcRace.valueOf(race.toUpperCase());
    } catch (IllegalArgumentException notAnEnumName) {
      RaceBucket named = RaceBucket.forBucketName(race);
      if (named != null) {
        return named.race();
      }
      RaceBucket keyword = RaceBucket.forKeyword(race);
      if (keyword != null) {
        return keyword.race();
      }

      log.debug("Unknown race '{}', using default voice", race);
      return NpcRace.UNKNOWN;
    }
  }

  public static NpcGender toGender(String gender) {
    if (gender == null || gender.isEmpty()) {
      return NpcGender.UNKNOWN;
    }

    try {
      return NpcGender.valueOf(gender.toUpperCase());
    } catch (IllegalArgumentException notAnEnumName) {
      String genderLower = gender.toLowerCase();

      if (genderLower.contains("female")
          || genderLower.contains("woman")
          || genderLower.contains("girl")
          || genderLower.contains("lady")) {
        return NpcGender.FEMALE;
      } else if (genderLower.contains("male")
          || genderLower.contains("man")
          || genderLower.contains("boy")
          || genderLower.contains("lord")) {
        return NpcGender.MALE;
      }

      log.debug("Unknown gender '{}', defaulting to MALE", gender);
      return DEFAULT_GENDER;
    }
  }

  public static NpcGender toVoiceGender(NpcGender detected) {
    return detected == NpcGender.FEMALE ? NpcGender.FEMALE : DEFAULT_GENDER;
  }
}

package com.grahambartley.runelite.voiced.dialogue.speaker;

public enum NpcGender {
  MALE,
  FEMALE,
  UNKNOWN
}

package com.grahambartley.runelite.voiced.dialogue.speaker;

public enum RaceBucket {
  ARCEUUS("Arceuus", NpcRace.ARCEUUS, "arceuus"),
  ARANEI("Aranei", NpcRace.ARANEI, "aranei"),
  HUMAN("Human", NpcRace.HUMAN, "human", "man", "person"),
  ELF("Elf", NpcRace.ELF, "elf", "elven"),
  DWARF("Dwarf", NpcRace.DWARF, "dwarf", "dwarven"),
  GNOME("Gnome", NpcRace.GOBLIN, "gnome"),
  GOBLIN("Goblin", NpcRace.GOBLIN, "goblin"),
  TROLL("Troll", NpcRace.TROLL, "troll", "giant"),
  UNDEAD("Undead", NpcRace.UNDEAD, "undead", "skeleton", "zombie", "ghost", "revenant", "reanimat"),
  DEMON("Demon", NpcRace.DEMON, "demon", "dragon", "devil", "hellhound"),
  DOG("Dog", NpcRace.DOG, "dog"),
  CRAB("Crab", NpcRace.CRAB, "crab"),
  PENGUIN("Penguin", NpcRace.PENGUIN, "penguin"),
  GORILLA("Gorilla", NpcRace.GORILLA, "gorilla"),
  MONKEY("Monkey", NpcRace.MONKEY, "monkey", "primate"),
  WIZARD("Wizard", NpcRace.WIZARD, "wizard", "mage"),
  TORTUGAN("Tortugan", NpcRace.TORTUGAN, "tortugan", "tortuga"),
  ICYENE("Icyene", NpcRace.ICYENE, "icyene");

  private final String bucketName;
  private final NpcRace race;
  private final String[] keywords;

  RaceBucket(String bucketName, NpcRace race, String... keywords) {
    this.bucketName = bucketName;
    this.race = race;
    this.keywords = keywords;
  }

  public NpcRace race() {
    return race;
  }

  static RaceBucket forBucketName(String race) {
    for (RaceBucket bucket : values()) {
      if (bucket.bucketName.equalsIgnoreCase(race)) {
        return bucket;
      }
    }
    return null;
  }

  static RaceBucket forKeyword(String race) {
    String lower = race.toLowerCase();
    for (RaceBucket bucket : values()) {
      for (String keyword : bucket.keywords) {
        if (lower.contains(keyword)) {
          return bucket;
        }
      }
    }
    return null;
  }
}

package com.grahambartley.runelite.voiced.dialogue.speaker;

import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.Collections;
import java.util.Map;
import java.util.regex.Pattern;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.NPC;
import net.runelite.api.NPCComposition;

@Slf4j
public class NpcDemographicAnalyzer {

  private static final String TABLE_RESOURCE = "/npc-voices.json";
  private static final String DEFAULT_RACE = "Unknown";
  private static final String DEFAULT_GENDER = "Male";

  private static final Pattern FEMALE_NAME_HINT =
      Pattern.compile(
          "\\b(woman|women|girl|lady|queen|princess|duchess|countess|baroness|empress|witch"
              + "|sorceress|priestess|huntress|banshee|hag|crone|mother|sister|nun|maiden|barmaid"
              + "|waitress|seamstress|goddess|mistress|madam|damsel|wife|maid)\\b",
          Pattern.CASE_INSENSITIVE);

  private Map<Integer, NpcAttributes> voiceTable = Collections.emptyMap();

  private LearnedNpcStore learnedStore;

  public void initialize() {
    voiceTable = loadVoiceTable();
    log.info("NPC voice table loaded with {} entries from {}", voiceTable.size(), TABLE_RESOURCE);
  }

  public void setLearnedStore(LearnedNpcStore learnedStore) {
    this.learnedStore = learnedStore;
  }

  public NpcAttributes analyzeNPC(NPC npc) {
    if (npc == null) {
      return null;
    }
    NPCComposition composition = npc.getComposition();
    if (composition == null) {
      return null;
    }
    int activeId = npc.getId();
    int baseId = composition.getId();
    NpcAttributes known = lookupKnown(activeId);
    if (known == null && baseId != activeId) {
      known = lookupKnown(baseId);
    }
    return known != null ? known : defaultAttributes(activeId, composition.getName());
  }

  private NpcAttributes lookupKnown(int npcId) {
    NpcAttributes attributes = voiceTable.get(npcId);
    if (attributes != null) {
      return attributes;
    }
    return learnedStore != null ? learnedStore.get(npcId) : null;
  }

  public boolean isVoiced(int npcId) {
    return voiceTable.containsKey(npcId) || (learnedStore != null && learnedStore.contains(npcId));
  }

  public int getTableSize() {
    return voiceTable.size();
  }

  private NpcAttributes defaultAttributes(int npcId, String npcName) {
    String gender =
        npcName != null && FEMALE_NAME_HINT.matcher(npcName).find() ? "Female" : DEFAULT_GENDER;
    NpcAttributes defaultData = new NpcAttributes(DEFAULT_RACE, gender, AttributeSource.DEFAULT);
    defaultData.setNpcId(npcId);
    return defaultData;
  }

  private Map<Integer, NpcAttributes> loadVoiceTable() {
    try (InputStream stream = getClass().getResourceAsStream(TABLE_RESOURCE)) {
      if (stream == null) {
        log.warn(
            "NPC voice table {} not found - every NPC will use the default voice", TABLE_RESOURCE);
        return Collections.emptyMap();
      }

      Map<Integer, NpcAttributes> table =
          NpcEntriesReader.read(
              new InputStreamReader(stream, StandardCharsets.UTF_8),
              AttributeSource.STATIC_TABLE,
              (key, e) ->
                  log.warn("Skipping malformed NPC voice entry {}: {}", key, e.getMessage()));
      if (table == null) {
        log.warn("NPC voice table {} has no 'npcs' object - using default voice", TABLE_RESOURCE);
        return Collections.emptyMap();
      }
      return Collections.unmodifiableMap(table);
    } catch (Exception e) {
      log.error("Failed to load NPC voice table {}: {}", TABLE_RESOURCE, e.getMessage());
      return Collections.emptyMap();
    }
  }
}

package com.grahambartley.runelite.voiced.dialogue.speaker.wiki;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import com.grahambartley.runelite.voiced.dialogue.speaker.AttributeSource;
import com.grahambartley.runelite.voiced.dialogue.speaker.NameNormalizer;
import com.grahambartley.runelite.voiced.dialogue.speaker.NpcAttributes;
import java.time.Duration;
import java.util.ArrayList;
import java.util.List;
import lombok.extern.slf4j.Slf4j;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;

@Slf4j
public final class WikiNpcClient {

  private static final String PRODUCTION_API = "https://oldschool.runescape.wiki/api.php";
  private static final String USER_AGENT = "runelite-voiced-dialogue";
  private static final Duration CALL_TIMEOUT = Duration.ofSeconds(8);
  private static final String CATEGORY_LIMIT = "500";

  private final OkHttpClient httpClient;
  private final String api;
  private final WikiMapping mapping = WikiMapping.get();

  public WikiNpcClient(OkHttpClient httpClient) {
    this(httpClient, PRODUCTION_API);
  }

  WikiNpcClient(OkHttpClient httpClient, String api) {
    this.httpClient = httpClient.newBuilder().callTimeout(CALL_TIMEOUT).build();
    this.api = api;
  }

  public WikiLookup lookup(int npcId, String npcName) {
    String title = NameNormalizer.normalize(npcName);
    if (title.isEmpty()) {
      return WikiLookup.undocumented();
    }
    HttpUrl url =
        HttpUrl.get(api)
            .newBuilder()
            .addQueryParameter("action", "query")
            .addQueryParameter("prop", "revisions|categories")
            .addQueryParameter("rvprop", "content")
            .addQueryParameter("rvslots", "main")
            .addQueryParameter("rvsection", "0")
            .addQueryParameter("cllimit", CATEGORY_LIMIT)
            .addQueryParameter("redirects", "1")
            .addQueryParameter("format", "json")
            .addQueryParameter("formatversion", "2")
            .addQueryParameter("titles", title)
            .build();
    Request request =
        new Request.Builder().url(url).addHeader("User-Agent", USER_AGENT).get().build();

    String body;
    try (Response response = httpClient.newCall(request).execute()) {
      if (!response.isSuccessful()) {
        log.debug("Wiki lookup for '{}' answered {}", title, response.code());
        return WikiLookup.unreachable();
      }
      ResponseBody payload = response.body();
      body = payload == null ? null : payload.string();
    } catch (Exception e) {
      log.debug("Wiki lookup for '{}' failed: {}", title, e.getMessage());
      return WikiLookup.unreachable();
    }

    JsonObject query = queryOf(body);
    if (query == null) {
      log.debug("Wiki lookup for '{}' answered something other than wiki json", title);
      return WikiLookup.unreachable();
    }
    JsonObject page = firstPage(query);
    if (page == null) {
      return WikiLookup.undocumented();
    }
    String wikitext = wikitextOf(page);
    if (wikitext == null || !mapping.isNpcPage(wikitext)) {
      return WikiLookup.undocumented();
    }
    return WikiLookup.of(attributesFrom(npcId, WikiInfobox.parse(wikitext, categoriesOf(page))));
  }

  private NpcAttributes attributesFrom(int npcId, WikiInfobox infobox) {
    String race = mapping.raceForWikiText(infobox.raceReadings());
    if (race == null) {
      race = mapping.raceForCategories(infobox.categories());
    }
    if (race == null) {
      race = mapping.defaultRace();
    }
    NpcAttributes attributes =
        new NpcAttributes(race, gender(npcId, infobox), AttributeSource.WIKI);
    attributes.setNpcId(npcId);
    attributes.setEthnicity(
        mapping.ethnicityKey(infobox.leagueRegion(), infobox.location(), infobox.categories()));
    return attributes;
  }

  private String gender(int npcId, WikiInfobox infobox) {
    return mapping.genderForWikiText(infobox.genderForVersion(npcId));
  }

  private static JsonObject queryOf(String json) {
    if (json == null) {
      return null;
    }
    try {
      JsonElement root = new JsonParser().parse(json);
      if (!root.isJsonObject() || !root.getAsJsonObject().has("query")) {
        return null;
      }
      return root.getAsJsonObject().getAsJsonObject("query");
    } catch (RuntimeException e) {
      return null;
    }
  }

  private static JsonObject firstPage(JsonObject query) {
    try {
      JsonArray pages = query.getAsJsonArray("pages");
      return pages.size() == 0 ? null : pages.get(0).getAsJsonObject();
    } catch (RuntimeException e) {
      return null;
    }
  }

  private static String wikitextOf(JsonObject page) {
    try {
      return page.getAsJsonArray("revisions")
          .get(0)
          .getAsJsonObject()
          .getAsJsonObject("slots")
          .getAsJsonObject("main")
          .get("content")
          .getAsString();
    } catch (RuntimeException e) {
      return null;
    }
  }

  private static List<String> categoriesOf(JsonObject page) {
    List<String> categories = new ArrayList<>();
    if (!page.has("categories") || !page.get("categories").isJsonArray()) {
      return categories;
    }
    for (JsonElement element : page.getAsJsonArray("categories")) {
      JsonObject category = element.getAsJsonObject();
      if (category.has("title")) {
        categories.add(category.get("title").getAsString());
      }
    }
    return categories;
  }
}

package com.grahambartley.runelite.voiced.dialogue.speaker.wiki;

import com.grahambartley.runelite.voiced.dialogue.speaker.LearnedNpcStore;
import com.grahambartley.runelite.voiced.dialogue.speaker.NpcAttributes;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.Executor;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.function.BooleanSupplier;
import java.util.function.IntPredicate;
import lombok.extern.slf4j.Slf4j;

@Slf4j
public final class NpcLearningService {

  private static final String DIALOGUE_OPTION_PREFIX = "talk";

  private static final int FAILURES_BEFORE_QUIET = 3;

  private static final long QUIET_MILLIS = TimeUnit.MINUTES.toMillis(2);

  private final WikiNpcClient client;
  private final LearnedNpcStore store;
  private final Executor executor;
  private final BooleanSupplier enabled;
  private final IntPredicate voiced;
  private final WikiCallThrottle throttle;
  private final Set<Integer> attempted = ConcurrentHashMap.newKeySet();

  private final AtomicInteger consecutiveFailures = new AtomicInteger();

  private volatile long quietUntilMillis;

  private volatile boolean closed;

  public NpcLearningService(
      WikiNpcClient client,
      LearnedNpcStore store,
      Executor executor,
      BooleanSupplier enabled,
      IntPredicate voiced,
      WikiCallThrottle throttle) {
    this.client = client;
    this.store = store;
    this.executor = executor;
    this.enabled = enabled;
    this.voiced = voiced;
    this.throttle = throttle;
  }

  public void close() {
    closed = true;
  }

  public boolean isEnabled() {
    return enabled.getAsBoolean();
  }

  public boolean startsConversation(String menuOption) {
    return menuOption != null
        && menuOption.regionMatches(
            true, 0, DIALOGUE_OPTION_PREFIX, 0, DIALOGUE_OPTION_PREFIX.length());
  }

  public void considerLearning(int npcId, String npcName) {
    if (closed || !enabled.getAsBoolean() || npcName == null || npcName.isEmpty()) {
      return;
    }
    long now = System.currentTimeMillis();
    if (now < quietUntilMillis) {
      return;
    }
    if (voiced.test(npcId) || !store.isPastMissWindow(npcId, now) || !attempted.add(npcId)) {
      return;
    }
    executor.execute(
        () -> {
          if (closed) {
            attempted.remove(npcId);
            return;
          }
          throttle.awaitTurn();
          if (closed) {
            attempted.remove(npcId);
            return;
          }
          WikiLookup lookup = client.lookup(npcId, npcName);
          if (closed) {
            attempted.remove(npcId);
            return;
          }
          if (lookup.isUnreachable()) {
            attempted.remove(npcId);
            if (consecutiveFailures.incrementAndGet() >= FAILURES_BEFORE_QUIET) {
              quietUntilMillis = System.currentTimeMillis() + QUIET_MILLIS;
            }
            log.debug("[TTS learn] wiki was unreachable for '{}' (id {})", npcName, npcId);
            return;
          }
          consecutiveFailures.set(0);
          if (lookup.isUndocumented()) {
            store.missed(npcId, System.currentTimeMillis());
            log.debug("[TTS learn] wiki had no usable entry for '{}' (id {})", npcName, npcId);
            return;
          }
          NpcAttributes attributes = lookup.attributes();
          store.learn(
              npcId, attributes.getRace(), attributes.getGender(), attributes.getEthnicity());
          log.info(
              "[TTS learn] learned '{}' (id {}) from wiki -> race={} gender={} ethnicity={}",
              npcName,
              npcId,
              attributes.getRace(),
              attributes.getGender(),
              attributes.getEthnicity() == null ? "-" : attributes.getEthnicity());
        });
  }
}

