public final class WikiLookup {

  private static final WikiLookup UNDOCUMENTED = new WikiLookup(null, true);
  private static final WikiLookup UNREACHABLE = new WikiLookup(null, false);

  private final NpcAttributes attributes;
  private final boolean answered;

  private WikiLookup(NpcAttributes attributes, boolean answered) {
    this.attributes = attributes;
    this.answered = answered;
  }

  static WikiLookup of(NpcAttributes attributes) {
    return new WikiLookup(attributes, true);
  }

  static WikiLookup undocumented() {
    return UNDOCUMENTED;
  }

  static WikiLookup unreachable() {
    return UNREACHABLE;
  }

  public NpcAttributes attributes() {
    return attributes;
  }

  public boolean isUndocumented() {
    return answered && attributes == null;
  }

  public boolean isUnreachable() {
    return !answered;
  }
}

package com.grahambartley.runelite.voiced.dialogue.speaker.wiki;

import java.util.concurrent.CompletableFuture;
import java.util.concurrent.TimeUnit;

public final class WikiCallThrottle {

  private final long intervalNanos;

  private boolean started;

  private long lastCallAt;

  public WikiCallThrottle(long intervalMillis) {
    this.intervalNanos = TimeUnit.MILLISECONDS.toNanos(intervalMillis);
  }

  public void awaitTurn() {
    long waitNanos;
    synchronized (this) {
      long now = System.nanoTime();
      long turnAt = started ? lastCallAt + intervalNanos : now;
      if (turnAt < now) {
        turnAt = now;
      }
      waitNanos = turnAt - now;
      lastCallAt = turnAt;
      started = true;
    }
    if (waitNanos <= 0) {
      return;
    }
    CompletableFuture.runAsync(
            () -> {}, CompletableFuture.delayedExecutor(waitNanos, TimeUnit.NANOSECONDS))
        .join();
  }
}

package com.grahambartley.runelite.voiced.dialogue.speaker.wiki;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.function.UnaryOperator;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

final class WikiInfobox {

  private static final Pattern RACE = versionedField("race");
  private static final Pattern GENDER = versionedField("gender");
  private static final Pattern ID = versionedField("id");
  private static final Pattern LEAGUE_REGION = field("leagueRegion");
  private static final Pattern LOCATION = field("location");
  private static final Pattern ID_SEPARATOR = Pattern.compile("[,\\s]+");
  private static final Pattern LINK = Pattern.compile("\\[\\[([^\\[\\]]*)\\]\\]");
  private static final Pattern REF_TAG =
      Pattern.compile("<ref[^>]*>.*?</ref>", Pattern.DOTALL | Pattern.CASE_INSENSITIVE);
  private static final Pattern HTML_TAG = Pattern.compile("<[^>]+>");
  private static final Pattern TEMPLATE = Pattern.compile("\\{\\{[^}]*\\}\\}");
  private static final UnaryOperator<String> LINK_TARGET = body -> body.split("\\|", -1)[0];
  private static final UnaryOperator<String> LINK_DISPLAY =
      body -> {
        String[] parts = body.split("\\|", -1);
        return parts[parts.length - 1];
      };

  private static Pattern versionedField(String key) {
    return field(key + "\\d*");
  }

  private static Pattern field(String key) {
    return Pattern.compile("\\|\\s*" + key + "\\s*=\\s*([^\\n]+)", Pattern.CASE_INSENSITIVE);
  }

  private final List<String> raceReadings;
  private final String leagueRegion;
  private final String location;
  private final List<String> genders;
  private final List<List<Integer>> idGroups;
  private final List<String> categories;

  private WikiInfobox(
      List<String> raceReadings,
      String leagueRegion,
      String location,
      List<String> genders,
      List<List<Integer>> idGroups,
      List<String> categories) {
    this.raceReadings = raceReadings;
    this.leagueRegion = leagueRegion;
    this.location = location;
    this.genders = genders;
    this.idGroups = idGroups;
    this.categories = categories;
  }

  static WikiInfobox parse(String wikitext, List<String> categories) {
    return new WikiInfobox(
        linkReadings(rawField(RACE, wikitext)),
        firstField(LEAGUE_REGION, wikitext),
        firstField(LOCATION, wikitext),
        cleanFields(GENDER, wikitext),
        idGroups(wikitext),
        categories == null ? Collections.<String>emptyList() : categories);
  }

  List<String> raceReadings() {
    return raceReadings;
  }

  String leagueRegion() {
    return leagueRegion;
  }

  String location() {
    return location;
  }

  List<String> categories() {
    return categories;
  }

  String genderForVersion(int npcId) {
    if (genders.isEmpty()) {
      return null;
    }
    if (genders.size() != idGroups.size()) {
      return genders.get(0);
    }
    for (int index = 0; index < idGroups.size(); index++) {
      if (idGroups.get(index).contains(npcId)) {
        return genders.get(index);
      }
    }
    return genders.get(0);
  }

  private static List<List<Integer>> idGroups(String wikitext) {
    List<List<Integer>> groups = new ArrayList<>();
    for (String raw : fieldTexts(ID, wikitext)) {
      List<Integer> ids = new ArrayList<>();
      for (String token : ID_SEPARATOR.split(clean(raw, LINK_TARGET))) {
        if (!token.isEmpty() && token.chars().allMatch(Character::isDigit)) {
          ids.add(Integer.valueOf(token));
        }
      }
      if (!ids.isEmpty()) {
        groups.add(ids);
      }
    }
    return groups;
  }

  private static List<String> cleanFields(Pattern pattern, String wikitext) {
    List<String> values = new ArrayList<>();
    for (String raw : fieldTexts(pattern, wikitext)) {
      values.add(clean(raw, LINK_TARGET));
    }
    return values;
  }

  private static String firstField(Pattern pattern, String wikitext) {
    String raw = rawField(pattern, wikitext);
    return raw == null ? null : clean(raw, LINK_TARGET);
  }

  private static String rawField(Pattern pattern, String wikitext) {
    List<String> texts = fieldTexts(pattern, wikitext);
    return texts.isEmpty() ? null : texts.get(0);
  }

  private static List<String> fieldTexts(Pattern pattern, String wikitext) {
    List<String> values = new ArrayList<>();
    Matcher matcher = pattern.matcher(wikitext);
    int from = 0;
    while (from <= wikitext.length() && matcher.find(from)) {
      String text = fieldText(matcher.group(1));
      values.add(text);
      from = matcher.start(1) + text.length();
    }
    return values;
  }

  private static String fieldText(String value) {
    int depth = 0;
    int index = 0;
    while (index < value.length()) {
      String token = value.length() - index >= 2 ? value.substring(index, index + 2) : "";
      if ("[[".equals(token) || "{{".equals(token)) {
        depth++;
        index += 2;
      } else if ("]]".equals(token) || "}}".equals(token)) {
        if (depth == 0) {
          return value.substring(0, index);
        }
        depth--;
        index += 2;
      } else if (value.charAt(index) == '|' && depth == 0) {
        return value.substring(0, index);
      } else {
        index++;
      }
    }
    return value;
  }

  private static List<String> linkReadings(String value) {
    List<String> readings = new ArrayList<>();
    if (value == null) {
      return readings;
    }
    String target = clean(value, LINK_TARGET);
    String display = clean(value, LINK_DISPLAY);
    if (!target.isEmpty()) {
      readings.add(target);
    }
    if (!display.isEmpty() && !display.equals(target)) {
      readings.add(display);
    }
    return readings;
  }

  private static String clean(String value, UnaryOperator<String> side) {
    String cleaned = REF_TAG.matcher(value).replaceAll("");
    cleaned = HTML_TAG.matcher(cleaned).replaceAll("");
    cleaned = resolveLinks(cleaned, side);
    cleaned = cleaned.replace("[[", "").replace("]]", "");
    cleaned = TEMPLATE.matcher(cleaned).replaceAll("");
    return cleaned.trim();
  }

  private static String resolveLinks(String value, UnaryOperator<String> side) {
    Matcher matcher = LINK.matcher(value);
    StringBuilder out = new StringBuilder();
    while (matcher.find()) {
      matcher.appendReplacement(out, Matcher.quoteReplacement(side.apply(matcher.group(1))));
    }
    matcher.appendTail(out);
    return out.toString();
  }
}

package com.grahambartley.runelite.voiced.dialogue.speaker.wiki;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.regex.Pattern;

final class WikiMapping {

  private static final String RESOURCE = "/wiki-mapping.json";

  private static final WikiMapping INSTANCE = load();

  private final List<RacePattern> raceRules;
  private final List<CategoryRule> categoryRules;
  private final Map<String, String> leagueRegionEthnicity;
  private final Pattern infoboxTemplates;
  private final String defaultRace;
  private final String defaultGender;
  private final String femaleGender;
  private final String desertLeagueRegion;
  private final Pattern menaphiteHint;
  private final String menaphiteEthnicity;
  private final String desertEthnicity;

  private WikiMapping(JsonObject root) {
    raceRules = new ArrayList<>();
    for (JsonElement element : root.getAsJsonArray("raceRules")) {
      JsonObject rule = element.getAsJsonObject();
      raceRules.add(
          new RacePattern(
              Pattern.compile(rule.get("pattern").getAsString(), Pattern.CASE_INSENSITIVE),
              rule.get("race").getAsString()));
    }
    categoryRules = new ArrayList<>();
    for (JsonElement element : root.getAsJsonArray("categoryRaceRules")) {
      JsonObject rule = element.getAsJsonObject();
      categoryRules.add(
          new CategoryRule(
              rule.get("keyword").getAsString().toLowerCase(Locale.ROOT),
              rule.get("race").getAsString()));
    }
    leagueRegionEthnicity = new HashMap<>();
    JsonObject regions = root.getAsJsonObject("leagueRegionEthnicity");
    for (String region : regions.keySet()) {
      leagueRegionEthnicity.put(region.toLowerCase(Locale.ROOT), regions.get(region).getAsString());
    }
    infoboxTemplates = infoboxPattern(root.getAsJsonArray("infoboxTemplates"));
    defaultRace = root.get("defaultRace").getAsString();
    defaultGender = root.get("defaultGender").getAsString();
    femaleGender = root.get("femaleGender").getAsString();
    JsonObject desert = root.getAsJsonObject("desert");
    desertLeagueRegion = desert.get("leagueRegion").getAsString().toLowerCase(Locale.ROOT);
    menaphiteHint = Pattern.compile(desert.get("hint").getAsString(), Pattern.CASE_INSENSITIVE);
    menaphiteEthnicity = desert.get("hinted").getAsString();
    desertEthnicity = desert.get("default").getAsString();
  }

  static WikiMapping get() {
    return INSTANCE;
  }

  String defaultRace() {
    return defaultRace;
  }

  String genderForWikiText(String genderText) {
    if (genderText != null) {
      String normalised = genderText.trim().toLowerCase(Locale.ROOT);
      if (normalised.startsWith("f")) {
        return femaleGender;
      }
    }
    return defaultGender;
  }

  String raceForWikiText(List<String> raceReadings) {
    if (raceReadings.isEmpty()) {
      return null;
    }
    for (String reading : raceReadings) {
      for (RacePattern rule : raceRules) {
        if (rule.pattern.matcher(reading).find()) {
          return rule.race;
        }
      }
    }
    return defaultRace;
  }

  String raceForCategories(List<String> categories) {
    if (categories == null || categories.isEmpty()) {
      return null;
    }
    String joined = String.join(" ", categories).toLowerCase(Locale.ROOT);
    for (CategoryRule rule : categoryRules) {
      if (joined.contains(rule.keyword)) {
        return rule.race;
      }
    }
    return null;
  }

  String ethnicityKey(String leagueRegion, String location, List<String> categories) {
    if (leagueRegion == null) {
      return null;
    }
    String region = leagueRegion.trim();
    if (region.contains(",") || region.contains("&")) {
      return null;
    }
    String key = region.toLowerCase(Locale.ROOT);
    if (key.equals(desertLeagueRegion)) {
      StringBuilder hint = new StringBuilder(location == null ? "" : location);
      if (categories != null) {
        for (String category : categories) {
          hint.append(' ').append(category);
        }
      }
      return menaphiteHint.matcher(hint).find() ? menaphiteEthnicity : desertEthnicity;
    }
    return leagueRegionEthnicity.get(key);
  }

  boolean isNpcPage(String wikitext) {
    return wikitext != null && infoboxTemplates.matcher(wikitext).find();
  }

  private static Pattern infoboxPattern(JsonArray templates) {
    StringBuilder alternatives = new StringBuilder();
    for (JsonElement element : templates) {
      String name = element.getAsString().replaceFirst("^[^:]+:", "");
      alternatives.append(alternatives.length() == 0 ? "" : "|");
      alternatives.append(Pattern.quote(name).replace(" ", "\\E[ _]+\\Q"));
    }
    return Pattern.compile("\\{\\{\\s*(" + alternatives + ")", Pattern.CASE_INSENSITIVE);
  }

  private static WikiMapping load() {
    try (InputStream stream = WikiMapping.class.getResourceAsStream(RESOURCE)) {
      if (stream == null) {
        throw new IllegalStateException("Missing bundled resource " + RESOURCE);
      }
      JsonObject root =
          new JsonParser()
              .parse(new InputStreamReader(stream, StandardCharsets.UTF_8))
              .getAsJsonObject();
      return new WikiMapping(root);
    } catch (Exception e) {
      throw new IllegalStateException("Could not read " + RESOURCE, e);
    }
  }

  private static final class RacePattern {
    private final Pattern pattern;
    private final String race;

    private RacePattern(Pattern pattern, String race) {
      this.pattern = pattern;
      this.race = race;
    }
  }

  private static final class CategoryRule {
    private final String keyword;
    private final String race;

    private CategoryRule(String keyword, String race) {
      this.keyword = keyword;
      this.race = race;
    }
  }
}

