public final class PublicChatSpeaker {

  private final Client client;
  private final DialogueTextCleaner textCleaner;
  private final SynthesisDispatcher dispatcher;

  private final BooleanSupplier enabled;

  public PublicChatSpeaker(
      Client client,
      DialogueTextCleaner textCleaner,
      SynthesisDispatcher dispatcher,
      BooleanSupplier enabled) {
    this.client = client;
    this.textCleaner = textCleaner;
    this.dispatcher = dispatcher;
    this.enabled = enabled;
  }

  public void onChatMessage(ChatMessage event) {
    if (event.getType() != ChatMessageType.PUBLICCHAT || !enabled.getAsBoolean()) {
      return;
    }
    Player local = client.getLocalPlayer();
    if (local == null || !PublicChatPolicy.isSelfPublicChat(event.getName(), local.getName())) {
      return;
    }
    String cleaned = textCleaner.clean(event.getMessage());
    if (cleaned.isEmpty()) {
      return;
    }
    dispatcher.speakPublicChat(cleaned);
  }
}

package com.grahambartley.runelite.voiced.dialogue.capture;

import java.util.regex.Pattern;

public final class AnimalNoises {

  private static final Pattern SEPARATOR = Pattern.compile("[\\s\\p{Punct}&&[^-]]+");

  private static final Pattern NOISE =
      Pattern.compile(
          "ba+|bah+|maa+|meh+|moo+|quack+|cluck+|cock-?a-?doodle-?doo|squeak+|squeal+"
              + "|woof+|bark+|arf+|yap+|howl+|gr+|growl+|snarl+|roar+|meow+|miaow+|mew+"
              + "|purr+|hiss+|ss+|oink+|snort+|neigh+|whinny+|bray+|hee-?haw|tweet+|chirp+|caw+"
              + "|squawk+|screech+|hoot+|ook+|eek+|ook-?ook|ribbit+|croak+|buzz+|chitter+"
              + "|click+|whistle+|bleat+|trumpet+|bellow+|yowl+|whine+|wuff+|rawr+|grunt+",
          Pattern.CASE_INSENSITIVE);

  private AnimalNoises() {}

  public static boolean isNothingButNoise(String line) {
    if (line == null || line.isEmpty()) {
      return false;
    }
    boolean sawWord = false;
    for (String token : SEPARATOR.split(line)) {
      if (token.isEmpty()) {
        continue;
      }
      sawWord = true;
      if (!NOISE.matcher(token).matches()) {
        return false;
      }
    }
    return sawWord;
  }
}

package com.grahambartley.runelite.voiced.dialogue.capture;

public final class AmbientEarshot {

  public static final int EARSHOT_TILES = 16;

  public static final int OUT_OF_EARSHOT = -1;

  static final int FAINTEST = 1;

  private AmbientEarshot() {}

  public static boolean isWithinEarshot(int distanceTiles) {
    return distanceTiles >= 0 && distanceTiles <= EARSHOT_TILES;
  }

  public static int volumeAt(int configuredVolume, int distanceTiles) {
    if (configuredVolume <= FAINTEST) {
      return configuredVolume;
    }
    if (distanceTiles >= EARSHOT_TILES) {
      return FAINTEST;
    }
    int travelled = Math.max(0, distanceTiles);
    int span = configuredVolume - FAINTEST;
    return configuredVolume - (span * travelled) / EARSHOT_TILES;
  }
}

package com.grahambartley.runelite.voiced.dialogue.capture;

import com.grahambartley.runelite.voiced.dialogue.speech.SynthesisDispatcher;
import java.util.EnumSet;
import java.util.Set;
import java.util.function.BooleanSupplier;
import java.util.function.Consumer;
import net.runelite.api.ChatMessageType;
import net.runelite.api.MessageNode;
import net.runelite.api.events.ChatMessage;

public final class ExamineSpeaker {

  private static final Set<ChatMessageType> EXAMINE_TYPES =
      EnumSet.of(
          ChatMessageType.ITEM_EXAMINE,
          ChatMessageType.NPC_EXAMINE,
          ChatMessageType.OBJECT_EXAMINE);

  private final DialogueTextCleaner textCleaner;
  private final SynthesisDispatcher dispatcher;

  private final BooleanSupplier enabled;

  private final BooleanSupplier dialogueOpen;

  private final Consumer<Runnable> defer;

  public ExamineSpeaker(
      DialogueTextCleaner textCleaner,
      SynthesisDispatcher dispatcher,
      BooleanSupplier enabled,
      BooleanSupplier dialogueOpen,
      Consumer<Runnable> defer) {
    this.textCleaner = textCleaner;
    this.dispatcher = dispatcher;
    this.enabled = enabled;
    this.dialogueOpen = dialogueOpen;
    this.defer = defer;
  }

  public void onChatMessage(ChatMessage event) {
    if (!EXAMINE_TYPES.contains(event.getType()) || !enabled.getAsBoolean()) {
      return;
    }
    String message = event.getMessage();
    if (message == null) {
      return;
    }
    MessageNode node = event.getMessageNode();
    defer.accept(() -> speakIfGameAuthored(node, message));
  }

  private void speakIfGameAuthored(MessageNode node, String message) {
    if (node != null && node.getRuneLiteFormatMessage() != null) {
      return;
    }
    if (dialogueOpen.getAsBoolean()) {
      return;
    }
    String cleaned = textCleaner.clean(message);
    if (cleaned.isEmpty()) {
      return;
    }
    dispatcher.speakNarration(cleaned);
  }
}

package com.grahambartley.runelite.voiced.dialogue.capture;

import com.grahambartley.runelite.voiced.dialogue.VoicedDialogueConfig;
import com.grahambartley.runelite.voiced.dialogue.profile.Emotion;
import com.grahambartley.runelite.voiced.dialogue.profile.ResolvedSpeaker;
import com.grahambartley.runelite.voiced.dialogue.profile.Speaker;
import com.grahambartley.runelite.voiced.dialogue.profile.VoiceManager;
import com.grahambartley.runelite.voiced.dialogue.speech.BackendProvider;
import com.grahambartley.runelite.voiced.dialogue.speech.SynthesisRequest;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import net.runelite.api.widgets.Widget;

public final class DialoguePrefetchCoordinator {

  private static final String OPTION_HEADER = "Select an Option";

  private final VoiceManager voiceManager;
  private final DialogueTextCleaner textCleaner;
  private final DialoguePrefetcher prefetcher;
  private final BackendProvider backendProvider;
  private final VoicedDialogueConfig config;

  private List<String> lastRawOptions = Collections.emptyList();

  public DialoguePrefetchCoordinator(
      VoiceManager voiceManager,
      DialogueTextCleaner textCleaner,
      DialoguePrefetcher prefetcher,
      BackendProvider backendProvider,
      VoicedDialogueConfig config) {
    this.voiceManager = voiceManager;
    this.textCleaner = textCleaner;
    this.prefetcher = prefetcher;
    this.backendProvider = backendProvider;
    this.config = config;
  }

  void prefetchOptions(Widget options) {
    if (!config.prefetch() || !backendProvider.active().isAvailable()) {
      return;
    }
    Widget[] children = options.getDynamicChildren();
    if (children == null || children.length == 0) {
      return;
    }
    List<String> raw = new ArrayList<>(children.length);
    for (Widget child : children) {
      raw.add(child == null ? null : child.getText());
    }
    if (raw.equals(lastRawOptions)) {
      return;
    }
    lastRawOptions = raw;

    ResolvedSpeaker resolved = voiceManager.resolve(Speaker.PLAYER, null);
    List<SynthesisRequest> candidates = new ArrayList<>(raw.size());
    for (String text : raw) {
      if (text == null) {
        continue;
      }
      String cleaned = textCleaner.clean(text);
      if (cleaned.isEmpty() || OPTION_HEADER.equalsIgnoreCase(cleaned)) {
        continue;
      }
      candidates.add(
          new SynthesisRequest(
                  cleaned, resolved.voice(), Emotion.NEUTRAL, resolved.profile(), false, true)
              .asPrefetch());
    }
    prefetcher.offer(candidates);
  }

  void reset() {
    lastRawOptions = Collections.emptyList();
    prefetcher.reset();
  }
}

package com.grahambartley.runelite.voiced.dialogue.capture;

import com.grahambartley.runelite.voiced.dialogue.profile.ProfanityFilter;
import java.util.regex.Pattern;

public final class DialogueTextCleaner {

  private static final Pattern MARKUP = Pattern.compile("<[^>]+>");

  private final ProfanityFilter profanityFilter;

  public DialogueTextCleaner(ProfanityFilter profanityFilter) {
    this.profanityFilter = profanityFilter;
  }

  public String clean(String raw) {
    return profanityFilter.mask(MARKUP.matcher(raw).replaceAll("").trim());
  }
}

package com.grahambartley.runelite.voiced.dialogue.capture;

import static com.grahambartley.runelite.voiced.dialogue.capture.DialogueWidgetReader.isVisible;

import com.grahambartley.runelite.voiced.dialogue.speech.SynthesisDispatcher;
import java.util.Arrays;
import java.util.function.BooleanSupplier;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;

public final class NarrationWatcher {

  private static final int[] TEXT_WIDGETS = {
    InterfaceID.Objectbox.TEXT, InterfaceID.ObjectboxDouble.TEXT, InterfaceID.Messagebox.TEXT
  };

  private final Client client;
  private final DialogueTextCleaner textCleaner;
  private final SynthesisDispatcher dispatcher;
  private final BooleanSupplier enabled;

  private final String[] lastSpokenByWidget = new String[TEXT_WIDGETS.length];

  public NarrationWatcher(
      Client client,
      DialogueTextCleaner textCleaner,
      SynthesisDispatcher dispatcher,
      BooleanSupplier enabled) {
    this.client = client;
    this.textCleaner = textCleaner;
    this.dispatcher = dispatcher;
    this.enabled = enabled;
  }

  public boolean isOnScreen() {
    for (int widgetId : TEXT_WIDGETS) {
      if (isVisible(client.getWidget(widgetId))) {
        return true;
      }
    }
    return false;
  }

  public boolean tick() {
    if (!enabled.getAsBoolean()) {
      return false;
    }
    boolean open = false;
    for (int i = 0; i < TEXT_WIDGETS.length; i++) {
      Widget box = client.getWidget(TEXT_WIDGETS[i]);
      if (!isVisible(box)) {
        continue;
      }
      open = true;
      speakIfNew(i, box);
    }
    return open;
  }

  public void reset() {
    Arrays.fill(lastSpokenByWidget, null);
  }

  private void speakIfNew(int index, Widget box) {
    String text = box.getText();
    if (text == null || text.isEmpty() || text.equals(lastSpokenByWidget[index])) {
      return;
    }
    lastSpokenByWidget[index] = text;
    dispatcher.speakNarration(textCleaner.clean(text));
  }
}

package com.grahambartley.runelite.voiced.dialogue.capture;

import com.grahambartley.runelite.voiced.dialogue.VoicedDialogueConfig;
import com.grahambartley.runelite.voiced.dialogue.speech.SynthesisBackend;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.chat.ChatColorType;
import net.runelite.client.chat.ChatMessageBuilder;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.ConfigManager;

@Slf4j
public final class ChatNoticeManager {

  static final String ONBOARDING_SEEN_KEY = "onboardingSeen";

  private static final String CHAT_NOTICE_COLOR = "ff3333";

  private static final String ONBOARDING_MESSAGE =
      "Voiced Dialogue is on. It needs an API key to voice dialogue. Google AI Studio starts lines"
          + " almost instantly but begins at 100 fresh lines a day, prefetched options included,"
          + " and billing does not lift that: set Voice Provider to Google AI Studio and use a key"
          + " from aistudio.google.com with billing enabled. OpenRouter is"
          + " simpler to set up and has no daily cap, at the cost of much slower lines: use a key"
          + " from openrouter.ai instead. Your dialogue text is sent to whichever provider you"
          + " pick. Until a key is set, lines stay silent.";

  private final Client client;
  private final ConfigManager configManager;
  private final ClientThread clientThread;
  private final ChatMessageManager chatMessageManager;

  private boolean onboardingChecked;
  private boolean cloudKeyNoticeChecked;

  public ChatNoticeManager(
      Client client,
      ConfigManager configManager,
      ClientThread clientThread,
      ChatMessageManager chatMessageManager) {
    this.client = client;
    this.configManager = configManager;
    this.clientThread = clientThread;
    this.chatMessageManager = chatMessageManager;
  }

  public void notifyFromBackendThread(String message) {
    log.warn(message);
    clientThread.invokeLater(() -> addGameMessage(message));
  }

  public void maybeShowOnboarding() {
    if (onboardingChecked) {
      return;
    }
    onboardingChecked = true;
    Boolean seen =
        configManager.getConfiguration(
            VoicedDialogueConfig.GROUP, ONBOARDING_SEEN_KEY, Boolean.class);
    if (!shouldShowOnboarding(seen)) {
      return;
    }
    addGameMessage(ONBOARDING_MESSAGE);
    configManager.setConfiguration(VoicedDialogueConfig.GROUP, ONBOARDING_SEEN_KEY, true);
  }

  static boolean shouldShowOnboarding(Boolean seenFlag) {
    return !Boolean.TRUE.equals(seenFlag);
  }

  public void maybeWarnMissingCloudKey(SynthesisBackend backend) {
    if (cloudKeyNoticeChecked || !shouldWarnMissingCloudKey(backend.isAvailable())) {
      return;
    }
    cloudKeyNoticeChecked = true;
    addGameMessage(backend.missingKeyNotice());
  }

  static boolean shouldWarnMissingCloudKey(boolean keyAvailable) {
    return !keyAvailable;
  }

  public void postCommandResponse(String message) {
    String formatted =
        new ChatMessageBuilder()
            .append(ChatColorType.HIGHLIGHT)
            .append("[Voiced Dialogue] ")
            .append(ChatColorType.NORMAL)
            .append(message)
            .build();
    chatMessageManager.queue(
        QueuedMessage.builder()
            .type(ChatMessageType.GAMEMESSAGE)
            .runeLiteFormattedMessage(formatted)
            .build());
  }

  private void addGameMessage(String message) {
    String line = "<col=" + CHAT_NOTICE_COLOR + ">[Voiced Dialogue] " + message + "</col>";
    client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", line, null);
  }
}

package com.grahambartley.runelite.voiced.dialogue.capture;

import static com.grahambartley.runelite.voiced.dialogue.capture.DialogueWidgetReader.isVisible;

import com.grahambartley.runelite.voiced.dialogue.profile.Speaker;
import com.grahambartley.runelite.voiced.dialogue.speech.DialogueAudioService;
import com.grahambartley.runelite.voiced.dialogue.speech.SynthesisDispatcher;
import java.util.EnumMap;
import java.util.Map;
import java.util.function.Supplier;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;

public final class DialogueWatcher {

  private final Client client;
  private final DialogueTextCleaner textCleaner;
  private final DialogueWidgetReader widgetReader;
  private final SynthesisDispatcher dispatcher;
  private final DialoguePrefetchCoordinator prefetchCoordinator;
  private final DialogueAudioService audioService;
  private final NarrationWatcher narrationWatcher;

  private final Map<Speaker, String> lastSpokenBySpeaker = new EnumMap<>(Speaker.class);

  private boolean dialogueOpen;
  private boolean wasFullyClosed;

  public DialogueWatcher(
      Client client,
      DialogueTextCleaner textCleaner,
      DialogueWidgetReader widgetReader,
      SynthesisDispatcher dispatcher,
      DialoguePrefetchCoordinator prefetchCoordinator,
      DialogueAudioService audioService,
      NarrationWatcher narrationWatcher) {
    this.client = client;
    this.textCleaner = textCleaner;
    this.widgetReader = widgetReader;
    this.dispatcher = dispatcher;
    this.prefetchCoordinator = prefetchCoordinator;
    this.audioService = audioService;
    this.narrationWatcher = narrationWatcher;
  }

  public void tick() {
    Widget npcDialogue = client.getWidget(InterfaceID.ChatLeft.TEXT);
    boolean npcVisible = isVisible(npcDialogue);
    Widget playerDialogue = client.getWidget(InterfaceID.ChatRight.TEXT);
    boolean playerVisible = isVisible(playerDialogue);

    if (npcVisible) {
      speakIfNew(npcDialogue, InterfaceID.ChatLeft.HEAD, Speaker.NPC, widgetReader::currentNpcName);
    }
    if (playerVisible) {
      speakIfNew(playerDialogue, InterfaceID.ChatRight.HEAD, Speaker.PLAYER, () -> null);
    }

    boolean narrationVisible = narrationWatcher.tick();

    Widget options = client.getWidget(InterfaceID.Chatmenu.OPTIONS);
    boolean optionsVisible = isVisible(options);
    if (optionsVisible) {
      prefetchCoordinator.prefetchOptions(options);
    }

    boolean open = npcVisible || playerVisible || narrationVisible;
    if (shouldCutOnClose(open, dialogueOpen)) {
      audioService.cutPlayback();
      lastSpokenBySpeaker.clear();
      narrationWatcher.reset();
    }
    dialogueOpen = open;

    boolean fullyClosed = !open && !optionsVisible;
    if (fullyClosed && !wasFullyClosed) {
      prefetchCoordinator.reset();
    }
    wasFullyClosed = fullyClosed;
  }

  public boolean isDialogueOpen() {
    return dialogueOpen;
  }

  public boolean isConversationOnScreen() {
    return isVisible(client.getWidget(InterfaceID.ChatLeft.TEXT))
        || isVisible(client.getWidget(InterfaceID.ChatRight.TEXT))
        || isVisible(client.getWidget(InterfaceID.Chatmenu.OPTIONS))
        || narrationWatcher.isOnScreen();
  }

  private void speakIfNew(
      Widget dialogue, int headWidgetId, Speaker speaker, Supplier<String> npcName) {
    String text = dialogue.getText();
    if (text == null || text.isEmpty() || text.equals(lastSpokenBySpeaker.get(speaker))) {
      return;
    }
    lastSpokenBySpeaker.put(speaker, text);
    dispatcher.speakDialogue(
        textCleaner.clean(text),
        speaker,
        npcName.get(),
        widgetReader.headAnimationId(headWidgetId));
  }

  static boolean shouldCutOnClose(boolean dialogueOpen, boolean wasDialogueOpen) {
    return wasDialogueOpen && !dialogueOpen;
  }
}

package com.grahambartley.runelite.voiced.dialogue.capture;

import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;

public final class DialogueWidgetReader {

  static final int NO_EXPRESSION = -1;

  private static final String UNKNOWN_NPC = "Unknown NPC";

  private final Client client;

  public DialogueWidgetReader(Client client) {
    this.client = client;
  }

  static boolean isVisible(Widget widget) {
    return widget != null && !widget.isHidden();
  }

  int headAnimationId(int headWidgetId) {
    Widget head = client.getWidget(headWidgetId);
    if (head == null) {
      return NO_EXPRESSION;
    }
    return head.getAnimationId();
  }

  String currentNpcName() {
    Widget npcNameWidget = client.getWidget(InterfaceID.ChatLeft.NAME);
    if (isVisible(npcNameWidget)) {
      String npcName = npcNameWidget.getText();
      if (npcName != null && !npcName.isEmpty()) {
        return npcName.trim();
      }
    }

    Player local = client.getLocalPlayer();
    if (local != null && local.getInteracting() != null) {
      String interactingName = local.getInteracting().getName();
      if (interactingName != null && !interactingName.isEmpty()) {
        return interactingName.trim();
      }
    }

    return UNKNOWN_NPC;
  }
}

