package com.grahambartley.runelite.voiced.dialogue.speech;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.time.Duration;
import java.util.Collections;
import java.util.concurrent.TimeUnit;
import java.util.regex.Pattern;
import lombok.extern.slf4j.Slf4j;
import okhttp3.ConnectionPool;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Protocol;
import okhttp3.Response;
import okhttp3.ResponseBody;

@Slf4j
public final class CloudHttp {

  public static final int HTTP_TOO_MANY_REQUESTS = 429;

  static final byte[] EMPTY_BODY = new byte[0];

  public static final String USER_AGENT = "runelite-voiced-dialogue";

  public static final MediaType JSON_MEDIA_TYPE = MediaType.parse("application/json");

  private static final int MAX_IDLE_CONNECTIONS = 8;

  private static final int BODY_SNIPPET_MAX_BYTES = 2_000;

  private static final Pattern CONTROL_CHARS = Pattern.compile("\\p{Cntrl}+");

  private CloudHttp() {}

  public static OkHttpClient deriveClient(
      OkHttpClient base, RetryTuning tuning, Duration keepAlive, boolean pinHttp1) {
    OkHttpClient.Builder builder = base.newBuilder();
    if (pinHttp1) {
      builder.protocols(Collections.singletonList(Protocol.HTTP_1_1));
    }
    return builder
        .connectionPool(
            new ConnectionPool(MAX_IDLE_CONNECTIONS, keepAlive.toMinutes(), TimeUnit.MINUTES))
        .connectTimeout(tuning.connectTimeout)
        .readTimeout(tuning.readTimeout)
        .callTimeout(tuning.callTimeout)
        .retryOnConnectionFailure(true)
        .build();
  }

  static long elapsedMs(long startNanos) {
    return (System.nanoTime() - startNanos) / 1_000_000L;
  }

  public static String headerOrEmpty(Response response, String name) {
    String value = response.header(name);
    return value == null ? "" : value;
  }

  static byte[] errorBody(Response response) {
    try {
      ResponseBody body = response.body();
      return body == null ? EMPTY_BODY : body.bytes();
    } catch (IOException e) {
      return EMPTY_BODY;
    }
  }

  static long retryAfterMillis(Response response) {
    String value = response.header("Retry-After");
    if (!isNonBlank(value)) {
      return 0;
    }
    try {
      long seconds = Long.parseLong(value.trim());
      return seconds <= 0 ? 0 : Math.multiplyExact(seconds, 1_000L);
    } catch (RuntimeException e) {
      log.debug("[TTS cloud] Retry-After '{}' is not a usable wait", value);
      return 0;
    }
  }

  public static boolean isNonBlank(String value) {
    return value != null && !value.trim().isEmpty();
  }

  static String bodySnippet(byte[] bytes) {
    int n = Math.min(bytes.length, BODY_SNIPPET_MAX_BYTES);
    String text =
        CONTROL_CHARS
            .matcher(new String(bytes, 0, n, StandardCharsets.UTF_8))
            .replaceAll(" ")
            .trim();
    return bytes.length > n ? text + "..." : text;
  }
}

package com.grahambartley.runelite.voiced.dialogue.speech.aistudio;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import lombok.extern.slf4j.Slf4j;

@Slf4j
final class AiStudioErrorDetails {

  private AiStudioErrorDetails() {}

  static List<JsonObject> ofType(Gson gson, byte[] body, String type) {
    if (body == null || body.length == 0) {
      return Collections.emptyList();
    }
    try {
      JsonObject document =
          gson.fromJson(new String(body, StandardCharsets.UTF_8), JsonObject.class);
      JsonObject error = document == null ? null : document.getAsJsonObject("error");
      JsonArray details = error == null ? null : error.getAsJsonArray("details");
      if (details == null) {
        return Collections.emptyList();
      }
      List<JsonObject> matches = new ArrayList<>();
      for (JsonElement element : details) {
        if (!element.isJsonObject()) {
          continue;
        }
        JsonObject detail = element.getAsJsonObject();
        if (type.equals(text(detail, "@type"))) {
          matches.add(detail);
        }
      }
      return matches;
    } catch (RuntimeException e) {
      log.debug("[TTS cloud] AI Studio quota failure parse error: {}", e.getMessage());
      return Collections.emptyList();
    }
  }

  static JsonArray array(JsonObject object, String field) {
    if (object == null) {
      return null;
    }
    JsonElement value = object.get(field);
    return value != null && value.isJsonArray() ? value.getAsJsonArray() : null;
  }

  static String text(JsonObject object, String field) {
    if (object == null || !object.has(field) || object.get(field).isJsonNull()) {
      return "";
    }
    try {
      return object.get(field).getAsString();
    } catch (RuntimeException e) {
      return "";
    }
  }
}

package com.grahambartley.runelite.voiced.dialogue.speech.aistudio;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.grahambartley.runelite.voiced.dialogue.VoicedDialogueConfig;
import com.grahambartley.runelite.voiced.dialogue.speech.CloudHttp;
import com.grahambartley.runelite.voiced.dialogue.speech.CloudTranslatorCall;
import com.grahambartley.runelite.voiced.dialogue.speech.CloudTtsText;
import com.grahambartley.runelite.voiced.dialogue.speech.model.GeminiTranslationModel;
import java.nio.charset.StandardCharsets;
import lombok.extern.slf4j.Slf4j;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;

@Slf4j
final class AiStudioTranslator implements CloudTranslatorCall.Ops {

  static final String MODEL = GeminiTranslationModel.GEMINI_MODEL_ID;

  static final String PRODUCTION_ENDPOINT =
      "https://generativelanguage.googleapis.com/v1beta/models/" + MODEL + ":generateContent";

  private final OkHttpClient httpClient;
  private final VoicedDialogueConfig config;
  private final Gson gson;
  private final String endpoint;

  AiStudioTranslator(
      OkHttpClient httpClient, VoicedDialogueConfig config, Gson gson, String endpoint) {
    this.httpClient = httpClient;
    this.config = config;
    this.gson = gson;
    this.endpoint = endpoint;
  }

  static final class Translation {
    final String text;
    final AiStudioTokenUsage usage;

    Translation(String text, AiStudioTokenUsage usage) {
      this.text = text;
      this.usage = usage;
    }
  }

  Translation translate(String text, String language, String apiKey) {
    if (text == null || text.isEmpty()) {
      return text == null ? null : new Translation(text, AiStudioTokenUsage.NONE);
    }
    CloudTranslatorCall.Outcome outcome =
        CloudTranslatorCall.run(httpClient, config, this, text, language, apiKey);
    if (outcome == null) {
      return null;
    }
    return new Translation(outcome.text, AiStudioTokenUsage.forText(gson, outcome.raw));
  }

  @Override
  public Request buildRequest(String text, String language, String apiKey) {
    JsonObject systemInstruction = new JsonObject();
    systemInstruction.add("parts", parts(CloudTtsText.translatorSystemPrompt(language)));
    JsonObject content = new JsonObject();
    content.add("parts", parts(text));
    JsonArray contents = new JsonArray();
    contents.add(content);
    JsonObject payload = new JsonObject();
    payload.add("systemInstruction", systemInstruction);
    payload.add("contents", contents);

    return new Request.Builder()
        .url(endpoint)
        .addHeader("x-goog-api-key", apiKey)
        .addHeader("User-Agent", CloudHttp.USER_AGENT)
        .post(
            RequestBody.create(
                CloudHttp.JSON_MEDIA_TYPE, gson.toJson(payload).getBytes(StandardCharsets.UTF_8)))
        .build();
  }

  private static JsonArray parts(String text) {
    JsonObject part = new JsonObject();
    part.addProperty("text", text);
    JsonArray parts = new JsonArray();
    parts.add(part);
    return parts;
  }

  @Override
  public String extractText(String raw) {
    if (raw == null || raw.isEmpty()) {
      return null;
    }
    try {
      JsonObject parsed = gson.fromJson(raw, JsonObject.class);
      JsonArray candidates = parsed == null ? null : parsed.getAsJsonArray("candidates");
      if (candidates == null || candidates.size() == 0) {
        return null;
      }
      JsonObject content = candidates.get(0).getAsJsonObject().getAsJsonObject("content");
      JsonArray parts = content == null ? null : content.getAsJsonArray("parts");
      if (parts == null) {
        return null;
      }
      StringBuilder translated = new StringBuilder();
      for (JsonElement element : parts) {
        JsonObject part = element.getAsJsonObject();
        if (part.has("text")) {
          translated.append(part.get("text").getAsString());
        }
      }
      String result = translated.toString().trim();
      return result.isEmpty() ? null : result;
    } catch (RuntimeException e) {
      log.debug("[TTS cloud] translation response parse error: {}", e.getMessage());
      return null;
    }
  }
}

package com.grahambartley.runelite.voiced.dialogue.speech.aistudio;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.util.Locale;
import java.util.regex.Pattern;
import lombok.extern.slf4j.Slf4j;

@Slf4j
final class AiStudioQuotaFailure {

  static final String QUOTA_NOTICE =
      "Your Google AI Studio quota was hit, so dialogue cannot be voiced right now. Check your"
          + " quota at aistudio.google.com, or switch Voice Provider to OpenRouter.";

  private static final String QUOTA_FAILURE_TYPE = "type.googleapis.com/google.rpc.QuotaFailure";

  private static final Pattern SEPARATORS = Pattern.compile("[^A-Za-z0-9]+");

  private static final String FREE_TIER_MARKER = "freetier";

  private static final String PER_DAY_MARKER = "perday";

  private static final String PER_MINUTE_MARKER = "perminute";

  private static final String TOKEN_MARKER = "token";

  private static final Pattern MARKUP = Pattern.compile("[<>]");

  final String quotaId;

  final String quotaMetric;

  final String quotaValue;

  final String model;

  private final String normalised;

  private AiStudioQuotaFailure(
      String quotaId, String quotaMetric, String quotaValue, String model) {
    this.quotaId = quotaId;
    this.quotaMetric = quotaMetric;
    this.quotaValue = quotaValue;
    this.model = model;
    this.normalised =
        SEPARATORS.matcher(quotaId + quotaMetric).replaceAll("").toLowerCase(Locale.ROOT);
  }

  static String noticeFor(Gson gson, byte[] body) {
    AiStudioQuotaFailure quota = parse(gson, body);
    if (quota == null) {
      return QUOTA_NOTICE;
    }
    log.debug("[TTS cloud] AI Studio quota exhausted: {}", quota);
    return quota.notice();
  }

  static AiStudioQuotaFailure parse(Gson gson, byte[] body) {
    for (JsonObject detail : AiStudioErrorDetails.ofType(gson, body, QUOTA_FAILURE_TYPE)) {
      JsonArray violations = AiStudioErrorDetails.array(detail, "violations");
      if (violations == null) {
        continue;
      }
      for (JsonElement violation : violations) {
        if (violation.isJsonObject()) {
          return of(violation.getAsJsonObject());
        }
      }
    }
    return null;
  }

  boolean isFreeTier() {
    return normalised.contains(FREE_TIER_MARKER);
  }

  boolean metersTokens() {
    return normalised.contains(TOKEN_MARKER);
  }

  Period period() {
    if (normalised.contains(PER_DAY_MARKER)) {
      return Period.DAILY;
    }
    if (normalised.contains(PER_MINUTE_MARKER)) {
      return Period.PER_MINUTE;
    }
    return Period.UNKNOWN;
  }

  @Override
  public String toString() {
    return "quotaId="
        + quotaId
        + " quotaMetric="
        + quotaMetric
        + " quotaValue="
        + quotaValue
        + " model="
        + model;
  }

  enum Period {
    DAILY("daily"),
    PER_MINUTE("per-minute"),

    UNKNOWN("");

    final String label;

    Period(String label) {
      this.label = label;
    }
  }

  private String notice() {
    Period period = period();
    if (period == Period.PER_MINUTE) {
      return cap(period).append(". Lines resume once the limit resets.").toString();
    }
    if (isFreeTier()) {
      return cap(period)
          .append(". Enable billing at aistudio.google.com to lift it, or switch Voice Provider")
          .append(" to OpenRouter.")
          .toString();
    }
    if (period == Period.DAILY) {
      return cap(period)
          .append(". Enabling billing does not lift this cap, so wait for it to reset, or switch")
          .append(" Voice Provider to OpenRouter.")
          .toString();
    }
    return cap(period)
        .append(". Check your quota at aistudio.google.com, or switch Voice Provider to")
        .append(" OpenRouter.")
        .toString();
  }

  private StringBuilder cap(Period period) {
    StringBuilder notice = new StringBuilder("Google AI Studio ");
    notice.append(period == Period.PER_MINUTE ? "paused dialogue: " : "stopped voicing dialogue: ");
    notice.append(model.isEmpty() ? "the speech model" : model);
    notice.append(" has reached its ");
    if (!period.label.isEmpty()) {
      notice.append(period.label).append(' ');
    }
    notice.append(metersTokens() ? "token cap" : "request cap");
    if (!quotaValue.isEmpty()) {
      notice.append(" of ").append(quotaValue);
    }
    return notice;
  }

  private static AiStudioQuotaFailure of(JsonObject violation) {
    JsonObject dimensions = violation.getAsJsonObject("quotaDimensions");
    return new AiStudioQuotaFailure(
        AiStudioErrorDetails.text(violation, "quotaId"),
        AiStudioErrorDetails.text(violation, "quotaMetric"),
        MARKUP.matcher(AiStudioErrorDetails.text(violation, "quotaValue")).replaceAll(""),
        MARKUP.matcher(AiStudioErrorDetails.text(dimensions, "model")).replaceAll(""));
  }
}

package com.grahambartley.runelite.voiced.dialogue.speech.aistudio;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import lombok.extern.slf4j.Slf4j;

@Slf4j
final class AiStudioRetryInfo {

  private static final String RETRY_INFO_TYPE = "type.googleapis.com/google.rpc.RetryInfo";

  private static final Pattern DURATION = Pattern.compile("^(\\d+)(?:\\.(\\d{1,9}))?s$");

  private static final long MILLIS_PER_SECOND = 1_000;

  private AiStudioRetryInfo() {}

  static long retryDelayMillis(Gson gson, byte[] body) {
    for (JsonObject detail : AiStudioErrorDetails.ofType(gson, body, RETRY_INFO_TYPE)) {
      long millis = durationMillis(AiStudioErrorDetails.text(detail, "retryDelay"));
      if (millis > 0) {
        return millis;
      }
    }
    return 0;
  }

  static long durationMillis(String duration) {
    if (duration == null) {
      return 0;
    }
    Matcher matched = DURATION.matcher(duration.trim());
    if (!matched.matches()) {
      return 0;
    }
    try {
      long seconds = Long.parseLong(matched.group(1));
      String fraction = matched.group(2);
      long millis = Math.multiplyExact(seconds, MILLIS_PER_SECOND);
      if (fraction != null) {
        millis += Long.parseLong((fraction + "00").substring(0, 3));
      }
      return millis;
    } catch (RuntimeException e) {
      log.debug("[TTS cloud] AI Studio retry delay '{}' is not a usable duration", duration);
      return 0;
    }
  }
}

package com.grahambartley.runelite.voiced.dialogue.speech.aistudio;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.grahambartley.runelite.voiced.dialogue.VoicedDialogueConfig;
import com.grahambartley.runelite.voiced.dialogue.audio.Pcm;
import com.grahambartley.runelite.voiced.dialogue.audio.PcmSink;
import com.grahambartley.runelite.voiced.dialogue.profile.Emotion;
import com.grahambartley.runelite.voiced.dialogue.speech.CloudBackendSupport;
import com.grahambartley.runelite.voiced.dialogue.speech.CloudHttp;
import com.grahambartley.runelite.voiced.dialogue.speech.CloudSpeechExecutor;
import com.grahambartley.runelite.voiced.dialogue.speech.RetryTuning;
import com.grahambartley.runelite.voiced.dialogue.speech.SynthesisBackend;
import com.grahambartley.runelite.voiced.dialogue.speech.SynthesisRequest;
import com.grahambartley.runelite.voiced.dialogue.speech.model.GeminiTtsModel;
import com.grahambartley.runelite.voiced.dialogue.speech.spend.SpendTracker;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.time.Duration;
import java.util.ArrayList;
import java.util.Base64;
import java.util.EnumSet;
import java.util.List;
import java.util.function.Consumer;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;
import okhttp3.ResponseBody;
import okio.BufferedSource;

@Slf4j
public final class AiStudioTtsBackend implements SynthesisBackend {

  public static final String ID = "cloud-google-ai-studio";

  static final String MODEL = GeminiTtsModel.GEMINI_MODEL_ID;

  static final String PRODUCTION_ENDPOINT =
      "https://generativelanguage.googleapis.com/v1beta/models/" + MODEL + ":generateContent";

  public static final String NO_KEY_NOTICE =
      "Add your Google AI Studio API key in the Voiced Dialogue settings to hear dialogue; without"
          + " a key, lines are not voiced. Google AI Studio begins at 100 fresh lines a day while"
          + " its speech model is in preview, prefetched options included; OpenRouter has no daily"
          + " cap.";

  private static final Duration KEEP_ALIVE = Duration.ofMinutes(5);

  private final OkHttpClient httpClient;
  private final VoicedDialogueConfig config;
  private final Gson gson;
  private final String endpoint;
  private final String streamingEndpoint;
  private final GeminiTtsModel model = new GeminiTtsModel();
  private final AiStudioTranslator translator;

  private final CloudBackendSupport support;

  private final CloudSpeechExecutor executor;

  public AiStudioTtsBackend(OkHttpClient httpClient, VoicedDialogueConfig config, Gson gson) {
    this(
        httpClient,
        config,
        gson,
        PRODUCTION_ENDPOINT,
        AiStudioTranslator.PRODUCTION_ENDPOINT,
        RetryTuning.googleAiStudio());
  }

  AiStudioTtsBackend(
      OkHttpClient httpClient,
      VoicedDialogueConfig config,
      Gson gson,
      String endpoint,
      String translatorEndpoint,
      RetryTuning tuning) {
    this.httpClient = CloudHttp.deriveClient(httpClient, tuning, KEEP_ALIVE, false);
    this.support =
        new CloudBackendSupport(
            config,
            VoicedDialogueConfig.TtsProvider.GOOGLE_AI_STUDIO,
            CloudSpeechExecutor.MAX_SPEECH_ATTEMPTS,
            tuning);
    this.config = config;
    this.gson = gson;
    this.endpoint = endpoint;
    this.streamingEndpoint = streamingEndpoint(endpoint);
    this.translator = new AiStudioTranslator(this.httpClient, config, gson, translatorEndpoint);
    this.executor =
        new CloudSpeechExecutor(config, support, model, "Google AI Studio", MODEL, new Ops());
  }

  public void setNotice(Consumer<String> notice) {
    support.setNotice(notice);
  }

  public void setSpendTracker(SpendTracker spend) {
    support.setSpendTracker(spend);
  }

  @Override
  public String id() {
    return ID;
  }

  @Override
  public boolean isAvailable() {
    return CloudHttp.isNonBlank(config.googleAiStudioApiKey());
  }

  @Override
  public String missingKeyNotice() {
    return NO_KEY_NOTICE;
  }

  @Override
  public EnumSet<Emotion> supportedEmotions() {
    return model.supportedEmotions();
  }

  @Override
  public boolean isThrottled() {
    return executor.isThrottled();
  }

  @Override
  public void clearRateLimit() {
    executor.clearRateLimit();
  }

  @Override
  public void warmUp() {
    if (!isAvailable()) {
      return;
    }
    Request request =
        new Request.Builder()
            .url(modelEndpoint(endpoint))
            .addHeader("x-goog-api-key", config.googleAiStudioApiKey().trim())
            .addHeader("User-Agent", CloudHttp.USER_AGENT)
            .get()
            .build();
    try (Response response = httpClient.newCall(request).execute()) {
      log.debug("[TTS cloud] AI Studio warm-up HTTP {}", response.code());
    } catch (IOException | RuntimeException e) {
      log.debug("[TTS cloud] AI Studio warm-up failed: {}", e.getMessage());
    }
  }

  @Override
  public String cacheVariant(SynthesisRequest request) {
    return executor.cacheVariant(request);
  }

  @Override
  public Pcm synthesize(SynthesisRequest request) {
    return executor.synthesize(request);
  }

  @Override
  public Pcm synthesizeStreaming(SynthesisRequest request, PcmSink sink) {
    return executor.synthesizeStreaming(request, sink);
  }

  static String failureNotice(Gson gson, int httpCode, byte[] body) {
    if (httpCode == CloudHttp.HTTP_TOO_MANY_REQUESTS) {
      return AiStudioQuotaFailure.noticeFor(gson, body);
    }
    return "Google AI Studio TTS request failed (HTTP "
        + httpCode
        + "); check your API key. This line was not voiced.";
  }

  private final class Ops implements CloudSpeechExecutor.Ops {

    @Override
    public String apiKey() {
      return config.googleAiStudioApiKey();
    }

    @Override
    public String missingKeyNotice() {
      return NO_KEY_NOTICE;
    }

    @Override
    public String translate(String text, String language, String apiKey) {
      AiStudioTranslator.Translation translation = translator.translate(text, language, apiKey);
      if (translation == null) {
        return null;
      }
      support.recordTranslationSpend(
          text.length(), translation.usage.promptTokens, translation.usage.textTokens);
      return translation.text;
    }

    @Override
    public CloudSpeechExecutor.PreparedSpeech buildRequests(
        CloudSpeechExecutor.SpokenLine line, SynthesisRequest request) {
      String input = line.input;
      if (line.speedPercent != CloudBackendSupport.DEFAULT_SPEED_PERCENT) {
        input = "SPEAKING PACE: " + line.speedPercent + "% of normal.\n\n" + input;
      }
      String languageCode = line.translating ? config.cloudLanguage().code() : null;
      JsonObject payload = buildPayload(input, model.voiceFor(request.voice()), languageCode);
      byte[] body = gson.toJson(payload).getBytes(StandardCharsets.UTF_8);
      return new CloudSpeechExecutor.PreparedSpeech(
          buildHttpRequest(endpoint, line.apiKey, body),
          buildHttpRequest(streamingEndpoint, line.apiKey, body),
          line.speedRatio,
          input.length(),
          request.prefetch());
    }

    @Override
    public Call newCall(Request httpRequest, int inputLength) {
      return httpClient.newCall(httpRequest);
    }

    @Override
    public CloudSpeechExecutor.DecodedSpeech decodeBuffered(
        byte[] bytes, CloudSpeechExecutor.PreparedSpeech prepared) {
      JsonObject document = parseResponse(new String(bytes, StandardCharsets.UTF_8));
      byte[] audio = extractAudio(document);
      if (audio == null || audio.length == 0) {
        return CloudSpeechExecutor.DecodedSpeech.EMPTY;
      }
      AiStudioTokenUsage usage = AiStudioTokenUsage.forSpeech(document);
      return new CloudSpeechExecutor.DecodedSpeech(
          model.decodeResponse(audio),
          audio.length,
          () ->
              support.recordSpeechSpend(
                  prepared.inputLen, prepared.prefetch, usage.audioTokens, usage.promptTokens));
    }

    @Override
    public CloudSpeechExecutor.StreamDrain newStreamDrain() {
      return new SseStreamDrain();
    }

    @Override
    public String failureNotice(int httpCode, byte[] body) {
      return AiStudioTtsBackend.failureNotice(gson, httpCode, body);
    }

    @Override
    public long statedWaitMillis(byte[] body) {
      return AiStudioRetryInfo.retryDelayMillis(gson, body);
    }

    @Override
    public String emptyBodyNotice() {
      return "Google AI Studio TTS returned no audio; this line was not voiced.";
    }
  }

  private final class SseStreamDrain implements CloudSpeechExecutor.StreamDrain {

    private String finishReason;
    private AiStudioTokenUsage usage = AiStudioTokenUsage.NONE;

    @Override
    public void drain(ResponseBody body, CloudSpeechExecutor.ChunkSink chunk) throws IOException {
      BufferedSource source = body.source();
      String data;
      while ((data = readSseData(source)) != null) {
        if (data.isEmpty()) {
          continue;
        }
        JsonObject event = parseResponse(data);
        String eventFinishReason = extractFinishReason(event);
        if (eventFinishReason != null) {
          finishReason = eventFinishReason;
        }
        usage = usage.max(AiStudioTokenUsage.forSpeech(event));
        for (byte[] audio : extractAudioChunks(event)) {
          chunk.accept(audio, audio.length);
        }
      }
    }

    @Override
    public boolean finishedCleanly() {
      return "STOP".equals(finishReason);
    }

    @Override
    public void bankSpend(CloudSpeechExecutor.PreparedSpeech prepared) {
      support.recordSpeechSpend(
          prepared.inputLen, prepared.prefetch, usage.audioTokens, usage.promptTokens);
    }
  }

  private static JsonObject buildPayload(String input, String voice, String languageCode) {
    JsonObject textPart = new JsonObject();
    textPart.addProperty("text", input);
    JsonArray parts = new JsonArray();
    parts.add(textPart);
    JsonObject content = new JsonObject();
    content.add("parts", parts);
    JsonArray contents = new JsonArray();
    contents.add(content);

    JsonObject prebuiltVoice = new JsonObject();
    prebuiltVoice.addProperty("voiceName", voice);
    JsonObject voiceConfig = new JsonObject();
    voiceConfig.add("prebuiltVoiceConfig", prebuiltVoice);
    JsonObject speechConfig = new JsonObject();
    speechConfig.add("voiceConfig", voiceConfig);
    if (languageCode != null) {
      speechConfig.addProperty("languageCode", languageCode);
    }
    JsonArray modalities = new JsonArray();
    modalities.add("AUDIO");
    JsonObject generationConfig = new JsonObject();
    generationConfig.add("responseModalities", modalities);
    generationConfig.add("speechConfig", speechConfig);

    JsonObject payload = new JsonObject();
    payload.add("contents", contents);
    payload.add("generationConfig", generationConfig);
    return payload;
  }

  private static Request buildHttpRequest(String target, String apiKey, byte[] body) {
    return new Request.Builder()
        .url(target)
        .addHeader("x-goog-api-key", apiKey)
        .addHeader("User-Agent", CloudHttp.USER_AGENT)
        .post(RequestBody.create(CloudHttp.JSON_MEDIA_TYPE, body))
        .build();
  }

  private JsonObject parseResponse(String raw) {
    try {
      return gson.fromJson(raw, JsonObject.class);
    } catch (RuntimeException e) {
      log.debug("[TTS cloud] AI Studio response parse error: {}", e.getMessage());
      return null;
    }
  }

  private byte[] extractAudio(JsonObject response) {
    List<byte[]> chunks = extractAudioChunks(response);
    if (chunks.isEmpty()) {
      return null;
    }
    ByteArrayOutputStream audio = new ByteArrayOutputStream();
    for (byte[] chunk : chunks) {
      audio.write(chunk, 0, chunk.length);
    }
    return audio.toByteArray();
  }

  private List<byte[]> extractAudioChunks(JsonObject response) {
    List<byte[]> chunks = new ArrayList<>();
    try {
      JsonArray candidates = response == null ? null : response.getAsJsonArray("candidates");
      if (candidates == null || candidates.size() == 0) {
        return chunks;
      }
      JsonObject content = candidates.get(0).getAsJsonObject().getAsJsonObject("content");
      JsonArray parts = content == null ? null : content.getAsJsonArray("parts");
      if (parts == null) {
        return chunks;
      }
      for (JsonElement element : parts) {
        JsonObject part = element.getAsJsonObject();
        JsonObject inlineData = part.getAsJsonObject("inlineData");
        if (inlineData == null) {
          inlineData = part.getAsJsonObject("inline_data");
        }
        if (inlineData != null && inlineData.has("data")) {
          chunks.add(Base64.getDecoder().decode(inlineData.get("data").getAsString()));
        }
      }
      return chunks;
    } catch (RuntimeException e) {
      log.debug("[TTS cloud] AI Studio response parse error: {}", e.getMessage());
      return chunks;
    }
  }

  private static String extractFinishReason(JsonObject response) {
    try {
      JsonArray candidates = response == null ? null : response.getAsJsonArray("candidates");
      if (candidates == null || candidates.size() == 0) {
        return null;
      }
      JsonObject candidate = candidates.get(0).getAsJsonObject();
      return candidate.has("finishReason") ? candidate.get("finishReason").getAsString() : null;
    } catch (RuntimeException e) {
      return null;
    }
  }

  private static String readSseData(BufferedSource source) throws IOException {
    StringBuilder data = null;
    String line;
    while ((line = source.readUtf8Line()) != null) {
      if (line.isEmpty()) {
        if (data != null) {
          return data.toString();
        }
        continue;
      }
      if (!line.startsWith("data:")) {
        continue;
      }
      if (data == null) {
        data = new StringBuilder();
      } else {
        data.append('\n');
      }
      String value = line.substring("data:".length());
      data.append(value.startsWith(" ") ? value.substring(1) : value);
    }
    return data == null ? null : data.toString();
  }

  private static String streamingEndpoint(String endpoint) {
    return endpoint.replace(":generateContent", ":streamGenerateContent") + "?alt=sse";
  }

  private static String modelEndpoint(String endpoint) {
    int action = endpoint.indexOf(":generateContent");
    return action < 0 ? endpoint : endpoint.substring(0, action);
  }
}

package com.grahambartley.runelite.voiced.dialogue.speech.aistudio;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;

final class AiStudioTokenUsage {

  static final AiStudioTokenUsage NONE = new AiStudioTokenUsage(0, 0, 0);

  final long promptTokens;

  final long audioTokens;

  final long textTokens;

  AiStudioTokenUsage(long promptTokens, long audioTokens, long textTokens) {
    this.promptTokens = promptTokens;
    this.audioTokens = audioTokens;
    this.textTokens = textTokens;
  }

  AiStudioTokenUsage max(AiStudioTokenUsage other) {
    if (other == null) {
      return this;
    }
    return new AiStudioTokenUsage(
        Math.max(promptTokens, other.promptTokens),
        Math.max(audioTokens, other.audioTokens),
        Math.max(textTokens, other.textTokens));
  }

  static AiStudioTokenUsage forSpeech(Gson gson, String raw) {
    return forSpeech(parse(gson, raw));
  }

  static AiStudioTokenUsage forSpeech(JsonObject response) {
    JsonObject usage = usageMetadata(response);
    if (usage == null) {
      return NONE;
    }
    long audio = modalityTokens(usage, "AUDIO");
    if (audio == 0) {
      audio = asLong(usage, "candidatesTokenCount");
    }
    return of(asLong(usage, "promptTokenCount"), audio, 0);
  }

  static AiStudioTokenUsage forText(Gson gson, String raw) {
    JsonObject usage = usageMetadata(parse(gson, raw));
    if (usage == null) {
      return NONE;
    }
    return of(asLong(usage, "promptTokenCount"), 0, asLong(usage, "candidatesTokenCount"));
  }

  private static AiStudioTokenUsage of(long prompt, long audio, long text) {
    return prompt == 0 && audio == 0 && text == 0
        ? NONE
        : new AiStudioTokenUsage(prompt, audio, text);
  }

  private static JsonObject parse(Gson gson, String raw) {
    if (raw == null || raw.isEmpty()) {
      return null;
    }
    try {
      return gson.fromJson(raw, JsonObject.class);
    } catch (RuntimeException e) {
      return null;
    }
  }

  private static JsonObject usageMetadata(JsonObject response) {
    if (response == null) {
      return null;
    }
    try {
      return response.getAsJsonObject("usageMetadata");
    } catch (RuntimeException e) {
      return null;
    }
  }

  private static long modalityTokens(JsonObject usage, String modality) {
    try {
      JsonArray details = usage.getAsJsonArray("candidatesTokensDetails");
      if (details == null) {
        return 0;
      }
      long total = 0;
      for (JsonElement element : details) {
        JsonObject detail = element.getAsJsonObject();
        if (detail.has("modality")
            && modality.equalsIgnoreCase(detail.get("modality").getAsString())) {
          total += asLong(detail, "tokenCount");
        }
      }
      return total;
    } catch (RuntimeException e) {
      return 0;
    }
  }

  private static long asLong(JsonObject object, String field) {
    if (object == null || !object.has(field) || object.get(field).isJsonNull()) {
      return 0;
    }
    try {
      return Math.max(0, object.get(field).getAsLong());
    } catch (RuntimeException e) {
      return 0;
    }
  }
}

package com.grahambartley.runelite.voiced.dialogue.speech;

import com.grahambartley.runelite.voiced.dialogue.audio.AudioOutput;
import com.grahambartley.runelite.voiced.dialogue.audio.CaveEcho;
import com.grahambartley.runelite.voiced.dialogue.audio.Pcm;
import com.grahambartley.runelite.voiced.dialogue.audio.PcmSink;
import com.grahambartley.runelite.voiced.dialogue.cache.DiskAudioCache;
import com.grahambartley.runelite.voiced.dialogue.cache.TieredSynthesisCache;
import com.grahambartley.runelite.voiced.dialogue.cache.TieredSynthesisCache.CacheKey;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ArrayBlockingQueue;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.Executor;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.LinkedBlockingQueue;
import java.util.concurrent.RejectedExecutionException;
import java.util.concurrent.SynchronousQueue;
import java.util.concurrent.ThreadFactory;
import java.util.concurrent.ThreadPoolExecutor;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicLong;
import java.util.function.IntSupplier;
import java.util.function.Supplier;
import lombok.extern.slf4j.Slf4j;

@Slf4j
public final class DialogueAudioService {

  private static final CompletableFuture<Void> NOTHING_PLAYING =
      CompletableFuture.completedFuture(null);

  private static final int SYNTH_THREADS = 2;

  private static final int PREFETCH_THREADS = 2;

  private static final int PREFETCH_QUEUE_CAPACITY = 16;

  private static final int SHUTDOWN_WAIT_SECONDS = 2;

  private static final int AMBIENT_SYNTH_THREADS = 6;

  private static final int AMBIENT_PLAYBACK_KEEPALIVE_SECONDS = 30;

  private final BackendProvider backends;
  private final AudioOutput output;
  private final Executor executor;
  private final Executor warmExecutor;
  private final Executor prefetchExecutor;
  private final TieredSynthesisCache cache;
  private final IntSupplier volume;
  private final Supplier<AudioOutput> ambientOutputs;
  private final Executor ambientExecutor;
  private final Executor ambientPlaybackExecutor;
  private final Set<AmbientLine> ambientLines = ConcurrentHashMap.newKeySet();
  private final Map<Integer, CompletableFuture<Void>> ambientChains = new ConcurrentHashMap<>();
  private final AtomicLong epoch = new AtomicLong();

  private volatile boolean closed;
  private final AtomicLong prefetchEpoch = new AtomicLong();
  private final AtomicLong ambientEpoch = new AtomicLong();

  public DialogueAudioService(
      BackendProvider backends,
      AudioOutput output,
      Supplier<AudioOutput> ambientOutputs,
      DiskAudioCache diskCache,
      int cacheSize,
      int queueCapacity,
      IntSupplier volume) {
    this(
        backends,
        output,
        ambientOutputs,
        new TieredSynthesisCache(cacheSize, diskCache),
        buildExecutor(queueCapacity),
        buildWarmExecutor(),
        buildPrefetchExecutor(),
        buildAmbientExecutor(),
        buildAmbientPlaybackExecutor(),
        volume);
  }

  DialogueAudioService(
      BackendProvider backends,
      AudioOutput output,
      Supplier<AudioOutput> ambientOutputs,
      TieredSynthesisCache cache,
      Executor executor,
      Executor warmExecutor,
      Executor prefetchExecutor,
      Executor ambientExecutor,
      Executor ambientPlaybackExecutor,
      IntSupplier volume) {
    this.backends = backends;
    this.output = output;
    this.ambientOutputs = ambientOutputs;
    this.cache = cache;
    this.executor = executor;
    this.warmExecutor = warmExecutor;
    this.prefetchExecutor = prefetchExecutor;
    this.ambientExecutor = ambientExecutor;
    this.ambientPlaybackExecutor = ambientPlaybackExecutor;
    this.volume = volume;
  }

  public void prewarm(Runnable warm) {
    submitQuietly(
        warmExecutor,
        () -> {
          if (!closed) {
            warm.run();
          }
        });
  }

  public void speak(SynthesisRequest request) {
    speak(request, false);
  }

  public void speak(SynthesisRequest request, boolean applyEcho) {
    if (request == null || request.text() == null || request.text().isEmpty()) {
      return;
    }
    long mine = epoch.incrementAndGet();
    output.stop();
    cutAmbient();
    SynthesisBackend backend = backends.active();
    SynthesisRequest effective = BackendProvider.downgradeFor(backend, request);
    CacheKey key = keyFor(backend, effective);
    submitQuietly(executor, () -> run(mine, backend, effective, key, applyEcho));
  }

  public void speakAmbient(
      SynthesisRequest request, boolean applyEcho, int speakerId, IntSupplier distanceVolume) {
    if (request == null || request.text() == null || request.text().isEmpty()) {
      return;
    }
    SynthesisBackend backend = backends.active();
    SynthesisRequest effective = BackendProvider.downgradeFor(backend, request);
    CacheKey key = keyFor(backend, effective);
    long node = ambientEpoch.get();
    AmbientLine line = new AmbientLine(distanceVolume);
    ambientLines.add(line);
    try {
      queueAmbientPlayback(
          speakerId,
          CompletableFuture.supplyAsync(
              () -> synthesizeAmbient(node, backend, effective, key, applyEcho), ambientExecutor),
          node,
          line);
    } catch (RejectedExecutionException closing) {
      ambientLines.remove(line);
    }
  }

  private Pcm synthesizeAmbient(
      long node,
      SynthesisBackend backend,
      SynthesisRequest request,
      CacheKey key,
      boolean applyEcho) {
    if (ambientEpoch.get() != node) {
      return null;
    }
    Pcm cached = cache.lookup(key);
    if (cached == null && backend.isThrottled()) {
      return null;
    }
    Pcm pcm = cached != null ? cached : synthesizeDeduped(backend, request, key);
    if (pcm == null) {
      return null;
    }
    return applyEcho ? CaveEcho.apply(pcm) : pcm;
  }

  private void queueAmbientPlayback(
      int speakerId, CompletableFuture<Pcm> synthesis, long node, AmbientLine line) {
    CompletableFuture<Pcm> rendered = synthesis.handle((pcm, error) -> pcm);
    CompletableFuture<Void> queued =
        ambientChains.compute(
            speakerId,
            (id, playing) ->
                (playing == null ? NOTHING_PLAYING : playing)
                    .handle((ignored, error) -> (Void) null)
                    .thenCombine(rendered, (ignored, pcm) -> pcm)
                    .thenAcceptAsync(
                        pcm -> {
                          if (pcm != null && ambientEpoch.get() == node) {
                            playAmbient(node, pcm, line);
                          }
                        },
                        ambientPlaybackExecutor));
    queued.whenComplete(
        (ignored, error) -> {
          ambientLines.remove(line);
          ambientChains.remove(speakerId, queued);
        });
  }

  private void playAmbient(long node, Pcm pcm, AmbientLine line) {
    int openingVolume = line.volumePercent.get();
    if (cutRequested(openingVolume)) {
      return;
    }
    AudioOutput ambient = ambientOutputs.get();
    line.output = ambient;
    try {
      if (ambientEpoch.get() == node) {
        ambient.stream(pcm.getSamples(), pcm.getSampleRate(), openingVolume);
      }
    } finally {
      line.output = null;
      ambient.close();
    }
  }

  public void refreshAmbientVolumes() {
    if (ambientLines.isEmpty()) {
      return;
    }
    for (AmbientLine line : ambientLines) {
      int volumePercent = line.distanceVolume.getAsInt();
      line.volumePercent.set(volumePercent);
      AudioOutput sounding = line.output;
      if (sounding == null) {
        continue;
      }
      if (cutRequested(volumePercent)) {
        sounding.stop();
        continue;
      }
      sounding.setVolume(volumePercent);
    }
  }

  private static boolean cutRequested(int volumePercent) {
    return volumePercent < 0;
  }

  private void cutAmbient() {
    ambientEpoch.incrementAndGet();
    if (ambientLines.isEmpty()) {
      return;
    }
    submitQuietly(ambientPlaybackExecutor, this::stopLiveAmbient);
  }

  private void stopLiveAmbient() {
    for (AmbientLine line : ambientLines) {
      AudioOutput sounding = line.output;
      if (sounding != null) {
        sounding.stop();
      }
    }
  }

  private static final class AmbientLine {
    private final IntSupplier distanceVolume;
    private final AtomicInteger volumePercent;
    private volatile AudioOutput output;

    private AmbientLine(IntSupplier distanceVolume) {
      this.distanceVolume = distanceVolume;
      this.volumePercent = new AtomicInteger(distanceVolume.getAsInt());
    }
  }

  public void prefetch(SynthesisRequest request) {
    if (request == null || request.text() == null || request.text().isEmpty()) {
      return;
    }
    SynthesisBackend backend = backends.active();
    if (!backend.isAvailable() || backend.isThrottled()) {
      return;
    }
    SynthesisRequest effective = BackendProvider.downgradeFor(backend, request);
    CacheKey key = keyFor(backend, effective);
    if (cache.memoryHit(key) != null) {
      return;
    }
    long node = prefetchEpoch.get();
    submitQuietly(
        prefetchExecutor,
        () -> {
          if (prefetchEpoch.get() != node || backend.isThrottled() || cache.lookup(key) != null) {
            return;
          }
          log.debug(
              "[TTS synth] prefetch ({}/{}) \"{}\"",
              key.backendId(),
              key.voiceKey(),
              key.textPreview());
          synthesizeDeduped(backend, effective, key);
        });
  }

  public void cancelPrefetch() {
    prefetchEpoch.incrementAndGet();
  }

  private CacheKey keyFor(SynthesisBackend backend, SynthesisRequest effective) {
    String variant = backend.cacheVariant(effective);
    String voiceKey =
        variant.isEmpty() ? effective.voice().key() : effective.voice().key() + "|" + variant;
    return new CacheKey(backend.id(), voiceKey, effective.emotion(), effective.text());
  }

  public void cutPlayback() {
    epoch.incrementAndGet();
    output.stop();
  }

  public void close() {
    closed = true;
    epoch.incrementAndGet();
    prefetchEpoch.incrementAndGet();
    output.stop();
    ambientEpoch.incrementAndGet();
    stopLiveAmbient();
    ambientChains.clear();
    ambientLines.clear();
    stopAccepting(ambientExecutor);
    stopAccepting(ambientPlaybackExecutor);
    stopAndAwait(executor);
    if (warmExecutor != executor) {
      stopAndAwait(warmExecutor);
    }
    if (prefetchExecutor != executor && prefetchExecutor != warmExecutor) {
      stopAndAwait(prefetchExecutor);
    }
    output.close();
  }

  private static void stopAccepting(Executor exec) {
    if (exec instanceof ExecutorService) {
      ((ExecutorService) exec).shutdown();
    }
  }

  private static void stopAndAwait(Executor exec) {
    if (exec instanceof ExecutorService) {
      ExecutorService es = (ExecutorService) exec;
      es.shutdown();
      try {
        if (!es.awaitTermination(SHUTDOWN_WAIT_SECONDS, TimeUnit.SECONDS)) {
          log.debug("A worker was still running after {}s, leaving it be", SHUTDOWN_WAIT_SECONDS);
        }
      } catch (InterruptedException e) {
        log.debug("Interrupted while awaiting executor shutdown");
      }
    }
  }

  private void run(
      long mine,
      SynthesisBackend backend,
      SynthesisRequest request,
      CacheKey key,
      boolean applyEcho) {
    if (epoch.get() != mine) {
      return;
    }
    Pcm pcm = cache.lookup(key);
    if (pcm != null) {
      playBuffered(mine, pcm, applyEcho);
      return;
    }
    if (!applyEcho) {
      runStreaming(mine, backend, request, key);
      return;
    }
    pcm = synthesizeDeduped(backend, request, key);
    if (pcm == null) {
      return;
    }
    playBuffered(mine, pcm, applyEcho);
  }

  private void playBuffered(long mine, Pcm pcm, boolean applyEcho) {
    if (epoch.get() != mine) {
      return;
    }
    Pcm toPlay = applyEcho ? CaveEcho.apply(pcm) : pcm;
    output.stream(toPlay.getSamples(), toPlay.getSampleRate(), volume.getAsInt());
  }

  void runStreaming(long mine, SynthesisBackend backend, SynthesisRequest request, CacheKey key) {
    if (epoch.get() != mine) {
      synthesizeDeduped(backend, request, key);
      return;
    }
    AtomicBoolean deduped = new AtomicBoolean();
    Pcm pcm =
        cache.withInFlight(
            key,
            () -> {
              AudioOutput.AudioStream stream = output.beginStream(volume.getAsInt());
              try {
                PcmSink sink = stream::write;
                return backends.synthesizeStreamingWith(backend, request, sink);
              } finally {
                stream.end();
              }
            },
            () -> deduped.set(true));
    if (deduped.get() && pcm != null) {
      playBuffered(mine, pcm, false);
    }
  }

  private Pcm synthesizeDeduped(SynthesisBackend backend, SynthesisRequest request, CacheKey key) {
    return cache.withInFlight(
        key,
        () -> {
          long start = System.nanoTime();
          Pcm pcm = backends.synthesizeWith(backend, request);
          log.debug(
              "[TTS synth] backend={} ok={} synthMs={} ({}/{}) \"{}\"",
              backend.id(),
              pcm != null,
              elapsedMs(start),
              key.backendId(),
              key.voiceKey(),
              key.textPreview());
          return pcm;
        },
        () ->
            log.debug(
                "[TTS synth] dedup reuse ({}/{}) \"{}\"",
                key.backendId(),
                key.voiceKey(),
                key.textPreview()));
  }

  private static void submitQuietly(Executor exec, Runnable task) {
    try {
      exec.execute(task);
    } catch (RejectedExecutionException ignored) {
    }
  }

  private static ThreadFactory daemonThreadFactory(String name) {
    return r -> {
      Thread t = new Thread(r, name);
      t.setDaemon(true);
      return t;
    };
  }

  private static ExecutorService buildExecutor(int queueCapacity) {
    return new ThreadPoolExecutor(
        SYNTH_THREADS,
        SYNTH_THREADS,
        0L,
        TimeUnit.MILLISECONDS,
        new ArrayBlockingQueue<>(queueCapacity),
        daemonThreadFactory("dialogue-audio"),
        (r, exec) -> {
          log.debug("[TTS synth] queue saturated; dropping oldest queued line");
          new ThreadPoolExecutor.DiscardOldestPolicy().rejectedExecution(r, exec);
        });
  }

  private static ExecutorService buildWarmExecutor() {
    return new ThreadPoolExecutor(
        1,
        1,
        0L,
        TimeUnit.MILLISECONDS,
        new LinkedBlockingQueue<>(),
        daemonThreadFactory("dialogue-warm"));
  }

  private static ExecutorService buildAmbientExecutor() {
    return new ThreadPoolExecutor(
        AMBIENT_SYNTH_THREADS,
        AMBIENT_SYNTH_THREADS,
        0L,
        TimeUnit.MILLISECONDS,
        new LinkedBlockingQueue<>(),
        daemonThreadFactory("dialogue-ambient"));
  }

  private static ExecutorService buildAmbientPlaybackExecutor() {
    return new ThreadPoolExecutor(
        0,
        Integer.MAX_VALUE,
        AMBIENT_PLAYBACK_KEEPALIVE_SECONDS,
        TimeUnit.SECONDS,
        new SynchronousQueue<>(),
        daemonThreadFactory("dialogue-ambient-play"));
  }

  private static ExecutorService buildPrefetchExecutor() {
    return new ThreadPoolExecutor(
        PREFETCH_THREADS,
        PREFETCH_THREADS,
        0L,
        TimeUnit.MILLISECONDS,
        new ArrayBlockingQueue<>(PREFETCH_QUEUE_CAPACITY),
        daemonThreadFactory("dialogue-prefetch"),
        new ThreadPoolExecutor.DiscardOldestPolicy());
  }

  private static long elapsedMs(long startNanos) {
    return (System.nanoTime() - startNanos) / 1_000_000L;
  }
}

package com.grahambartley.runelite.voiced.dialogue.speech;

import java.util.concurrent.atomic.AtomicReference;
import java.util.function.LongSupplier;
import lombok.extern.slf4j.Slf4j;

@Slf4j
public final class RateLimitBackoff {

  private static final long BACKOFF_BASE_MILLIS = 1_000;

  private static final long BACKOFF_MAX_MILLIS = 30_000;

  private static final long HINT_MAX_MILLIS = 60 * 60 * 1_000L;

  private static final long NANOS_PER_MILLI = 1_000_000L;

  private final AtomicReference<Window> window = new AtomicReference<>(Window.clear(0));

  private final LongSupplier clock;

  public RateLimitBackoff() {
    this(System::nanoTime);
  }

  RateLimitBackoff(LongSupplier nanoClock) {
    this.clock = nanoClock;
  }

  long generation() {
    return window.get().generation;
  }

  boolean isThrottled() {
    return window.get().isOpen(clock.getAsLong());
  }

  boolean isRefusing() {
    Window standing = window.get();
    return standing.stated && standing.isOpen(clock.getAsLong());
  }

  void recordRateLimited(long statedWaitMillis, long observedGeneration) {
    long now = clock.getAsLong();
    long statedWait = Math.min(Math.max(statedWaitMillis, 0), HINT_MAX_MILLIS);
    Window standing =
        window.updateAndGet(current -> current.rateLimited(now, statedWait, observedGeneration));
    if (standing.generation != observedGeneration) {
      log.debug("[TTS cloud] 429 predates a call that succeeded; leaving the back-off clear");
      return;
    }
    if (statedWaitMillis > HINT_MAX_MILLIS) {
      log.warn(
          "[TTS cloud] 429 asked for a {}ms wait; clamped to {}ms",
          statedWaitMillis,
          HINT_MAX_MILLIS);
    }
    log.debug(
        "[TTS cloud] rate limited (429); {} for {}ms",
        standing.stated ? "the provider asked to be left alone" : "backing off prefetch",
        standing.remainingMillis(now));
  }

  void recordSuccess() {
    reset();
  }

  void reset() {
    window.updateAndGet(current -> Window.clear(current.generation + 1));
  }

  static long backoffWindowMillis(int consecutive) {
    int shift = Math.min(Math.max(consecutive, 1) - 1, 16);
    long window = BACKOFF_BASE_MILLIS << shift;
    return Math.min(window, BACKOFF_MAX_MILLIS);
  }

  private static final class Window {

    private final long endNanos;
    private final boolean stated;
    private final boolean open;
    private final long generation;
    private final int consecutive;

    static Window clear(long generation) {
      return new Window(0, false, false, generation, 0);
    }

    private Window(long endNanos, boolean stated, boolean open, long generation, int consecutive) {
      this.endNanos = endNanos;
      this.stated = stated;
      this.open = open;
      this.generation = generation;
      this.consecutive = consecutive;
    }

    Window rateLimited(long nowNanos, long statedWaitMillis, long observedGeneration) {
      if (generation != observedGeneration) {
        return this;
      }
      int rejections = consecutive + 1;
      boolean nowStated = statedWaitMillis > 0;
      long millis = nowStated ? statedWaitMillis : backoffWindowMillis(rejections);
      Window opened =
          new Window(nowNanos + millis * NANOS_PER_MILLI, nowStated, true, generation, rejections);
      return outranks(opened, nowNanos)
          ? new Window(endNanos, stated, open, generation, rejections)
          : opened;
    }

    boolean isOpen(long nowNanos) {
      return open && nowNanos - endNanos < 0;
    }

    long remainingMillis(long nowNanos) {
      return isOpen(nowNanos) ? (endNanos - nowNanos) / NANOS_PER_MILLI : 0;
    }

    private boolean outranks(Window proposed, long nowNanos) {
      if (!isOpen(nowNanos)) {
        return false;
      }
      if (stated != proposed.stated) {
        return stated;
      }
      return proposed.endNanos - endNanos < 0;
    }
  }
}

package com.grahambartley.runelite.voiced.dialogue.speech;

import com.grahambartley.runelite.voiced.dialogue.VoicedDialogueConfig;
import com.grahambartley.runelite.voiced.dialogue.audio.Pcm;
import com.grahambartley.runelite.voiced.dialogue.audio.PcmSink;
import com.grahambartley.runelite.voiced.dialogue.profile.Emotion;
import java.util.function.Supplier;
import lombok.extern.slf4j.Slf4j;

@Slf4j
public final class BackendProvider {

  private final SynthesisBackend openRouter;
  private final SynthesisBackend googleAiStudio;
  private final Supplier<VoicedDialogueConfig.TtsProvider> selectedProvider;

  public BackendProvider(SynthesisBackend backend) {
    this(backend, backend, () -> VoicedDialogueConfig.TtsProvider.OPENROUTER);
  }

  public BackendProvider(
      SynthesisBackend openRouter,
      SynthesisBackend googleAiStudio,
      Supplier<VoicedDialogueConfig.TtsProvider> selectedProvider) {
    this.openRouter = openRouter;
    this.googleAiStudio = googleAiStudio;
    this.selectedProvider = selectedProvider;
  }

  public void clearRateLimits() {
    openRouter.clearRateLimit();
    googleAiStudio.clearRateLimit();
  }

  public SynthesisBackend active() {
    return selectedProvider.get() == VoicedDialogueConfig.TtsProvider.GOOGLE_AI_STUDIO
        ? googleAiStudio
        : openRouter;
  }

  public static SynthesisRequest downgradeFor(SynthesisBackend backend, SynthesisRequest request) {
    if (backend.supportedEmotions().contains(request.emotion())) {
      return request;
    }
    return request.withEmotion(Emotion.NEUTRAL);
  }

  public Pcm synthesizeWith(SynthesisBackend backend, SynthesisRequest request) {
    return backend.synthesize(downgradeFor(backend, request));
  }

  public Pcm synthesizeStreamingWith(
      SynthesisBackend backend, SynthesisRequest request, PcmSink sink) {
    return backend.synthesizeStreaming(downgradeFor(backend, request), sink);
  }

  public void warmUpActive() {
    active().warmUp();
  }

  public void close() {
    closeQuietly(openRouter);
    if (googleAiStudio != openRouter) {
      closeQuietly(googleAiStudio);
    }
  }

  private static void closeQuietly(SynthesisBackend backend) {
    try {
      backend.close();
    } catch (RuntimeException e) {
      log.debug("Error closing backend {}: {}", backend.id(), e.getMessage());
    }
  }
}

package com.grahambartley.runelite.voiced.dialogue.speech;

import com.grahambartley.runelite.voiced.dialogue.VoicedDialogueConfig;

public final class CloudTtsText {

  private CloudTtsText() {}

  static boolean needsTranslation(String language) {
    return language != null
        && !language.trim().isEmpty()
        && !language.trim().equalsIgnoreCase("English");
  }

  static String effectiveSpokenLanguage(VoicedDialogueConfig config, SynthesisRequest request) {
    return combineLanguage(config.cloudLanguage().label(), styleFor(config, request));
  }

  private static VoicedDialogueConfig.SpeakingStyle styleFor(
      VoicedDialogueConfig config, SynthesisRequest request) {
    if (request.voice().narrator()) {
      return VoicedDialogueConfig.SpeakingStyle.NONE;
    }
    return request.player() ? config.cloudPlayerSpeakingStyle() : config.cloudNpcSpeakingStyle();
  }

  static String combineLanguage(String language, VoicedDialogueConfig.SpeakingStyle quirk) {
    String base = language == null || language.trim().isEmpty() ? "English" : language.trim();
    if (quirk == null || quirk.isNone()) {
      return base;
    }
    return base + " " + quirk.phrase();
  }

  public static String translatorSystemPrompt(String language) {
    return "You are a translation engine for an Old School RuneScape dialogue voice plugin."
        + " Translate the user's line into "
        + language
        + ". Preserve proper nouns, character names, place names, item names, and RuneScape"
        + " terminology exactly as written. Output only the translation, with no quotes, notes,"
        + " explanations, or preamble.";
  }
}

package com.grahambartley.runelite.voiced.dialogue.speech;

import com.grahambartley.runelite.voiced.dialogue.VoicedDialogueConfig;
import com.grahambartley.runelite.voiced.dialogue.VoicedDialogueConfig.TtsProvider;
import com.grahambartley.runelite.voiced.dialogue.speech.spend.SpendTracker;
import java.util.Set;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ThreadLocalRandom;
import java.util.concurrent.TimeUnit;
import java.util.function.Consumer;
import lombok.extern.slf4j.Slf4j;

@Slf4j
public final class CloudBackendSupport {

  public static final int DEFAULT_SPEED_PERCENT = 100;

  private static final int MIN_SPEED_PERCENT = 50;

  private static final int MAX_SPEED_PERCENT = 200;

  private final VoicedDialogueConfig config;
  private final TtsProvider provider;
  private final int maxAttempts;
  private final long networkRetryBaseMillis;
  private final long networkRetryJitterMillis;

  private SpendTracker spend = new SpendTracker();

  private Consumer<String> notice = msg -> {};

  private final Set<String> warned = ConcurrentHashMap.newKeySet();

  public CloudBackendSupport(
      VoicedDialogueConfig config, TtsProvider provider, int maxAttempts, RetryTuning tuning) {
    this.config = config;
    this.provider = provider;
    this.maxAttempts = maxAttempts;
    this.networkRetryBaseMillis = tuning.retryBackoffBaseMillis;
    this.networkRetryJitterMillis = tuning.retryJitterMillis;
  }

  public void setNotice(Consumer<String> notice) {
    this.notice = notice == null ? msg -> {} : notice;
  }

  public void setSpendTracker(SpendTracker spend) {
    this.spend = spend == null ? new SpendTracker() : spend;
  }

  public void recordSpeechSpend(int characters, boolean prefetch) {
    spend.recordSpeech(provider, characters, prefetch);
  }

  public void recordSpeechSpend(
      int characters, boolean prefetch, long audioTokens, long promptTokens) {
    spend.recordSpeech(provider, characters, prefetch, audioTokens, promptTokens);
  }

  public void recordTranslationSpend(int characters) {
    spend.recordTranslation(provider, characters);
  }

  public void recordTranslationSpend(int characters, long inputTokens, long outputTokens) {
    spend.recordTranslation(provider, characters, inputTokens, outputTokens);
  }

  void noticeMissingKey(String message) {
    log.debug(message);
    notice.accept(message);
  }

  void warnOnce(String message) {
    log.debug(message);
    if (warned.add(message)) {
      notice.accept(message);
    }
  }

  void logFailure(
      String kind,
      int attempt,
      long elapsedMs,
      int inputLen,
      int code,
      String message,
      String contentType,
      String generationId,
      byte[] bytes) {
    log.warn(
        CloudSynthTrace.failure(
            kind,
            attempt,
            maxAttempts,
            elapsedMs,
            inputLen,
            code,
            contentType,
            generationId,
            bytes.length,
            message));
    if (config.debugMode() && bytes.length > 0) {
      log.info("[TTS cloud] {} body snippet: {}", kind, CloudHttp.bodySnippet(bytes));
    }
  }

  void logNetworkFailure(String kind, int attempt, long elapsedMs, int inputLen, Exception e) {
    log.warn(
        CloudSynthTrace.failure(
            kind, attempt, maxAttempts, elapsedMs, inputLen, 0, "", "", 0, e.getMessage()));
  }

  void backoffBeforeNetworkRetry(int attempt) {
    long base = networkRetryBaseMillis << (attempt - 1);
    long jitter =
        networkRetryJitterMillis <= 0
            ? 0
            : ThreadLocalRandom.current().nextLong(networkRetryJitterMillis + 1);
    long delayMillis = base + jitter;
    if (delayMillis <= 0) {
      return;
    }
    CompletableFuture.runAsync(
            () -> {}, CompletableFuture.delayedExecutor(delayMillis, TimeUnit.MILLISECONDS))
        .join();
  }

  int speedPercent() {
    int percent = config.speakingPace();
    if (percent < MIN_SPEED_PERCENT) {
      return MIN_SPEED_PERCENT;
    }
    if (percent > MAX_SPEED_PERCENT) {
      return MAX_SPEED_PERCENT;
    }
    return percent;
  }
}

package com.grahambartley.runelite.voiced.dialogue.speech.openrouter;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import com.grahambartley.runelite.voiced.dialogue.VoicedDialogueConfig;
import com.grahambartley.runelite.voiced.dialogue.speech.CloudHttp;
import com.grahambartley.runelite.voiced.dialogue.speech.CloudTranslatorCall;
import com.grahambartley.runelite.voiced.dialogue.speech.CloudTtsText;
import com.grahambartley.runelite.voiced.dialogue.speech.model.GeminiTranslationModel;
import java.nio.charset.StandardCharsets;
import lombok.extern.slf4j.Slf4j;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;

@Slf4j
final class OpenRouterTranslator implements CloudTranslatorCall.Ops {

  static final String MODEL = GeminiTranslationModel.MODEL_ID;

  private final OkHttpClient httpClient;
  private final VoicedDialogueConfig config;
  private final Gson gson;
  private final String endpoint;

  OpenRouterTranslator(
      OkHttpClient httpClient, VoicedDialogueConfig config, Gson gson, String endpoint) {
    this.httpClient = httpClient;
    this.config = config;
    this.gson = gson;
    this.endpoint = endpoint;
  }

  String translate(String text, String language, String apiKey) {
    if (text == null || text.isEmpty()) {
      return text;
    }
    CloudTranslatorCall.Outcome outcome =
        CloudTranslatorCall.run(httpClient, config, this, text, language, apiKey);
    return outcome == null ? null : outcome.text;
  }

  @Override
  public Request buildRequest(String text, String language, String apiKey) {
    JsonObject payload = new JsonObject();
    payload.addProperty("model", MODEL);
    JsonArray messages = new JsonArray();
    messages.add(message("system", CloudTtsText.translatorSystemPrompt(language)));
    messages.add(message("user", text));
    payload.add("messages", messages);
    OpenRouterProvider.apply(payload);

    return OpenRouterProvider.attributedRequest(endpoint, apiKey)
        .post(
            RequestBody.create(
                CloudHttp.JSON_MEDIA_TYPE, gson.toJson(payload).getBytes(StandardCharsets.UTF_8)))
        .build();
  }

  private static JsonObject message(String role, String content) {
    JsonObject message = new JsonObject();
    message.addProperty("role", role);
    message.addProperty("content", content);
    return message;
  }

  @Override
  public String extractText(String raw) {
    if (raw == null || raw.isEmpty()) {
      return null;
    }
    try {
      JsonObject parsed = gson.fromJson(raw, JsonObject.class);
      if (parsed == null || !parsed.has("choices")) {
        return null;
      }
      JsonArray choices = parsed.getAsJsonArray("choices");
      if (choices.size() == 0) {
        return null;
      }
      JsonObject message = choices.get(0).getAsJsonObject().getAsJsonObject("message");
      if (message == null || !message.has("content")) {
        return null;
      }
      return message.get("content").getAsString().trim();
    } catch (RuntimeException e) {
      log.debug("[TTS cloud] translation response parse error: {}", e.getMessage());
      return null;
    }
  }
}

package com.grahambartley.runelite.voiced.dialogue.speech.openrouter;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import com.grahambartley.runelite.voiced.dialogue.speech.CloudHttp;
import java.io.IOException;
import lombok.extern.slf4j.Slf4j;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;

@Slf4j
public final class OpenRouterUsageClient {

  static final String PRODUCTION_ENDPOINT = "https://openrouter.ai/api/v1/key";

  private final OkHttpClient httpClient;
  private final Gson gson;
  private final String endpoint;

  public OpenRouterUsageClient(OkHttpClient httpClient, Gson gson) {
    this(httpClient, gson, PRODUCTION_ENDPOINT);
  }

  OpenRouterUsageClient(OkHttpClient httpClient, Gson gson, String endpoint) {
    this.httpClient = httpClient;
    this.gson = gson;
    this.endpoint = endpoint;
  }

  public Double fetchUsage(String apiKey) {
    if (!CloudHttp.isNonBlank(apiKey)) {
      return null;
    }
    Request request =
        new Request.Builder()
            .url(endpoint)
            .addHeader("Authorization", "Bearer " + apiKey.trim())
            .addHeader("User-Agent", CloudHttp.USER_AGENT)
            .get()
            .build();
    try (Response response = httpClient.newCall(request).execute()) {
      ResponseBody body = response.body();
      String raw = body == null ? "" : body.string();
      if (!response.isSuccessful()) {
        log.debug("[TTS spend] balance read HTTP {}", response.code());
        return null;
      }
      return extractUsage(raw);
    } catch (IOException | RuntimeException e) {
      log.debug("[TTS spend] balance read failed: {}", e.getMessage());
      return null;
    }
  }

  Double extractUsage(String raw) {
    if (raw == null || raw.isEmpty()) {
      return null;
    }
    try {
      JsonObject parsed = gson.fromJson(raw, JsonObject.class);
      if (parsed == null || !parsed.has("data")) {
        return null;
      }
      JsonObject data = parsed.getAsJsonObject("data");
      if (data == null || !data.has("usage") || data.get("usage").isJsonNull()) {
        return null;
      }
      return data.get("usage").getAsDouble();
    } catch (RuntimeException e) {
      log.debug("[TTS spend] balance response parse error: {}", e.getMessage());
      return null;
    }
  }
}

package com.grahambartley.runelite.voiced.dialogue.speech.openrouter;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import com.grahambartley.runelite.voiced.dialogue.VoicedDialogueConfig;
import com.grahambartley.runelite.voiced.dialogue.audio.Pcm;
import com.grahambartley.runelite.voiced.dialogue.audio.PcmSink;
import com.grahambartley.runelite.voiced.dialogue.profile.CharacterProfile;
import com.grahambartley.runelite.voiced.dialogue.profile.Emotion;
import com.grahambartley.runelite.voiced.dialogue.speech.CloudBackendSupport;
import com.grahambartley.runelite.voiced.dialogue.speech.CloudHttp;
import com.grahambartley.runelite.voiced.dialogue.speech.CloudSpeechExecutor;
import com.grahambartley.runelite.voiced.dialogue.speech.RetryTuning;
import com.grahambartley.runelite.voiced.dialogue.speech.SynthesisBackend;
import com.grahambartley.runelite.voiced.dialogue.speech.SynthesisRequest;
import com.grahambartley.runelite.voiced.dialogue.speech.model.GeminiTtsModel;
import com.grahambartley.runelite.voiced.dialogue.speech.spend.SpendTracker;
import java.io.IOException;
import java.io.InputStream;
import java.net.HttpURLConnection;
import java.nio.charset.StandardCharsets;
import java.time.Duration;
import java.util.EnumSet;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.TimeUnit;
import java.util.function.Consumer;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;
import okhttp3.ResponseBody;

@Slf4j
public final class OpenRouterTtsBackend implements SynthesisBackend {

  public static final String ID = "cloud-openrouter";

  private static final String API_BASE = "https://openrouter.ai/api/v1";
  private static final String SPEECH_PATH = "/audio/speech";
  private static final String CHAT_COMPLETIONS_PATH = "/chat/completions";

  private static final String KEY_PATH = "/key";

  private static final String PRODUCTION_ENDPOINT = API_BASE + SPEECH_PATH;

  private static final Duration CALL_BUDGET_BASE = Duration.ofSeconds(15);

  private static final long CALL_BUDGET_MILLIS_PER_CHAR = 75;

  private static final Duration KEEP_ALIVE = Duration.ofMinutes(15);

  static final int WARM_UP_CONNECTIONS = 2;

  private static final int STREAM_READ_BUFFER = 16_384;

  public static final String NO_KEY_NOTICE =
      "Add your OpenRouter API key in the Voiced Dialogue settings to hear dialogue; without a key,"
          + " lines are not voiced.";

  static final String OUT_OF_CREDITS_NOTICE =
      "Your OpenRouter account is out of credits, so dialogue cannot be voiced. Top up at"
          + " openrouter.ai/settings/credits.";

  private static final Callback WARM_UP_CALLBACK =
      new Callback() {
        @Override
        public void onFailure(Call call, IOException e) {
          log.debug("[TTS cloud] OpenRouter warm-up failed: {}", e.getMessage());
        }

        @Override
        public void onResponse(Call call, Response response) {
          try (ResponseBody body = response.body()) {
            if (body != null) {
              body.bytes();
            }
            log.debug("[TTS cloud] OpenRouter warm-up HTTP {}", response.code());
          } catch (IOException e) {
            log.debug("[TTS cloud] OpenRouter warm-up body read failed: {}", e.getMessage());
          }
        }
      };

  private final OkHttpClient httpClient;
  private final VoicedDialogueConfig config;
  private final Gson gson;
  private final String endpoint;
  private final String warmUpEndpoint;
  private final GeminiTtsModel model = new GeminiTtsModel();
  private final OpenRouterTranslator translator;

  private final Map<String, Integer> prefixHashes = new ConcurrentHashMap<>();

  private final Duration callTimeout;

  private final CloudBackendSupport support;

  private final CloudSpeechExecutor executor;

  public OpenRouterTtsBackend(OkHttpClient httpClient, VoicedDialogueConfig config, Gson gson) {
    this(httpClient, config, gson, PRODUCTION_ENDPOINT);
  }

  OpenRouterTtsBackend(
      OkHttpClient httpClient, VoicedDialogueConfig config, Gson gson, String endpoint) {
    this(httpClient, config, gson, endpoint, RetryTuning.openRouter());
  }

  OpenRouterTtsBackend(
      OkHttpClient httpClient,
      VoicedDialogueConfig config,
      Gson gson,
      String endpoint,
      RetryTuning tuning) {
    this.httpClient = CloudHttp.deriveClient(httpClient, tuning, KEEP_ALIVE, true);
    this.callTimeout = tuning.callTimeout;
    this.support =
        new CloudBackendSupport(
            config,
            VoicedDialogueConfig.TtsProvider.OPENROUTER,
            CloudSpeechExecutor.MAX_SPEECH_ATTEMPTS,
            tuning);
    this.config = config;
    this.gson = gson;
    this.endpoint = endpoint;
    this.warmUpEndpoint = siblingEndpoint(endpoint, KEY_PATH);
    this.translator =
        new OpenRouterTranslator(
            this.httpClient, config, gson, siblingEndpoint(endpoint, CHAT_COMPLETIONS_PATH));
    this.executor =
        new CloudSpeechExecutor(config, support, model, "OpenRouter", model.modelId(), new Ops());
  }

  private static String siblingEndpoint(String endpoint, String path) {
    return endpoint.contains(SPEECH_PATH) ? endpoint.replace(SPEECH_PATH, path) : API_BASE + path;
  }

  public void setNotice(Consumer<String> notice) {
    support.setNotice(notice);
  }

  public void setSpendTracker(SpendTracker spend) {
    support.setSpendTracker(spend);
  }

  @Override
  public String id() {
    return ID;
  }

  @Override
  public boolean isAvailable() {
    return CloudHttp.isNonBlank(config.openRouterApiKey());
  }

  @Override
  public String missingKeyNotice() {
    return NO_KEY_NOTICE;
  }

  @Override
  public EnumSet<Emotion> supportedEmotions() {
    return model.supportedEmotions();
  }

  @Override
  public boolean isThrottled() {
    return executor.isThrottled();
  }

  @Override
  public void clearRateLimit() {
    executor.clearRateLimit();
  }

  @Override
  public void warmUp() {
    if (!isAvailable() || pooledConnectionCount() > 0) {
      return;
    }
    Request request =
        new Request.Builder()
            .url(warmUpEndpoint)
            .addHeader("Authorization", "Bearer " + config.openRouterApiKey().trim())
            .addHeader("User-Agent", CloudHttp.USER_AGENT)
            .get()
            .build();
    for (int i = 0; i < WARM_UP_CONNECTIONS; i++) {
      httpClient.newCall(request).enqueue(WARM_UP_CALLBACK);
    }
  }

  int pooledConnectionCount() {
    return httpClient.connectionPool().connectionCount();
  }

  int idlePooledConnectionCount() {
    return httpClient.connectionPool().idleConnectionCount();
  }

  Duration callBudgetFor(int inputLength) {
    Duration scaled =
        CALL_BUDGET_BASE.plusMillis(Math.max(0, inputLength) * CALL_BUDGET_MILLIS_PER_CHAR);
    return scaled.compareTo(callTimeout) > 0 ? callTimeout : scaled;
  }

  @Override
  public String cacheVariant(SynthesisRequest request) {
    return executor.cacheVariant(request);
  }

  @Override
  public Pcm synthesize(SynthesisRequest request) {
    return executor.synthesize(request);
  }

  @Override
  public Pcm synthesizeStreaming(SynthesisRequest request, PcmSink sink) {
    return executor.synthesizeStreaming(request, sink);
  }

  static String failureNotice(int httpCode) {
    if (httpCode == HttpURLConnection.HTTP_PAYMENT_REQUIRED) {
      return OUT_OF_CREDITS_NOTICE;
    }
    return "OpenRouter TTS request failed (HTTP "
        + httpCode
        + "); check your API key. This line was not voiced.";
  }

  private void assertStablePrefix(CharacterProfile profile) {
    if (!config.debugMode()) {
      return;
    }
    int hash = profile.renderPromptBlock().hashCode();
    Integer seen = prefixHashes.putIfAbsent(profile.cacheKey(), hash);
    if (seen != null && seen != hash) {
      log.warn(
          "[TTS cloud] cacheable prefix for profile '{}' changed across calls (prompt cache will"
              + " miss); cacheKey={}",
          profile.name(),
          profile.cacheKey());
    }
  }

  private final class Ops implements CloudSpeechExecutor.Ops {

    @Override
    public String apiKey() {
      return config.openRouterApiKey();
    }

    @Override
    public String missingKeyNotice() {
      return NO_KEY_NOTICE;
    }

    @Override
    public String translate(String text, String language, String apiKey) {
      String translated = translator.translate(text, language, apiKey);
      if (translated != null) {
        support.recordTranslationSpend(text.length());
      }
      return translated;
    }

    @Override
    public void profileApplied(CharacterProfile profile) {
      assertStablePrefix(profile);
    }

    @Override
    public CloudSpeechExecutor.PreparedSpeech buildRequests(
        CloudSpeechExecutor.SpokenLine line, SynthesisRequest request) {
      JsonObject payload = new JsonObject();
      payload.addProperty("model", model.modelId());
      payload.addProperty("input", line.input);
      payload.addProperty("voice", model.voiceFor(request.voice()));
      payload.addProperty("response_format", model.responseFormat());
      if (line.speedPercent != CloudBackendSupport.DEFAULT_SPEED_PERCENT) {
        payload.addProperty("speed", line.speedRatio);
      }
      if (line.translating) {
        payload.addProperty("language_code", config.cloudLanguage().code());
      }
      OpenRouterProvider.apply(payload);

      Request httpRequest =
          OpenRouterProvider.attributedRequest(endpoint, line.apiKey)
              .post(
                  RequestBody.create(
                      CloudHttp.JSON_MEDIA_TYPE,
                      gson.toJson(payload).getBytes(StandardCharsets.UTF_8)))
              .build();
      return new CloudSpeechExecutor.PreparedSpeech(
          httpRequest, line.speedRatio, line.input.length(), request.prefetch());
    }

    @Override
    public Call newCall(Request httpRequest, int inputLength) {
      Call call = httpClient.newCall(httpRequest);
      call.timeout().timeout(callBudgetFor(inputLength).toMillis(), TimeUnit.MILLISECONDS);
      return call;
    }

    @Override
    public String generationId(Response response) {
      return CloudHttp.headerOrEmpty(response, "X-Generation-Id");
    }

    @Override
    public CloudSpeechExecutor.DecodedSpeech decodeBuffered(
        byte[] bytes, CloudSpeechExecutor.PreparedSpeech prepared) {
      if (bytes.length == 0) {
        return CloudSpeechExecutor.DecodedSpeech.EMPTY;
      }
      return new CloudSpeechExecutor.DecodedSpeech(
          model.decodeResponse(bytes),
          bytes.length,
          () -> support.recordSpeechSpend(prepared.inputLen, prepared.prefetch));
    }

    @Override
    public CloudSpeechExecutor.StreamDrain newStreamDrain() {
      return OpenRouterTtsBackend::drainRawBody;
    }

    @Override
    public void recordSpendOnFirstChunk(CloudSpeechExecutor.PreparedSpeech prepared) {
      support.recordSpeechSpend(prepared.inputLen, prepared.prefetch);
    }

    @Override
    public String failureNotice(int httpCode, byte[] body) {
      return OpenRouterTtsBackend.failureNotice(httpCode);
    }

    @Override
    public String emptyBodyNotice() {
      return "OpenRouter TTS returned an empty response; this line was not voiced.";
    }
  }

  private static void drainRawBody(ResponseBody body, CloudSpeechExecutor.ChunkSink chunk)
      throws IOException {
    InputStream in = body.byteStream();
    byte[] buffer = new byte[STREAM_READ_BUFFER];
    int read;
    while ((read = in.read(buffer)) != -1) {
      if (read == 0) {
        continue;
      }
      chunk.accept(buffer, read);
    }
  }
}

package com.grahambartley.runelite.voiced.dialogue.speech.openrouter;

import com.google.gson.JsonObject;
import com.grahambartley.runelite.voiced.dialogue.speech.CloudHttp;
import okhttp3.Request;

final class OpenRouterProvider {

  static final String THROUGHPUT_SORT = "throughput";

  static final String APP_TITLE = "RuneLite Voiced Dialogue";

  static final String APP_URL = "https://github.com/grabartley/runelite-voiced-dialogue";

  private OpenRouterProvider() {}

  static void apply(JsonObject body) {
    JsonObject provider = new JsonObject();
    provider.addProperty("sort", THROUGHPUT_SORT);
    body.add("provider", provider);
  }

  static Request.Builder attributedRequest(String url, String apiKey) {
    return new Request.Builder()
        .url(url)
        .addHeader("Authorization", "Bearer " + apiKey)
        .addHeader("User-Agent", CloudHttp.USER_AGENT)
        .addHeader("HTTP-Referer", APP_URL)
        .addHeader("X-Title", APP_TITLE);
  }
}

package com.grahambartley.runelite.voiced.dialogue.speech.openrouter;

public final class OpenRouterCreditMeter {

  private Double baseline;

  private String baselineKey;

  public synchronized void recordBaseline(String apiKey, Double usage) {
    if (usage == null) {
      return;
    }
    if (baseline != null && sameKey(apiKey)) {
      return;
    }
    baseline = usage;
    baselineKey = apiKey == null ? null : apiKey.trim();
  }

  public synchronized Double spentSince(String apiKey, Double currentUsage) {
    if (baseline == null || currentUsage == null || !sameKey(apiKey)) {
      return null;
    }
    return Math.max(0, currentUsage - baseline);
  }

  public synchronized boolean hasBaselineFor(String apiKey) {
    return baseline != null && sameKey(apiKey);
  }

  public synchronized void reset() {
    baseline = null;
    baselineKey = null;
  }

  private boolean sameKey(String apiKey) {
    String trimmed = apiKey == null ? null : apiKey.trim();
    return baselineKey == null ? trimmed == null : baselineKey.equals(trimmed);
  }
}

package com.grahambartley.runelite.voiced.dialogue.speech;

import com.grahambartley.runelite.voiced.dialogue.VoicedDialogueConfig;
import java.io.IOException;
import lombok.extern.slf4j.Slf4j;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;

@Slf4j
public final class CloudTranslatorCall {

  public interface Ops {

    Request buildRequest(String text, String language, String apiKey);

    String extractText(String raw);
  }

  public static final class Outcome {
    public final String text;
    public final String raw;

    public Outcome(String text, String raw) {
      this.text = text;
      this.raw = raw;
    }
  }

  private CloudTranslatorCall() {}

  public static Outcome run(
      OkHttpClient httpClient,
      VoicedDialogueConfig config,
      Ops ops,
      String text,
      String language,
      String apiKey) {
    Request httpRequest = ops.buildRequest(text, language, apiKey);
    long start = System.nanoTime();
    try (Response response = httpClient.newCall(httpRequest).execute()) {
      ResponseBody body = response.body();
      String raw = body == null ? "" : body.string();
      long elapsedMs = CloudHttp.elapsedMs(start);
      if (!response.isSuccessful()) {
        log.warn(
            "[TTS cloud] translate fail reason=non-2xx http={} elapsedMs={} inLen={} detail={}",
            response.code(),
            elapsedMs,
            text.length(),
            response.message());
        return null;
      }
      String translated = ops.extractText(raw);
      if (translated == null || translated.isEmpty()) {
        log.warn(
            "[TTS cloud] translate fail reason=no-content http={} elapsedMs={} inLen={}",
            response.code(),
            elapsedMs,
            text.length());
        return null;
      }
      if (config.debugMode()) {
        log.info(
            "[TTS cloud] translate ok lang={} elapsedMs={} inLen={} outLen={} -> \"{}\"",
            language,
            elapsedMs,
            text.length(),
            translated.length(),
            translated);
      }
      return new Outcome(translated, raw);
    } catch (IOException | RuntimeException e) {
      log.warn(
          "[TTS cloud] translate fail reason=error elapsedMs={} inLen={} detail={}",
          CloudHttp.elapsedMs(start),
          text.length(),
          e.getMessage());
      return null;
    }
  }
}

package com.grahambartley.runelite.voiced.dialogue.speech;

import com.grahambartley.runelite.voiced.dialogue.VoicedDialogueConfig;
import java.util.Set;

public final class BackendWarmUpPolicy {

  private static final Set<String> WARM_TRIGGER_KEYS =
      Set.of(
          VoicedDialogueConfig.OPENROUTER_API_KEY,
          VoicedDialogueConfig.GOOGLE_AI_STUDIO_API_KEY,
          VoicedDialogueConfig.PROVIDER_KEY);

  private BackendWarmUpPolicy() {}

  public static boolean affectsBackendWarmUp(String group, String key) {
