package com.grahambartley.runelite.voiced.dialogue.speech.model;

import com.grahambartley.runelite.voiced.dialogue.profile.Emotion;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.Map;

public final class GeminiEmotionStyle {

  static final EnumSet<Emotion> SUPPORTED =
      EnumSet.of(Emotion.NEUTRAL, Emotion.HAPPY, Emotion.SAD, Emotion.ANGRY, Emotion.SCARED);

  private static final Map<Emotion, String> TAGS = new EnumMap<>(Emotion.class);

  static {
    TAGS.put(Emotion.HAPPY, "happy");
    TAGS.put(Emotion.SAD, "sad");
    TAGS.put(Emotion.ANGRY, "angry");
    TAGS.put(Emotion.SCARED, "fearful");
  }

  private GeminiEmotionStyle() {}

  public static String tagFor(Emotion emotion) {
    return emotion == null ? null : TAGS.get(emotion);
  }

  static String apply(String input, Emotion emotion) {
    String tag = tagFor(emotion);
    if (tag == null) {
      return input;
    }
    return "[" + tag + "] " + input;
  }
}

package com.grahambartley.runelite.voiced.dialogue.speech;

import com.grahambartley.runelite.voiced.dialogue.profile.CharacterProfile;

final class CloudCacheKeyBuilder {

  private CloudCacheKeyBuilder() {}

  static String build(
      String modelId,
      String voice,
      int speedPercent,
      CharacterProfile profile,
      String language,
      boolean skipTranslation) {
    StringBuilder variant = new StringBuilder(modelId).append('|').append(voice);
    if (speedPercent != CloudBackendSupport.DEFAULT_SPEED_PERCENT) {
      variant.append("|s").append(speedPercent);
    }
    variant.append("|p").append(profile.cacheKey());
    if (CloudTtsText.needsTranslation(language) && !skipTranslation) {
      variant.append("|l").append(language.toLowerCase());
    }
    return variant.toString();
  }
}

package com.grahambartley.runelite.voiced.dialogue.speech;

import com.grahambartley.runelite.voiced.dialogue.VoicedDialogueConfig;
import com.grahambartley.runelite.voiced.dialogue.audio.CaveEchoPolicy;
import com.grahambartley.runelite.voiced.dialogue.profile.Emotion;
import com.grahambartley.runelite.voiced.dialogue.profile.EmotionResolver;
import com.grahambartley.runelite.voiced.dialogue.profile.ResolvedSpeaker;
import com.grahambartley.runelite.voiced.dialogue.profile.Speaker;
import com.grahambartley.runelite.voiced.dialogue.profile.VoiceManager;
import com.grahambartley.runelite.voiced.dialogue.profile.VoiceTraceFormatter;
import java.util.function.IntSupplier;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.NPC;

@Slf4j
public final class SynthesisDispatcher {

  private final VoiceManager voiceManager;
  private final EmotionResolver emotionResolver;
  private final CaveEchoPolicy caveEchoPolicy;
  private final VoicedDialogueConfig config;
  private final BackendProvider backendProvider;
  private final DialogueAudioService audioService;

  public SynthesisDispatcher(
      VoiceManager voiceManager,
      EmotionResolver emotionResolver,
      CaveEchoPolicy caveEchoPolicy,
      VoicedDialogueConfig config,
      BackendProvider backendProvider,
      DialogueAudioService audioService) {
    this.voiceManager = voiceManager;
    this.emotionResolver = emotionResolver;
    this.caveEchoPolicy = caveEchoPolicy;
    this.config = config;
    this.backendProvider = backendProvider;
    this.audioService = audioService;
  }

  public void speakDialogue(String text, Speaker speaker, String npcName, int headAnimationId) {
    Emotion emotion = emotionResolver.resolve(headAnimationId, config.cloudEmotion());
    if (config.debugMode()) {
      log.info("[TTS voice] resolved emotion {} for head animation {}", emotion, headAnimationId);
    }
    ResolvedSpeaker resolved = voiceManager.resolve(speaker, npcName);
    boolean player = speaker == Speaker.PLAYER;
    dispatch(
        new SynthesisRequest(text, resolved.voice(), emotion, resolved.profile(), false, player),
        npcName);
  }

  public void speakPublicChat(String text) {
    ResolvedSpeaker resolved = voiceManager.resolve(Speaker.PLAYER, null);
    dispatch(
        new SynthesisRequest(
            text, resolved.voice(), Emotion.NEUTRAL, resolved.profile(), true, true),
        null);
  }

  public void speakAmbient(String text, NPC npc, IntSupplier distanceVolume) {
    SynthesisBackend backend = backendProvider.active();
    if (!backend.isAvailable() || backend.isThrottled()) {
      return;
    }
    ResolvedSpeaker resolved = voiceManager.resolveNpc(npc);
    SynthesisRequest request =
        new SynthesisRequest(
            text, resolved.voice(), Emotion.NEUTRAL, resolved.profile(), false, false);
    trace(backend, request, npc.getName());
    audioService.speakAmbient(request, echoFor(request), npc.getIndex(), distanceVolume);
  }

  public void speakNarration(String text) {
    ResolvedSpeaker resolved = voiceManager.resolveNarrator();
    dispatch(
        new SynthesisRequest(
            text, resolved.voice(), Emotion.NEUTRAL, resolved.profile(), false, false),
        null);
  }

  private void dispatch(SynthesisRequest request, String npcName) {
    SynthesisBackend backend = backendProvider.active();
    if (!backend.isAvailable()) {
      return;
    }
    trace(backend, request, npcName);
    audioService.speak(request, echoFor(request));
  }

  private boolean echoFor(SynthesisRequest request) {
    return !request.voice().narrator() && caveEchoPolicy.shouldEcho();
  }

  private void trace(SynthesisBackend backend, SynthesisRequest request, String npcName) {
    if (!config.debugMode()) {
      return;
    }
    Emotion effective = BackendProvider.downgradeFor(backend, request).emotion();
    log.info(
        VoiceTraceFormatter.buildResolvedLine(
            backend.id(), request.voice(), npcName, effective.name(), request.profile()));
  }
}

package com.grahambartley.runelite.voiced.dialogue.speech;

import com.grahambartley.runelite.voiced.dialogue.VoicedDialogueConfig;
import com.grahambartley.runelite.voiced.dialogue.audio.Pcm;
import com.grahambartley.runelite.voiced.dialogue.audio.PcmCompleteness;
import com.grahambartley.runelite.voiced.dialogue.audio.PcmSink;
import com.grahambartley.runelite.voiced.dialogue.audio.StreamingPcmDecoder;
import com.grahambartley.runelite.voiced.dialogue.profile.CharacterProfile;
import com.grahambartley.runelite.voiced.dialogue.speech.model.GeminiEmotionStyle;
import com.grahambartley.runelite.voiced.dialogue.speech.model.GeminiTtsModel;
import java.io.IOException;
import java.net.ConnectException;
import java.util.ArrayList;
import java.util.List;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;

@Slf4j
public final class CloudSpeechExecutor {

  public static final int MAX_SPEECH_ATTEMPTS = 2;

  public interface Ops {

    public String apiKey();

    String missingKeyNotice();

    String translate(String text, String language, String apiKey);

    default void profileApplied(CharacterProfile profile) {}

    PreparedSpeech buildRequests(SpokenLine line, SynthesisRequest request);

    Call newCall(Request httpRequest, int inputLen);

    default String generationId(Response response) {
      return "";
    }

    DecodedSpeech decodeBuffered(byte[] bytes, PreparedSpeech prepared);

    StreamDrain newStreamDrain();

    default void recordSpendOnFirstChunk(PreparedSpeech prepared) {}

    String failureNotice(int httpCode, byte[] body);

    default long statedWaitMillis(byte[] body) {
      return 0;
    }

    String emptyBodyNotice();
  }

  public interface StreamDrain {

    void drain(ResponseBody body, ChunkSink chunk) throws IOException;

    default boolean finishedCleanly() {
      return true;
    }

    default void bankSpend(PreparedSpeech prepared) {}
  }

  public interface ChunkSink {
    void accept(byte[] bytes, int len);
  }

  public static final class SpokenLine {
    public final String apiKey;
    public final String input;
    public final boolean translating;
    public final double speedRatio;
    public final int speedPercent;

    public SpokenLine(
        String apiKey, String input, boolean translating, double speedRatio, int speedPercent) {
      this.apiKey = apiKey;
      this.input = input;
      this.translating = translating;
      this.speedRatio = speedRatio;
      this.speedPercent = speedPercent;
    }
  }

  public static final class PreparedSpeech {
    final Request buffered;
    final Request streaming;
    public final double speedRatio;
    public final int inputLen;
    public final boolean prefetch;

    public PreparedSpeech(
        Request buffered, Request streaming, double speedRatio, int inputLen, boolean prefetch) {
      this.buffered = buffered;
      this.streaming = streaming;
      this.speedRatio = speedRatio;
      this.inputLen = inputLen;
      this.prefetch = prefetch;
    }

    public PreparedSpeech(Request request, double speedRatio, int inputLen, boolean prefetch) {
      this(request, request, speedRatio, inputLen, prefetch);
    }
  }

  public static final class DecodedSpeech {

    public static final DecodedSpeech EMPTY = new DecodedSpeech(null, 0, () -> {});

    final Pcm pcm;
    final int audioBytes;

    final Runnable bankSpend;

    public DecodedSpeech(Pcm pcm, int audioBytes, Runnable bankSpend) {
      this.pcm = pcm;
      this.audioBytes = audioBytes;
      this.bankSpend = bankSpend;
    }
  }

  private final VoicedDialogueConfig config;
  private final CloudBackendSupport support;
  private final GeminiTtsModel model;
  private final String providerName;
  private final String cacheModelId;
  private final Ops ops;
  private final RateLimitBackoff backoff = new RateLimitBackoff();

  public CloudSpeechExecutor(
      VoicedDialogueConfig config,
      CloudBackendSupport support,
      GeminiTtsModel model,
      String providerName,
      String cacheModelId,
      Ops ops) {
    this.config = config;
    this.support = support;
    this.model = model;
    this.providerName = providerName;
    this.cacheModelId = cacheModelId;
    this.ops = ops;
  }

  public boolean isThrottled() {
    return backoff.isThrottled();
  }

  public void clearRateLimit() {
    backoff.reset();
  }

  public String cacheVariant(SynthesisRequest request) {
    return CloudCacheKeyBuilder.build(
        cacheModelId,
        model.voiceFor(request.voice()),
        support.speedPercent(),
        request.profile(),
        CloudTtsText.effectiveSpokenLanguage(config, request),
        request.skipTranslation());
  }

  public Pcm synthesize(SynthesisRequest request) {
    PreparedSpeech prepared = prepare(request);
    if (prepared == null) {
      return null;
    }
    return runBuffered(prepared);
  }

  public Pcm synthesizeStreaming(SynthesisRequest request, PcmSink sink) {
    PreparedSpeech prepared = prepare(request);
    if (prepared == null) {
      return null;
    }
    return runStreaming(prepared, sink);
  }

  private PreparedSpeech prepare(SynthesisRequest request) {
    if (backoff.isRefusing()) {
      log.debug("[TTS cloud] {} asked to be left alone; this line was not voiced", providerName);
      return null;
    }
    String rawKey = ops.apiKey();
    if (!CloudHttp.isNonBlank(rawKey)) {
      support.noticeMissingKey(ops.missingKeyNotice());
      return null;
    }
    String apiKey = rawKey.trim();
    String text = request.text();
    String language = CloudTtsText.effectiveSpokenLanguage(config, request);
    boolean translating =
        CloudTtsText.needsTranslation(language) && !request.skipTranslation() && !text.isEmpty();
    String spokenText = text;
    if (translating) {
      String translated = ops.translate(text, language.trim(), apiKey);
      if (translated == null) {
        support.warnOnce(
            providerName
                + " translation to "
                + language.trim()
                + " failed; this line was not voiced.");
        return null;
      }
      spokenText = translated;
    }
    String styledInput = model.styleInput(spokenText, request.emotion());
    CharacterProfile profile = request.profile();
    String input = profile.renderPromptBlock() + styledInput;
    ops.profileApplied(profile);
    int speed = support.speedPercent();
    double speedRatio = speed / (double) CloudBackendSupport.DEFAULT_SPEED_PERCENT;

    if (config.debugMode()) {
      String tag = GeminiEmotionStyle.tagFor(request.emotion());
      log.info(
          "[TTS voice] cloud emotion {} -> {}",
          request.emotion(),
          tag == null ? "no tag (neutral input)" : "inline tag [" + tag + "]");
      log.info(
          "[TTS cloud] character profile '{}' accent='{}' (cacheKey={})",
          profile.name(),
          profile.accent(),
          profile.cacheKey());
      if (speed != CloudBackendSupport.DEFAULT_SPEED_PERCENT) {
        log.info("[TTS cloud] speed {}", speedRatio);
      }
    }

    return ops.buildRequests(
        new SpokenLine(apiKey, input, translating, speedRatio, speed), request);
  }

  private Pcm runBuffered(PreparedSpeech prepared) {
    for (int attempt = 1; attempt <= MAX_SPEECH_ATTEMPTS; attempt++) {
      long attemptStart = System.nanoTime();
      long backoffGeneration = backoff.generation();
      try (Response response = ops.newCall(prepared.buffered, prepared.inputLen).execute()) {
        ResponseBody body = response.body();
        byte[] bytes = body == null ? CloudHttp.EMPTY_BODY : body.bytes();
        String contentType = CloudHttp.headerOrEmpty(response, "Content-Type");
        String generationId = ops.generationId(response);
        long elapsedMs = CloudHttp.elapsedMs(attemptStart);

        if (!response.isSuccessful()) {
          if (response.code() == CloudHttp.HTTP_TOO_MANY_REQUESTS) {
            backoff.recordRateLimited(statedWait(response, bytes), backoffGeneration);
          }
          support.warnOnce(ops.failureNotice(response.code(), bytes));
          support.logFailure(
              "non-2xx",
              attempt,
              elapsedMs,
              prepared.inputLen,
              response.code(),
              response.message(),
              contentType,
              generationId,
              bytes);
          return null;
        }
        backoff.recordSuccess();
        DecodedSpeech decoded = ops.decodeBuffered(bytes, prepared);
        if (decoded.audioBytes == 0) {
          support.logFailure(
              "empty-body",
              attempt,
              elapsedMs,
              prepared.inputLen,
              response.code(),
              response.message(),
              contentType,
              generationId,
              bytes);
          if (attempt < MAX_SPEECH_ATTEMPTS) {
            log.debug(CloudSynthTrace.retry("empty-body", attempt, MAX_SPEECH_ATTEMPTS, elapsedMs));
            continue;
          }
          support.warnOnce(ops.emptyBodyNotice());
          return null;
        }
        if (decoded.pcm == null) {
          support.warnOnce(
              providerName
                  + " TTS returned audio that could not be decoded; this line was not voiced.");
          support.logFailure(
              "undecodable",
              attempt,
              elapsedMs,
              prepared.inputLen,
              response.code(),
              response.message(),
              contentType,
              generationId,
              bytes);
          return null;
        }
        if (PcmCompleteness.isTruncated(decoded.pcm, prepared.speedRatio)) {
          if (attempt < MAX_SPEECH_ATTEMPTS) {
            log.debug(CloudSynthTrace.retry("truncated", attempt, MAX_SPEECH_ATTEMPTS, elapsedMs));
            continue;
          }
          support.warnOnce(
              providerName + " TTS returned a truncated line; this line was not voiced.");
          support.logFailure(
              "truncated",
              attempt,
              elapsedMs,
              prepared.inputLen,
              response.code(),
              response.message(),
              contentType,
              generationId,
              bytes);
          return null;
        }
        if (config.debugMode()) {
          log.info(
              CloudSynthTrace.success(
                  attempt,
                  MAX_SPEECH_ATTEMPTS,
                  elapsedMs,
                  prepared.inputLen,
                  decoded.audioBytes,
                  generationId));
        }
        decoded.bankSpend.run();
        return decoded.pcm;
      } catch (ConnectException e) {
        support.warnOnce(networkNotice());
        support.logNetworkFailure(
            "connect", attempt, CloudHttp.elapsedMs(attemptStart), prepared.inputLen, e);
        return null;
      } catch (IOException e) {
        long elapsedMs = CloudHttp.elapsedMs(attemptStart);
        if (attempt < MAX_SPEECH_ATTEMPTS) {
          log.debug(CloudSynthTrace.retry("network", attempt, MAX_SPEECH_ATTEMPTS, elapsedMs));
          support.backoffBeforeNetworkRetry(attempt);
          continue;
        }
        support.warnOnce(networkNotice());
        support.logNetworkFailure("network", attempt, elapsedMs, prepared.inputLen, e);
        return null;
      } catch (RuntimeException e) {
        support.warnOnce(
            providerName + " TTS request failed unexpectedly; this line was not voiced.");
        support.logNetworkFailure(
            "unexpected", attempt, CloudHttp.elapsedMs(attemptStart), prepared.inputLen, e);
        return null;
      }
    }
    return null;
  }

  private Pcm runStreaming(PreparedSpeech prepared, PcmSink sink) {
    int rate = model.sampleRate();
    for (int attempt = 1; attempt <= MAX_SPEECH_ATTEMPTS; attempt++) {
      long attemptStart = System.nanoTime();
      StreamDrain drain = ops.newStreamDrain();
      Accumulator acc = new Accumulator(prepared, sink, rate, attemptStart);
      long backoffGeneration = backoff.generation();
      try (Response response = ops.newCall(prepared.streaming, prepared.inputLen).execute()) {
        String contentType = CloudHttp.headerOrEmpty(response, "Content-Type");
        String generationId = ops.generationId(response);
        if (!response.isSuccessful()) {
          byte[] bytes = CloudHttp.errorBody(response);
          if (response.code() == CloudHttp.HTTP_TOO_MANY_REQUESTS) {
            backoff.recordRateLimited(statedWait(response, bytes), backoffGeneration);
          }
          support.warnOnce(ops.failureNotice(response.code(), bytes));
          support.logFailure(
              "non-2xx",
              attempt,
              CloudHttp.elapsedMs(attemptStart),
              prepared.inputLen,
              response.code(),
              response.message(),
              contentType,
              generationId,
              bytes);
          return null;
        }
        backoff.recordSuccess();
        ResponseBody body = response.body();
        if (body != null) {
          drain.drain(body, acc);
        }
        long elapsedMs = CloudHttp.elapsedMs(attemptStart);
        if (acc.totalBytes == 0) {
          support.logFailure(
              "empty-body",
              attempt,
              elapsedMs,
              prepared.inputLen,
              response.code(),
              response.message(),
              contentType,
              generationId,
              CloudHttp.EMPTY_BODY);
          if (attempt < MAX_SPEECH_ATTEMPTS) {
            log.debug(CloudSynthTrace.retry("empty-body", attempt, MAX_SPEECH_ATTEMPTS, elapsedMs));
            continue;
          }
          support.warnOnce(ops.emptyBodyNotice());
          return null;
        }
        drain.bankSpend(prepared);
        if (config.debugMode()) {
          log.info(
              "{} firstChunkMs={}",
              CloudSynthTrace.success(
                  attempt,
                  MAX_SPEECH_ATTEMPTS,
                  elapsedMs,
                  prepared.inputLen,
                  (int) acc.totalBytes,
                  generationId),
              acc.firstChunkMs);
        }
        Pcm pcm = new Pcm(flatten(acc.chunks, acc.sampleCount), rate);
        if (!drain.finishedCleanly()
            || acc.decoder.hasPendingByte()
            || PcmCompleteness.isTruncated(pcm, prepared.speedRatio)) {
          log.debug("[TTS cloud] streamed line played but not cached (incomplete tail)");
          return null;
        }
        return pcm;
      } catch (ConnectException e) {
        support.warnOnce(networkNotice());
        support.logNetworkFailure(
            "connect", attempt, CloudHttp.elapsedMs(attemptStart), prepared.inputLen, e);
        return null;
      } catch (IOException e) {
        long elapsedMs = CloudHttp.elapsedMs(attemptStart);
        if (!acc.fedSink && attempt < MAX_SPEECH_ATTEMPTS) {
          log.debug(CloudSynthTrace.retry("network", attempt, MAX_SPEECH_ATTEMPTS, elapsedMs));
          support.backoffBeforeNetworkRetry(attempt);
          continue;
        }
        support.warnOnce(networkNotice());
        support.logNetworkFailure("network", attempt, elapsedMs, prepared.inputLen, e);
        return null;
      } catch (RuntimeException e) {
        support.warnOnce(
            providerName + " TTS request failed unexpectedly; this line was not voiced.");
        support.logNetworkFailure(
            "unexpected", attempt, CloudHttp.elapsedMs(attemptStart), prepared.inputLen, e);
        return null;
      }
    }
    return null;
  }

  private long statedWait(Response response, byte[] body) {
    return Math.max(CloudHttp.retryAfterMillis(response), ops.statedWaitMillis(body));
  }

  private String networkNotice() {
    return providerName + " TTS request could not reach the network; this line was not voiced.";
  }

  private final class Accumulator implements ChunkSink {
    final StreamingPcmDecoder decoder = new StreamingPcmDecoder();
    final List<float[]> chunks = new ArrayList<>();
    int sampleCount;
    long totalBytes;
    boolean fedSink;
    long firstChunkMs = -1;

    private final PreparedSpeech prepared;
    private final PcmSink sink;
    private final int rate;
    private final long attemptStart;

    Accumulator(PreparedSpeech prepared, PcmSink sink, int rate, long attemptStart) {
      this.prepared = prepared;
      this.sink = sink;
      this.rate = rate;
      this.attemptStart = attemptStart;
    }

    @Override
    public void accept(byte[] bytes, int len) {
      totalBytes += len;
      float[] chunk = decoder.decode(bytes, len);
      if (chunk.length > 0) {
        sink.accept(chunk, rate);
        if (!fedSink) {
          firstChunkMs = CloudHttp.elapsedMs(attemptStart);
          ops.recordSpendOnFirstChunk(prepared);
        }
        fedSink = true;
        chunks.add(chunk);
        sampleCount += chunk.length;
      }
    }
  }

  private static float[] flatten(List<float[]> chunks, int totalSamples) {
    float[] out = new float[totalSamples];
    int pos = 0;
    for (float[] chunk : chunks) {
      System.arraycopy(chunk, 0, out, pos, chunk.length);
      pos += chunk.length;
    }
    return out;
  }
}

package com.grahambartley.runelite.voiced.dialogue.speech;

import java.time.Duration;

public final class RetryTuning {

  private static final Duration CONNECT_TIMEOUT = Duration.ofSeconds(2);

  private static final Duration OPEN_ROUTER_CEILING = Duration.ofSeconds(120);

  private static final Duration AI_STUDIO_CEILING = Duration.ofSeconds(60);

  private static final long NETWORK_RETRY_BASE_MILLIS = 400;

  private static final long NETWORK_RETRY_JITTER_MILLIS = 250;

  final Duration connectTimeout;
  final Duration readTimeout;
  public final Duration callTimeout;
  final long retryBackoffBaseMillis;
  final long retryJitterMillis;

  public RetryTuning(
      Duration connectTimeout,
      Duration readTimeout,
      Duration callTimeout,
      long retryBackoffBaseMillis,
      long retryJitterMillis) {
    this.connectTimeout = connectTimeout;
    this.readTimeout = readTimeout;
    this.callTimeout = callTimeout;
    this.retryBackoffBaseMillis = retryBackoffBaseMillis;
    this.retryJitterMillis = retryJitterMillis;
  }

  public static RetryTuning openRouter() {
    return ceiling(OPEN_ROUTER_CEILING);
  }

  public static RetryTuning googleAiStudio() {
    return ceiling(AI_STUDIO_CEILING);
  }

  private static RetryTuning ceiling(Duration ceiling) {
    return new RetryTuning(
        CONNECT_TIMEOUT, ceiling, ceiling, NETWORK_RETRY_BASE_MILLIS, NETWORK_RETRY_JITTER_MILLIS);
  }
}

package com.grahambartley.runelite.voiced.dialogue.speech.spend;

import com.grahambartley.runelite.voiced.dialogue.VoicedDialogueConfig.TtsProvider;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicLong;
import lombok.Value;
import lombok.experimental.Accessors;

public final class SpendTracker {

  @Value
  @Accessors(fluent = true)
  public static class ProviderSpend {
    TtsProvider provider;
    long voicedLines;
    long prefetchedLines;
    long speechCharacters;
    long translationCalls;
    long translationCharacters;

    long audioTokens;

    long speechPromptTokens;

    long translationInputTokens;

    long translationOutputTokens;
  }

  private final Map<TtsProvider, Counters> byProvider = new ConcurrentHashMap<>();

  public void recordSpeech(TtsProvider provider, int characters, boolean prefetch) {
    recordSpeech(provider, characters, prefetch, 0, 0);
  }

  public void recordSpeech(
      TtsProvider provider, int characters, boolean prefetch, long audioTokens, long promptTokens) {
    Counters counters = counters(provider);
    if (prefetch) {
      counters.prefetchedLines.incrementAndGet();
    } else {
      counters.voicedLines.incrementAndGet();
    }
    counters.speechCharacters.addAndGet(Math.max(0, characters));
    counters.audioTokens.addAndGet(Math.max(0, audioTokens));
    counters.speechPromptTokens.addAndGet(Math.max(0, promptTokens));
  }

  public void recordTranslation(TtsProvider provider, int characters) {
    recordTranslation(provider, characters, 0, 0);
  }

  public void recordTranslation(
      TtsProvider provider, int characters, long inputTokens, long outputTokens) {
    Counters counters = counters(provider);
    counters.translationCalls.incrementAndGet();
    counters.translationCharacters.addAndGet(Math.max(0, characters));
    counters.translationInputTokens.addAndGet(Math.max(0, inputTokens));
    counters.translationOutputTokens.addAndGet(Math.max(0, outputTokens));
  }

  public List<ProviderSpend> snapshot() {
    List<ProviderSpend> out = new ArrayList<>(byProvider.size());
    for (TtsProvider provider : TtsProvider.values()) {
      Counters counters = byProvider.get(provider);
      if (counters != null) {
        out.add(counters.toSpend(provider));
      }
    }
    return out;
  }

  private Counters counters(TtsProvider provider) {
    return byProvider.computeIfAbsent(provider, p -> new Counters());
  }

  private static final class Counters {
    final AtomicLong voicedLines = new AtomicLong();
    final AtomicLong prefetchedLines = new AtomicLong();
    final AtomicLong speechCharacters = new AtomicLong();
    final AtomicLong translationCalls = new AtomicLong();
    final AtomicLong translationCharacters = new AtomicLong();
    final AtomicLong audioTokens = new AtomicLong();
    final AtomicLong speechPromptTokens = new AtomicLong();
    final AtomicLong translationInputTokens = new AtomicLong();
    final AtomicLong translationOutputTokens = new AtomicLong();

    ProviderSpend toSpend(TtsProvider provider) {
      return new ProviderSpend(
          provider,
          voicedLines.get(),
          prefetchedLines.get(),
          speechCharacters.get(),
          translationCalls.get(),
          translationCharacters.get(),
          audioTokens.get(),
          speechPromptTokens.get(),
          translationInputTokens.get(),
          translationOutputTokens.get());
    }
  }
}

package com.grahambartley.runelite.voiced.dialogue.speech.spend;

public final class SpendPricing {

  static final double AUDIO_USD_PER_TOKEN = 10.00 / 1_000_000;

  static final double SPEECH_TEXT_USD_PER_TOKEN = 0.50 / 1_000_000;

  static final double TRANSLATION_INPUT_USD_PER_TOKEN = 0.10 / 1_000_000;

  static final double TRANSLATION_OUTPUT_USD_PER_TOKEN = 0.40 / 1_000_000;

  private SpendPricing() {}

  public static double estimateSpeechUsd(long audioTokens, long promptTokens) {
    return Math.max(0, audioTokens) * AUDIO_USD_PER_TOKEN
        + Math.max(0, promptTokens) * SPEECH_TEXT_USD_PER_TOKEN;
  }

  public static double estimateTranslationUsd(long inputTokens, long outputTokens) {
    return Math.max(0, inputTokens) * TRANSLATION_INPUT_USD_PER_TOKEN
        + Math.max(0, outputTokens) * TRANSLATION_OUTPUT_USD_PER_TOKEN;
  }
}

package com.grahambartley.runelite.voiced.dialogue.speech.spend;

import com.grahambartley.runelite.voiced.dialogue.VoicedDialogueConfig.TtsProvider;
import com.grahambartley.runelite.voiced.dialogue.speech.spend.SpendTracker.ProviderSpend;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Locale;

public final class SpendReport {

  public static final String COMMAND = "voicedspend";

  private static final String NOTHING_SPENT =
      "Nothing has been voiced this session, so nothing has been spent.";

  private static final double SMALLEST_SHOWN_USD = 0.0001;

  private SpendReport() {}

  public static boolean matches(String command) {
    return command != null && COMMAND.equalsIgnoreCase(command.trim());
  }

  public static List<String> lines(List<ProviderSpend> snapshot, Double openRouterSpentUsd) {
    if (snapshot == null || snapshot.isEmpty()) {
      return Collections.singletonList(NOTHING_SPENT);
    }
    List<String> lines = new ArrayList<>(snapshot.size());
    for (ProviderSpend spend : snapshot) {
      lines.add(
          spend.provider() == TtsProvider.GOOGLE_AI_STUDIO
              ? aiStudioLine(spend)
              : openRouterLine(spend, openRouterSpentUsd));
    }
    return lines;
  }

  private static String openRouterLine(ProviderSpend spend, Double spentUsd) {
    StringBuilder text = counts(spend);
    text.append(count(spend.speechCharacters())).append(" characters sent");
    translation(text, spend);
    if (spentUsd == null) {
      return text.append(
              ". OpenRouter's billed spend could not be read; see openrouter.ai/settings/credits.")
          .toString();
    }
    return text.append(". Spent ")
        .append(usd(spentUsd))
        .append(", billed by OpenRouter.")
        .toString();
  }

  private static String aiStudioLine(ProviderSpend spend) {
    StringBuilder text = counts(spend);
    long tokens =
        spend.audioTokens()
            + spend.speechPromptTokens()
            + spend.translationInputTokens()
            + spend.translationOutputTokens();
    if (tokens == 0) {
      text.append(count(spend.speechCharacters())).append(" characters sent");
      translation(text, spend);
      return text.append(". Google AI Studio reported no token counts, so cost is unknown.")
          .toString();
    }
    text.append(count(spend.audioTokens()))
        .append(" audio tokens, ")
        .append(count(spend.speechPromptTokens()))
        .append(" text tokens");
    translationTokens(text, spend);
    double usd =
        SpendPricing.estimateSpeechUsd(spend.audioTokens(), spend.speechPromptTokens())
            + SpendPricing.estimateTranslationUsd(
                spend.translationInputTokens(), spend.translationOutputTokens());
    return text.append(". Estimated ")
        .append(usd(usd))
        .append(" (tokens measured, price from Google's published rate).")
        .toString();
  }

  private static StringBuilder counts(ProviderSpend spend) {
    return new StringBuilder()
        .append(spend.provider())
        .append(" this session: ")
        .append(count(spend.voicedLines()))
        .append(" lines voiced, ")
        .append(count(spend.prefetchedLines()))
        .append(" prefetched, ");
  }

  private static void translation(StringBuilder text, ProviderSpend spend) {
    if (spend.translationCalls() > 0) {
      text.append(", plus ")
          .append(count(spend.translationCalls()))
          .append(" translation calls (")
          .append(count(spend.translationCharacters()))
          .append(" characters)");
    }
  }

  private static void translationTokens(StringBuilder text, ProviderSpend spend) {
    if (spend.translationCalls() > 0) {
      text.append(", plus ")
          .append(count(spend.translationCalls()))
          .append(" translation calls (")
          .append(count(spend.translationInputTokens() + spend.translationOutputTokens()))
          .append(" tokens)");
    }
  }

  private static String count(long value) {
    return String.format(Locale.US, "%,d", value);
  }

  private static String usd(double value) {
    if (value > 0 && value < SMALLEST_SHOWN_USD) {
      return "under $" + String.format(Locale.US, "%.4f", SMALLEST_SHOWN_USD);
    }
    return String.format(Locale.US, "$%.4f", value);
  }
}

package com.grahambartley.runelite.voiced.dialogue.speech;

