package com.grahambartley.runelite.voiced.dialogue.audio;

public final class StreamingPcmDecoder {

  private static final float[] EMPTY = new float[0];

  private int pendingLowByte = -1;

  public float[] decode(byte[] chunk, int len) {
    if (chunk == null || len <= 0) {
      return EMPTY;
    }
    int totalBytes = len + (pendingLowByte >= 0 ? 1 : 0);
    int sampleCount = totalBytes / 2;
    if (sampleCount == 0) {
      if (pendingLowByte < 0) {
        pendingLowByte = chunk[0] & 0xff;
      }
      return EMPTY;
    }
    float[] out = new float[sampleCount];
    int bi = 0;
    int oi = 0;
    if (pendingLowByte >= 0) {
      out[oi++] = sampleToFloat(pendingLowByte, chunk[bi++]);
      pendingLowByte = -1;
    }
    while (len - bi >= 2) {
      out[oi++] = sampleToFloat(chunk[bi] & 0xff, chunk[bi + 1]);
      bi += 2;
    }
    if (len - bi == 1) {
      pendingLowByte = chunk[bi] & 0xff;
    }
    return out;
  }

  public boolean hasPendingByte() {
    return pendingLowByte >= 0;
  }

  private static float sampleToFloat(int lo, int hi) {
    short s = (short) ((hi << 8) | (lo & 0xff));
    return s / 32768f;
  }
}

package com.grahambartley.runelite.voiced.dialogue.audio;

import java.util.concurrent.BlockingQueue;
import java.util.concurrent.LinkedBlockingQueue;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicLong;
import javax.sound.sampled.AudioFormat;
import javax.sound.sampled.AudioSystem;
import javax.sound.sampled.FloatControl;
import javax.sound.sampled.LineUnavailableException;
import javax.sound.sampled.SourceDataLine;
import lombok.extern.slf4j.Slf4j;

@Slf4j
public class StreamingAudioPlayer implements AudioOutput {

  public interface LineFactory {
    SourceDataLine getLine(AudioFormat format) throws LineUnavailableException;
  }

  private static final int CHUNK_BYTES = 4096;

  private static final int QUEUE_POLL_MS = 20;

  private final LineFactory lineFactory;
  private final AtomicLong generation = new AtomicLong();
  private volatile SourceDataLine line;

  public StreamingAudioPlayer() {
    this(AudioSystem::getSourceDataLine);
  }

  StreamingAudioPlayer(LineFactory lineFactory) {
    this.lineFactory = lineFactory;
  }

  @Override
  public void stream(float[] samples, int sampleRate, int volumePercent) {
    if (samples == null || samples.length == 0) {
      return;
    }
    long gen = generation.incrementAndGet();
    byte[] pcm = PcmAudio.toPcm16LE(samples);
    SourceDataLine sdl = null;
    try {
      sdl = openLine(PcmAudio.format(sampleRate), volumePercent);
      writeChunked(sdl, pcm, gen);
      if (generation.get() == gen) {
        sdl.drain();
      }
    } catch (Exception e) {
      log.warn("Audio playback failed: {}", e.getMessage());
    } finally {
      if (sdl != null) {
        releaseLine(sdl);
      }
    }
  }

  @Override
  public AudioStream beginStream(int volumePercent) {
    long gen = generation.incrementAndGet();
    return new BufferedLineStream(gen, volumePercent);
  }

  @Override
  public void setVolume(int volumePercent) {
    SourceDataLine current = this.line;
    if (current == null) {
      return;
    }
    try {
      applyVolume(current, volumePercent);
    } catch (Exception ignored) {
    }
  }

  @Override
  public void stop() {
    generation.incrementAndGet();
    SourceDataLine current = this.line;
    if (current != null) {
      try {
        current.stop();
        current.flush();
      } catch (Exception ignored) {
      }
    }
  }

  @Override
  public void close() {
    stop();
  }

  private final class BufferedLineStream implements AudioStream {
    private final long gen;
    private final int volumePercent;
    private final BlockingQueue<float[]> queue = new LinkedBlockingQueue<>();
    private volatile int sampleRate = -1;
    private volatile boolean ended;
    private boolean playerStarted;

    private BufferedLineStream(long gen, int volumePercent) {
      this.gen = gen;
      this.volumePercent = volumePercent;
    }

    @Override
    public void write(float[] samples, int sampleRate) {
      if (samples == null || samples.length == 0 || generation.get() != gen) {
        return;
      }
      if (this.sampleRate < 0) {
        this.sampleRate = sampleRate;
      }
      queue.offer(samples);
      startPlayer();
    }

    @Override
    public void end() {
      ended = true;
      startPlayer();
    }

    private synchronized void startPlayer() {
      if (playerStarted || sampleRate < 0) {
        return;
      }
      playerStarted = true;
      Thread player = new Thread(this::playLoop, "dialogue-audio-play");
      player.setDaemon(true);
      player.start();
    }

    private void playLoop() {
      SourceDataLine sdl = null;
      try {
        sdl = openLine(PcmAudio.format(sampleRate), volumePercent);
        while (generation.get() == gen) {
          float[] chunk = queue.poll(QUEUE_POLL_MS, TimeUnit.MILLISECONDS);
          if (chunk == null) {
            if (ended && queue.isEmpty()) {
              break;
            }
            continue;
          }
          writeChunked(sdl, PcmAudio.toPcm16LE(chunk), gen);
        }
        if (generation.get() == gen) {
          sdl.drain();
        }
      } catch (Exception e) {
        log.warn("Audio streaming failed: {}", e.getMessage());
      } finally {
        if (sdl != null) {
          releaseLine(sdl);
        }
      }
    }
  }

  private SourceDataLine openLine(AudioFormat format, int volumePercent)
      throws LineUnavailableException {
    SourceDataLine sdl = lineFactory.getLine(format);
    boolean opened = false;
    try {
      sdl.open(format);
      applyVolume(sdl, volumePercent);
      sdl.start();
      this.line = sdl;
      opened = true;
      return sdl;
    } finally {
      if (!opened) {
        releaseLine(sdl);
      }
    }
  }

  private void writeChunked(SourceDataLine sdl, byte[] pcm, long gen) {
    int offset = 0;
    while (offset < pcm.length && generation.get() == gen) {
      offset += sdl.write(pcm, offset, Math.min(CHUNK_BYTES, pcm.length - offset));
    }
  }

  private void releaseLine(SourceDataLine sdl) {
    try {
      sdl.stop();
      sdl.close();
    } catch (Exception ignored) {
    }
    if (this.line == sdl) {
      this.line = null;
    }
  }

  private static void applyVolume(SourceDataLine line, int volumePercent) {
    if (!line.isControlSupported(FloatControl.Type.MASTER_GAIN)) {
      return;
    }
    FloatControl gain = (FloatControl) line.getControl(FloatControl.Type.MASTER_GAIN);
    int volume = Math.max(0, Math.min(100, volumePercent));
    if (volume == 0) {
      gain.setValue(gain.getMinimum());
      return;
    }
    float db = (float) (20.0 * Math.log10(volume / 100.0));
    gain.setValue(Math.max(gain.getMinimum(), Math.min(gain.getMaximum(), db)));
  }
}

package com.grahambartley.runelite.voiced.dialogue.audio;

public final class PcmCompleteness {

  private static final float SILENCE_FLOOR = 0.02f;

  private static final int MIN_TRAILING_SILENCE_MS = 120;

  private static final int MIN_JUDGED_MS = 500;

  private PcmCompleteness() {}

  public static boolean isTruncated(Pcm pcm, double speedRatio) {
    int rate = pcm.getSampleRate();
    if (rate <= 0) {
      return false;
    }
    float[] samples = pcm.getSamples();
    if (samples.length < msToSamples(MIN_JUDGED_MS, rate)) {
      return false;
    }
    double ratio = speedRatio > 0 ? speedRatio : 1.0;
    int needed = Math.max(1, (int) Math.round(msToSamples(MIN_TRAILING_SILENCE_MS, rate) / ratio));
    int quiet = 0;
    for (int i = samples.length - 1; i >= 0; i--) {
      if (Math.abs(samples[i]) >= SILENCE_FLOOR) {
        break;
      }
      if (++quiet >= needed) {
        return false;
      }
    }
    return true;
  }

  private static int msToSamples(int ms, int rate) {
    return Math.round(ms / 1000f * rate);
  }
}

package com.grahambartley.runelite.voiced.dialogue.audio;

import javax.sound.sampled.AudioFormat;

public final class PcmAudio {

  private PcmAudio() {}

  public static byte[] toPcm16LE(float[] samples) {
    byte[] pcm = new byte[samples.length * 2];
    for (int i = 0; i < samples.length; i++) {
      float clamped = Math.max(-1f, Math.min(1f, samples[i]));
      int s = Math.round(clamped * 32767f);
      pcm[2 * i] = (byte) (s & 0xff);
      pcm[2 * i + 1] = (byte) ((s >> 8) & 0xff);
    }
    return pcm;
  }

  public static AudioFormat format(int sampleRate) {
    return new AudioFormat(sampleRate, 16, 1, true, false);
  }
}

package com.grahambartley.runelite.voiced.dialogue.audio;

public interface AudioOutput {

  void stream(float[] samples, int sampleRate, int volumePercent);

  AudioStream beginStream(int volumePercent);

  void setVolume(int volumePercent);

  void stop();

  void close();

  interface AudioStream {

    void write(float[] samples, int sampleRate);

    void end();
  }
}

package com.grahambartley.runelite.voiced.dialogue.audio;

public final class RawPcmDecoder {

  private RawPcmDecoder() {}

  public static Pcm decode(byte[] pcm, int sampleRate) {
    if (pcm == null || pcm.length < 2 || sampleRate <= 0) {
      return null;
    }
    if ((pcm.length & 1) != 0) {
      return null;
    }
    int sampleCount = pcm.length / 2;
    float[] samples = new float[sampleCount];
    for (int i = 0; i < sampleCount; i++) {
      int lo = pcm[2 * i] & 0xff;
      int hi = pcm[2 * i + 1];
      short s = (short) ((hi << 8) | lo);
      samples[i] = s / 32768f;
    }
    return new Pcm(samples, sampleRate);
  }
}

package com.grahambartley.runelite.voiced.dialogue.audio;

public final class CaveEcho {
  private CaveEcho() {}

  static final int DELAY_MS = 260;
  static final float FEEDBACK = 0.35f;
  static final float DAMPING = 0.40f;
  static final int MAX_TAIL_MS = 2000;

  static final double TAIL_FLOOR = 1e-3;

  public static Pcm apply(Pcm dry) {
    float[] in = dry.getSamples();
    int rate = dry.getSampleRate();
    int d = Math.max(1, Math.round(DELAY_MS * rate / 1000f));

    int hops = (int) Math.ceil(Math.log(TAIL_FLOOR) / Math.log(FEEDBACK));
    int tail = Math.min(hops * d, MAX_TAIL_MS * rate / 1000);
    float[] out = new float[in.length + tail];

    float lp = 0f;
    for (int i = 0; i < out.length; i++) {
      float dryS = i < in.length ? in[i] : 0f;
      float delayed = i >= d ? out[i - d] : 0f;
      lp = DAMPING * lp + (1f - DAMPING) * delayed;
      float s = dryS + FEEDBACK * lp;
      out[i] = s < -1f ? -1f : (s > 1f ? 1f : s);
    }
    return new Pcm(out, rate);
  }
}

package com.grahambartley.runelite.voiced.dialogue.audio;

public final class Pcm {
  private final float[] samples;
  private final int sampleRate;

  public Pcm(float[] samples, int sampleRate) {
    this.samples = samples;
    this.sampleRate = sampleRate;
  }

  public float[] getSamples() {
    return samples;
  }

  public int getSampleRate() {
    return sampleRate;
  }
}

package com.grahambartley.runelite.voiced.dialogue.audio;

import com.grahambartley.runelite.voiced.dialogue.VoicedDialogueConfig;
import java.util.Set;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Constants;
import net.runelite.api.Player;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;

@Slf4j
public final class CaveEchoPolicy {

  static final Set<Integer> POH_REGION_IDS =
      Set.of(7257, 7534, 7535, 7790, 7791, 8046, 8047, 8302, 8303);

  private final Client client;
  private final VoicedDialogueConfig config;

  public CaveEchoPolicy(Client client, VoicedDialogueConfig config) {
    this.client = client;
    this.config = config;
  }

  public boolean shouldEcho() {
    return config.cloudCaveEcho() && isUnderground();
  }

  boolean isUnderground() {
    Player local = client.getLocalPlayer();
    if (local == null) {
      return false;
    }
    LocalPoint lp = local.getLocalLocation();
    WorldPoint wp =
        client.isInInstancedRegion() && lp != null
            ? WorldPoint.fromLocalInstance(client, lp)
            : local.getWorldLocation();
    if (wp == null) {
      return false;
    }
    boolean underground = isUndergroundPoint(wp);
    if (config.debugMode()) {
      log.info(
          "[TTS echo] x={} y={} plane={} region={} instanced={} underground={}",
          wp.getX(),
          wp.getY(),
          wp.getPlane(),
          wp.getRegionID(),
          client.isInInstancedRegion(),
          underground);
    }
    return underground;
  }

  static boolean isUndergroundPoint(WorldPoint wp) {
    if (POH_REGION_IDS.contains(wp.getRegionID())) {
      return false;
    }
    return WorldPoint.getMirrorPoint(wp, true).getY() >= Constants.OVERWORLD_MAX_Y;
  }
}

