package com.grahambartley.runelite.voiced.dialogue.profile;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;

import junitparams.JUnitParamsRunner;
import junitparams.Parameters;
import org.junit.Test;
import org.junit.runner.RunWith;

@RunWith(JUnitParamsRunner.class)
public class CharacterProfileTest {

  private static final CharacterProfile WIZARD =
      new CharacterProfile(
          "Wizard", "Distinguished elderly British English.", "A wise old wizard.", "Measured.");

  @Test
  public void renderPromptBlockMatchesTheGeminiDirectorsNotesFormat() {
    assertEquals(
        "VOICE ONLY THE TRANSCRIPT BELOW THE DIVIDER, WORD FOR WORD. ADD NO WORDS OF YOUR OWN.\n\n"
            + "AUDIO PROFILE: Wizard\n\n"
            + "DIRECTOR'S NOTES:\n"
            + "- Style: A wise old wizard.\n"
            + "- Accent: Distinguished elderly British English.\n"
            + "- Pace: Measured.\n\n"
            + "#### TRANSCRIPT\n",
        WIZARD.renderPromptBlock());
  }

  @Test
  public void renderPromptBlockLeadsWithTheStaticGuardLine() {
    assertTrue(
        "every block starts with the cache-stable guard instruction",
        WIZARD
            .renderPromptBlock()
            .startsWith(
                "VOICE ONLY THE TRANSCRIPT BELOW THE DIVIDER, WORD FOR WORD."
                    + " ADD NO WORDS OF YOUR OWN.\n\n"));
  }

  @Test
  public void renderPromptBlockEndsAtTheDividerSoTheTranscriptAppendsCleanly() {
    String block = WIZARD.renderPromptBlock();
    assertTrue("block ends with the divider and a newline", block.endsWith("#### TRANSCRIPT\n"));
    assertTrue(
        "appending the transcript yields a single composed input",
        (block + "[happy] Greetings.").endsWith("#### TRANSCRIPT\n[happy] Greetings."));
  }

  @Test
  public void cacheKeyIsStableForIdenticalFields() {
    CharacterProfile same =
        new CharacterProfile(
            "Wizard", "Distinguished elderly British English.", "A wise old wizard.", "Measured.");
    assertEquals("identical profiles share a cache key", WIZARD.cacheKey(), same.cacheKey());
  }

  @Test
  public void trailingWhitespaceIsStrippedSoThePrefixIsByteIdenticalAndCacheStable() {
    CharacterProfile padded =
        new CharacterProfile(
            "Wizard  ",
            "Distinguished elderly British English.\n",
            "A wise old wizard. \t",
            "Measured.   ");
    assertEquals(
        "the rendered block is identical to the unpadded profile",
        WIZARD.renderPromptBlock(),
        padded.renderPromptBlock());
    assertEquals(
        "padded and unpadded profiles share a cache key", WIZARD.cacheKey(), padded.cacheKey());
  }

  @Test
  @Parameters(method = "changedFieldProfiles")
  public void cacheKeyChangesWhenAnyFieldChanges(CharacterProfile changed) {
    assertNotEquals(WIZARD.cacheKey(), changed.cacheKey());
  }

  private Object[] changedFieldProfiles() {
    return new Object[] {
      new CharacterProfile(
          "Wizard", "Distinguished elderly British English.", "A foolish wizard.", "Measured."),
      new CharacterProfile("Wizard", "Irish English.", "A wise old wizard.", "Measured."),
      new CharacterProfile(
          "Mage", "Distinguished elderly British English.", "A wise old wizard.", "Measured."),
    };
  }
}

package com.grahambartley.runelite.voiced.dialogue.profile;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyInt;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

import com.google.gson.Gson;
import com.grahambartley.runelite.voiced.dialogue.VoicedDialogueConfig;
import com.grahambartley.runelite.voiced.dialogue.profile.VoiceManager.PlayerVoice;
import com.grahambartley.runelite.voiced.dialogue.speaker.LearnedNpcStore;
import com.grahambartley.runelite.voiced.dialogue.speaker.NpcDemographicAnalyzer;
import com.grahambartley.runelite.voiced.dialogue.speaker.NpcGender;
import com.grahambartley.runelite.voiced.dialogue.speaker.NpcRace;
import com.grahambartley.runelite.voiced.dialogue.speaker.wiki.NpcLearningService;
import java.util.Collections;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.NPCComposition;
import org.junit.Test;

public class VoiceManagerTest {

  private static final class TestConfig implements VoicedDialogueConfig {
    private final PlayerVoice playerVoice;

    TestConfig(PlayerVoice playerVoice) {
      this.playerVoice = playerVoice;
    }

    @Override
    public PlayerVoice playerVoice() {
      return playerVoice;
    }
  }

  private static final int DWARF_ID = 290;

  private VoiceManager newManager(PlayerVoice playerVoice) {
    Client client = mock(Client.class);
    when(client.getNpcs()).thenReturn(Collections.emptyList());
    return newManager(client, playerVoice);
  }

  private VoiceManager newManager(Client client, PlayerVoice playerVoice) {
    NpcDemographicAnalyzer demographicAnalyzer = new NpcDemographicAnalyzer();
    demographicAnalyzer.initialize();
    NpcProfileTable profileTable = new NpcProfileTable();
    profileTable.initialize();
    return new VoiceManager(new TestConfig(playerVoice), client, demographicAnalyzer, profileTable);
  }

  @Test
  public void playerVoiceTypesFixGender() {
    assertEquals(NpcGender.MALE, PlayerVoice.TYPE_A.getGender());
    assertEquals(NpcGender.FEMALE, PlayerVoice.TYPE_B.getGender());
  }

  @Test
  public void playerResolvesToPlayerSpecWithConfiguredGender() {
    VoiceSpec spec = newManager(PlayerVoice.TYPE_B).resolve(Speaker.PLAYER, null).voice();
    assertTrue("player voice should be a player spec", spec.player());
    assertEquals(NpcGender.FEMALE, spec.gender());
    assertEquals("player:FEMALE", spec.key());
    assertFalse("the player carries no per-NPC variety seed", spec.hasVoiceSeed());
  }

  @Test
  public void undetectedNpcResolvesToTheDefaultHumanMaleVoice() {
    VoiceSpec spec = newManager(PlayerVoice.TYPE_A).resolve(Speaker.NPC, "Hans").voice();
    assertFalse(spec.player());
    assertEquals(NpcRace.HUMAN, spec.race());
    assertEquals(NpcGender.MALE, spec.gender());
    assertTrue("default-voice NPC still gets a per-NPC variety seed", spec.hasVoiceSeed());
    assertEquals("npc:HUMAN:MALE", spec.key());
  }

  @Test
  public void narratorResolvesToTheFixedNarratorSpec() {
    VoiceManager manager = newManager(PlayerVoice.TYPE_B);

    VoiceSpec spec = manager.resolveNarrator().voice();
    assertTrue("the narrator is its own speaker class", spec.narrator());
    assertEquals("narrator", spec.key());
    assertEquals(
        "the player voice setting must not move the narrator",
        spec,
        newManager(PlayerVoice.TYPE_A).resolveNarrator().voice());
  }

  @Test
  public void everySpeakerAlwaysResolvesToACharacterProfile() {
    VoiceManager manager = newManager(PlayerVoice.TYPE_A);
    assertNotNull(
        "the player always carries a profile", manager.resolve(Speaker.PLAYER, null).profile());
    assertNotNull(
        "an NPC always carries a profile", manager.resolve(Speaker.NPC, "Hans").profile());
    assertNotNull("the narrator always carries a profile", manager.resolveNarrator().profile());
  }

  @Test
  public void anUndetectedNpcStillResolvesToTheDefaultProfileRatherThanNone() {
    CharacterProfile profile =
        newManager(PlayerVoice.TYPE_A).resolve(Speaker.NPC, "Hans").profile();
    assertNotNull(profile);
    assertFalse("the default profile still names a voice", profile.name().trim().isEmpty());
    assertFalse("the default profile still carries an accent", profile.accent().trim().isEmpty());
  }

  @Test
  public void anNpcHandedInDirectlyResolvesFromItsOwnIdWithoutAWorldScan() {
    Client client = mock(Client.class);
    when(client.getNpcs()).thenReturn(Collections.emptyList());
    VoiceManager manager = newManager(client, PlayerVoice.TYPE_A);

    VoiceSpec spec = manager.resolveNpc(worldNpc(DWARF_ID, "Dwarf")).voice();

    assertEquals(NpcRace.DWARF, spec.race());
    assertEquals(NpcGender.MALE, spec.gender());
    verify(client, never()).getNpcs();
  }

  @Test
  public void theDirectNpcPathResolvesExactlyAsTheNameLookupDoes() {
    NPC dwarf = worldNpc(DWARF_ID, "Dwarf");
    Client client = mock(Client.class);
    when(client.getNpcs()).thenReturn(Collections.singletonList(dwarf));
    VoiceManager manager = newManager(client, PlayerVoice.TYPE_A);

    assertEquals(manager.resolve(Speaker.NPC, "Dwarf"), manager.resolveNpc(dwarf));
  }

  @Test
  public void aTransformedNpcIsOfferedUnderTheIdItIsVoicedUnder() {
    NpcLearningService learning = mock(NpcLearningService.class);
    VoiceManager manager = newManager(PlayerVoice.TYPE_A);
    manager.enableLearning(new LearnedNpcStore(null, new Gson()), learning);

    when(learning.isEnabled()).thenReturn(true);
    when(learning.startsConversation("Talk-to")).thenReturn(true);

    manager.offerToLearning("Talk-to", transformedNpc(999_000_001, DWARF_ID, "Dwarf"));

    verify(learning).considerLearning(DWARF_ID, "Dwarf");
  }

  @Test
  public void anUnvoicedNpcIsOfferedUnderItsOwnId() {
    NpcLearningService learning = mock(NpcLearningService.class);
    VoiceManager manager = newManager(PlayerVoice.TYPE_A);
    manager.enableLearning(new LearnedNpcStore(null, new Gson()), learning);

    when(learning.isEnabled()).thenReturn(true);
    when(learning.startsConversation("Talk-to")).thenReturn(true);

    manager.offerToLearning("Talk-to", worldNpc(999_000_002, "Nobody"));

    verify(learning).considerLearning(999_000_002, "Nobody");
  }

  @Test
  public void aClickThatStartsNoConversationIsNotOffered() {
    NpcLearningService learning = mock(NpcLearningService.class);
    when(learning.isEnabled()).thenReturn(true);
    when(learning.startsConversation("Attack")).thenReturn(false);
    VoiceManager manager = newManager(PlayerVoice.TYPE_A);
    manager.enableLearning(new LearnedNpcStore(null, new Gson()), learning);

    manager.offerToLearning("Attack", worldNpc(DWARF_ID, "Dwarf"));

    verify(learning, never()).considerLearning(anyInt(), any());
  }

  private static NPC transformedNpc(int activeId, int baseId, String name) {
    NPCComposition composition = mock(NPCComposition.class);
    when(composition.getId()).thenReturn(baseId);
    when(composition.getName()).thenReturn(name);
    NPC npc = mock(NPC.class);
    when(npc.getId()).thenReturn(activeId);
    when(npc.getName()).thenReturn(name);
    when(npc.getComposition()).thenReturn(composition);
    return npc;
  }

  private static NPC worldNpc(int npcId, String name) {
    NPCComposition composition = mock(NPCComposition.class);
    when(composition.getId()).thenReturn(npcId);
    when(composition.getName()).thenReturn(name);
    NPC npc = mock(NPC.class);
    when(npc.getId()).thenReturn(npcId);
    when(npc.getName()).thenReturn(name);
    when(npc.getComposition()).thenReturn(composition);
    return npc;
  }
}

package com.grahambartley.runelite.voiced.dialogue.profile;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import junitparams.JUnitParamsRunner;
import junitparams.Parameters;
import org.junit.Test;
import org.junit.runner.RunWith;

@RunWith(JUnitParamsRunner.class)
public class ProfanityFilterTest {

  private final ProfanityFilter filter = new ProfanityFilter();

  private Object[] baseWordCases() {
    return new Object[] {
      new Object[] {"Oh shit off, adventurer.", "Oh **** off, adventurer."},
      new Object[] {"You Twat!", "You ****!"},
    };
  }

  @Test
  @Parameters(method = "baseWordCases")
  public void masksABaseWordButKeepsSurroundingTextAndCasing(String input, String expected) {
    assertEquals(expected, filter.mask(input));
  }

  private Object[] leetspeakCases() {
    return new Object[] {
      new Object[] {"sh1t", "****"},
      new Object[] {"@ss", "***"},
      new Object[] {"a$$", "***"},
      new Object[] {"b1tch", "*****"},
    };
  }

  @Test
  @Parameters(method = "leetspeakCases")
  public void resolvesLeetspeakEvasions(String input, String expected) {
    assertEquals(expected, filter.mask(input));
  }

  private Object[] interiorSeparatorCases() {
    return new Object[] {
      new Object[] {"f.u.c.k", "*******"},
      new Object[] {"s-h-i-t", "*******"},
      new Object[] {"you b.itch", "you ******"},
    };
  }

  @Test
  @Parameters(method = "interiorSeparatorCases")
  public void resolvesInteriorSeparatorEvasions(String input, String expected) {
    assertEquals(expected, filter.mask(input));
  }

  private Object[] scunthorpeCases() {
    return new Object[] {
      new Object[] {"Scunthorpe", "Scunthorpe"},
      new Object[] {"an assassin lurks", "an assassin lurks"},
      new Object[] {"Welcome to Sussex", "Welcome to Sussex"},
      new Object[] {"a class of mages", "a class of mages"},
    };
  }

  @Test
  @Parameters(method = "scunthorpeCases")
  public void leavesScunthorpeStyleSubstringsAlone(String input, String expected) {
    assertEquals(expected, filter.mask(input));
  }

  private Object[] cleanPassthroughCases() {
    return new Object[] {
      new Object[] {
        "Greetings, traveller! The bank is to the north.",
        "Greetings, traveller! The bank is to the north."
      },
      new Object[] {null, null},
      new Object[] {"", ""},
    };
  }

  @Test
  @Parameters(method = "cleanPassthroughCases")
  public void cleanTextPassesThroughUnchangedAndNullsSurvive(String input, String expected) {
    assertEquals(expected, filter.mask(input));
  }

  @Test
  public void maskingIsIdempotent() {
    String once = filter.mask("you absolute bastard");
    assertEquals("re-masking changes nothing", once, filter.mask(once));
  }

  @Test
  public void maskingARepresentativeLineIsFarCheaperThanASynthesisCall() {
    String line =
        "Oh shit, you absolute twat, get your arse over here before I lose my damn mind, you cretin.";
    for (int i = 0; i < 1_000; i++) {
      filter.mask(line);
    }
    long start = System.nanoTime();
    String masked = null;
    for (int i = 0; i < 10_000; i++) {
      masked = filter.mask(line);
    }
    long perCallNanos = (System.nanoTime() - start) / 10_000;
    assertTrue("the line was actually masked", masked.contains("****"));
    assertTrue(
        "masking a representative line stays far off the per-line synthesis path (was "
            + perCallNanos
            + "ns)",
        perCallNanos < 10_000_000);
  }
}

package com.grahambartley.runelite.voiced.dialogue.profile;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import org.junit.Test;

public class NpcProfileTableTest {

  private static final String JSON =
      "{"
          + "\"default\":{\"name\":\"Default\",\"accent\":\"British RP.\",\"style\":\"Plain.\",\"pace\":\"Steady.\"},"
          + "\"player\":{\"name\":\"Adventurer\",\"style\":\"Brave hero.\"},"
          + "\"narrator\":{\"name\":\"Narrator\",\"style\":\"Measured storyteller.\"},"
          + "\"byRace\":{"
          + "\"Human\":{\"name\":\"Human\",\"accent\":\"British.\",\"style\":\"Ordinary.\"},"
          + "\"Troll\":{\"name\":\"Troll\",\"accent\":\"Brixton.\",\"style\":\"Big and dim.\"}},"
          + "\"byEthnicity\":{\"kharidian\":{\"accent\":\"Middle Eastern.\"}},"
          + "\"byCategory\":["
          + "{\"id\":\"vampyre\",\"keywords\":[\"vampyre\",\"vyre\"],\"name\":\"Vampyre\",\"accent\":\"Transylvanian.\",\"style\":\"Predatory.\"},"
          + "{\"id\":\"imp\",\"keywords\":[\"imp\"],\"name\":\"Imp\",\"style\":\"Squeaky.\"},"
          + "{\"id\":\"child\",\"keywords\":[\"child\",\"urchin\"],\"lifeStage\":\"child\","
          + "\"style\":\"Bright and young.\"}"
          + "],"
          + "\"byId\":{\"_comment\":\"x\",\"100\":{\"name\":\"Vanstrom\",\"style\":\"An ancient vampyre lord.\"}}"
          + "}";

  private static NpcProfileTable.Resolution resolve(
      NpcProfileTable table, Integer npcId, String npcName, String race, String ethnicity) {
    return table.resolveNpc(npcId, table.matchName(npcName), race, ethnicity);
  }

  private static boolean isChild(NpcProfileTable table, String npcName) {
    return table.matchName(npcName).child();
  }

  private static NpcProfileTable table() {
    JsonObject profiles = new JsonParser().parse(JSON).getAsJsonObject();
    return NpcProfileTable.fromProfilesJson(profiles);
  }

  @Test
  public void noMatchingLayerFallsBackToTheCompleteDefault() {
    CharacterProfile p = resolve(table(), null, "Random Bloke", null, null).profile();
    assertEquals("Default", p.name());
    assertEquals("British RP.", p.accent());
    assertEquals("Plain.", p.style());
    assertEquals("Steady.", p.pace());
  }

  @Test
  public void raceLayerOverridesDefaultAndInheritsUnsetFields() {
    NpcProfileTable.Resolution r = resolve(table(), null, "Mountain Troll", "Troll", null);
    assertEquals("race:Troll", r.source());
    assertEquals("Troll", r.profile().name());
    assertEquals("Brixton.", r.profile().accent());
    assertEquals("Big and dim.", r.profile().style());
    assertEquals("pace falls through to the default", "Steady.", r.profile().pace());
  }

  @Test
  public void ethnicityAccentTintsPlainFolkOverTheRaceAccent() {
    NpcProfileTable.Resolution r = resolve(table(), null, "Desert Trader", "Human", "kharidian");
    assertEquals("race:Human+ethnicity:kharidian", r.source());
    assertEquals(
        "the ethnicity accent wins for plain folk", "Middle Eastern.", r.profile().accent());
    assertEquals(
        "style stays the race style (ethnicity is accent-only)", "Ordinary.", r.profile().style());
  }

  @Test
  public void ethnicityIsSkippedForDistinctiveRaces() {
    NpcProfileTable.Resolution r = resolve(table(), null, "Desert Troll", "Troll", "kharidian");
    assertEquals("ethnicity is not applied to a distinctive race", "race:Troll", r.source());
    assertEquals("Brixton.", r.profile().accent());
  }

  @Test
  public void aKeywordCategoryStillBeatsTheEthnicityAccent() {
    NpcProfileTable.Resolution r = resolve(table(), null, "Feral Vampyre", "Human", "kharidian");
    assertEquals("race:Human+ethnicity:kharidian+keyword:vampyre", r.source());
    assertEquals("Transylvanian.", r.profile().accent());
  }

  @Test
  public void raceAndCategoryCombineStyleWhileTheCategoryAccentWins() {
    NpcProfileTable.Resolution r = resolve(table(), null, "Vampyre Brute", "Troll", null);
    assertEquals("race:Troll+keyword:vampyre", r.source());
    assertEquals("the most specific name wins", "Vampyre", r.profile().name());
    assertEquals(
        "the category accent beats the race accent", "Transylvanian.", r.profile().accent());
    assertTrue("the race style is part of the blend", r.profile().style().contains("Big and dim."));
    assertTrue(
        "the category style is part of the blend", r.profile().style().contains("Predatory."));
  }

  @Test
  public void multipleCategoriesAllCombine() {
    NpcProfileTable.Resolution r = resolve(table(), null, "Imp Vampyre", null, null);
    assertEquals(
        "both categories appear in declaration order", "keyword:vampyre+keyword:imp", r.source());
    assertTrue(r.profile().style().contains("Predatory."));
    assertTrue(r.profile().style().contains("Squeaky."));
    assertEquals("the last category to set a name wins", "Imp", r.profile().name());
  }

  @Test
  public void perIdOverrideAddsOnTopAndWinsSingleValuedFields() {
    NpcProfileTable.Resolution r = resolve(table(), 100, "Vampyre Vanstrom", "Undead", null);
    assertEquals("every match contributes", "keyword:vampyre+id:100", r.source());
    assertEquals("the bespoke name wins", "Vanstrom", r.profile().name());
    assertTrue(
        "the category style is still in the blend", r.profile().style().contains("Predatory."));
    assertTrue(
        "the bespoke style is added on top",
        r.profile().style().contains("An ancient vampyre lord."));
    assertEquals(
        "accent the id entry did not set inherits from the matched keyword layer",
        "Transylvanian.",
        r.profile().accent());
  }

  @Test
  public void raceMatchingIsCaseInsensitive() {
    assertEquals("Troll", resolve(table(), null, "x", "TROLL", null).profile().name());
    assertEquals("Troll", resolve(table(), null, "x", "troll", null).profile().name());
  }

  @Test
  public void keywordMatchingRespectsWordBoundaries() {
    assertEquals(
        "'imp' must not match inside 'important'",
        "Default",
        resolve(table(), null, "Important Person", null, null).profile().name());
    assertEquals(
        "'imp' matches the whole word",
        "Imp",
        resolve(table(), null, "Imp", null, null).profile().name());
  }

  @Test
  public void wordContainsIsBoundedOnBothSides() {
    assertTrue(NpcProfileTable.wordContains("feral vampyre", "vampyre"));
    assertTrue(NpcProfileTable.wordContains("tztok-jad", "jad"));
    assertFalse(NpcProfileTable.wordContains("important", "imp"));
    assertFalse(NpcProfileTable.wordContains("shrimp", "imp"));
  }

  @Test
  public void playerProfileLayersOverDefaultThenConfigOverridesNonBlankFields() {
    NpcProfileTable t = table();

    CharacterProfile base = t.resolvePlayer(null, null, null);
    assertEquals("Adventurer", base.name());
    assertEquals("the player style comes from the player layer", "Brave hero.", base.style());
    assertEquals("accent inherits from the default", "British RP.", base.accent());

    CharacterProfile overridden = t.resolvePlayer("Pirate drawl.", "   ", "");
    assertEquals("a non-blank accent overrides", "Pirate drawl.", overridden.accent());
    assertEquals("a blank style inherits", "Brave hero.", overridden.style());
    assertEquals("a blank pace inherits", "Steady.", overridden.pace());
  }

  @Test
  public void narratorProfileLayersOverDefaultAndTakesNoConfiguredFields() {
    CharacterProfile narrator = table().resolveNarrator();

    assertEquals("Narrator", narrator.name());
    assertEquals(
        "the narrator style comes from the narrator layer",
        "Measured storyteller.",
        narrator.style());
    assertEquals("accent inherits from the default", "British RP.", narrator.accent());
    assertEquals("pace inherits from the default", "Steady.", narrator.pace());
  }

  @Test
  public void narratorProfileIsIdenticalEveryCallSoItsCacheKeyHolds() {
    NpcProfileTable t = table();
    assertEquals(t.resolveNarrator().cacheKey(), t.resolveNarrator().cacheKey());
  }

  @Test
  public void aTableWithNoNarratorLayerStillResolvesTheDefault() {
    JsonObject profiles =
        new JsonParser()
            .parse(
                "{\"default\":{\"name\":\"Default\",\"accent\":\"British RP.\","
                    + "\"style\":\"Plain.\",\"pace\":\"Steady.\"}}")
            .getAsJsonObject();

    CharacterProfile narrator = NpcProfileTable.fromProfilesJson(profiles).resolveNarrator();

    assertEquals("Default", narrator.name());
    assertEquals("Plain.", narrator.style());
  }

  @Test
  public void childAgeCategoryMarksMatchingNamesAsChildren() {
    NpcProfileTable t = table();
    assertTrue("'Child' matches the child category", isChild(t, "Child"));
    assertTrue("'Street urchin' matches the child category", isChild(t, "Street urchin"));
    assertFalse("an adult name is not a child", isChild(t, "Random Bloke"));
    assertFalse("a non-child category match is not a child", isChild(t, "Imp"));
    assertFalse("a null name is not a child", isChild(t, null));
  }

  @Test
  public void childCategoryStyleLayersOverTheRaceStyle() {
    NpcProfileTable.Resolution r = resolve(table(), null, "Troll child", "Troll", null);
    assertEquals("race:Troll+keyword:child", r.source());
    assertEquals("Big and dim. Bright and young.", r.profile().style());
    assertEquals(
        "the child category leaves the accent to the race", "Brixton.", r.profile().accent());
  }
}

package com.grahambartley.runelite.voiced.dialogue.profile;

import static org.junit.Assert.assertTrue;

import com.grahambartley.runelite.voiced.dialogue.speaker.NpcGender;
import com.grahambartley.runelite.voiced.dialogue.speaker.NpcRace;
import org.junit.Test;

public class VoiceTraceFormatterTest {

  private static CharacterProfile profile(String name, String accent) {
    return new CharacterProfile(name, accent, "Warm.", "Normal.");
  }

  @Test
  public void buildNpcTraceShowsWorldHitSourceAndSeed() {
    String trace =
        VoiceTraceFormatter.buildNpcTrace(
            "Goblin", 101, NpcRace.GOBLIN, NpcGender.MALE, false, "table-hit", 24);
    assertTrue(trace, trace.contains("npc='Goblin'"));
    assertTrue(trace, trace.contains("world=HIT(id=101)"));
    assertTrue(trace, trace.contains("race=GOBLIN"));
    assertTrue(trace, trace.contains("lifeStage=adult"));
    assertTrue(trace, trace.contains("source=table-hit"));
    assertTrue(trace, trace.contains("seed=24"));
  }

  @Test
  public void buildNpcTraceShowsWorldMissForUntabledNpc() {
    String trace =
        VoiceTraceFormatter.buildNpcTrace(
            "Hans", null, NpcRace.UNKNOWN, NpcGender.UNKNOWN, false, "not-in-world", 26);
    assertTrue(trace, trace.contains("world=MISS"));
    assertTrue(trace, trace.contains("race=UNKNOWN"));
    assertTrue(trace, trace.contains("seed=26"));
  }

  @Test
  public void buildResolvedLineGivesTheWholeDecisionInOneRecord() {
    String line =
        VoiceTraceFormatter.buildResolvedLine(
            "cloud-openrouter",
            VoiceSpec.npc(NpcRace.HUMAN, NpcGender.MALE, 26),
            "Hans",
            "HAPPY",
            profile("Hans", "British"));
    assertTrue(line, line.startsWith("[TTS line]"));
    assertTrue(line, line.contains("backend=cloud-openrouter"));
    assertTrue(line, line.contains("kind=npc"));
    assertTrue(line, line.contains("name='Hans'"));
    assertTrue(line, line.contains("emotion=HAPPY"));
    assertTrue(line, line.contains("race=HUMAN"));
    assertTrue(line, line.contains("gender=MALE"));
    assertTrue(line, line.contains("lifeStage=adult"));
    assertTrue(line, line.contains("seed=26"));
    assertTrue(line, line.contains("profile='Hans'"));
    assertTrue(line, line.contains("accent='British'"));
  }

  @Test
  public void buildResolvedLineCollapsesAbsentNameAndSeedToDashButStillNamesTheProfile() {
    String line =
        VoiceTraceFormatter.buildResolvedLine(
            "cloud-openrouter",
            VoiceSpec.player(NpcGender.FEMALE),
            null,
            "NEUTRAL",
            profile("Adventurer", "Irish"));
    assertTrue(line, line.contains("kind=player"));
    assertTrue(line, line.contains("name=-"));
    assertTrue(line, line.contains("seed=-"));
    assertTrue(line, line.contains("profile='Adventurer'"));
    assertTrue(line, line.contains("accent='Irish'"));
  }

  @Test
  public void buildNpcTraceShowsChildAge() {
    String trace =
        VoiceTraceFormatter.buildNpcTrace(
            "Shilop", 3501, NpcRace.HUMAN, NpcGender.MALE, true, "table-hit", 12);
    assertTrue(trace, trace.contains("lifeStage=child"));
  }

  @Test
  public void buildResolvedLineShowsChildAge() {
    String line =
        VoiceTraceFormatter.buildResolvedLine(
            "cloud-openrouter",
            VoiceSpec.npc(NpcRace.HUMAN, NpcGender.MALE, 12, true),
            "Shilop",
            "HAPPY",
            profile("Shilop", "British"));
    assertTrue(line, line.contains("lifeStage=child"));
  }

  @Test
  public void buildResolvedLineMarksNarrationAsItsOwnKindWithNoCharacterFields() {
    String line =
        VoiceTraceFormatter.buildResolvedLine(
            "cloud-openrouter",
            VoiceSpec.NARRATOR,
            null,
            "NEUTRAL",
            profile("Narrator", "British"));
    assertTrue(line, line.contains("kind=narrator"));
    assertTrue("narration must never log a literal null name: " + line, line.contains("name=-"));
    assertTrue(line, line.contains("race=-"));
    assertTrue(line, line.contains("gender=-"));
    assertTrue(line, line.contains("lifeStage=-"));
    assertTrue(line, line.contains("seed=-"));
    assertTrue(line, line.contains("profile='Narrator'"));
  }

  @Test
  public void buildPlayerTraceShowsGender() {
    String trace = VoiceTraceFormatter.buildPlayerTrace(NpcGender.FEMALE);
    assertTrue(trace, trace.contains("player ->"));
    assertTrue(trace, trace.contains("gender=FEMALE"));
  }
}

