package com.grahambartley.runelite.voiced.dialogue.profile;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

import com.grahambartley.runelite.voiced.dialogue.speaker.AttributeSource;
import com.grahambartley.runelite.voiced.dialogue.speaker.NpcAttributes;
import com.grahambartley.runelite.voiced.dialogue.speaker.NpcDemographicAnalyzer;
import com.grahambartley.runelite.voiced.dialogue.speaker.NpcFinder;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import org.junit.Test;

public class NpcIdentityResolverTest {

  private static final NpcProfileTable PROFILE_TABLE = loadProfileTable();

  private final NpcFinder finder = mock(NpcFinder.class);
  private final NpcDemographicAnalyzer analyzer = mock(NpcDemographicAnalyzer.class);
  private final NpcIdentityResolver resolver =
      new NpcIdentityResolver(finder, analyzer, PROFILE_TABLE);

  private static NpcProfileTable loadProfileTable() {
    NpcProfileTable table = new NpcProfileTable();
    table.initialize();
    return table;
  }

  @Test
  public void carriesTheWorldIdAttributesAndNameMatch() {
    NPC npc = mock(NPC.class);
    when(npc.getId()).thenReturn(3501);
    when(finder.findByName("Shilop child")).thenReturn(npc);
    NpcAttributes attributes = new NpcAttributes("Human", "Male", AttributeSource.STATIC_TABLE);
    when(analyzer.analyzeNPC(npc)).thenReturn(attributes);

    NpcIdentity identity = resolver.resolve("Shilop child");

    assertEquals(Integer.valueOf(3501), identity.worldId());
    assertSame(attributes, identity.attributes());
    assertTrue("the child keyword category matched", identity.nameMatch().child());
  }

  @Test
  public void anNpcNotInTheWorldStillCarriesItsNameMatch() {
    when(finder.findByName("Child")).thenReturn(null);

    NpcIdentity identity = resolver.resolve("Child");

    assertNull(identity.worldId());
    assertNull(identity.attributes());
    assertTrue("a name-only child is still a child", identity.nameMatch().child());
  }

  @Test
  public void anUnanalysableNpcKeepsItsWorldId() {
    NPC npc = mock(NPC.class);
    when(npc.getId()).thenReturn(7);
    when(finder.findByName("Hans")).thenReturn(npc);
    when(analyzer.analyzeNPC(npc)).thenReturn(null);

    NpcIdentity identity = resolver.resolve("Hans");

    assertEquals(Integer.valueOf(7), identity.worldId());
    assertNull(identity.attributes());
    assertFalse(identity.nameMatch().child());
  }

  @Test
  public void oneResolutionCostsOneWorldScanAndOneAnalysis() {
    NPC npc = mock(NPC.class);
    when(finder.findByName("Hans")).thenReturn(npc);

    resolver.resolve("Hans");

    verify(finder, times(1)).findByName("Hans");
    verify(analyzer, times(1)).analyzeNPC(npc);
  }

  @Test
  public void aBlankNameNeverScansTheWorldForAMatch() {
    Client client = mock(Client.class);
    NpcIdentityResolver realFinder =
        new NpcIdentityResolver(new NpcFinder(client), analyzer, PROFILE_TABLE);

    NpcIdentity identity = realFinder.resolve("");

    assertNull(identity.worldId());
    assertFalse(identity.nameMatch().child());
  }
}

package com.grahambartley.runelite.voiced.dialogue.profile;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;

import com.grahambartley.runelite.voiced.dialogue.speaker.NpcGender;
import com.grahambartley.runelite.voiced.dialogue.speaker.NpcRace;
import junitparams.JUnitParamsRunner;
import junitparams.Parameters;
import org.junit.Test;
import org.junit.runner.RunWith;

@RunWith(JUnitParamsRunner.class)
public class VoiceSpecTest {

  @Test
  @Parameters(method = "playerKeyCases")
  public void playerKeyOmitsRace(NpcGender gender, String expected) {
    assertEquals(expected, VoiceSpec.player(gender).key());
  }

  private Object[] playerKeyCases() {
    return new Object[] {
      new Object[] {NpcGender.MALE, "player:MALE"},
      new Object[] {NpcGender.FEMALE, "player:FEMALE"},
    };
  }

  @Test
  @Parameters(method = "npcKeyCases")
  public void npcKeyCarriesRaceAndGender(NpcRace race, NpcGender gender, String expected) {
    assertEquals(expected, VoiceSpec.npc(race, gender).key());
  }

  private Object[] npcKeyCases() {
    return new Object[] {
      new Object[] {NpcRace.ELF, NpcGender.FEMALE, "npc:ELF:FEMALE"},
      new Object[] {NpcRace.DEMON, NpcGender.MALE, "npc:DEMON:MALE"},
    };
  }

  @Test
  @Parameters(method = "playerFlagCases")
  public void playerSpecIsFlaggedAsPlayer(VoiceSpec spec, boolean expected) {
    assertEquals(expected, spec.player());
  }

  private Object[] playerFlagCases() {
    return new Object[] {
      new Object[] {VoiceSpec.player(NpcGender.MALE), true},
      new Object[] {VoiceSpec.npc(NpcRace.HUMAN, NpcGender.MALE), false},
    };
  }

  @Test
  public void equalSpecsShareKeyAndEquality() {
    VoiceSpec a = VoiceSpec.npc(NpcRace.GOBLIN, NpcGender.FEMALE);
    VoiceSpec b = VoiceSpec.npc(NpcRace.GOBLIN, NpcGender.FEMALE);
    assertEquals(a, b);
    assertEquals(a.hashCode(), b.hashCode());
    assertEquals(a.key(), b.key());
  }

  @Test
  public void playerAndNpcOfSameGenderAreDistinct() {
    VoiceSpec player = VoiceSpec.player(NpcGender.MALE);
    VoiceSpec npc = VoiceSpec.npc(NpcRace.HUMAN, NpcGender.MALE);
    assertNotEquals(player, npc);
    assertNotEquals(player.key(), npc.key());
  }

  @Test
  public void bareNpcSpecHasNoVoiceSeed() {
    VoiceSpec spec = VoiceSpec.npc(NpcRace.HUMAN, NpcGender.MALE);
    assertFalse(spec.hasVoiceSeed());
    assertEquals(VoiceSpec.UNSPECIFIED_SEED, spec.voiceSeed());
    assertEquals("npc:HUMAN:MALE", spec.key());
  }

  @Test
  public void voiceSeedIsCarriedButNotFoldedIntoKey() {
    VoiceSpec spec = VoiceSpec.npc(NpcRace.HUMAN, NpcGender.MALE, 17);
    assertTrue(spec.hasVoiceSeed());
    assertEquals(17, spec.voiceSeed());
    assertEquals("npc:HUMAN:MALE", spec.key());
  }

  @Test
  public void sameRaceGenderDifferentSeedShareKeyButDifferOnEquality() {
    VoiceSpec a = VoiceSpec.npc(NpcRace.HUMAN, NpcGender.MALE, 14);
    VoiceSpec b = VoiceSpec.npc(NpcRace.HUMAN, NpcGender.MALE, 17);
    assertEquals(a.key(), b.key());
    assertNotEquals(a, b);
  }

  @Test
  public void negativeSeedIsNormalisedToUnspecified() {
    VoiceSpec spec = VoiceSpec.npc(NpcRace.HUMAN, NpcGender.MALE, -5);
    assertFalse(spec.hasVoiceSeed());
    assertEquals(VoiceSpec.UNSPECIFIED_SEED, spec.voiceSeed());
    assertEquals("npc:HUMAN:MALE", spec.key());
  }

  @Test
  public void specsDefaultToAdult() {
    assertFalse(VoiceSpec.npc(NpcRace.HUMAN, NpcGender.MALE).child());
    assertFalse(VoiceSpec.npc(NpcRace.HUMAN, NpcGender.MALE, 7).child());
    assertFalse("the player is never a child", VoiceSpec.player(NpcGender.FEMALE).child());
  }

  @Test
  public void narratorIsItsOwnSpeakerClassWithAStableKey() {
    VoiceSpec narrator = VoiceSpec.NARRATOR;

    assertTrue(narrator.narrator());
    assertEquals("narrator", narrator.key());
    assertEquals(
        "the narrator is identical every call, so its cached lines never re-key",
        VoiceSpec.NARRATOR,
        narrator);
  }

  @Test
  public void narratorKeyCollidesWithNoCharacterKey() {
    String narrator = VoiceSpec.NARRATOR.key();
    for (NpcRace race : NpcRace.values()) {
      for (NpcGender gender : NpcGender.values()) {
        assertNotEquals(narrator, VoiceSpec.npc(race, gender).key());
      }
    }
    assertNotEquals(narrator, VoiceSpec.player(NpcGender.MALE).key());
    assertNotEquals(narrator, VoiceSpec.player(NpcGender.FEMALE).key());
  }

  @Test
  public void charactersAreNeverTheNarrator() {
    assertFalse(VoiceSpec.npc(NpcRace.HUMAN, NpcGender.MALE).narrator());
    assertFalse(VoiceSpec.npc(NpcRace.TROLL, NpcGender.MALE, 7, true).narrator());
    assertFalse(VoiceSpec.player(NpcGender.FEMALE).narrator());
  }

  @Test
  public void childFlagIsCarriedButNotFoldedIntoKey() {
    VoiceSpec child = VoiceSpec.npc(NpcRace.TROLL, NpcGender.MALE, 7, true);
    assertTrue(child.child());
    assertEquals("npc:TROLL:MALE", child.key());
    assertNotEquals(child, VoiceSpec.npc(NpcRace.TROLL, NpcGender.MALE, 7));
  }
}

package com.grahambartley.runelite.voiced.dialogue.profile;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.google.gson.JsonParser;
import com.grahambartley.runelite.voiced.dialogue.profile.NpcProfileLayers.CategoryRule;
import org.junit.Test;

public class NpcProfileParserTest {

  private static NpcProfileLayers parse(String json) {
    return NpcProfileParser.parse(new JsonParser().parse(json).getAsJsonObject());
  }

  private static final String COMPLETE_DEFAULT =
      "\"default\":{\"name\":\"D\",\"accent\":\"A\",\"style\":\"S\",\"pace\":\"P\"}";

  @Test
  public void parsesTheCompleteDefault() {
    NpcProfileLayers layers = parse("{" + COMPLETE_DEFAULT + "}");
    assertEquals("D", layers.defaultProfile().name());
    assertEquals("A", layers.defaultProfile().accent());
    assertEquals("S", layers.defaultProfile().style());
    assertEquals("P", layers.defaultProfile().pace());
  }

  @Test
  public void anIncompleteDefaultFallsBackToTheBuiltInOne() {
    NpcProfileLayers layers = parse("{\"default\":{\"name\":\"D\"}}");
    assertEquals(NpcProfileLayers.BUILTIN_DEFAULT, layers.defaultProfile());
  }

  @Test
  public void aMissingDefaultFallsBackToTheBuiltInOne() {
    assertEquals(NpcProfileLayers.BUILTIN_DEFAULT, parse("{}").defaultProfile());
  }

  @Test
  public void layerMapsAreKeyedLowerCaseAndSkipComments() {
    NpcProfileLayers layers =
        parse(
            "{\"byRace\":{\"Troll\":{\"accent\":\"Brixton.\"},\"_comment\":{\"accent\":\"x\"}},"
                + "\"byEthnicity\":{\"Kharidian\":{\"accent\":\"Middle Eastern.\"}}}");

    assertEquals("Brixton.", layers.byRace().get("troll").accent());
    assertNull("a comment key is not a layer", layers.byRace().get("_comment"));
    assertEquals("Middle Eastern.", layers.byEthnicity().get("kharidian").accent());
  }

  @Test
  public void sparseLayersLeaveUnsetFieldsNullSoTheyInherit() {
    NpcProfileLayers layers = parse("{\"player\":{\"style\":\"Brave hero.\"}}");
    assertEquals("Brave hero.", layers.playerLayer().style());
    assertNull(layers.playerLayer().name());
    assertNull(layers.playerLayer().accent());
    assertNull(layers.playerLayer().pace());
  }

  @Test
  public void anEmptyStringFieldIsTreatedAsAbsent() {
    NpcProfileLayers layers = parse("{\"player\":{\"accent\":\"\"}}");
    assertNull(layers.playerLayer().accent());
  }

  @Test
  public void categoriesKeepDeclarationOrderAndLowerCasedKeywords() {
    NpcProfileLayers layers =
        parse(
            "{\"byCategory\":["
                + "{\"id\":\"vampyre\",\"keywords\":[\"Vampyre\"],\"accent\":\"Transylvanian.\"},"
                + "{\"id\":\"child\",\"keywords\":[\"Child\"],\"lifeStage\":\"child\"}]}");

    assertEquals(2, layers.byCategory().size());
    CategoryRule vampyre = layers.byCategory().get(0);
    assertEquals("vampyre", vampyre.id());
    assertEquals("vampyre", vampyre.keywords().get(0));
    assertEquals("Transylvanian.", vampyre.layer().accent());
    assertTrue("the child marker rides on the rule", layers.byCategory().get(1).child());
  }

  @Test
  public void categoriesWithoutKeywordsAreSkippedAndAnIdIsOptional() {
    NpcProfileLayers layers =
        parse(
            "{\"byCategory\":[{\"accent\":\"orphan\"},\"not an object\","
                + "{\"keywords\":[\"imp\"],\"style\":\"Squeaky.\"}]}");

    assertEquals(1, layers.byCategory().size());
    assertEquals("category", layers.byCategory().get(0).id());
  }

  @Test
  public void byIdSkipsCommentsAndNonNumericKeys() {
    NpcProfileLayers layers =
        parse(
            "{\"byId\":{\"_comment\":\"x\",\"nope\":{\"name\":\"N\"},\"100\":{\"name\":\"Vanstrom\"}}}");

    assertEquals(1, layers.byId().size());
    assertEquals("Vanstrom", layers.byId().get(100).name());
  }

  @Test
  public void theBundledResourceParses() {
    assertNotNull(NpcProfileParser.loadResource("/npc-voices.json"));
  }

  @Test
  public void aMissingResourceIsAnAbsentSection() {
    assertNull(NpcProfileParser.loadResource("/no-such-resource.json"));
  }

  @Test
  public void aResourceWithoutAProfilesSectionIsAbsent() {
    assertNull(NpcProfileParser.loadResource("/expression-emotions.json"));
  }

  @Test
  public void anEmptySectionParsesToEmptyLayers() {
    NpcProfileLayers layers = parse("{}");
    assertTrue(layers.byRace().isEmpty());
    assertTrue(layers.byEthnicity().isEmpty());
    assertTrue(layers.byCategory().isEmpty());
    assertTrue(layers.byId().isEmpty());
    assertNull(layers.playerLayer());
  }
}

package com.grahambartley.runelite.voiced.dialogue.profile;

import static org.junit.Assert.assertEquals;

import junitparams.JUnitParamsRunner;
import junitparams.Parameters;
import org.junit.Test;
import org.junit.runner.RunWith;

@RunWith(JUnitParamsRunner.class)
public class EmotionResolverTest {

  private final EmotionResolver resolver = new EmotionResolver();

  private Object[] resolveCases() {
    return new Object[] {
      new Object[] {614, true, Emotion.ANGRY},
      new Object[] {596, true, Emotion.SCARED},
      new Object[] {567, true, Emotion.HAPPY},
      new Object[] {610, true, Emotion.SAD},
      new Object[] {588, true, Emotion.NEUTRAL},
      new Object[] {614, false, Emotion.NEUTRAL},
      new Object[] {567, false, Emotion.NEUTRAL},
      new Object[] {-1, true, Emotion.NEUTRAL},
      new Object[] {123456, true, Emotion.NEUTRAL},
    };
  }

  @Test
  @Parameters(method = "resolveCases")
  public void resolvesExpressionIdToEmotion(
      int expressionId, boolean emotionEnabled, Emotion expected) {
    assertEquals(expected, resolver.resolve(expressionId, emotionEnabled));
  }
}

package com.grahambartley.runelite.voiced.dialogue.profile;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;

import org.junit.Before;
import org.junit.Test;

public class NpcProfilesResourceTest {

  private NpcProfileTable table;

  private NpcProfileTable.Resolution resolve(
      Integer npcId, String npcName, String race, String ethnicity) {
    return table.resolveNpc(npcId, table.matchName(npcName), race, ethnicity);
  }

  private boolean isChild(String npcName) {
    return table.matchName(npcName).child();
  }

  @Before
  public void setUp() {
    table = new NpcProfileTable();
    table.initialize();
  }

  @Test
  public void theBundledProfilesSectionLoads() {
    assertTrue("the bundled profiles section loaded", table.isLoaded());
  }

  @Test
  public void everyRaceBucketResolvesToItsOwnLayer() {
    for (String race :
        new String[] {
          "Human",
          "Elf",
          "Dwarf",
          "Goblin",
          "Monkey",
          "Gorilla",
          "Troll",
          "Undead",
          "Demon",
          "Wizard",
          "Tortugan",
          "Icyene",
          "Arceuus",
          "Aranei",
          "Dog",
          "Crab",
          "Penguin"
        }) {
      assertEquals(
          "race " + race + " resolves to its own bucket",
          "race:" + race,
          resolve(null, "someone", race, null).source());
    }
  }

  @Test
  public void everythingDefaultsToABritishAccent() {
    CharacterProfile p = resolve(null, "A Nameless Stranger", null, null).profile();
    assertTrue("the default accent is British", p.accent().contains("British"));
  }

  @Test
  public void statedSpecialAccentsHold() {
    assertTrue(
        "trolls sound South London / Brixton",
        resolve(null, "Mountain Troll", "Troll", null).profile().accent().contains("Brixton"));
    assertTrue(
        "dwarves sound Scottish",
        resolve(null, "Dwarf Miner", "Dwarf", null).profile().accent().contains("Scottish"));
    assertTrue(
        "gnomes sound country Irish",
        resolve(null, "Gnome Child", "Gnome", null).profile().accent().contains("Irish"));
    assertTrue(
        "leprechauns sound Irish",
        resolve(null, "Tool Leprechaun", "Human", null).profile().accent().contains("Irish"));
    assertTrue(
        "vampyres sound Transylvanian / Dracula-esque",
        resolve(null, "Feral Vampyre", "Undead", null)
            .profile()
            .accent()
            .contains("Transylvanian"));
    assertTrue(
        "gorillas sound deep and booming, not chattery island monkey",
        resolve(null, "Gorilla", "Gorilla", null).profile().accent().contains("booming"));
    assertTrue(
        "tortugans sound Bajan / Barbados",
        resolve(null, "Elder Korel", "Tortugan", null).profile().accent().contains("Barbados"));
    assertTrue(
        "Citizens of Arceuus sound refined and faintly echoing",
        resolve(null, "Tyss", "Arceuus", null).profile().accent().contains("beyond the room"));
    assertTrue(
        "the aranei sound soft-spoken and breathy",
        resolve(null, "Aranei scout", "Aranei", null).profile().accent().contains("breathy"));
    assertTrue(
        "dogs vocalise their lines rather than pronouncing them",
        resolve(null, "Stray dog", "Dog", null).profile().accent().contains("barked"));
    assertTrue(
        "crabs sound bright and West Country seaside",
        resolve(null, "Crab", "Crab", null).profile().accent().contains("West Country"));
    assertTrue(
        "penguins sound Russian",
        resolve(null, "KGP Agent", "Penguin", null).profile().accent().contains("Russian"));
  }

  @Test
  public void theCrabQuestLeadsLayerABespokeStyleOverTheirRaceAccent() {
    NpcProfileTable.Resolution hero = resolve(16469, "Crab", "Crab", null);
    assertTrue("the protagonist resolves his own entry", hero.source().contains("id:16469"));
    assertTrue("he is the bass player", hero.profile().style().contains("bass guitar"));
    assertTrue(
        "the crab accent still carries him", hero.profile().accent().contains("West Country"));

    NpcProfileTable.Resolution lover = resolve(16484, "Crab", "Crab", null);
    assertTrue("the lover resolves her own entry", lover.source().contains("id:16484"));
    assertNotEquals(
        "the lover is not delivered as the protagonist",
        hero.profile().style(),
        lover.profile().style());

    NpcProfileTable.Resolution spy = resolve(16485, "'Crab'", "Penguin", null);
    assertTrue(
        "the penguin in the crab costume resolves his own entry",
        spy.source().contains("id:16485"));
    assertTrue("he is running a disguise", spy.profile().style().contains("costume"));
    assertTrue("the penguin accent carries him", spy.profile().accent().contains("Russian"));
  }

  @Test
  public void penguinsKeepTheirOwnAccentRatherThanTheRegionTheyAreFoundIn() {
    CharacterProfile p = resolve(null, "Pescaling Pax", "Penguin", "fremennik").profile();
    assertTrue("the penguin accent holds over the region", p.accent().contains("Russian"));
    assertFalse("the Fremennik accent does not apply", p.accent().contains("Norse"));
  }

  @Test
  public void dogsKeepTheirVocalisedDeliveryWhereverTheyAreFound() {
    CharacterProfile p = resolve(null, "Stray dog", "Dog", "morytania").profile();
    assertTrue("the dog delivery holds over the region", p.accent().contains("barked"));
    assertFalse("the Morytanian accent does not apply", p.accent().contains("gothic"));
  }

  @Test
  public void arceuusCitizensKeepTheirOwnAccentRatherThanTheKourendOne() {
    CharacterProfile p = resolve(null, "Regath", "Arceuus", "kourend").profile();
    assertTrue("the Arceuus accent holds over the region", p.accent().contains("beyond the room"));
    assertFalse("the rustic Kourend accent does not apply", p.accent().contains("rustic"));
  }

  @Test
  public void aBespokeArceuusStyleLayersOverTheRaceAccent() {
    NpcProfileTable.Resolution r = resolve(7044, "Logosia", "Arceuus", "kourend");
    assertTrue("the bespoke layer contributes", r.source().contains("id:7044"));
    assertTrue("the race layer contributes", r.source().contains("race:Arceuus"));
    assertTrue("her librarian persona survives", r.profile().style().contains("chief librarian"));
    assertTrue(
        "she still speaks with the Arceuus accent",
        r.profile().accent().contains("beyond the room"));
  }

  @Test
  public void ethnicityAccentsHoldFromTheBundledTable() {
    assertTrue(
        "Kharidian desert locals sound Middle Eastern",
        resolve(null, "Desert Trader", "Human", "kharidian")
            .profile()
            .accent()
            .contains("Middle Eastern"));
    assertTrue(
        "Menaphite locals sound Egyptian",
        resolve(null, "Citizen", "Human", "menaphite").profile().accent().contains("Egyptian"));
    assertTrue(
        "Karamja locals sound West African",
        resolve(null, "Trader", "Human", "karamja").profile().accent().contains("African"));
    assertTrue(
        "Fremennik locals sound Norse",
        resolve(null, "Villager", "Human", "fremennik").profile().accent().contains("Norse"));
    assertTrue(
        "Wyrmscraig islanders sound country Irish",
        resolve(null, "Villager", "Human", "wyrmscraig").profile().accent().contains("Irish"));
  }

  @Test
  public void aBespokePerNpcProfileResolvesByIdFromTheBundledTable() {
    NpcProfileTable.Resolution r = resolve(3105, "Hans", "Human", null);
    assertTrue("the bespoke id contributes to the blend", r.source().contains("id:3105"));
    assertEquals("the bespoke name wins", "Hans", r.profile().name());
  }

  @Test
  public void newlyAddedBespokeNpcsResolveByIdFromTheBundledTable() {
    NpcProfileTable.Resolution roald = resolve(1399, "King Roald", "Human", "misthalin");
    assertTrue("King Roald resolves by his bespoke id", roald.source().contains("id:1399"));
    assertEquals("King Roald's bespoke name wins", "King Roald", roald.profile().name());

    NpcProfileTable.Resolution aubury = resolve(10681, "Aubury", "Human", "misthalin");
    assertEquals("Aubury's bespoke name wins", "Aubury", aubury.profile().name());
  }

  @Test
  public void barrowsBrothersResolveGhostlyUndeadWithBespokeId() {
    NpcProfileTable.Resolution ahrim = resolve(1672, "Ahrim the Blighted", "Undead", "misthalin");
    assertTrue("Ahrim keeps his bespoke id layer", ahrim.source().contains("id:1672"));
    assertEquals("Ahrim's bespoke name wins", "Ahrim the Blighted", ahrim.profile().name());
    assertTrue(
        "the Undead racial accent drives the ghostly timbre, not the British default",
        ahrim.source().contains("race:Undead"));
  }

  @Test
  public void bothMortimerFormsShareOneBespokeUndeadProfile() {
    NpcProfileTable.Resolution first = resolve(16175, "Mortimer", "Undead", null);
    NpcProfileTable.Resolution second = resolve(16294, "Mortimer", "Undead", null);
    assertTrue("the bespoke layer contributes", first.source().contains("id:16175"));
    assertTrue("the bespoke layer contributes", second.source().contains("id:16294"));
    assertTrue("the Undead race layer contributes", first.source().contains("race:Undead"));
    assertTrue("the Undead race layer contributes", second.source().contains("race:Undead"));
    assertTrue(
        "his bespoke Irish accent survives the Undead race layer",
        first.profile().accent().contains("Irish"));
    assertTrue("his skeletal persona reads undead", first.profile().style().contains("skeletal"));
    assertTrue(
        "he keeps a brisk Slayer-master delivery over the drawling Undead pace",
        first.profile().pace().contains("Brisk"));
    assertEquals(
        "both forms resolve the same profile directive",
