    assertTrue("'Child' is a child", isChild("Child"));
    assertTrue("'Schoolboy' is a child", isChild("Schoolboy"));
    assertTrue("'Schoolgirl' is a child", isChild("Schoolgirl"));
    assertTrue("'Troll child' is a child", isChild("Troll child"));
