    TIER.put("speech.spend", 1);
  }

  private static final Set<String> ROOT_TYPES_ANY_TIER =
      Collections.singleton("VoicedDialogueConfig");

  private static final Pattern IMPORT =
      Pattern.compile("^import (?:static )?" + Pattern.quote(BASE) + "\\.([\\w.]+);");

  private static String packageOfImport(String path) {
    StringBuilder pkg = new StringBuilder();
    for (String segment : path.split("\\.")) {
      if (!Character.isLowerCase(segment.charAt(0))) {
        break;
      }
      pkg.append(pkg.length() == 0 ? "" : ".").append(segment);
    }
    return pkg.toString();
  }

  @Test
  public void everyPackageIsPlacedInTheLayering() throws IOException {
    for (Path dir : walk(Files::isDirectory)) {
      assertTrue(
          "package '"
              + packageOf(dir)
              + "' is missing from the layering; place it here and in"
              + " docs/development.md",
          TIER.containsKey(packageOf(dir)));
    }
  }

  @Test
  public void noImportRunsAgainstTheLayering() throws IOException {
    List<String> violations = new ArrayList<>();
    for (Path source : sources()) {
      String from = packageOf(source.getParent());
      for (String line : Files.readAllLines(source, StandardCharsets.UTF_8)) {
        Matcher matcher = IMPORT.matcher(line);
        if (!matcher.find()) {
          continue;
        }
        String to = packageOfImport(matcher.group(1));
        if (from.equals(to)) {
          continue;
        }
        if (to.isEmpty()) {
          String type = matcher.group(1).split("\\.")[0];
          if (!ROOT_TYPES_ANY_TIER.contains(type)) {
            violations.add(
                String.format(
                    "%s imports root type %s in %s", label(from), type, source.getFileName()));
          }
          continue;
        }
        if (!TIER.containsKey(to)) {
          violations.add(
              String.format(
                  "%s imports unplaced package %s in %s",
                  label(from), label(to), source.getFileName()));
          continue;
        }
        if (TIER.get(from) > TIER.get(to)) {
          continue;
        }
        violations.add(
            String.format(
                "%s (tier %d) imports %s (tier %d) in %s",
                label(from), TIER.get(from), to, TIER.get(to), source.getFileName()));
      }
    }
    if (!violations.isEmpty()) {
      fail("imports run against the package layering:\n  " + String.join("\n  ", violations));
    }
  }

  @Test
  public void everySourceFileSitsInTheDirectoryItsPackageNames() throws IOException {
    for (Path source : sources()) {
      String pkg = packageOf(source.getParent());
      String expected = pkg.isEmpty() ? BASE : BASE + "." + pkg;
      assertEquals("misplaced source file " + source, expected, declaredPackage(source));
    }
  }

  private static String label(String pkg) {
    return pkg.isEmpty() ? "<root>" : pkg;
  }

  private static String declaredPackage(Path source) throws IOException {
    for (String line : Files.readAllLines(source, StandardCharsets.UTF_8)) {
      if (line.startsWith("package ")) {
        return line.substring("package ".length()).replace(";", "").trim();
      }
    }
    throw new AssertionError("no package declaration in " + source);
  }

  private static String packageOf(Path dir) {
    return MAIN.relativize(dir).toString().replace('/', '.');
  }

  private static List<Path> sources() throws IOException {
    return walk(path -> path.toString().endsWith(".java"));
  }

  private static List<Path> walk(java.util.function.Predicate<Path> keep) throws IOException {
    try (Stream<Path> walk = Files.walk(MAIN)) {
      return walk.filter(keep).sorted().collect(toList());
    }
  }
}

package com.grahambartley.runelite.voiced.dialogue.cache;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

import com.grahambartley.runelite.voiced.dialogue.audio.Pcm;
import com.grahambartley.runelite.voiced.dialogue.cache.TieredSynthesisCache.CacheKey;
import com.grahambartley.runelite.voiced.dialogue.profile.Emotion;
import java.nio.file.Path;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicReference;
import java.util.function.Supplier;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

public class TieredSynthesisCacheTest {

  @Rule public TemporaryFolder tmp = new TemporaryFolder();

  private static final CacheKey KEY =
      new CacheKey("cloud-openrouter", "npc:HUMAN:MALE", Emotion.NEUTRAL, "Echo");

  private static final class CountingDiskCache extends DiskAudioCache {
    final AtomicInteger gets = new AtomicInteger();

    CountingDiskCache(Path dir) {
      super(dir);
    }

    @Override
    public Pcm get(String backendId, String voiceKey, Emotion emotion, String text) {
      gets.incrementAndGet();
      return super.get(backendId, voiceKey, emotion, text);
    }
  }

  private Path cacheDir() {
    return tmp.getRoot().toPath().resolve("cache");
  }

  private static Pcm pcm(float sample) {
    return new Pcm(new float[] {sample}, 24_000);
  }

  private static Pcm synthOnce(TieredSynthesisCache cache, CacheKey key, Pcm result) {
    return cache.withInFlight(key, () -> result, () -> {});
  }

  @Test
  public void anUnknownKeyMissesBothTiers() {
    TieredSynthesisCache cache = new TieredSynthesisCache(8, null);
    assertNull(cache.lookup(KEY));
    assertNull(cache.memoryHit(KEY));
  }

  @Test
  public void aSynthIsWrittenThroughToBothTiers() {
    DiskAudioCache disk = new DiskAudioCache(cacheDir());
    Pcm synthed = pcm(0.5f);
    synthOnce(new TieredSynthesisCache(8, disk), KEY, synthed);

    TieredSynthesisCache nextSession = new TieredSynthesisCache(8, new DiskAudioCache(cacheDir()));
    Pcm read = nextSession.lookup(KEY);
    assertNotNull("the line survives into a fresh session", read);
    assertEquals(0.5f, read.getSamples()[0], 0f);
  }

  @Test
  public void aDiskHitIsPromotedIntoMemory() {
    synthOnce(new TieredSynthesisCache(8, new DiskAudioCache(cacheDir())), KEY, pcm(0.5f));

    CountingDiskCache disk = new CountingDiskCache(cacheDir());
    TieredSynthesisCache cache = new TieredSynthesisCache(8, disk);

    assertNotNull("the first lookup falls through to disk", cache.lookup(KEY));
    assertEquals("which cost exactly one disk read", 1, disk.gets.get());
    assertNotNull("the promoted entry is now in the memory tier", cache.memoryHit(KEY));

    assertNotNull(cache.lookup(KEY));
    assertEquals("the replay never touches disk again", 1, disk.gets.get());
  }

  @Test
  public void memoryHitNeverReadsTheDiskTier() {
    synthOnce(new TieredSynthesisCache(8, new DiskAudioCache(cacheDir())), KEY, pcm(0.5f));

    CountingDiskCache disk = new CountingDiskCache(cacheDir());
    assertNull(new TieredSynthesisCache(8, disk).memoryHit(KEY));
    assertEquals("the game-thread-safe lookup must not reach the filesystem", 0, disk.gets.get());
  }

  @Test
  public void aFailedSynthIsNotCached() {
    TieredSynthesisCache cache = new TieredSynthesisCache(8, new DiskAudioCache(cacheDir()));

    assertNull(cache.withInFlight(KEY, () -> null, () -> {}));
    assertNull("nothing was written through", cache.lookup(KEY));
  }

  @Test
  public void aCacheWithNoDiskTierStillServesFromMemory() {
    TieredSynthesisCache cache = new TieredSynthesisCache(8, null);
    Pcm synthed = pcm(0.25f);

    assertSame(synthed, synthOnce(cache, KEY, synthed));
    assertSame(synthed, cache.lookup(KEY));
  }

  @Test
  public void concurrentIdenticalSynthsIssueExactlyOneBackendCall() throws Exception {
    TieredSynthesisCache cache = new TieredSynthesisCache(8, null);
    CountDownLatch entered = new CountDownLatch(1);
    CountDownLatch release = new CountDownLatch(1);
    AtomicInteger calls = new AtomicInteger();
    AtomicBoolean waiterWasDeduped = new AtomicBoolean();
    Pcm canned = pcm(0.2f);

    Supplier<Pcm> slowSynth =
        () -> {
          calls.incrementAndGet();
          entered.countDown();
          try {
            release.await();
          } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
          }
          return canned;
        };

    AtomicReference<Pcm> first = new AtomicReference<>();
    AtomicReference<Pcm> second = new AtomicReference<>();
    AtomicBoolean ownerWasDeduped = new AtomicBoolean();
    Thread owner =
        new Thread(
            () -> first.set(cache.withInFlight(KEY, slowSynth, () -> ownerWasDeduped.set(true))));
    owner.start();
    assertTrue("owner reached the synth", entered.await(2, TimeUnit.SECONDS));

    Thread waiter =
        new Thread(
            () -> second.set(cache.withInFlight(KEY, slowSynth, () -> waiterWasDeduped.set(true))));
    waiter.start();
    while (waiter.getState() != Thread.State.WAITING) {
      Thread.onSpinWait();
    }
    release.countDown();
    owner.join(2_000);
    waiter.join(2_000);

    assertEquals("two simultaneous identical requests issue exactly one synth", 1, calls.get());
    assertNotNull("the owner produced audio", first.get());
    assertSame("the waiter reuses the owner's audio", first.get(), second.get());
    assertFalse("the owner ran the synth itself", ownerWasDeduped.get());
    assertTrue("the waiter was told it reused an in-flight synth", waiterWasDeduped.get());
  }

  @Test
  public void aKeyIsSynthesizableAgainOnceTheFirstSynthFinishes() {
    TieredSynthesisCache cache = new TieredSynthesisCache(8, null);

    try {
      cache.withInFlight(
          KEY,
          () -> {
            throw new IllegalStateException("backend blew up");
          },
          () -> {});
    } catch (IllegalStateException expected) {
    }

    Pcm retry = pcm(0.9f);
    assertSame("a retry after a failed synth is not blocked", retry, synthOnce(cache, KEY, retry));
    assertSame("and its result is cached", retry, cache.lookup(KEY));
  }
}

package com.grahambartley.runelite.voiced.dialogue.cache;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import org.junit.Test;

public class LruCacheTest {

  @Test
  public void evictsLeastRecentlyUsedBeyondCapacity() {
    LruCache<String, Integer> cache = new LruCache<>(2);
    cache.put("a", 1);
    cache.put("b", 2);
    cache.put("c", 3);

    assertEquals(2, cache.size());
    assertFalse("oldest entry should be evicted", cache.containsKey("a"));
    assertTrue(cache.containsKey("b"));
    assertTrue(cache.containsKey("c"));
  }

  @Test
  public void readingAnEntryMarksItMostRecentlyUsed() {
    LruCache<String, Integer> cache = new LruCache<>(2);
    cache.put("a", 1);
    cache.put("b", 2);

    assertEquals(Integer.valueOf(1), cache.get("a"));
    cache.put("c", 3);

    assertTrue(cache.containsKey("a"));
    assertFalse("untouched entry should be evicted", cache.containsKey("b"));
    assertTrue(cache.containsKey("c"));
  }

  @Test
  public void putReplacesExistingValueWithoutGrowing() {
    LruCache<String, Integer> cache = new LruCache<>(2);
    cache.put("a", 1);
    cache.put("a", 2);

    assertEquals(1, cache.size());
    assertEquals(Integer.valueOf(2), cache.get("a"));
  }

  @Test
  public void missingKeyReturnsNull() {
    LruCache<String, Integer> cache = new LruCache<>(2);
    assertNull(cache.get("nope"));
  }

  @Test(expected = IllegalArgumentException.class)
  public void rejectsNonPositiveCapacity() {
    new LruCache<String, Integer>(0);
  }
}

package com.grahambartley.runelite.voiced.dialogue.cache;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.grahambartley.runelite.voiced.dialogue.audio.Pcm;
import com.grahambartley.runelite.voiced.dialogue.profile.Emotion;
import java.io.IOException;
import java.nio.ByteBuffer;
import java.nio.ByteOrder;
import java.nio.charset.StandardCharsets;
import java.nio.file.DirectoryStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.attribute.FileTime;
import java.util.HashSet;
import java.util.Set;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicLong;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

public class DiskAudioCacheTest {

  private static final long MTIME_BASE = System.currentTimeMillis() - TimeUnit.HOURS.toMillis(1);

  @Rule public TemporaryFolder tmp = new TemporaryFolder();

  private Path cacheDir() {
    return tmp.getRoot().toPath().resolve("cache");
  }

  private static Pcm pcm(int sampleRate, float... samples) {
    return new Pcm(samples, sampleRate);
  }

  @Test
  public void missWhenNothingStored() {
    DiskAudioCache cache = new DiskAudioCache(cacheDir());
    assertNull(cache.get("cloud-openrouter", "npc:HUMAN:MALE", Emotion.NEUTRAL, "Hello"));
  }

  @Test
  public void roundTripsPcmAndPreservesSampleRate() {
    DiskAudioCache cache = new DiskAudioCache(cacheDir());
    Pcm stored = pcm(48_000, 0.5f, -0.25f, 1.0f, -1.0f, 0.0f);
    cache.put("cloud-openrouter", "npc:HUMAN:MALE", Emotion.NEUTRAL, "Hello", stored);

    Pcm read = cache.get("cloud-openrouter", "npc:HUMAN:MALE", Emotion.NEUTRAL, "Hello");
    assertNotNull(read);
    assertEquals("sample rate must survive disk round-trip", 48_000, read.getSampleRate());
    assertArrayEquals(stored.getSamples(), read.getSamples(), 0.0f);
  }

  @Test
  public void survivesAcrossFreshCacheInstance() {
    Pcm stored = pcm(24_000, 0.1f, -0.1f);
    new DiskAudioCache(cacheDir())
        .put("cloud-openrouter", "npc:HUMAN:MALE", Emotion.NEUTRAL, "Persist me", stored);

    Pcm read =
        new DiskAudioCache(cacheDir())
            .get("cloud-openrouter", "npc:HUMAN:MALE", Emotion.NEUTRAL, "Persist me");
    assertNotNull("a fresh session should still find the line on disk", read);
    assertArrayEquals(stored.getSamples(), read.getSamples(), 0.0f);
  }

  @Test
  public void differentEmotionDoesNotCollide() {
    DiskAudioCache cache = new DiskAudioCache(cacheDir());
    cache.put("cloud-openrouter", "npc:HUMAN:MALE", Emotion.NEUTRAL, "Halt", pcm(24_000, 0.1f));
    cache.put("cloud-openrouter", "npc:HUMAN:MALE", Emotion.ANGRY, "Halt", pcm(24_000, 0.9f));

    Pcm neutral = cache.get("cloud-openrouter", "npc:HUMAN:MALE", Emotion.NEUTRAL, "Halt");
    Pcm angry = cache.get("cloud-openrouter", "npc:HUMAN:MALE", Emotion.ANGRY, "Halt");
    assertArrayEquals(new float[] {0.1f}, neutral.getSamples(), 0.0f);
    assertArrayEquals(new float[] {0.9f}, angry.getSamples(), 0.0f);
  }

  @Test
  public void differentBackendDoesNotCollide() {
    DiskAudioCache cache = new DiskAudioCache(cacheDir());
    cache.put(
        "cloud-openrouter", "npc:HUMAN:MALE", Emotion.NEUTRAL, "Greetings", pcm(24_000, 0.2f));
    cache.put("other-backend", "npc:HUMAN:MALE", Emotion.NEUTRAL, "Greetings", pcm(24_000, 0.8f));

    assertArrayEquals(
        new float[] {0.2f},
        cache.get("cloud-openrouter", "npc:HUMAN:MALE", Emotion.NEUTRAL, "Greetings").getSamples(),
        0.0f);
    assertArrayEquals(
        new float[] {0.8f},
        cache.get("other-backend", "npc:HUMAN:MALE", Emotion.NEUTRAL, "Greetings").getSamples(),
        0.0f);
  }

  @Test
  public void corruptFileIsTreatedAsMissAndDeleted() throws IOException {
    DiskAudioCache cache = new DiskAudioCache(cacheDir());
    cache.put(
        "cloud-openrouter", "npc:HUMAN:MALE", Emotion.NEUTRAL, "Boom", pcm(24_000, 0.3f, 0.4f));

    Path entry = onlyEntry(cacheDir());
    Files.write(entry, "not a valid cache file".getBytes(StandardCharsets.UTF_8));

    assertNull(
        "a corrupt file must read as a miss, not crash",
        cache.get("cloud-openrouter", "npc:HUMAN:MALE", Emotion.NEUTRAL, "Boom"));
    assertTrue("the corrupt file should be deleted on miss", Files.notExists(entry));

    cache.put(
        "cloud-openrouter", "npc:HUMAN:MALE", Emotion.NEUTRAL, "Boom", pcm(24_000, 0.3f, 0.4f));
    assertNotNull(cache.get("cloud-openrouter", "npc:HUMAN:MALE", Emotion.NEUTRAL, "Boom"));
  }

  @Test
  public void truncatedFileIsTreatedAsMiss() throws IOException {
    DiskAudioCache cache = new DiskAudioCache(cacheDir());
    cache.put(
        "cloud-openrouter",
        "npc:HUMAN:MALE",
        Emotion.NEUTRAL,
        "Cut",
        pcm(24_000, 0.3f, 0.4f, 0.5f));

    Path entry = onlyEntry(cacheDir());
    byte[] full = Files.readAllBytes(entry);
    Files.write(entry, java.util.Arrays.copyOf(full, full.length - 4));

    assertNull(cache.get("cloud-openrouter", "npc:HUMAN:MALE", Emotion.NEUTRAL, "Cut"));
  }

  @Test
  public void evictionKeepsUsageBoundedAndDropsOldest() throws Exception {
    long cap = 600;
    DiskAudioCache cache = new DiskAudioCache(cacheDir(), cap);

    float[] samples = new float[26];
    for (int i = 0; i < 12; i++) {
      putStamped(cache, "npc:HUMAN:MALE", "line-" + i, new Pcm(samples, 24_000), i);
    }

    assertTrue("total cache size must stay under the cap", dirSize(cacheDir()) <= cap);
    assertNull(
        "oldest line should be evicted",
        cache.get("cloud-openrouter", "npc:HUMAN:MALE", Emotion.NEUTRAL, "line-0"));
    assertNotNull(
        "newest line should remain",
        cache.get("cloud-openrouter", "npc:HUMAN:MALE", Emotion.NEUTRAL, "line-11"));
  }

  @Test
  public void unlimitedCapNeverEvicts() throws Exception {
    DiskAudioCache cache = new DiskAudioCache(cacheDir(), DiskAudioCache.UNLIMITED);

    float[] samples = new float[26];
    for (int i = 0; i < 12; i++) {
      cache.put(
          "cloud-openrouter",
          "npc:HUMAN:MALE",
          Emotion.NEUTRAL,
          "line-" + i,
          new Pcm(samples, 24_000));
    }

    assertNotNull(
        "the oldest line survives under an unlimited cache",
        cache.get("cloud-openrouter", "npc:HUMAN:MALE", Emotion.NEUTRAL, "line-0"));
    assertNotNull(
        "the newest line survives too",
        cache.get("cloud-openrouter", "npc:HUMAN:MALE", Emotion.NEUTRAL, "line-11"));
  }

  @Test
  public void readDoesNotRescueAnEntryFromFifoEviction() throws Exception {
    long cap = 600;
    DiskAudioCache cache = new DiskAudioCache(cacheDir(), cap);
    float[] samples = new float[26];

    putStamped(cache, "v", "first", new Pcm(samples, 24_000), 0);
    assertNotNull(
        "the oldest entry is present before the cache fills",
        cache.get("cloud-openrouter", "v", Emotion.NEUTRAL, "first"));

    for (int i = 0; i < 5; i++) {
      putStamped(cache, "v", "fill-" + i, new Pcm(samples, 24_000), i + 1);
    }

    assertTrue("total cache size must stay under the cap", dirSize(cacheDir()) <= cap);
    assertNull(
        "the oldest entry is evicted FIFO even though it was read",
        cache.get("cloud-openrouter", "v", Emotion.NEUTRAL, "first"));
    assertNotNull(
        "the newest entry survives", cache.get("cloud-openrouter", "v", Emotion.NEUTRAL, "fill-4"));
  }

  @Test
  public void readFailureDoesNotThrowWhenDirIsUnreadable() {
    DiskAudioCache cache = new DiskAudioCache(cacheDir());
    assertNull(cache.get("x", "y", Emotion.NEUTRAL, "z"));
    cache.put("x", "y", Emotion.NEUTRAL, "z", new Pcm(new float[] {0f}, 24_000));
  }

  @Test
  public void storedBytesAreLittleEndianFloat32AfterTheHeader() throws IOException {
    DiskAudioCache cache = new DiskAudioCache(cacheDir());
    cache.put(
        "cloud-openrouter", "npc:HUMAN:MALE", Emotion.NEUTRAL, "Bytes", pcm(24_000, 0.5f, -0.25f));

    byte[] stored = Files.readAllBytes(onlyEntry(cacheDir()));
    assertEquals("header(16) + 2 float32 samples", 16 + 2 * 4, stored.length);
    ByteBuffer buf = ByteBuffer.wrap(stored).order(ByteOrder.LITTLE_ENDIAN);
    assertEquals("magic \"TDC1\"", 0x54_44_43_31, buf.getInt());
    assertEquals("sample rate", 24_000, buf.getInt());
    assertEquals("sample count", 2, buf.getInt());
    assertEquals("reserved word", 0, buf.getInt());
    assertEquals(0.5f, buf.getFloat(), 0f);
    assertEquals(-0.25f, buf.getFloat(), 0f);
  }

  @Test
  public void loweringTheCapEvictsDownToItOnTheNextWrite() throws Exception {
    AtomicLong cap = new AtomicLong(DiskAudioCache.UNLIMITED);
    DiskAudioCache cache = new DiskAudioCache(cacheDir(), cap::get);
    float[] samples = new float[26];

    for (int i = 0; i < 6; i++) {
      putStamped(cache, "v", "line-" + i, new Pcm(samples, 24_000), i);
    }
    long grownTo = dirSize(cacheDir());
    assertTrue("the uncapped cache should hold every line", grownTo > 600);

    cap.set(600);
    putStamped(cache, "v", "after-the-change", new Pcm(samples, 24_000), 6);

    assertTrue("the lowered cap is enforced by the next write", dirSize(cacheDir()) <= 600);
    assertNull(
        "the oldest line goes first under the lowered cap",
        cache.get("cloud-openrouter", "v", Emotion.NEUTRAL, "line-0"));
    assertNotNull(
        "the line that triggered the eviction survives it",
        cache.get("cloud-openrouter", "v", Emotion.NEUTRAL, "after-the-change"));
  }

  @Test
  public void raisingTheCapEvictsNothing() throws Exception {
    AtomicLong cap = new AtomicLong(600);
    DiskAudioCache cache = new DiskAudioCache(cacheDir(), cap::get);
    float[] samples = new float[26];

    for (int i = 0; i < 4; i++) {
      putStamped(cache, "v", "line-" + i, new Pcm(samples, 24_000), i);
    }

    cap.set(64L * 1024 * 1024);
    for (int i = 4; i < 10; i++) {
      putStamped(cache, "v", "line-" + i, new Pcm(samples, 24_000), i);
    }

    assertTrue(
        "the directory should now sit well past the cap it started with",
        dirSize(cacheDir()) > 600);
    for (int i = 0; i < 10; i++) {
      assertNotNull(
          "every line survives once the cap is raised above the directory size",
          cache.get("cloud-openrouter", "v", Emotion.NEUTRAL, "line-" + i));
    }
  }

  @Test
  public void switchingTheCapToUnlimitedStopsEviction() throws Exception {
    AtomicLong cap = new AtomicLong(600);
    DiskAudioCache cache = new DiskAudioCache(cacheDir(), cap::get);
    float[] samples = new float[26];

    for (int i = 0; i < 8; i++) {
      putStamped(cache, "v", "capped-" + i, new Pcm(samples, 24_000), i);
    }
    assertTrue("the finite cap is enforced while it is set", dirSize(cacheDir()) <= 600);

    cap.set(DiskAudioCache.UNLIMITED);
    for (int i = 0; i < 8; i++) {
      putStamped(cache, "v", "uncapped-" + i, new Pcm(samples, 24_000), 8 + i);
    }

    assertTrue("nothing is evicted once the cap is lifted", dirSize(cacheDir()) > 600);
    for (int i = 0; i < 8; i++) {
      assertNotNull(
          "every line written after the cap is lifted survives",
          cache.get("cloud-openrouter", "v", Emotion.NEUTRAL, "uncapped-" + i));
    }
  }

  @Test
  public void aClipLargerThanTheCapIsNotKeptByTheWriteThatStoredIt() throws Exception {
    DiskAudioCache cache = new DiskAudioCache(cacheDir(), () -> 64L);

    cache.put(
        "cloud-openrouter", "v", Emotion.NEUTRAL, "oversized", new Pcm(new float[64], 24_000));

    assertNull(
        "a clip that alone exceeds the cap is evicted by its own write",
        cache.get("cloud-openrouter", "v", Emotion.NEUTRAL, "oversized"));
  }

  @Test
  public void anUnlimitedSupplierNeverEvicts() throws Exception {
    DiskAudioCache cache = new DiskAudioCache(cacheDir(), () -> DiskAudioCache.UNLIMITED);
    float[] samples = new float[26];

    for (int i = 0; i < 12; i++) {
      putStamped(cache, "v", "line-" + i, new Pcm(samples, 24_000), i);
    }

    assertNotNull(
        "the oldest line survives an unlimited supplier",
        cache.get("cloud-openrouter", "v", Emotion.NEUTRAL, "line-0"));
    assertNotNull(
        "the newest line survives too",
        cache.get("cloud-openrouter", "v", Emotion.NEUTRAL, "line-11"));
  }

  @Test
  public void theCapIsReadOncePerWriteSoOnePassEnforcesOneLimit() {
    AtomicInteger reads = new AtomicInteger();
    DiskAudioCache cache =
        new DiskAudioCache(
            cacheDir(),
            () -> {
              reads.incrementAndGet();
              return 600L;
            });

    cache.put("cloud-openrouter", "v", Emotion.NEUTRAL, "first", pcm(24_000, new float[26]));
    assertEquals("one write reads the cap once", 1, reads.get());

    cache.put("cloud-openrouter", "v", Emotion.NEUTRAL, "second", pcm(24_000, new float[26]));
    assertEquals("a second write reads it once more", 2, reads.get());
  }

  @Test
  public void aReadNeverConsultsTheCap() {
    AtomicInteger reads = new AtomicInteger();
    DiskAudioCache cache =
        new DiskAudioCache(
            cacheDir(),
            () -> {
              reads.incrementAndGet();
              return 600L;
            });

    assertNull(cache.get("cloud-openrouter", "v", Emotion.NEUTRAL, "absent"));
    assertEquals("a lookup has nothing to evict, so it never reads the cap", 0, reads.get());
  }

  private void putStamped(DiskAudioCache cache, String voiceKey, String text, Pcm pcm, int order)
      throws IOException {
    Set<Path> before = entries(cacheDir());
    cache.put("cloud-openrouter", voiceKey, Emotion.NEUTRAL, text, pcm);
    for (Path p : entries(cacheDir())) {
      if (!before.contains(p)) {
        Files.setLastModifiedTime(p, FileTime.fromMillis(MTIME_BASE + order * 1_000L));
      }
    }
  }

  private static Set<Path> entries(Path dir) throws IOException {
    Set<Path> paths = new HashSet<>();
    if (!Files.isDirectory(dir)) {
      return paths;
    }
    try (DirectoryStream<Path> stream = Files.newDirectoryStream(dir, "*.tdc")) {
      for (Path p : stream) {
        paths.add(p);
      }
    }
    return paths;
  }

  private static Path onlyEntry(Path dir) throws IOException {
    try (DirectoryStream<Path> stream = Files.newDirectoryStream(dir, "*.tdc")) {
      for (Path p : stream) {
        return p;
      }
    }
    throw new IllegalStateException("no cache entry found in " + dir);
  }

  private static long dirSize(Path dir) throws IOException {
    long total = 0;
    try (DirectoryStream<Path> stream = Files.newDirectoryStream(dir, "*.tdc")) {
      for (Path p : stream) {
        total += Files.size(p);
      }
    }
    return total;
  }
}

package com.grahambartley.runelite.voiced.dialogue;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

import com.puppycrawl.tools.checkstyle.Checker;
import com.puppycrawl.tools.checkstyle.ConfigurationLoader;
import com.puppycrawl.tools.checkstyle.PropertiesExpander;
import com.puppycrawl.tools.checkstyle.api.AuditEvent;
import com.puppycrawl.tools.checkstyle.api.AuditListener;
import com.puppycrawl.tools.checkstyle.api.Configuration;
import java.io.File;
import java.io.InputStream;
import java.nio.file.Files;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.TreeSet;
import org.junit.BeforeClass;
import org.junit.ClassRule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

public class NoCommentsRuleTest {

  private static final String CONFIG_PATH = "config/checkstyle/checkstyle.xml";
  private static final String FIXTURE_RESOURCE = "/comment-gate/CommentGateFixture.java.txt";
  private static final String RULE_ID = "NoComments";
  private static final String STANDARD_DOC = "docs/development.md";

  private static final Map<Integer, String> COMMENT_LINES = commentLines();
  private static final Map<Integer, String> COMMENT_LIKE_LITERAL_LINES = commentLikeLiteralLines();

  @ClassRule public static final TemporaryFolder WORKSPACE = new TemporaryFolder();

  private static List<AuditEvent> violations;

  private static Map<Integer, String> commentLines() {
    Map<Integer, String> lines = new LinkedHashMap<>();
    lines.put(3, "javadoc on the type");
    lines.put(6, "a plain line comment");
    lines.put(19, "a trailing comment after code");
    lines.put(21, "a bare double slash carrying no text");
    lines.put(23, "a block comment");
    lines.put(25, "an inline block comment after code");
    return Collections.unmodifiableMap(lines);
  }

  private static Map<Integer, String> commentLikeLiteralLines() {
    Map<Integer, String> lines = new LinkedHashMap<>();
    lines.put(7, "a url whose slashes sit inside a string");
    lines.put(9, "block comment markers inside a string");
    lines.put(11, "a double quote character literal");
    lines.put(13, "an escaped quote followed by slashes inside a string");
    lines.put(15, "the opening delimiter of a text block");
    lines.put(16, "comment markers inside a text block");
    lines.put(17, "the closing delimiter of a text block");
    return Collections.unmodifiableMap(lines);
  }

  @BeforeClass
  public static void auditTheFixture() throws Exception {
    File config = new File(CONFIG_PATH);
    assertTrue(
        CONFIG_PATH + " is missing, so the gate has no configuration to enforce", config.isFile());
    violations = audit(config, fixtureWrittenToDisk());
  }

  @Test
  public void everyCommentFormIsReported() {
    Set<Integer> reported = reportedLines();
    List<String> missed = new ArrayList<>();
    for (Map.Entry<Integer, String> line : COMMENT_LINES.entrySet()) {
      if (!reported.contains(line.getKey())) {
        missed.add("line " + line.getKey() + " (" + line.getValue() + ")");
      }
    }
    assertEquals(
        "the gate failed to report comment forms it must catch, so it has stopped gating",
        Collections.emptyList(),
        missed);
  }

  @Test
  public void noCommentLikeStringLiteralIsMistakenForAComment() {
    Set<Integer> reported = reportedLines();
    List<String> wronglyReported = new ArrayList<>();
    for (Map.Entry<Integer, String> line : COMMENT_LIKE_LITERAL_LINES.entrySet()) {
      if (reported.contains(line.getKey())) {
        wronglyReported.add("line " + line.getKey() + " (" + line.getValue() + ")");
      }
    }
    assertEquals(
        "the gate reported source that is not a comment, so the query matches too much",
        Collections.emptyList(),
        wronglyReported);
  }

  @Test
  public void theGateReportsEveryCommentAndNothingElse() {
    assertEquals(
        "expected one violation per comment in the fixture, got them at lines " + reportedLines(),
        COMMENT_LINES.size(),
        violations.size());
  }

  @Test
  public void everyViolationCarriesTheRuleIdSoCiOutputIsTraceable() {
    assertFalse("no violations were produced, so the id proves nothing", violations.isEmpty());
    for (AuditEvent violation : violations) {
      assertEquals(
          "a violation reached the build without the rule id that names it",
          RULE_ID,
          violation.getModuleId());
    }
  }

  @Test
  public void everyViolationNamesTheStandardItEnforces() {
    assertFalse("no violations were produced, so the message proves nothing", violations.isEmpty());
    for (AuditEvent violation : violations) {
      assertTrue(
          "a violation reached the build without pointing at " + STANDARD_DOC,
          violation.getMessage().contains(STANDARD_DOC));
    }
  }

  private static Set<Integer> reportedLines() {
    Set<Integer> lines = new TreeSet<>();
    for (AuditEvent violation : violations) {
      lines.add(violation.getLine());
    }
    return lines;
  }

  private static File fixtureWrittenToDisk() throws Exception {
    File target = new File(WORKSPACE.getRoot(), "CommentGateFixture.java");
    try (InputStream source = NoCommentsRuleTest.class.getResourceAsStream(FIXTURE_RESOURCE)) {
      assertNotNull(FIXTURE_RESOURCE + " is missing from the gate test resources", source);
      Files.copy(source, target.toPath());
    }
    return target;
  }

  private static List<AuditEvent> audit(File config, File subject) throws Exception {
    Configuration configuration =
        ConfigurationLoader.loadConfiguration(
            config.getPath(), new PropertiesExpander(System.getProperties()));
    List<AuditEvent> collected = new ArrayList<>();
    Checker checker = new Checker();
    try {
      checker.setModuleClassLoader(Checker.class.getClassLoader());
      checker.configure(configuration);
      checker.addListener(new ViolationCollector(collected));
      checker.process(Collections.singletonList(subject));
    } finally {
      checker.destroy();
    }
    return collected;
  }

  private static final class ViolationCollector implements AuditListener {

    private final List<AuditEvent> collected;

    private ViolationCollector(List<AuditEvent> collected) {
      this.collected = collected;
    }

    @Override
    public void addError(AuditEvent event) {
      collected.add(event);
    }

    @Override
    public void addException(AuditEvent event, Throwable throwable) {
      throw new IllegalStateException("checkstyle failed to audit the fixture", throwable);
    }

    @Override
    public void auditStarted(AuditEvent event) {}

    @Override
    public void auditFinished(AuditEvent event) {}

    @Override
    public void fileStarted(AuditEvent event) {}

    @Override
    public void fileFinished(AuditEvent event) {}
  }
}

