package com.grahambartley.runelite.voiced.dialogue.speaker;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import java.io.StringReader;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import org.junit.Test;

public class NpcEntriesReaderTest {

  private final List<String> skipped = new ArrayList<>();

  private Map<Integer, NpcAttributes> read(String json) {
    return NpcEntriesReader.read(
        new StringReader(json), AttributeSource.STATIC_TABLE, (key, e) -> skipped.add(key));
  }

  @Test
  public void readsRaceGenderEthnicityAndLifeStage() {
    Map<Integer, NpcAttributes> entries =
        read(
            "{\"npcs\":{\"7\":{\"race\":\"Elf\",\"gender\":\"Female\",\"ethnicity\":\"tirannwn\","
                + "\"lifeStage\":\"child\"}}}");

    NpcAttributes a = entries.get(7);
    assertEquals("Elf", a.getRace());
    assertEquals("Female", a.getGender());
    assertEquals("tirannwn", a.getEthnicity());
    assertEquals(AttributeSource.STATIC_TABLE, a.getSource());
    assertEquals(7, a.getNpcId());
    assertTrue("the life-stage marker rides along", a.isChild());
  }

  @Test
  public void absentOptionalFieldsStayNull() {
    NpcAttributes a = read("{\"npcs\":{\"7\":{\"race\":\"Human\",\"gender\":\"Male\"}}}").get(7);
    assertNull(a.getEthnicity());
    assertNull(a.getLifeStage());
  }

  @Test
  public void jsonNullOptionalFieldsStayNull() {
    NpcAttributes a =
        read("{\"npcs\":{\"7\":{\"race\":\"Human\",\"gender\":\"Male\",\"ethnicity\":null,"
                + "\"lifeStage\":null}}}")
            .get(7);
    assertNull(a.getEthnicity());
    assertNull(a.getLifeStage());
  }

  @Test
  public void aMalformedEntryIsReportedAndSkippedWithoutLosingTheRest() {
    Map<Integer, NpcAttributes> entries =
        read(
            "{\"npcs\":{\"notAnId\":{\"race\":\"Human\",\"gender\":\"Male\"},"
                + "\"8\":{\"gender\":\"Male\"},"
                + "\"9\":{\"race\":\"Human\",\"gender\":\"Male\"}}}");

    assertEquals("only the well-formed entry survives", 1, entries.size());
    assertEquals("Human", entries.get(9).getRace());
    assertEquals("both bad rows are reported", 2, skipped.size());
  }

  @Test
  public void aDocumentWithoutAnNpcsObjectReadsAsAbsent() {
    assertNull(read("{}"));
    assertNull(read("{\"npcs\":[]}"));
  }
}

package com.grahambartley.runelite.voiced.dialogue.speaker;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.concurrent.TimeUnit;
import org.junit.Test;

public class LearnedNpcStoreTest {

  private final Gson gson = new Gson();

  @Test
  public void learnsAndReadsBackWithEthnicity() throws Exception {
    Path file = Files.createTempDirectory("learned").resolve("learned-npcs.json");
    LearnedNpcStore store = new LearnedNpcStore(file, gson);

    store.learn(123, "Dwarf", "Female", "kharidian");

    NpcAttributes a = store.get(123);
    assertEquals("Dwarf", a.getRace());
    assertEquals("Female", a.getGender());
    assertEquals("kharidian", a.getEthnicity());
    assertEquals(AttributeSource.LEARNED, a.getSource());
    assertEquals(123, a.getNpcId());
    assertNull("an unlearned id is absent", store.get(999));
    assertTrue("a learned id is present", store.contains(123));
    assertFalse("an unlearned id is absent", store.contains(999));
  }

  @Test
  public void persistsAcrossInstances() throws Exception {
    Path file = Files.createTempDirectory("learned").resolve("learned-npcs.json");
    new LearnedNpcStore(file, gson).learn(456, "Human", "Male", null);

    LearnedNpcStore reloaded = new LearnedNpcStore(file, gson);
    NpcAttributes a = reloaded.get(456);
    assertEquals("Human", a.getRace());
    assertEquals("Male", a.getGender());
    assertNull("a null ethnicity is not persisted", a.getEthnicity());
    assertEquals(1, reloaded.size());
  }

  @Test
  public void aMissIsRememberedUntilItsRetryWindowPasses() throws Exception {
    Path file = Files.createTempDirectory("learned").resolve("learned-npcs.json");
    LearnedNpcStore store = new LearnedNpcStore(file, gson);
    long now = System.currentTimeMillis();

    assertTrue("an unseen id is worth looking up", store.isPastMissWindow(11, now));

    store.missed(11, now);
    assertFalse("a fresh miss is not repeated", store.isPastMissWindow(11, now));
    assertFalse(
        "a fresh miss survives a restart",
        new LearnedNpcStore(file, gson).isPastMissWindow(11, now));
    assertTrue(
        "a stale miss is retried", store.isPastMissWindow(11, now + TimeUnit.DAYS.toMillis(31)));
  }

  @Test
  public void learningAnIdClearsItsMiss() throws Exception {
    Path file = Files.createTempDirectory("learned").resolve("learned-npcs.json");
    LearnedNpcStore store = new LearnedNpcStore(file, gson);
    long now = System.currentTimeMillis();

    store.missed(22, now);
    store.learn(22, "Human", "Female", "kandarin");

    assertTrue("learning clears the miss", store.isPastMissWindow(22, now));
    LearnedNpcStore reloaded = new LearnedNpcStore(file, gson);
    assertEquals("Female", reloaded.get(22).getGender());
    assertTrue(reloaded.isPastMissWindow(22, now));
  }

  @Test
  public void missingFileStartsEmpty() throws Exception {
    Path file = Files.createTempDirectory("learned").resolve("does-not-exist.json");
    assertEquals(0, new LearnedNpcStore(file, gson).size());
  }

  @Test
  public void repeatedWritesReplaceTheStoreCleanlyAndLeaveNoTempFile() throws Exception {
    Path dir = Files.createTempDirectory("learned");
    Path file = dir.resolve("learned-npcs.json");
    LearnedNpcStore store = new LearnedNpcStore(file, gson);

    store.learn(1, "Human", "Male", null);
    store.learn(2, "Dwarf", "Female", null);
    store.learn(3, "Gnome", "Male", null);

    assertEquals(3, new LearnedNpcStore(file, gson).size());
    assertEquals(
        "the temp file is consumed by the move, never left behind",
        0,
        Files.list(dir).filter(p -> p.getFileName().toString().endsWith(".tmp")).count());
  }
}

package com.grahambartley.runelite.voiced.dialogue.speaker;

import static org.junit.Assert.assertNull;
