import org.junit.runner.RunWith;

@RunWith(JUnitParamsRunner.class)
public class WikiMappingTest {

  private final WikiMapping mapping = WikiMapping.get();

  private Object[] wikiRaceCases() {
    return new Object[] {
      new Object[] {"Human", "Human"},
      new Object[] {"[[Gnome]]", "Gnome"},
      new Object[] {"Hobgoblin", "Goblin"},
      new Object[] {"Dwarven", "Dwarf"},
      new Object[] {"Elves", "Elf"},
      new Object[] {"Ogre", "Troll"},
      new Object[] {"Cyclops", "Troll"},
      new Object[] {"Gorilla", "Gorilla"},
      new Object[] {"Monkey", "Monkey"},
      new Object[] {"Vampyre", "Undead"},
      new Object[] {"GHOST", "Undead"},
      new Object[] {"Dragon", "Demon"},
      new Object[] {"TzHaar", "Demon"},
      new Object[] {"Dogs", "Dog"},
      new Object[] {"Crab", "Crab"},
      new Object[] {"Penguins", "Penguin"},
      new Object[] {"Citizens of Arceuus", "Arceuus"},
      new Object[] {"Aranei", "Aranei"},
      new Object[] {"Tortugan", "Tortugan"},
      new Object[] {"Icyene", "Icyene"},
      new Object[] {"Half Icyene", "Human"},
      new Object[] {"Skeleton Hellhound", "Undead"},
      new Object[] {"Human/Elf hybrid", "Elf"},
      new Object[] {"Imp", "Demon"},
      new Object[] {"[[Crab (disambiguation)|Crab]]", "Crab"},
      new Object[] {"[[Dog_(disambiguation)|Dog]]", "Dog"},
      new Object[] {"[[Dwarf (race)|Dwarves]]", "Dwarf"},
      new Object[] {"[[Abyss (disambiguation)#Monsters|Abyssal monsters]]", "Demon"},
      new Object[] {"Merfolk", "Human"},
    };
  }

  @Test
  @Parameters(method = "wikiRaceCases")
  public void wikiRaceTextBucketsTheSameWayTheGeneratorDoes(String wikiText, String bucket) {
    assertEquals(
        "bucket for '" + wikiText + "'", bucket, mapping.raceForWikiText(readings(wikiText)));
  }

  @Test
  public void anAbsentRaceFieldHasNoBucketSoCategoriesCanAnswer() {
    assertNull(mapping.raceForWikiText(Collections.<String>emptyList()));
    assertNull(mapping.raceForWikiText(readings("{{plink|Human}}")));
  }

  @Test
  public void gorillaBeatsMonkeySoApesStayOffTheIslandVoice() {
    assertEquals("Gorilla", mapping.raceForWikiText(readings("Gorilla")));
  }

  private Object[] categoryCases() {
    return new Object[] {
      new Object[] {"Category:Trolls", "Troll"},
      new Object[] {"Category:Ghosts", "Undead"},
      new Object[] {"Category:TzHaar", "Demon"},
      new Object[] {"Category:Wizards", "Wizard"},
      new Object[] {"Category:Penguins", "Penguin"},
      new Object[] {"Category:Humans", "Human"},
    };
  }

  @Test
  @Parameters(method = "categoryCases")
  public void categoriesCarryTheRaceWhenTheInfoboxDoesNot(String category, String bucket) {
    assertEquals(bucket, mapping.raceForCategories(singletonList(category)));
  }

  @Test
  public void categoriesWithNoRaceKeywordAnswerNothing() {
    assertNull(mapping.raceForCategories(singletonList("Category:Quest NPCs")));
    assertNull(mapping.raceForCategories(Collections.<String>emptyList()));
    assertNull(mapping.raceForCategories(null));
  }

  @Test
  public void leagueRegionMapsOntoAnEthnicityAccent() {
    assertEquals("fremennik", mapping.ethnicityKey("Fremennik", null, null));
    assertEquals("varlamore", mapping.ethnicityKey("Varlamore", null, null));
    assertEquals("morytania", mapping.ethnicityKey("Morytania", null, null));
  }

  @Test
  public void multiRegionAndUnmappedRegionsCarryNoSingleEthnicity() {
    assertNull(mapping.ethnicityKey("Desert, Misthalin", null, null));
    assertNull(mapping.ethnicityKey("Asgarnia & Misthalin", null, null));
    assertNull(mapping.ethnicityKey("No", null, null));
    assertNull(mapping.ethnicityKey(null, null, null));
  }

  @Test
  public void theDesertSplitsOnLocationOrCategory() {
    assertEquals("kharidian", mapping.ethnicityKey("Desert", "Pollnivneach", null));
    assertEquals("menaphite", mapping.ethnicityKey("Desert", "Sophanem", null));
    assertEquals(
        "menaphite",
        mapping.ethnicityKey("Desert", "Unknown", Arrays.asList("Category:Menaphites")));
    assertEquals(
        "kharidian", mapping.ethnicityKey("Desert", null, Arrays.asList("Category:Bandits")));
  }

  @Test
  public void onlyNpcAndMonsterPagesAreWorthReading() {
    assertTrue(mapping.isNpcPage("{{Infobox NPC\n|race=Human\n}}"));
    assertTrue(mapping.isNpcPage("{{infobox_monster\n}}"));
    assertTrue(mapping.isNpcPage("{{Multi Infobox\n|item1={{Infobox NPC\n}}\n}}"));
    assertFalse(mapping.isNpcPage("{{Infobox Item\n|name=Bucket\n}}"));
    assertFalse(mapping.isNpcPage(null));
  }

  @Test
  public void genderTextNormalisesToTheStoredValues() {
    assertEquals("Female", mapping.genderForWikiText("female"));
    assertEquals("Male", mapping.genderForWikiText("Male"));
    assertEquals("Male", mapping.genderForWikiText("Unknown"));
    assertEquals("Male", mapping.genderForWikiText(null));
  }

  @Test
  public void everyDeclaredRaceVoicesFromTheRuntimeTables() {
    for (JsonElement race : mappingResource().getAsJsonArray("races")) {
      assertNotEquals(
          "voice race for declared race '" + race.getAsString() + "'",
          NpcRace.UNKNOWN,
          NpcDemographicParser.toRace(race.getAsString()));
    }
  }

  @Test
  public void everyRuleAnswersWithARaceTheOverridesAccept() {
    JsonObject resource = mappingResource();
    List<String> declared = new ArrayList<>();
    for (JsonElement race : resource.getAsJsonArray("races")) {
      declared.add(race.getAsString());
    }
    for (String rules : new String[] {"raceRules", "categoryRaceRules"}) {
      for (JsonElement rule : resource.getAsJsonArray(rules)) {
        String race = rule.getAsJsonObject().get("race").getAsString();
        assertTrue("'" + race + "' is a declared race", declared.contains(race));
      }
    }
    assertTrue(declared.contains(mapping.raceForWikiText(readings("Ogre"))));
    assertTrue(declared.contains(mapping.raceForCategories(singletonList("Category:Wizards"))));
  }

  private static List<String> readings(String wikiText) {
    return WikiInfobox.parse("{{Infobox NPC\n|race = " + wikiText + "\n}}", null).raceReadings();
  }

  private static JsonObject mappingResource() {
    return new JsonParser()
        .parse(
            new InputStreamReader(
                WikiMapping.class.getResourceAsStream("/wiki-mapping.json"),
                StandardCharsets.UTF_8))
        .getAsJsonObject();
  }
}

package com.grahambartley.runelite.voiced.dialogue.speaker.wiki;

import static java.net.HttpURLConnection.HTTP_UNAVAILABLE;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import com.grahambartley.runelite.voiced.dialogue.speaker.LearnedNpcStore;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.Executor;
import java.util.function.IntPredicate;
import okhttp3.OkHttpClient;
import okhttp3.mockwebserver.Dispatcher;
import okhttp3.mockwebserver.MockResponse;
import okhttp3.mockwebserver.MockWebServer;
import okhttp3.mockwebserver.RecordedRequest;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;

public class NpcLearningServiceTest {

  private static final Executor INLINE = Runnable::run;
  private static final WikiCallThrottle UNTHROTTLED = new WikiCallThrottle(0);

  private final Gson gson = new Gson();

  private MockWebServer server;
  private WikiNpcClient client;
  private LearnedNpcStore store;
  private Path file;

  @Before
  public void setUp() throws Exception {
    server = new MockWebServer();
    server.start();
    client = new WikiNpcClient(new OkHttpClient(), server.url("/api.php").toString());
    file = Files.createTempDirectory("learn").resolve("learned-npcs.json");
    store = new LearnedNpcStore(file, gson);
  }

  @After
  public void tearDown() throws Exception {
    server.shutdown();
  }

  private NpcLearningService service(boolean enabled) {
    return service(enabled, npcId -> false);
  }

  private NpcLearningService service(boolean enabled, IntPredicate voiced) {
    return new NpcLearningService(client, store, INLINE, () -> enabled, voiced, UNTHROTTLED);
  }

  private void enqueueNpc() {
    server.enqueue(npcResponse());
  }

  private static MockResponse npcResponse() {
    return new MockResponse()
        .setBody(
            "{\"query\":{\"pages\":[{\"revisions\":[{\"slots\":{\"main\":{\"content\":"
                + "\"{{Infobox NPC\\n|race=[[Troll]]\\n|gender=Male\\n|id=1\\n}}\"}}}]}]}}");
  }

  private void enqueueMiss() {
    server.enqueue(new MockResponse().setBody("{\"query\":{\"pages\":[{\"missing\":true}]}}"));
  }

  @Test
  public void learnsAnUnknownNpcThenDoesNotQueryAgain() {
    enqueueNpc();
    NpcLearningService service = service(true);

    service.considerLearning(500, "New Troll");
    assertNotNull("the wiki hit is stored", store.get(500));
    assertEquals("Troll", store.get(500).getRace());
    assertEquals(1, server.getRequestCount());

    service.considerLearning(500, "New Troll");
    assertEquals("an id is attempted at most once", 1, server.getRequestCount());
  }

  @Test
  public void disabledMakesNoRequest() {
    service(false).considerLearning(600, "Someone");
    assertEquals(0, server.getRequestCount());
    assertNull(store.get(600));
  }

  @Test
  public void alreadyLearnedIdIsNotRefetched() {
    store.learn(700, "Human", "Female", null);
    service(true, npcId -> store.get(npcId) != null).considerLearning(700, "Known");
    assertEquals(0, server.getRequestCount());
  }

  @Test
  public void aMissIsRememberedSoTheNextSessionDoesNotRepeatIt() throws Exception {
    enqueueMiss();
    service(true).considerLearning(800, "Nobody");
    assertEquals(1, server.getRequestCount());

    LearnedNpcStore reloaded = new LearnedNpcStore(file, gson);
    assertFalse(reloaded.isPastMissWindow(800, System.currentTimeMillis()));
    new NpcLearningService(client, reloaded, INLINE, () -> true, npcId -> false, UNTHROTTLED)
        .considerLearning(800, "Nobody");
    assertEquals("a remembered miss is not queried again", 1, server.getRequestCount());
  }

  @Test
  public void aStaleMissIsRetried() throws Exception {
    enqueueMiss();
    service(true).considerLearning(900, "Nobody");

    String aged =
        new String(Files.readAllBytes(file), "UTF-8").replaceAll("\"900\":\\d+", "\"900\":1");
    Files.write(file, aged.getBytes("UTF-8"));

    LearnedNpcStore reloaded = new LearnedNpcStore(file, gson);
    assertTrue(reloaded.isPastMissWindow(900, System.currentTimeMillis()));
    enqueueNpc();
    new NpcLearningService(client, reloaded, INLINE, () -> true, npcId -> false, UNTHROTTLED)
        .considerLearning(900, "New Troll");
    assertEquals(2, server.getRequestCount());
    assertEquals("Troll", reloaded.get(900).getRace());
  }

  @Test
  public void aRunOfUnreachableAnswersStopsAskingForAWhile() {
    for (int call = 0; call < 3; call++) {
      server.enqueue(new MockResponse().setResponseCode(HTTP_UNAVAILABLE));
    }
    NpcLearningService service = service(true);

    service.considerLearning(1200, "Someone");
    service.considerLearning(1201, "Someone Else");
    service.considerLearning(1202, "A Third");
    assertEquals(3, server.getRequestCount());

    service.considerLearning(1203, "A Fourth");
    assertEquals("a wiki that keeps failing is left alone", 3, server.getRequestCount());
  }

  @Test
  public void onlyDialogueMenuOptionsStartAConversation() {
    NpcLearningService service = service(true);

    assertTrue(service.startsConversation("Talk-to"));
    assertTrue(service.startsConversation("talk to"));
    assertFalse(service.startsConversation("Attack"));
    assertFalse(service.startsConversation("Examine"));
    assertFalse(service.startsConversation(null));
  }

  @Test
  public void anNpcTheBundledTableAlreadyVoicesIsNeverLookedUp() {
    service(true, npcId -> npcId == 1100).considerLearning(1100, "Bundled NPC");

    assertEquals("the bundled table wins, so nothing is asked", 0, server.getRequestCount());
    assertNull(store.get(1100));
  }

  @Test
  public void aClosedServiceNeverQueuesAnotherLookup() {
    NpcLearningService service = service(true);
    service.close();

    service.considerLearning(1, "Troll");

    assertEquals("a closed service makes no wiki call", 0, server.getRequestCount());
    assertNull("a closed service learns nothing", store.get(1));
  }

  @Test
  public void aQueuedLookupIsDroppedWhenTheServiceClosesBeforeItRuns() {
    DeferredExecutor executor = new DeferredExecutor();
    NpcLearningService service =
        new NpcLearningService(client, store, executor, () -> true, npcId -> false, UNTHROTTLED);

    service.considerLearning(1, "Troll");
    service.close();
    executor.runAll();

    assertEquals("a lookup queued at close makes no wiki call", 0, server.getRequestCount());
    assertNull("a lookup queued at close learns nothing", store.get(1));
  }

  @Test
  public void aLookupAnsweredAfterTheServiceClosesNeverWritesToTheStore() {
    NpcLearningService[] holder = new NpcLearningService[1];
    server.setDispatcher(
        new Dispatcher() {
          @Override
          public MockResponse dispatch(RecordedRequest request) {
            holder[0].close();
            return npcResponse();
          }
        });
    NpcLearningService service =
        new NpcLearningService(client, store, INLINE, () -> true, npcId -> false, UNTHROTTLED);
    holder[0] = service;

    service.considerLearning(1, "Troll");

    assertEquals("the lookup still went out", 1, server.getRequestCount());
    assertNull("a lookup answered after close is discarded", store.get(1));
  }

  @Test
  public void aServiceClosedDuringItsThrottleWaitNeverCallsTheWiki() {
    DeferredExecutor executor = new DeferredExecutor();
    WikiCallThrottle throttle = new WikiCallThrottle(50);
    throttle.awaitTurn();
    NpcLearningService service =
        new NpcLearningService(client, store, executor, () -> true, npcId -> false, throttle);

    service.considerLearning(1, "Troll");
    service.close();
    executor.runAll();

    assertEquals("a service closed mid-wait makes no wiki call", 0, server.getRequestCount());
    assertNull("and learns nothing", store.get(1));
  }

  private static final class DeferredExecutor implements Executor {
    private final List<Runnable> tasks = new ArrayList<>();

    @Override
    public void execute(Runnable command) {
      tasks.add(command);
    }

    void runAll() {
      List<Runnable> snapshot = new ArrayList<>(tasks);
      tasks.clear();
      for (Runnable task : snapshot) {
        task.run();
      }
    }
  }
}

package com.grahambartley.runelite.voiced.dialogue.speaker.wiki;

import static java.net.HttpURLConnection.HTTP_INTERNAL_ERROR;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.grahambartley.runelite.voiced.dialogue.speaker.AttributeSource;
import com.grahambartley.runelite.voiced.dialogue.speaker.NpcAttributes;
import okhttp3.OkHttpClient;
import okhttp3.mockwebserver.MockResponse;
import okhttp3.mockwebserver.MockWebServer;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;

public class WikiNpcClientTest {

  private MockWebServer server;
  private WikiNpcClient client;

  @Before
  public void setUp() throws Exception {
    server = new MockWebServer();
    server.start();
    client = new WikiNpcClient(new OkHttpClient(), server.url("/api.php").toString());
  }

  @After
  public void tearDown() throws Exception {
    server.shutdown();
  }

  private static String pageBody(String infobox, String... categories) {
    String content = infobox.replace("\n", "\\n").replace("\"", "\\\"");
    StringBuilder categoryJson = new StringBuilder();
    for (String category : categories) {
      categoryJson.append(categoryJson.length() == 0 ? "" : ",");
      categoryJson.append("{\"title\":\"").append(category).append("\"}");
    }
    return "{\"query\":{\"pages\":[{\"title\":\"X\",\"categories\":["
        + categoryJson
        + "],\"revisions\":[{\"slots\":{\"main\":{\"content\":\""
        + content
        + "\"}}}]}]}}";
  }

  private void enqueue(String infobox, String... categories) {
    server.enqueue(new MockResponse().setBody(pageBody(infobox, categories)));
  }

  @Test
  public void parsesRaceGenderAndDesertEthnicity() {
    enqueue(
        "{{Infobox NPC\n|race = [[Human]]\n|gender = Female\n|leagueRegion = Desert\n"
            + "|location = Pollnivneach\n|id = 123\n}}");

    NpcAttributes attributes = client.lookup(123, "Some Trader").attributes();
    assertEquals("Human", attributes.getRace());
    assertEquals("Female", attributes.getGender());
    assertEquals("kharidian", attributes.getEthnicity());
    assertEquals(AttributeSource.WIKI, attributes.getSource());
    assertEquals(123, attributes.getNpcId());
  }

  @Test
  public void eachVersionOfASwitchInfoboxLearnsItsOwnGender() {
    enqueue(
        "{{Infobox NPC\n|race = [[Human]]\n|gender1 = Male\n|gender2 = Female\n"
            + "|id1 = 3010\n|id2 = 3012\n|leagueRegion = Asgarnia\n}}");

    assertEquals("Female", client.lookup(3012, "Guard").attributes().getGender());
  }

  @Test
  public void menaphiteCategoryMapsToTheEgyptianEthnicity() {
    enqueue(
        "{{Infobox NPC\n|race=[[Human]]\n|gender=Male\n|leagueRegion=Desert\n|id=1\n}}",
        "Category:Menaphites");

    assertEquals("menaphite", client.lookup(1, "Menaphite Thug").attributes().getEthnicity());
  }

  @Test
  public void aMonsterPageTakesItsRaceFromTheCategories() {
    enqueue(
        "{{Infobox Monster\n|gender = Female\n|leagueRegion = Fremennik\n|id = 55\n}}",
        "Category:Trolls");

    NpcAttributes attributes = client.lookup(55, "Kob").attributes();
    assertEquals("Troll", attributes.getRace());
    assertEquals("Female", attributes.getGender());
    assertEquals("fremennik", attributes.getEthnicity());
  }

  @Test
  public void aPageWithNoRaceAnywhereStillLearnsGenderAndEthnicity() {
    enqueue("{{Infobox NPC\n|gender = Female\n|leagueRegion = Kandarin\n|id = 7\n}}");

    NpcAttributes attributes = client.lookup(7, "Someone").attributes();
    assertEquals("Human", attributes.getRace());
    assertEquals("Female", attributes.getGender());
    assertEquals("kandarin", attributes.getEthnicity());
  }

  @Test
  public void mapsLoreRaceOntoVoiceBucket() {
    enqueue("{{Infobox NPC\n|race=[[Ogre]]\n|gender=Male\n|id=1\n}}");
    assertEquals(
        "an ogre voices from the Troll bucket",
        "Troll",
        client.lookup(1, "Ogre").attributes().getRace());
  }

  @Test
  public void aRaceLinkedThroughADisambiguationPageStillBucketsOnItsDisplayText() {
    enqueue("{{Infobox NPC\n|race=[[Dog_(disambiguation)|Dog]]\n|gender=Female\n|id=10439\n}}");
    NpcAttributes attributes = client.lookup(10439, "Sheepdog").attributes();
    assertEquals("Dog", attributes.getRace());
    assertEquals("Female", attributes.getGender());
  }

  @Test
  public void aPageThatIsNotAnNpcIsUndocumented() {
    enqueue("{{Infobox Item\n|name = Bucket\n}}");

    WikiLookup lookup = client.lookup(1, "Bucket");
    assertTrue("a page the wiki holds is answered, not retried", lookup.isUndocumented());
    assertFalse(lookup.isUnreachable());
    assertNull(lookup.attributes());
  }

  @Test
  public void aMissingPageIsUndocumented() {
    server.enqueue(new MockResponse().setBody("{\"query\":{\"pages\":[{\"missing\":true}]}}"));
    assertTrue(client.lookup(1, "Not An NPC").isUndocumented());
  }

  @Test
  public void anErrorLeavesTheNpcUnanswered() {
    server.enqueue(new MockResponse().setResponseCode(HTTP_INTERNAL_ERROR));

    WikiLookup lookup = client.lookup(1, "Anything");
    assertTrue("a wiki outage must not blacklist the npc", lookup.isUnreachable());
    assertFalse(lookup.isUndocumented());
  }

  @Test
  public void aBlankNameIsNotLookedUp() {
    assertTrue(client.lookup(1, " ").isUndocumented());
    assertTrue(client.lookup(1, null).isUndocumented());
    assertTrue(client.lookup(1, "<col=00ffff></col>").isUndocumented());
    assertEquals(0, server.getRequestCount());
  }

  @Test
  public void theNameIsNormalisedBeforeItReachesTheWiki() throws Exception {
    enqueue("{{Infobox NPC\n|race=Human\n|gender=Male\n|id=1\n}}");

    client.lookup(1, "<col=00ffff>Hans</col> ");

    assertTrue(
        "markup and padding never reach the query",
        server.takeRequest().getPath().contains("titles=Hans"));
  }

  @Test
  public void aResponseThatIsNotWikiJsonLeavesTheNpcUnanswered() {
    server.enqueue(new MockResponse().setBody("{\"error\":{\"code\":\"invalidtitle\"}}"));
    assertTrue("an api error is worth retrying", client.lookup(1, "?").isUnreachable());

    server.enqueue(new MockResponse().setBody("<html>captive portal</html>"));
    assertTrue("a portal page is not an answer", client.lookup(1, "Hans").isUnreachable());
  }

  @Test
  public void aQueryThatHoldsNoPagesIsUndocumented() {
    server.enqueue(new MockResponse().setBody("{\"query\":{\"pages\":[]}}"));

    assertTrue(client.lookup(1, "Nobody").isUndocumented());
  }

  @Test
  public void theCategoriesAreRequestedAlongsideTheRevision() throws Exception {
    enqueue("{{Infobox NPC\n|race=Human\n|gender=Male\n|id=1\n}}");
    client.lookup(1, "Someone");

    String path = server.takeRequest().getPath();
    assertEquals("categories are requested", true, path.contains("revisions%7Ccategories"));
  }
}

package com.grahambartley.runelite.voiced.dialogue.speaker.wiki;

import static org.junit.Assert.assertTrue;

import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import org.junit.Test;

public class WikiCallThrottleTest {

  @Test
  public void theFirstTurnIsTakenImmediately() {
    long before = System.nanoTime();
    new WikiCallThrottle(60_000).awaitTurn();

    assertTrue(
        "the first call never waits", System.nanoTime() - before < TimeUnit.SECONDS.toNanos(30));
  }

  @Test
  public void aSecondTurnWaitsOutTheInterval() {
    long interval = 20;
    WikiCallThrottle throttle = new WikiCallThrottle(interval);

    long before = System.nanoTime();
    throttle.awaitTurn();
    throttle.awaitTurn();

    assertTrue(
        "a second call waits at least the interval",
        System.nanoTime() - before >= TimeUnit.MILLISECONDS.toNanos(interval));
  }

  @Test
  public void aZeroIntervalNeverWaits() {
    WikiCallThrottle throttle = new WikiCallThrottle(0);
    long before = System.nanoTime();
    for (int call = 0; call < 5; call++) {
      throttle.awaitTurn();
    }

    assertTrue(
        "a zero interval never waits", System.nanoTime() - before < TimeUnit.SECONDS.toNanos(1));
  }

  @Test
  public void aWaitingTurnIgnoresAnInterruptAndStillTakesItsTurn() throws Exception {
    WikiCallThrottle throttle = new WikiCallThrottle(200);
    throttle.awaitTurn();

    AtomicBoolean tookTurn = new AtomicBoolean();
    CountDownLatch waiting = new CountDownLatch(1);
    CountDownLatch done = new CountDownLatch(1);
    Thread waiter =
        new Thread(
            () -> {
              waiting.countDown();
              throttle.awaitTurn();
              tookTurn.set(true);
              done.countDown();
            });

    waiter.start();
    assertTrue("the waiter reached its turn", waiting.await(5, TimeUnit.SECONDS));
    waiter.interrupt();

    assertTrue("the waiter completes its turn", done.await(5, TimeUnit.SECONDS));
    assertTrue("an interrupt never makes a waiting call skip the wiki", tookTurn.get());
  }
}

package com.grahambartley.runelite.voiced.dialogue.speaker.wiki;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import java.util.Arrays;
import java.util.Collections;
import org.junit.Test;

public class WikiInfoboxTest {

  private static final String SWITCH_PAGE =
      "{{Infobox NPC\n"
          + "|race = [[Human]]\n"
          + "|gender1 = Male\n"
          + "|gender2 = Female\n"
          + "|id1 = 3010, 3011\n"
          + "|id2 = 3012\n"
          + "|leagueRegion = Asgarnia\n"
          + "}}";

  @Test
  public void fieldsAreStrippedOfWikiMarkup() {
    WikiInfobox infobox =
        WikiInfobox.parse(
            "{{Infobox NPC\n|race = [[Dwarf (race)]]<ref>a ref</ref>\n|location = ''Keldagrim''\n}}",
            null);
    assertEquals(Collections.singletonList("Dwarf (race)"), infobox.raceReadings());
    assertEquals("''Keldagrim''", infobox.location());
  }

  @Test
  public void eachVersionKeepsItsOwnGender() {
    WikiInfobox infobox = WikiInfobox.parse(SWITCH_PAGE, null);
    assertEquals("Male", infobox.genderForVersion(3010));
    assertEquals("Male", infobox.genderForVersion(3011));
    assertEquals("Female", infobox.genderForVersion(3012));
  }

  @Test
  public void anIdTheVersionsDoNotListFallsBackToTheFirstGender() {
    assertEquals("Male", WikiInfobox.parse(SWITCH_PAGE, null).genderForVersion(99999));
  }

  @Test
  public void gendersThatDoNotPairWithTheIdGroupsAllUseTheFirst() {
    WikiInfobox infobox =
        WikiInfobox.parse("{{Infobox NPC\n|gender = Female\n|id1 = 1\n|id2 = 2\n}}", null);
    assertEquals("Female", infobox.genderForVersion(1));
    assertEquals("Female", infobox.genderForVersion(2));
  }

  @Test
  public void aPageWithoutAGenderFieldAnswersNothing() {
    assertNull(WikiInfobox.parse("{{Infobox NPC\n|race = Human\n}}", null).genderForVersion(1));
  }

  @Test
  public void aPipedRaceReadsItsTargetBeforeItsDisplayText() {
    assertEquals(
        Arrays.asList("Dog_(disambiguation)", "Dog"),
        WikiInfobox.parse("{{Infobox NPC\n|race = [[Dog_(disambiguation)|Dog]]\n}}", null)
            .raceReadings());
  }

  @Test
  public void aPipedLeagueRegionAndLocationReadTheirTargets() {
    WikiInfobox infobox =
        WikiInfobox.parse(
            "{{Infobox NPC\n|leagueRegion = [[Kandarin|the Kandarin region]]\n"
                + "|location = [[Ardougne|East Ardougne]]\n}}",
            null);
    assertEquals("Kandarin", infobox.leagueRegion());
    assertEquals("Ardougne", infobox.location());
  }

  @Test
  public void aSingleLineSwitchInfoboxKeepsEveryVersion() {
    WikiInfobox infobox =
        WikiInfobox.parse(
            "{{Infobox NPC|id1=10438|gender1=Male|id2=10439|gender2=Female"
                + "|race=[[Dog_(disambiguation)|Dog]]}}",
            null);
    assertEquals("Male", infobox.genderForVersion(10438));
    assertEquals("Female", infobox.genderForVersion(10439));
    assertEquals(Arrays.asList("Dog_(disambiguation)", "Dog"), infobox.raceReadings());
  }

  @Test
  public void aTemplatedValueIsNotCutAtItsInnerPipe() {
    assertEquals(
        "and Draynor",
        WikiInfobox.parse(
                "{{Infobox NPC\n|location = {{plink|Lumbridge}} and [[Draynor|the village]]\n}}",
                null)
            .location());
  }

  @Test
  public void aStrayCloseEndsTheValueRatherThanSwallowingTheNextParameter() {
    WikiInfobox infobox = WikiInfobox.parse("{{Infobox NPC|race=Dog]]|gender=Female|id=1}}", null);
    assertEquals(Collections.singletonList("Dog"), infobox.raceReadings());
    assertEquals("Female", infobox.genderForVersion(1));
  }

  @Test
  public void categoriesRideAlongWithTheInfobox() {
    assertEquals(
        Collections.singletonList("Category:Trolls"),
        WikiInfobox.parse("{{Infobox Monster\n}}", Collections.singletonList("Category:Trolls"))
            .categories());
    assertTrue(WikiInfobox.parse("{{Infobox Monster\n}}", null).categories().isEmpty());
  }
}

