  @Test
  public void missingKeyWarningPostsOnceWithTheBackendsOwnNotice() {
    manager.maybeWarnMissingCloudKey(backend(false, OpenRouterTtsBackend.NO_KEY_NOTICE));
    manager.maybeWarnMissingCloudKey(backend(false, OpenRouterTtsBackend.NO_KEY_NOTICE));

    verify(client, times(1))
        .addChatMessage(
            eq(ChatMessageType.GAMEMESSAGE),
            eq(""),
            contains(OpenRouterTtsBackend.NO_KEY_NOTICE),
            isNull());
  }

  @Test
  public void missingKeyWarningNamesTheActiveProvider() {
    manager.maybeWarnMissingCloudKey(backend(false, "Add your Google AI Studio API key"));

    verify(client, times(1))
        .addChatMessage(
            eq(ChatMessageType.GAMEMESSAGE),
            eq(""),
            contains("Add your Google AI Studio API key"),
            isNull());
  }

  @Test
  public void missingKeyWarningStaysQuietWhenKeyAvailable() {
    manager.maybeWarnMissingCloudKey(backend(true, OpenRouterTtsBackend.NO_KEY_NOTICE));

    verify(client, never())
        .addChatMessage(eq(ChatMessageType.GAMEMESSAGE), eq(""), contains(""), isNull());
  }

  @Test
  public void clearingTheKeyLaterInTheSessionStillWarnsOnce() {
    manager.maybeWarnMissingCloudKey(backend(true, OpenRouterTtsBackend.NO_KEY_NOTICE));
    manager.maybeWarnMissingCloudKey(backend(false, OpenRouterTtsBackend.NO_KEY_NOTICE));
    manager.maybeWarnMissingCloudKey(backend(false, OpenRouterTtsBackend.NO_KEY_NOTICE));

    verify(client, times(1))
        .addChatMessage(
            eq(ChatMessageType.GAMEMESSAGE),
            eq(""),
            contains(OpenRouterTtsBackend.NO_KEY_NOTICE),
            isNull());
  }

  private static SynthesisBackend backend(boolean available, String missingKeyNotice) {
    SynthesisBackend backend = mock(SynthesisBackend.class);
    when(backend.isAvailable()).thenReturn(available);
    when(backend.missingKeyNotice()).thenReturn(missingKeyNotice);
    return backend;
  }

  @Test
  public void aCommandResponseIsQueuedThroughTheClientsChatManager() {
    manager.postCommandResponse("OpenRouter this session: 1 lines voiced.");

    ArgumentCaptor<QueuedMessage> captor = ArgumentCaptor.forClass(QueuedMessage.class);
    verify(chatMessageManager).queue(captor.capture());
    QueuedMessage queued = captor.getValue();

    assertEquals(ChatMessageType.GAMEMESSAGE, queued.getType());
    assertTrue(
        "the readout is tagged as the plugin's: " + queued.getRuneLiteFormattedMessage(),
        queued.getRuneLiteFormattedMessage().contains("[Voiced Dialogue] "));
    assertTrue(
        "and carries the line: " + queued.getRuneLiteFormattedMessage(),
        queued.getRuneLiteFormattedMessage().contains("1 lines voiced"));
    verifyNoInteractions(client);
  }

  @Test
  public void aCommandResponseNeedsNoHopOntoTheClientThread() {
    manager.postCommandResponse("anything");

    verifyNoInteractions(clientThread);
  }
}

package com.grahambartley.runelite.voiced.dialogue.capture;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import com.grahambartley.runelite.voiced.dialogue.profile.Emotion;
import com.grahambartley.runelite.voiced.dialogue.profile.VoiceSpec;
import com.grahambartley.runelite.voiced.dialogue.speaker.NpcGender;
import com.grahambartley.runelite.voiced.dialogue.speaker.NpcRace;
import com.grahambartley.runelite.voiced.dialogue.speech.SynthesisRequest;
import com.grahambartley.runelite.voiced.dialogue.speech.TestFixtures;
import java.util.ArrayList;
import java.util.List;
import org.junit.Test;

public class DialoguePrefetcherTest {

  private final List<SynthesisRequest> warmed = new ArrayList<>();
  private int cancels;

  private DialoguePrefetcher prefetcher() {
    return new DialoguePrefetcher(warmed::add, () -> cancels++);
  }

  private static SynthesisRequest req(String text) {
    return new SynthesisRequest(
        text,
        VoiceSpec.npc(NpcRace.HUMAN, NpcGender.MALE),
        Emotion.NEUTRAL,
        TestFixtures.TROLL_PROFILE,
        false,
        false);
  }

  private static List<SynthesisRequest> options(String... texts) {
    List<SynthesisRequest> list = new ArrayList<>();
    for (String text : texts) {
      list.add(req(text));
    }
    return list;
  }

  @Test
  public void offersEachReachableLineOnce() {
    DialoguePrefetcher prefetcher = prefetcher();

    prefetcher.offer(options("Yes.", "No.", "Maybe."));

    assertEquals("every distinct option is warmed once", 3, warmed.size());
  }

  @Test
  public void reOfferingTheSameOptionsEachTickDoesNotReWarm() {
    DialoguePrefetcher prefetcher = prefetcher();

    prefetcher.offer(options("Yes.", "No."));
    prefetcher.offer(options("Yes.", "No."));
    prefetcher.offer(options("Yes.", "No."));

    assertEquals("the same options are only warmed once per session", 2, warmed.size());
  }

  @Test
  public void capsPrefetchesPerSession() {
    DialoguePrefetcher prefetcher = prefetcher();

    List<SynthesisRequest> many = new ArrayList<>();
    for (int i = 0; i < DialoguePrefetcher.MAX_PER_SESSION + 5; i++) {
      many.add(req("Option " + i));
    }
    prefetcher.offer(many);

    assertEquals(
        "a session never warms more than the cap",
        DialoguePrefetcher.MAX_PER_SESSION,
        warmed.size());
  }

  @Test
  public void blankAndNullOptionsAreSkippedWithoutConsumingTheCap() {
    DialoguePrefetcher prefetcher = prefetcher();

    List<SynthesisRequest> mixed = new ArrayList<>();
    mixed.add(req(""));
    mixed.add(null);
    mixed.add(req("Real line."));
    prefetcher.offer(mixed);

    assertEquals("only the real line is warmed", 1, warmed.size());
    assertEquals("Real line.", warmed.get(0).text());
  }

  @Test
  public void resetCancelsAndStartsAFreshSession() {
    DialoguePrefetcher prefetcher = prefetcher();

    prefetcher.offer(options("Yes.", "No."));
    prefetcher.reset();
    prefetcher.offer(options("Yes.", "No."));

    assertEquals("reset clears dedup so a new conversation re-warms", 4, warmed.size());
    assertTrue("reset cancels still-queued prefetches", cancels >= 1);
  }
}

