package com.grahambartley.runelite.voiced.dialogue.capture;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import org.junit.Test;

public class AnimalNoisesTest {

  private static final String[] NOISES = {
    "Baa", "Baa!", "Baaaa", "Baa baa", "Quack", "Quack!", "Quack quack quack", "Moo", "Moooo.",
    "Cluck cluck", "Squeak!", "Woof woof", "Grrr", "Meow", "Hiss!", "Oink", "Neigh", "Tweet",
    "Squawk!", "Ook ook", "Ribbit", "baa", "MOO", "Cock-a-doodle-doo", "Hee-haw", "Bleat",
  };

  private static final String[] SPEECH = {
    "Hear ye, hear ye!",
    "The cow says moo",
    "Baa, said the sheep to the farmer",
    "Buy my wares",
    "Moo over there and buy a cowbell",
    "Grrr, I will have my revenge",
    "Join the H.A.M.",
    "Alright bruv",
  };

  @Test
  public void anAnimalNoiseIsNotSomethingToVoice() {
    for (String line : NOISES) {
      assertTrue(line + " should read as noise", AnimalNoises.isNothingButNoise(line));
    }
  }

  @Test
  public void realSpeechIsAlwaysVoicedEvenWhenItMentionsANoise() {
    for (String line : SPEECH) {
      assertFalse(line + " should read as speech", AnimalNoises.isNothingButNoise(line));
    }
  }

  @Test
  public void anEmptyOrAbsentLineIsNotTreatedAsNoise() {
    assertFalse(AnimalNoises.isNothingButNoise(null));
    assertFalse(AnimalNoises.isNothingButNoise(""));
    assertFalse(AnimalNoises.isNothingButNoise("!!!"));
  }
}

package com.grahambartley.runelite.voiced.dialogue.capture;

import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

import com.grahambartley.runelite.voiced.dialogue.profile.ProfanityFilter;
import com.grahambartley.runelite.voiced.dialogue.speech.SynthesisDispatcher;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.events.ChatMessage;
import org.junit.Before;
import org.junit.Test;

public class PublicChatSpeakerTest {

  private static final String LOCAL_NAME = "Zezima";

  private final Client client = mock(Client.class);
  private final SynthesisDispatcher dispatcher = mock(SynthesisDispatcher.class);
  private boolean enabled = true;

  private final PublicChatSpeaker speaker =
      new PublicChatSpeaker(
          client, new DialogueTextCleaner(new ProfanityFilter()), dispatcher, () -> enabled);

  @Before
  public void setUp() {
    Player local = mock(Player.class);
    when(local.getName()).thenReturn(LOCAL_NAME);
    when(client.getLocalPlayer()).thenReturn(local);
  }

  @Test
  public void theLocalPlayersOwnPublicChatIsSpokenCleaned() {
    speaker.onChatMessage(chat(ChatMessageType.PUBLICCHAT, LOCAL_NAME, "<col=ff0000>Hi there!"));

    verify(dispatcher).speakPublicChat("Hi there!");
  }

  @Test
  public void aRankIconOnTheChatNameStillMatchesTheLocalPlayer() {
    speaker.onChatMessage(chat(ChatMessageType.PUBLICCHAT, "<img=2>" + LOCAL_NAME, "Hi there!"));

    verify(dispatcher).speakPublicChat("Hi there!");
  }

  @Test
  public void anotherPlayersPublicChatIsIgnored() {
    speaker.onChatMessage(chat(ChatMessageType.PUBLICCHAT, "Woox", "Hi there!"));

    verify(dispatcher, never()).speakPublicChat(org.mockito.ArgumentMatchers.anyString());
  }

  @Test
  public void otherChatTypesAreIgnored() {
    speaker.onChatMessage(chat(ChatMessageType.GAMEMESSAGE, LOCAL_NAME, "Hi there!"));

    verify(dispatcher, never()).speakPublicChat(org.mockito.ArgumentMatchers.anyString());
  }

  @Test
  public void theToggleIsReadLiveSoTurningItOffSilencesTheNextMessage() {
    enabled = false;

    speaker.onChatMessage(chat(ChatMessageType.PUBLICCHAT, LOCAL_NAME, "Hi there!"));

    verify(dispatcher, never()).speakPublicChat(org.mockito.ArgumentMatchers.anyString());
  }

  @Test
  public void aMessageThatCleansAwayToNothingIsNotSpoken() {
    speaker.onChatMessage(chat(ChatMessageType.PUBLICCHAT, LOCAL_NAME, "<img=2>"));

    verify(dispatcher, never()).speakPublicChat(org.mockito.ArgumentMatchers.anyString());
  }

  @Test
  public void aMessageArrivingWhileLoggedOutIsIgnored() {
    when(client.getLocalPlayer()).thenReturn(null);

    speaker.onChatMessage(chat(ChatMessageType.PUBLICCHAT, LOCAL_NAME, "Hi there!"));

    verify(dispatcher, never()).speakPublicChat(org.mockito.ArgumentMatchers.anyString());
  }

  private static ChatMessage chat(ChatMessageType type, String name, String message) {
    ChatMessage event = new ChatMessage();
    event.setType(type);
    event.setName(name);
    event.setMessage(message);
    return event;
  }
}

package com.grahambartley.runelite.voiced.dialogue.capture;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

import com.grahambartley.runelite.voiced.dialogue.profile.ProfanityFilter;
import com.grahambartley.runelite.voiced.dialogue.speech.SynthesisDispatcher;
import java.util.function.IntSupplier;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.OverheadTextChanged;
import org.junit.Before;
import org.junit.Test;
import org.mockito.ArgumentCaptor;

public class AmbientChatterWatcherTest {

  private static final WorldPoint PLAYER_TILE = new WorldPoint(3200, 3200, 0);

  private final Client client = mock(Client.class);
  private final SynthesisDispatcher dispatcher = mock(SynthesisDispatcher.class);

  private boolean enabled = true;
  private boolean conversationOnScreen = false;
  private int volume = 100;

  private final AmbientChatterWatcher watcher =
      new AmbientChatterWatcher(
          client,
          new DialogueTextCleaner(new ProfanityFilter()),
          dispatcher,
          () -> enabled,
          () -> conversationOnScreen,
          () -> volume);

  @Before
  public void setUp() {
    Player local = mock(Player.class);
    when(local.getWorldLocation()).thenReturn(PLAYER_TILE);
    when(client.getLocalPlayer()).thenReturn(local);
  }

  @Test
  public void aNearbyNpcsOverheadLineIsSpokenInItsOwnVoice() {
    NPC hans = npc(3);

    watcher.onOverheadTextChanged(overhead(hans, "<col=ff0000>Lovely day!"));

    verify(dispatcher).speakAmbient(eq("Lovely day!"), eq(hans), any(IntSupplier.class));
  }

  @Test
  public void everyNpcInAChatteringCrowdIsVoiced() {
    for (int tilesAway = 1; tilesAway <= 12; tilesAway++) {
      watcher.onOverheadTextChanged(overhead(npc(tilesAway), "Line " + tilesAway));
    }

    verify(dispatcher, times(12)).speakAmbient(anyString(), any(NPC.class), any(IntSupplier.class));
  }

  @Test
  public void oneNpcRepeatingItselfIsVoicedEveryTime() {
    NPC crier = npc(2);

    watcher.onOverheadTextChanged(overhead(crier, "Hear ye!"));
    watcher.onOverheadTextChanged(overhead(crier, "Hear ye!"));
    watcher.onOverheadTextChanged(overhead(crier, "Come one, come all!"));

    verify(dispatcher, times(2)).speakAmbient(eq("Hear ye!"), eq(crier), any(IntSupplier.class));
    verify(dispatcher).speakAmbient(eq("Come one, come all!"), eq(crier), any(IntSupplier.class));
  }

  @Test
  public void anotherPlayersOverheadTextIsNeverSpoken() {
    Player other = mock(Player.class);
    when(other.getWorldLocation()).thenReturn(PLAYER_TILE);

    watcher.onOverheadTextChanged(overhead(other, "Selling whips"));

    verifyNothingSpoken();
  }

  @Test
  public void anNpcBeyondTheRenderedAreaIsIgnored() {
    watcher.onOverheadTextChanged(overhead(npc(AmbientEarshot.EARSHOT_TILES + 1), "Too far away"));

    verifyNothingSpoken();
  }

  @Test
  public void anNpcExactlyAtTheEdgeOfEarshotIsSpoken() {
    watcher.onOverheadTextChanged(overhead(npc(AmbientEarshot.EARSHOT_TILES), "Just in range"));

    verify(dispatcher).speakAmbient(eq("Just in range"), any(NPC.class), any(IntSupplier.class));
  }

  @Test
  public void anNpcOnAnotherPlaneIsIgnored() {
    NPC upstairs = mock(NPC.class);
    when(upstairs.getWorldLocation()).thenReturn(new WorldPoint(3200, 3200, 1));

    watcher.onOverheadTextChanged(overhead(upstairs, "Up here"));

    verifyNothingSpoken();
  }

  @Test
  public void nothingIsSpokenWhileAConversationIsOnScreen() {
    conversationOnScreen = true;

    watcher.onOverheadTextChanged(overhead(npc(1), "Lovely day!"));

    verifyNothingSpoken();
  }

  @Test
  public void theToggleIsReadLiveSoTurningItOffSilencesTheNextLine() {
    enabled = false;

    watcher.onOverheadTextChanged(overhead(npc(1), "Lovely day!"));

    verifyNothingSpoken();
  }

  @Test
  public void anOverheadLineArrivingWhileLoggedOutIsIgnored() {
    when(client.getLocalPlayer()).thenReturn(null);

    watcher.onOverheadTextChanged(overhead(npc(1), "Lovely day!"));

    verifyNothingSpoken();
  }

  @Test
  public void aLineThatCleansAwayToNothingIsNotSpoken() {
    watcher.onOverheadTextChanged(overhead(npc(1), "<col=ff0000>"));

    verifyNothingSpoken();
  }

  @Test
  public void aNullOverheadLineIsIgnored() {
    watcher.onOverheadTextChanged(overhead(npc(1), null));

    verifyNothingSpoken();
  }

  private void verifyNothingSpoken() {
    verify(dispatcher, never()).speakAmbient(anyString(), any(NPC.class), any(IntSupplier.class));
  }

  private static NPC npc(int tilesAway) {
    NPC npc = mock(NPC.class);
    when(npc.getWorldLocation())
        .thenReturn(
            new WorldPoint(
                PLAYER_TILE.getX() + tilesAway, PLAYER_TILE.getY(), PLAYER_TILE.getPlane()));
    return npc;
  }

  private static OverheadTextChanged overhead(Actor actor, String text) {
    return new OverheadTextChanged(actor, text);
  }

  @Test
  public void aQuackOrABaaIsLeftUnvoiced() {
    watcher.onOverheadTextChanged(overhead(npc(2), "Baa baa"));
    watcher.onOverheadTextChanged(overhead(npc(2), "Quack!"));
    watcher.onOverheadTextChanged(overhead(npc(2), "Moooo"));

    verifyNothingSpoken();
  }

  @Test
  public void aSentenceThatMerelyMentionsANoiseIsStillVoiced() {
    NPC farmer = npc(2);

    watcher.onOverheadTextChanged(overhead(farmer, "Baa, said the sheep"));

    verify(dispatcher).speakAmbient(eq("Baa, said the sheep"), eq(farmer), any(IntSupplier.class));
  }

  @Test
  public void theVolumeHandedOverFadesWithTheSpeakersDistance() {
    volume = 100;
    NPC crier = npc(4);

    watcher.onOverheadTextChanged(overhead(crier, "Hear ye!"));

    assertEquals(
        "the supplier reports the fade for the current distance",
        AmbientEarshot.volumeAt(100, 4),
        capturedVolume().getAsInt());
  }

  @Test
  public void theVolumeHandedOverFollowsTheSpeakerAsTheyWalkOff() {
    volume = 100;
    NPC crier = npc(2);

    watcher.onOverheadTextChanged(overhead(crier, "Hear ye!"));
    IntSupplier live = capturedVolume();
    int near = live.getAsInt();
    moveTo(crier, 12);

    assertTrue("walking away makes the line quieter", live.getAsInt() < near);
  }

  @Test
  public void aSpeakerLeavingEarshotAsksForTheLineToBeCut() {
    NPC crier = npc(2);

    watcher.onOverheadTextChanged(overhead(crier, "Hear ye!"));
    IntSupplier live = capturedVolume();
    moveTo(crier, AmbientEarshot.EARSHOT_TILES + 1);

    assertEquals(AmbientEarshot.OUT_OF_EARSHOT, live.getAsInt());
  }

  @Test
  public void aLineInFlightWhenThePlayerLogsOutAsksToBeCut() {
    NPC crier = npc(2);

    watcher.onOverheadTextChanged(overhead(crier, "Hear ye!"));
    IntSupplier live = capturedVolume();
    when(client.getLocalPlayer()).thenReturn(null);

    assertEquals(AmbientEarshot.OUT_OF_EARSHOT, live.getAsInt());
  }

  private IntSupplier capturedVolume() {
    ArgumentCaptor<IntSupplier> captor = ArgumentCaptor.forClass(IntSupplier.class);
    verify(dispatcher).speakAmbient(anyString(), any(NPC.class), captor.capture());
    return captor.getValue();
  }

  private static void moveTo(NPC npc, int tilesAway) {
    when(npc.getWorldLocation())
        .thenReturn(
            new WorldPoint(
                PLAYER_TILE.getX() + tilesAway, PLAYER_TILE.getY(), PLAYER_TILE.getPlane()));
  }
}

package com.grahambartley.runelite.voiced.dialogue.capture;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.verifyNoInteractions;
import static org.mockito.Mockito.when;

import com.grahambartley.runelite.voiced.dialogue.profile.ProfanityFilter;
import com.grahambartley.runelite.voiced.dialogue.speech.SynthesisDispatcher;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import org.junit.Test;

public class NarrationWatcherTest {

  private final Client client = mock(Client.class);
  private final SynthesisDispatcher dispatcher = mock(SynthesisDispatcher.class);

  private boolean enabled = true;

  private final NarrationWatcher watcher =
      new NarrationWatcher(
          client, new DialogueTextCleaner(new ProfanityFilter()), dispatcher, () -> enabled);

  private Widget visibleWidget(String text) {
    Widget widget = mock(Widget.class);
    when(widget.isHidden()).thenReturn(false);
    when(widget.getText()).thenReturn(text);
    return widget;
  }

  private void showing(int widgetId, String text) {
    Widget box = visibleWidget(text);
    when(client.getWidget(widgetId)).thenReturn(box);
  }

  @Test
  public void anItemBoxIsNarratedOnceThenDeduped() {
    showing(InterfaceID.Objectbox.TEXT, "You find a key.");

    assertTrue("an open box reports the narration open", watcher.tick());
    watcher.tick();

    verify(dispatcher, times(1)).speakNarration("You find a key.");
  }

  @Test
  public void everyNarrationBoxKindIsNarrated() {
    showing(InterfaceID.Objectbox.TEXT, "You find a key.");
    showing(InterfaceID.ObjectboxDouble.TEXT, "You combine the halves.");
    showing(InterfaceID.Messagebox.TEXT, "The door creaks open.");

    watcher.tick();

    verify(dispatcher).speakNarration("You find a key.");
    verify(dispatcher).speakNarration("You combine the halves.");
    verify(dispatcher).speakNarration("The door creaks open.");
  }

  @Test
  public void eachBoxIsDedupedAgainstItsOwnLastLineOnly() {
    Widget objectbox = mock(Widget.class);
    when(objectbox.isHidden()).thenReturn(false);
    when(objectbox.getText()).thenReturn("You feel a chill.");
    when(client.getWidget(InterfaceID.Objectbox.TEXT)).thenReturn(objectbox);
    Widget messagebox = visibleWidget("You feel a chill.");
    when(client.getWidget(InterfaceID.Messagebox.TEXT)).thenReturn(null, messagebox);

    watcher.tick();
    watcher.tick();

    verify(dispatcher, times(2)).speakNarration("You feel a chill.");
  }

  @Test
  public void advancingAnItemBoxToItsNextLineNarratesTheNewLine() {
    Widget box = mock(Widget.class);
    when(box.isHidden()).thenReturn(false);
    when(box.getText()).thenReturn("You find a key.", "You find a rusty sword.");
    when(client.getWidget(InterfaceID.Objectbox.TEXT)).thenReturn(box);

    watcher.tick();
    watcher.tick();

    verify(dispatcher).speakNarration("You find a key.");
    verify(dispatcher).speakNarration("You find a rusty sword.");
  }

  @Test
  public void reopeningABoxAfterAResetNarratesItAgain() {
    showing(InterfaceID.Messagebox.TEXT, "The door creaks open.");

    watcher.tick();
    watcher.reset();
    watcher.tick();

    verify(dispatcher, times(2)).speakNarration("The door creaks open.");
  }

  @Test
  public void aHiddenOrAbsentBoxIsNeitherNarratedNorCountedAsOpen() {
    Widget hidden = mock(Widget.class);
