package com.grahambartley.runelite.voiced.dialogue.speech;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import com.grahambartley.runelite.voiced.dialogue.VoicedDialogueConfig;
import java.time.Duration;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import junitparams.JUnitParamsRunner;
import junitparams.Parameters;
import org.junit.Test;
import org.junit.runner.RunWith;

@RunWith(JUnitParamsRunner.class)
public class CloudBackendSupportTest {

  private static final RetryTuning INSTANT =
      new RetryTuning(Duration.ofSeconds(1), Duration.ofSeconds(1), Duration.ofSeconds(1), 0, 0);

  private static CloudBackendSupport support(int pace) {
    VoicedDialogueConfig config =
        new VoicedDialogueConfig() {
          @Override
          public int speakingPace() {
            return pace;
          }
        };
    return new CloudBackendSupport(config, VoicedDialogueConfig.TtsProvider.OPENROUTER, 2, INSTANT);
  }

  @Test
  public void warnOnceSurfacesEachFailureNoticeExactlyOnce() {
    CloudBackendSupport support = support(100);
    List<String> notices = new ArrayList<>();
    support.setNotice(notices::add);

    support.warnOnce("first failure");
    support.warnOnce("first failure");
    support.warnOnce("second failure");

    assertEquals(
        "a repeated failure says its piece once, a different one is not silenced by it",
        Arrays.asList("first failure", "second failure"),
        notices);
  }

  @Test
  public void missingKeyNoticeIsNotOnceGuarded() {
    CloudBackendSupport support = support(100);
    List<String> notices = new ArrayList<>();
    support.setNotice(notices::add);

    support.noticeMissingKey("no key");
    support.noticeMissingKey("no key");
    support.warnOnce("real failure");

    assertEquals(
        "the missing-key notice repeats and leaves the once-guard for a real failure",
        Arrays.asList("no key", "no key", "real failure"),
        notices);
  }

  @Test
  public void nullNoticeHookIsSafe() {
    CloudBackendSupport support = support(100);
    support.setNotice(null);
    support.warnOnce("dropped");
    support.noticeMissingKey("dropped");
  }

  @Test
  @Parameters(method = "speedPercentCases")
  public void speedPercentClampsToTheSupportedRange(int configured, int expected) {
    assertEquals(expected, support(configured).speedPercent());
  }

  private Object[] speedPercentCases() {
    return new Object[] {
      new Object[] {100, 100},
      new Object[] {50, 50},
      new Object[] {200, 200},
      new Object[] {10, 50},
      new Object[] {999, 200},
    };
  }

  @Test
  public void backoffWithZeroBudgetsReturnsImmediately() {
    long start = System.nanoTime();
    support(100).backoffBeforeNetworkRetry(1);
    assertTrue(
        "a zero base and jitter must not park the worker", CloudHttp.elapsedMs(start) < 1_000);
  }
}

package com.grahambartley.runelite.voiced.dialogue.speech.aistudio;

import static java.nio.charset.StandardCharsets.UTF_8;
import static org.junit.Assert.assertEquals;

import com.google.gson.Gson;
import org.junit.Test;

public class AiStudioRetryInfoTest {

  private final Gson gson = new Gson();

  @Test
  public void theStatedDelayIsReadOutOfTheRejection() {
    assertEquals(
        2_917_000,
        AiStudioRetryInfo.retryDelayMillis(
            gson, AiStudioResponses.statedRetryDelay("2917s").getBytes(UTF_8)));
  }

  @Test
  public void aRejectionStatingNoDelayReadsAsNoHint() {
    assertEquals(
        0,
        AiStudioRetryInfo.retryDelayMillis(
            gson, AiStudioResponses.quotaExhausted().getBytes(UTF_8)));
    assertEquals(0, AiStudioRetryInfo.retryDelayMillis(gson, "not json".getBytes(UTF_8)));
    assertEquals(0, AiStudioRetryInfo.retryDelayMillis(gson, new byte[0]));
    assertEquals(0, AiStudioRetryInfo.retryDelayMillis(gson, null));
  }

  @Test
  public void aQuotaFailureAheadOfTheHintDoesNotHideIt() {
    byte[] body =
        AiStudioResponses.quotaFailure(
                "GenerateRequestsPerDayPerProjectPerModel", "", "100", "gemini-3.1-flash-tts")
            .getBytes(UTF_8);

    assertEquals(2_917_000, AiStudioRetryInfo.retryDelayMillis(gson, body));
  }

  @Test
  public void aFractionalDelayKeepsItsMilliseconds() {
    assertEquals(500, AiStudioRetryInfo.durationMillis("0.5s"));
    assertEquals(1_250, AiStudioRetryInfo.durationMillis("1.25s"));
    assertEquals(1_123, AiStudioRetryInfo.durationMillis("1.123456789s"));
    assertEquals(
        "whitespace around the value is not a malformation",
        7_000,
        AiStudioRetryInfo.durationMillis(" 7s "));
  }

  @Test
  public void aMalformedDelayReadsAsNoHint() {
    assertEquals("a duration must carry its unit", 0, AiStudioRetryInfo.durationMillis("2917"));
    assertEquals(0, AiStudioRetryInfo.durationMillis("soon"));
    assertEquals("a negative wait is not a wait", 0, AiStudioRetryInfo.durationMillis("-5s"));
    assertEquals(0, AiStudioRetryInfo.durationMillis("5m"));
    assertEquals(0, AiStudioRetryInfo.durationMillis(""));
  }

  @Test
  public void aDelayTooLargeToMeasureReadsAsNoHint() {
    assertEquals(
        "an unrepresentable wait is as unusable as a malformed one",
        0,
        AiStudioRetryInfo.durationMillis("99999999999999999999s"));
    assertEquals(0, AiStudioRetryInfo.durationMillis(Long.MAX_VALUE + "s"));
  }
}

