import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import com.grahambartley.runelite.voiced.dialogue.speech.aistudio.AiStudioQuotaFailure.Period;
import org.junit.Test;

public class AiStudioQuotaFailureTest {

  private static final String PAID_DAILY_CAP = AiStudioResponses.dailyCapExhausted();

  private static final String FREE_TIER_CAP =
      AiStudioResponses.quotaFailure(
          "GenerateRequestsPerDayPerProjectPerModel-FreeTier",
          "generativelanguage.googleapis.com/generate_content_free_tier_requests",
          "15",
          "gemini-3.1-flash-tts");

  private final Gson gson = new Gson();

  @Test
  public void aPaidPerModelCapIsReadOutOfTheViolation() {
    AiStudioQuotaFailure quota = parse(PAID_DAILY_CAP);

    assertEquals("GenerateRequestsPerDayPerProjectPerModel", quota.quotaId);
    assertEquals("100", quota.quotaValue);
    assertEquals("gemini-3.1-flash-tts", quota.model);
    assertEquals(Period.DAILY, quota.period());
    assertFalse("a paid per-model cap is not a free-tier one", quota.isFreeTier());
  }

  @Test
  public void aFreeTierMetricIsRecognisedFromEitherSpelling() {
    assertTrue(parse(FREE_TIER_CAP).isFreeTier());
    assertTrue(
        "the id alone carries the marker when the metric does not",
        parse(quota("GenerateRequestsPerDayPerProjectPerModel-FreeTier", "")).isFreeTier());
    assertTrue(
        "and the metric alone when the id does not",
        parse(quota("", "generate_content_free_tier_requests")).isFreeTier());
    assertTrue(
        "however the marker is separated",
        parse(quota("GenerateRequests-Free-Tier", "")).isFreeTier());
  }

  @Test
  public void aQuotaPeriodIsReadFromWhicheverFieldNamesIt() {
    assertEquals(
        Period.PER_MINUTE,
        parse(quota("GenerateRequestsPerMinutePerProjectPerModel", "")).period());
    assertEquals(Period.DAILY, parse(quota("", "generate_requests_per_model_per_day")).period());
    assertEquals(
        "a quota naming no period claims none",
        Period.UNKNOWN,
        parse(quota("GenerateContentPerProject", "")).period());
  }

  @Test
  public void aBodyWithoutAQuotaFailureParsesToNothing() {
    assertNull(parse(AiStudioResponses.quotaExhausted()));
    assertNull("a truncated body must not throw", parse("{\"error\": {\"details\": [{\"@ty"));
    assertNull(parse("not json at all"));
    assertNull(parse(""));
    assertNull(AiStudioQuotaFailure.parse(gson, null));
  }

  @Test
  public void aMalformedDetailDoesNotHideAViolationBehindIt() {
    String body =
        "{\"error\": {\"details\": [\"not an object\", {\"@type\":"
            + " \"type.googleapis.com/google.rpc.QuotaFailure\", \"violations\":"
            + " [{\"quotaDimensions\": {\"model\": \"gemini-3.1-flash-tts\"}}]}]}}";

    assertEquals("gemini-3.1-flash-tts", parse(body).model);
  }

  @Test
  public void violationsOfTheWrongShapeFallBackRatherThanThrow() {
    assertNull("an object where an array belongs is not a violation", parse(violations("{}")));
    assertNull(parse(violations("7")));
    assertEquals(
        "and the player still gets a quota notice rather than an unexplained failure",
        AiStudioQuotaFailure.QUOTA_NOTICE,
        noticeFor(violations("7")));
  }

  @Test
  public void aPaidCapNamesTheCapAndNeverAsksForBilling() {
    String notice = noticeFor(PAID_DAILY_CAP);

    assertTrue("the model is named: " + notice, notice.contains("gemini-3.1-flash-tts"));
    assertTrue("as is the cap it hit: " + notice, notice.contains("daily request cap of 100"));
    assertTrue(
        "billing is already on, so the notice says so rather than asking for it",
        notice.contains("Enabling billing does not lift this cap"));
    assertFalse("the free tier is not the cause here", notice.contains("free tier"));
    assertTrue("the working alternative is still offered", notice.contains("OpenRouter"));
  }

  @Test
  public void aFreeTierCapKeepsTheEnableBillingAdviceAndNamesTheCeiling() {
    String notice = noticeFor(FREE_TIER_CAP);

    assertTrue("the ceiling is named: " + notice, notice.contains("daily request cap of 15"));
    assertTrue(
        "the free tier is the one case billing lifts",
        notice.contains("Enable billing at aistudio.google.com to lift it"));
  }

  @Test
  public void markupInAReportedValueCannotBreakTheChatLine() {
    String notice =
        noticeFor(AiStudioResponses.quotaFailure("GenerateRequestsPerDay", "", "1<0>0", "<b>"));

    assertFalse("no markup survives from the response: " + notice, notice.contains("<"));
    assertFalse(notice.contains(">"));
  }

  @Test
  public void aMalformedViolationDoesNotHideAWellFormedOneBehindIt() {
    String body = violations("[7, {\"quotaDimensions\": {\"model\": \"gemini-3.1-flash-tts\"}}]");

    assertEquals("gemini-3.1-flash-tts", parse(body).model);
  }

  @Test
  public void aPerMinuteLimitReadsAsAPauseRatherThanAProviderSwitch() {
    String notice = noticeFor(quota("GenerateRequestsPerMinutePerProjectPerModel", ""));

    assertTrue("the ceiling is named: " + notice, notice.contains("per-minute request cap of 10"));
    assertTrue("a limit that clears itself says so", notice.contains("Lines resume"));
    assertFalse(
        "a minute of waiting is not worth changing provider over", notice.contains("OpenRouter"));
  }

  @Test
  public void aFreeTierPerMinuteLimitIsStillAPauseRatherThanAnAccountProblem() {
    String notice =
        noticeFor(
            quota(
                "GenerateRequestsPerMinutePerProjectPerModel-FreeTier",
                "generativelanguage.googleapis.com/generate_content_free_tier_requests"));

    assertTrue("a limit that clears itself says so", notice.contains("Lines resume"));
    assertFalse(
        "60 seconds of waiting is not an account to go and fix", notice.contains("enable billing"));
  }

  @Test
  public void anUnreadableBodyFallsBackToTheGenericNotice() {
    assertEquals(AiStudioQuotaFailure.QUOTA_NOTICE, noticeFor(AiStudioResponses.quotaExhausted()));
    assertEquals(
        AiStudioQuotaFailure.QUOTA_NOTICE, AiStudioQuotaFailure.noticeFor(gson, new byte[0]));
    assertFalse(
        "an unknown cause must not be blamed on the free tier",
        AiStudioQuotaFailure.QUOTA_NOTICE.contains("free tier"));
  }

  @Test
  public void aViolationMissingItsDimensionsStillWordsANotice() {
    assertEquals(
        "Google AI Studio stopped voicing dialogue: the speech model has reached its request cap."
            + " Check your quota at aistudio.google.com, or switch Voice Provider to OpenRouter.",
        noticeFor(AiStudioResponses.quotaFailure("GenerateRequestsPerProject", "", "", "")));
  }

  @Test
  public void aQuotaNamingNeitherPeriodNorTierClaimsNeither() {
    String notice = noticeFor(quota("GenerateRequestsPerProject", ""));

    assertFalse("nothing says how long it holds", notice.contains("wait for it to reset"));
    assertFalse("nor whether billing would lift it", notice.contains("billing"));
  }

  @Test
  public void aTokenQuotaIsNotReportedAsARequestCap() {
    String notice =
        noticeFor(
            quota(
                "GenerateContentInputTokensPerModelPerMinute",
                "generativelanguage.googleapis.com/generate_content_input_token_count"));

    assertTrue("tokens are not requests: " + notice, notice.contains("per-minute token cap of 10"));
  }

  @Test
  public void theDebugLineCarriesEveryFieldTheVerdictRestsOn() {
    String logged = parse(PAID_DAILY_CAP).toString();

    assertTrue(logged.contains("quotaId=GenerateRequestsPerDayPerProjectPerModel"));
    assertTrue("the metric decides the free-tier verdict", logged.contains("generate_requests"));
    assertTrue(logged.contains("quotaValue=100"));
    assertTrue(logged.contains("model=gemini-3.1-flash-tts"));
  }

  private static String violations(String value) {
    return "{\"error\": {\"code\": 429, \"details\": [{\"@type\":"
        + " \"type.googleapis.com/google.rpc.QuotaFailure\", \"violations\": "
        + value
        + "}]}}";
  }

  private static String quota(String quotaId, String quotaMetric) {
    return AiStudioResponses.quotaFailure(quotaId, quotaMetric, "10", "");
  }

  private AiStudioQuotaFailure parse(String body) {
    return AiStudioQuotaFailure.parse(gson, body.getBytes(UTF_8));
  }

  private String noticeFor(String body) {
    return AiStudioQuotaFailure.noticeFor(gson, body.getBytes(UTF_8));
  }
}

package com.grahambartley.runelite.voiced.dialogue.speech.aistudio;

import static java.nio.charset.StandardCharsets.UTF_8;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import java.util.List;
import org.junit.Test;

public class AiStudioErrorDetailsTest {

  private static final String QUOTA_FAILURE = "type.googleapis.com/google.rpc.QuotaFailure";

  private static final String RETRY_INFO = "type.googleapis.com/google.rpc.RetryInfo";

  private final Gson gson = new Gson();

  @Test
  public void eachReaderSeesOnlyTheTypeItAskedFor() {
    byte[] body =
        AiStudioResponses.quotaFailure("GenerateRequestsPerDay", "", "100", "gemini-3.1-flash-tts")
            .getBytes(UTF_8);

    assertEquals(1, ofType(body, QUOTA_FAILURE).size());
    assertEquals(
        AiStudioResponses.DAILY_CAP_RETRY_DELAY,
        AiStudioErrorDetails.text(ofType(body, RETRY_INFO).get(0), "retryDelay"));
  }

  @Test
  public void anUnreadableBodyYieldsNothingRatherThanThrowing() {
    assertTrue(ofType(AiStudioResponses.quotaExhausted().getBytes(UTF_8), RETRY_INFO).isEmpty());
    assertTrue(
        ofType("{\"error\": {\"details\": {\"not\": \"an array\"}}}".getBytes(UTF_8), RETRY_INFO)
            .isEmpty());
    assertTrue(ofType("{\"error\": [1, 2]}".getBytes(UTF_8), RETRY_INFO).isEmpty());
    assertTrue(ofType("not json".getBytes(UTF_8), RETRY_INFO).isEmpty());
    assertTrue(ofType(new byte[0], RETRY_INFO).isEmpty());
    assertTrue(AiStudioErrorDetails.ofType(gson, null, RETRY_INFO).isEmpty());
  }

  @Test
  public void aMalformedEntryDoesNotHideTheOnesAroundIt() {
    byte[] body =
        ("{\"error\": {\"details\": [7, {\"@type\": \""
                + RETRY_INFO
                + "\", \"retryDelay\": \"30s\"}]}}")
            .getBytes(UTF_8);

    assertEquals("30s", AiStudioErrorDetails.text(ofType(body, RETRY_INFO).get(0), "retryDelay"));
  }

  @Test
  public void aMissingOrUnreadableFieldReadsAsEmpty() {
    JsonObject detail = new JsonObject();
    detail.addProperty("retryDelay", "30s");
    detail.add("nulled", null);

    assertEquals("30s", AiStudioErrorDetails.text(detail, "retryDelay"));
    assertEquals("", AiStudioErrorDetails.text(detail, "absent"));
    assertEquals("", AiStudioErrorDetails.text(detail, "nulled"));
    assertEquals("", AiStudioErrorDetails.text(null, "retryDelay"));
  }

  private List<JsonObject> ofType(byte[] body, String type) {
    return AiStudioErrorDetails.ofType(gson, body, type);
  }
}

package com.grahambartley.runelite.voiced.dialogue.speech.aistudio;

import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import com.grahambartley.runelite.voiced.dialogue.audio.TestPcm;
import com.grahambartley.runelite.voiced.dialogue.speech.CloudHttp;
import java.net.HttpURLConnection;
import java.util.Base64;
import java.util.List;
import okhttp3.mockwebserver.MockResponse;

final class AiStudioResponses {

  static final String DAILY_CAP_RETRY_DELAY = "2917s";

  private AiStudioResponses() {}

  static MockResponse ok(String body) {
    return new MockResponse().setResponseCode(HttpURLConnection.HTTP_OK).setBody(body);
  }

  static MockResponse tooManyRequests(String body) {
    return new MockResponse().setResponseCode(CloudHttp.HTTP_TOO_MANY_REQUESTS).setBody(body);
  }

  static MockResponse quotaRejection() {
    return tooManyRequests(dailyCapExhausted());
  }

  static String audio(short[] samples) {
    return audioDocument(TestPcm.raw(samples), "STOP");
  }

  static String audioWithUsage(short[] samples, long audioTokens, long textTokens) {
    return withUsage(audio(samples), audioTokens, textTokens);
  }

  static String withUsage(String document, long audioTokens, long textTokens) {
    JsonObject detail = new JsonObject();
    detail.addProperty("modality", "AUDIO");
    detail.addProperty("tokenCount", audioTokens);
    JsonArray details = new JsonArray();
    details.add(detail);
    JsonObject usage = new JsonObject();
    usage.addProperty("promptTokenCount", textTokens);
    usage.addProperty("candidatesTokenCount", audioTokens);
    usage.add("candidatesTokensDetails", details);
    JsonObject body = new JsonParser().parse(document).getAsJsonObject();
    body.add("usageMetadata", usage);
    return body.toString();
  }

  static String audioDocument(byte[] audioBytes, String finishReason) {
    JsonObject inlineData = new JsonObject();
    inlineData.addProperty("mimeType", "audio/L16;codec=pcm;rate=24000");
    inlineData.addProperty("data", Base64.getEncoder().encodeToString(audioBytes));
    JsonObject part = new JsonObject();
    part.add("inlineData", inlineData);
    return candidates(part, finishReason);
  }

  static String sse(List<byte[]> chunks, String finishReason) {
    StringBuilder sse = new StringBuilder();
    for (int i = 0; i < chunks.size(); i++) {
      String reason = i == chunks.size() - 1 ? finishReason : null;
      sse.append("data: ").append(audioDocument(chunks.get(i), reason)).append("\n\n");
    }
    return sse.toString();
  }

  static String translation(String content) {
    JsonObject textPart = new JsonObject();
    textPart.addProperty("text", content);
    return candidates(textPart, "STOP");
  }

  static String quotaFailure(String quotaId, String quotaMetric, String quotaValue, String model) {
    JsonObject violation = new JsonObject();
    addIfPresent(violation, "quotaId", quotaId);
    addIfPresent(violation, "quotaMetric", quotaMetric);
    addIfPresent(violation, "quotaValue", quotaValue);
    if (!model.isEmpty()) {
      JsonObject dimensions = new JsonObject();
      dimensions.addProperty("model", model);
      dimensions.addProperty("location", "global");
      violation.add("quotaDimensions", dimensions);
    }
    JsonArray violations = new JsonArray();
    violations.add(violation);
    JsonObject quotaFailure = new JsonObject();
    quotaFailure.addProperty("@type", "type.googleapis.com/google.rpc.QuotaFailure");
    quotaFailure.add("violations", violations);
    JsonArray details = new JsonArray();
    details.add(quotaFailure);
    details.add(retryInfo(DAILY_CAP_RETRY_DELAY));
    return rejection(details);
  }

  static String dailyCapExhausted() {
    return quotaFailure(
        "GenerateRequestsPerDayPerProjectPerModel",
        "generativelanguage.googleapis.com/generate_requests_per_model_per_day",
        "100",
        "gemini-3.1-flash-tts");
  }

  static String statedRetryDelay(String retryDelay) {
    JsonArray details = new JsonArray();
    details.add(retryInfo(retryDelay));
    return rejection(details);
  }

  static String quotaExhausted() {
    return rejection(null);
  }

  private static JsonObject retryInfo(String retryDelay) {
    JsonObject retryInfo = new JsonObject();
    retryInfo.addProperty("@type", "type.googleapis.com/google.rpc.RetryInfo");
    retryInfo.addProperty("retryDelay", retryDelay);
    return retryInfo;
  }

  private static String rejection(JsonArray details) {
    JsonObject error = new JsonObject();
    error.addProperty("code", 429);
    error.addProperty("message", "Resource has been exhausted.");
    error.addProperty("status", "RESOURCE_EXHAUSTED");
    if (details != null) {
      error.add("details", details);
    }
    JsonObject body = new JsonObject();
    body.add("error", error);
    return body.toString();
  }

  private static void addIfPresent(JsonObject object, String field, String value) {
    if (!value.isEmpty()) {
      object.addProperty(field, value);
    }
  }

  private static String candidates(JsonObject part, String finishReason) {
    JsonArray parts = new JsonArray();
    parts.add(part);
    JsonObject content = new JsonObject();
    content.add("parts", parts);
    JsonObject candidate = new JsonObject();
    candidate.add("content", content);
    if (finishReason != null) {
      candidate.addProperty("finishReason", finishReason);
    }
    JsonArray candidates = new JsonArray();
    candidates.add(candidate);
    JsonObject body = new JsonObject();
    body.add("candidates", candidates);
    return body.toString();
  }
}

package com.grahambartley.runelite.voiced.dialogue.speech.aistudio;

import static java.net.HttpURLConnection.HTTP_INTERNAL_ERROR;
import static java.net.HttpURLConnection.HTTP_OK;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import com.grahambartley.runelite.voiced.dialogue.VoicedDialogueConfig;
import com.grahambartley.runelite.voiced.dialogue.speech.CloudTtsText;
import okhttp3.OkHttpClient;
import okhttp3.mockwebserver.MockResponse;
import okhttp3.mockwebserver.MockWebServer;
import okhttp3.mockwebserver.RecordedRequest;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;

public class AiStudioTranslatorTest {

  private MockWebServer server;
  private OkHttpClient client;
  private final Gson gson = new Gson();
  private final VoicedDialogueConfig config = new VoicedDialogueConfig() {};

  @Before
  public void setUp() throws Exception {
    server = new MockWebServer();
    server.start();
    client = new OkHttpClient();
  }

  @After
  public void tearDown() throws Exception {
    server.shutdown();
  }

  private AiStudioTranslator translator() {
    return new AiStudioTranslator(
        client,
        config,
        gson,
        server.url("/v1beta/models/" + AiStudioTranslator.MODEL + ":generateContent").toString());
  }

  @Test
  public void translatesAndReturnsTrimmedContent() throws Exception {
    server.enqueue(
        new MockResponse()
            .setResponseCode(HTTP_OK)
            .setBody(AiStudioResponses.translation("  Bonjour  ")));

    AiStudioTranslator.Translation result = translator().translate("Hello", "French", "AIza-abc");

    assertEquals("Bonjour", result.text);

    RecordedRequest recorded = server.takeRequest();
    assertEquals("POST", recorded.getMethod());
    assertEquals("AIza-abc", recorded.getHeader("x-goog-api-key"));
    JsonObject body = new JsonParser().parse(recorded.getBody().readUtf8()).getAsJsonObject();
    String systemPrompt =
        body.getAsJsonObject("systemInstruction")
            .getAsJsonArray("parts")
            .get(0)
            .getAsJsonObject()
            .get("text")
            .getAsString();
    assertEquals(
        "the fixed system prompt is shared with the OpenRouter hop",
        CloudTtsText.translatorSystemPrompt("French"),
        systemPrompt);
    assertEquals(
        "the per-line text is the user content, keeping the system prefix stable",
        "Hello",
        body.getAsJsonArray("contents")
            .get(0)
            .getAsJsonObject()
            .getAsJsonArray("parts")
            .get(0)
            .getAsJsonObject()
            .get("text")
            .getAsString());
  }

  @Test
  public void emptyInputIsReturnedWithoutCallingTheNetwork() {
    AiStudioTranslator.Translation result = translator().translate("", "French", "AIza-abc");

    assertEquals("", result.text);
    assertEquals("no HTTP request for empty input", 0, server.getRequestCount());
  }

  @Test
  public void nonSuccessReturnsNull() {
    server.enqueue(new MockResponse().setResponseCode(HTTP_INTERNAL_ERROR).setBody("boom"));
    assertNull(translator().translate("Hello", "French", "AIza-abc"));
  }

  @Test
  public void unparseableOrEmptyBodyReturnsNull() {
    server.enqueue(new MockResponse().setResponseCode(HTTP_OK).setBody("not json"));
    assertNull(translator().translate("Hello", "French", "AIza-abc"));
  }
}

package com.grahambartley.runelite.voiced.dialogue.speech.aistudio;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertSame;

import com.google.gson.Gson;
import org.junit.Test;

public class AiStudioTokenUsageTest {

  private final Gson gson = new Gson();

  private AiStudioTokenUsage parse(String raw) {
    return AiStudioTokenUsage.forSpeech(gson, raw);
  }

  @Test
  public void takesAudioTokensFromThePerModalityBreakdown() {
    AiStudioTokenUsage usage =
        parse(
            "{\"usageMetadata\":{\"promptTokenCount\":42,\"candidatesTokenCount\":1700,"
                + "\"candidatesTokensDetails\":[{\"modality\":\"AUDIO\",\"tokenCount\":1700}]}}");

    assertEquals(1700, usage.audioTokens);
    assertEquals(42, usage.promptTokens);
    assertEquals("a speech call has no text output", 0, usage.textTokens);
  }

  @Test
  public void fallsBackToTheCandidateTotalWhenNoBreakdownIsGiven() {
    AiStudioTokenUsage usage =
        parse("{\"usageMetadata\":{\"promptTokenCount\":42,\"candidatesTokenCount\":1700}}");

    assertEquals("a speech call's candidates are audio in their entirety", 1700, usage.audioTokens);
    assertEquals(42, usage.promptTokens);
  }

  @Test
  public void sumsEveryAudioEntryAndIgnoresOtherModalities() {
    AiStudioTokenUsage usage =
        parse(
            "{\"usageMetadata\":{\"promptTokenCount\":10,\"candidatesTokensDetails\":["
                + "{\"modality\":\"AUDIO\",\"tokenCount\":600},"
                + "{\"modality\":\"TEXT\",\"tokenCount\":99},"
                + "{\"modality\":\"AUDIO\",\"tokenCount\":400}]}}");

    assertEquals(1000, usage.audioTokens);
  }

  @Test
  public void anUnrecognisedOrAbsentBlockReportsNothingRatherThanAWrongNumber() {
    assertSame(AiStudioTokenUsage.NONE, parse(null));
    assertSame(AiStudioTokenUsage.NONE, parse(""));
    assertSame(AiStudioTokenUsage.NONE, parse("not json"));
    assertSame(AiStudioTokenUsage.NONE, parse("{}"));
    assertSame(AiStudioTokenUsage.NONE, parse("{\"usageMetadata\":{}}"));
    assertSame(AiStudioTokenUsage.NONE, parse("{\"candidates\":[]}"));
  }

  @Test
  public void aTextCallBillsItsOutputAsTextRatherThanAudio() {
    AiStudioTokenUsage usage =
        AiStudioTokenUsage.forText(
            gson, "{\"usageMetadata\":{\"promptTokenCount\":90,\"candidatesTokenCount\":75}}");

    assertEquals(90, usage.promptTokens);
    assertEquals(75, usage.textTokens);
    assertEquals(
        "reading the hop's output as audio would misprice it by more than twenty times",
        0,
        usage.audioTokens);
  }

  @Test
  public void anAbsentBlockOnATextCallReportsNothing() {
    assertSame(AiStudioTokenUsage.NONE, AiStudioTokenUsage.forText(gson, "{}"));
    assertSame(AiStudioTokenUsage.NONE, AiStudioTokenUsage.forText(gson, "not json"));
  }

  @Test
  public void negativeCountsAreFloored() {
    AiStudioTokenUsage usage =
        parse("{\"usageMetadata\":{\"promptTokenCount\":-5,\"candidatesTokenCount\":-9}}");

    assertSame(AiStudioTokenUsage.NONE, usage);
  }

  @Test
  public void maxKeepsTheLargestReadingSoACumulativeStreamIsNeverDoubleCounted() {
    AiStudioTokenUsage first = new AiStudioTokenUsage(42, 400, 0);
    AiStudioTokenUsage running = new AiStudioTokenUsage(42, 1700, 0);

    AiStudioTokenUsage combined = first.max(running);

    assertEquals(1700, combined.audioTokens);
    assertEquals(42, combined.promptTokens);
    assertEquals("a null reading leaves the total alone", 1700, combined.max(null).audioTokens);
  }
}

