public class OpenRouterTranslatorTest {

  private MockWebServer server;
  private OkHttpClient client;
  private final Gson gson = new Gson();
  private final VoicedDialogueConfig config = new VoicedDialogueConfig() {};

  @Before
  public void setUp() throws Exception {
    server = new MockWebServer();
    server.start();
    client = new OkHttpClient();
  }

  @After
  public void tearDown() throws Exception {
    server.shutdown();
  }

  private OpenRouterTranslator translator() {
    return new OpenRouterTranslator(
        client, config, gson, server.url("/api/v1/chat/completions").toString());
  }

  @Test
  public void translatesAndReturnsTrimmedContent() throws Exception {
    server.enqueue(
        new MockResponse()
            .setResponseCode(HTTP_OK)
            .setBody(TestFixtures.chatResponse("  Bonjour  ")));

    String result = translator().translate("Hello", "French", "sk-or-abc");

    assertEquals("Bonjour", result);

    RecordedRequest recorded = server.takeRequest();
    assertEquals("POST", recorded.getMethod());
    assertEquals("Bearer sk-or-abc", recorded.getHeader("Authorization"));
    assertEquals(
        "the OpenRouter app name is attributed",
        "RuneLite Voiced Dialogue",
        recorded.getHeader("X-Title"));
    JsonObject body = new JsonParser().parse(recorded.getBody().readUtf8()).getAsJsonObject();
    assertEquals("google/gemini-3.1-flash-lite", body.get("model").getAsString());
    assertEquals(
        "throughput routing applies to the translation hop too",
        "throughput",
        body.getAsJsonObject("provider").get("sort").getAsString());
    JsonArray messages = body.getAsJsonArray("messages");
    assertEquals("system prompt then user line", 2, messages.size());
    assertEquals("system", messages.get(0).getAsJsonObject().get("role").getAsString());
    assertEquals(
        "the per-line text is the user message, keeping the system prefix stable",
        "Hello",
        messages.get(1).getAsJsonObject().get("content").getAsString());
  }

  @Test
  public void nonSuccessReturnsNull() {
    server.enqueue(
        new MockResponse().setResponseCode(HTTP_TOO_MANY_REQUESTS).setBody("rate limited"));
    assertNull(translator().translate("Hello", "French", "sk-or-abc"));
  }

  @Test
  public void unparseableOrEmptyBodyReturnsNull() {
    server.enqueue(new MockResponse().setResponseCode(HTTP_OK).setBody("not json"));
    assertNull(translator().translate("Hello", "French", "sk-or-abc"));
  }

  @Test
  public void emptyInputIsReturnedWithoutCallingTheNetwork() {
    assertEquals("", translator().translate("", "French", "sk-or-abc"));
    assertEquals("no HTTP request for empty input", 0, server.getRequestCount());
  }
}

package com.grahambartley.runelite.voiced.dialogue.speech.openrouter;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import org.junit.Test;

public class OpenRouterCreditMeterTest {

  private static final double TOLERANCE = 1e-9;

  @Test
  public void spendIsTheRiseAboveTheSessionBaseline() {
    OpenRouterCreditMeter meter = new OpenRouterCreditMeter();
    meter.recordBaseline("sk-or-abc", 4.5000);

    assertEquals(0.1187, meter.spentSince("sk-or-abc", 4.6187), TOLERANCE);
  }

  @Test
  public void spendIsUnknownUntilABaselineIsTaken() {
    OpenRouterCreditMeter meter = new OpenRouterCreditMeter();

    assertNull(
        "an unread balance must never be reported as a free session",
        meter.spentSince("sk-or-abc", 4.6187));
    assertFalse(meter.hasBaselineFor("sk-or-abc"));
  }

  @Test
  public void anUnreadableBaselineIsNotBanked() {
    OpenRouterCreditMeter meter = new OpenRouterCreditMeter();
    meter.recordBaseline("sk-or-abc", null);

    assertFalse("a failed read leaves the meter unarmed", meter.hasBaselineFor("sk-or-abc"));
    assertNull(meter.spentSince("sk-or-abc", 4.6187));
  }

  @Test
  public void aSecondBaselineForTheSameKeyNeverErasesSpendAlreadyMade() {
    OpenRouterCreditMeter meter = new OpenRouterCreditMeter();
    meter.recordBaseline("sk-or-abc", 4.5000);
    meter.recordBaseline("sk-or-abc", 4.6000);

    assertEquals(
        "a re-warm mid-session must not rebase and hide what was already spent",
        0.1187,
        meter.spentSince("sk-or-abc", 4.6187),
        TOLERANCE);
  }

  @Test
  public void aSwappedKeyIsMeasuredFromItsOwnBaseline() {
    OpenRouterCreditMeter meter = new OpenRouterCreditMeter();
    meter.recordBaseline("sk-or-abc", 4.5000);

    assertNull(
        "usage on a different key is a different running total, so it cannot be subtracted",
        meter.spentSince("sk-or-xyz", 90.0));

    meter.recordBaseline("sk-or-xyz", 90.0);
    assertEquals(0.25, meter.spentSince("sk-or-xyz", 90.25), TOLERANCE);
  }

  @Test
  public void aBalanceBelowTheBaselineClampsToZeroRatherThanGoingNegative() {
    OpenRouterCreditMeter meter = new OpenRouterCreditMeter();
    meter.recordBaseline("sk-or-abc", 4.5000);

    assertEquals(0.0, meter.spentSince("sk-or-abc", 4.0000), TOLERANCE);
  }

  @Test
  public void anUnreadableCurrentBalanceLeavesSpendUnknown() {
    OpenRouterCreditMeter meter = new OpenRouterCreditMeter();
    meter.recordBaseline("sk-or-abc", 4.5000);

    assertNull(meter.spentSince("sk-or-abc", null));
  }

  @Test
  public void resetStartsAFreshMeasurement() {
    OpenRouterCreditMeter meter = new OpenRouterCreditMeter();
    meter.recordBaseline("sk-or-abc", 4.5000);
    meter.reset();

    assertFalse(meter.hasBaselineFor("sk-or-abc"));
    meter.recordBaseline("sk-or-abc", 4.6187);
    assertEquals(0.0, meter.spentSince("sk-or-abc", 4.6187), TOLERANCE);
  }

  @Test
  public void keysAreComparedIgnoringSurroundingWhitespace() {
    OpenRouterCreditMeter meter = new OpenRouterCreditMeter();
    meter.recordBaseline("  sk-or-abc  ", 4.5000);

    assertTrue(meter.hasBaselineFor("sk-or-abc"));
    assertEquals(0.1187, meter.spentSince("sk-or-abc", 4.6187), TOLERANCE);
  }
}

