  public void repeatedNetworkTimeoutFailsGracefullyAfterOneRetry() {
    server.enqueue(new MockResponse().setSocketPolicy(SocketPolicy.NO_RESPONSE));
    server.enqueue(new MockResponse().setSocketPolicy(SocketPolicy.NO_RESPONSE));

    int[] notices = {0};
    OpenRouterTtsBackend backend = backendWith(keyedConfig(), FAST_RETRY);
    backend.setNotice(msg -> notices[0]++);

    assertNull("two timeouts in a row fail the line gracefully", backend.synthesize(req()));
    assertEquals("it retries exactly once, never storms", 2, server.getRequestCount());
    assertEquals("the persistent timeout surfaces one notice", 1, notices[0]);
  }

  @Test
  public void unreachableHostFailsFastAndGracefully() throws Exception {
    OpenRouterTtsBackend backend = backendWith(keyedConfig(), FAST_RETRY);
    server.shutdown();

    int[] notices = {0};
    backend.setNotice(msg -> notices[0]++);

    assertNull("an unreachable host fails the line gracefully", backend.synthesize(req()));
    assertEquals("the failure surfaces one notice", 1, notices[0]);
  }

  @Test
  public void callBudgetGrowsWithTheLineLength() {
    OpenRouterTtsBackend backend = backend(new MutableTestConfig());

    Duration shortLine = backend.callBudgetFor(20);
    Duration longLine = backend.callBudgetFor(600);

    assertTrue(
        "a long line gets more time than a short one, because OpenRouter withholds audio until the"
            + " whole clip is generated",
        longLine.compareTo(shortLine) > 0);
    assertTrue(
        "a short line still fails fast rather than inheriting a long line's budget",
        shortLine.compareTo(Duration.ofSeconds(30)) < 0);
    assertTrue(
        "a 600 character line clears the ~23s it needs in practice",
        longLine.compareTo(Duration.ofSeconds(30)) > 0);
  }

  @Test
  public void callBudgetIsClampedToTheClientCeiling() {
    OpenRouterTtsBackend backend = backendWith(new MutableTestConfig(), FAST_RETRY);

    assertEquals(
        "an uncapped line cannot exceed the configured ceiling",
        FAST_RETRY.callTimeout,
        backend.callBudgetFor(100_000));
  }

  @Test
  public void callBudgetTreatsANegativeLengthAsEmpty() {
    OpenRouterTtsBackend backend = backend(new MutableTestConfig());

    assertEquals(backend.callBudgetFor(0), backend.callBudgetFor(-1));
  }

  private final List<RecordedRequest> warmUpRequests = new ArrayList<>();

  private OpenRouterTtsBackend warmedBackend(MutableTestConfig config) throws Exception {
    for (int i = 0; i < WARM_UP_CONNECTIONS; i++) {
      server.enqueue(new MockResponse().setResponseCode(HTTP_OK).setBody("{}"));
    }
    OpenRouterTtsBackend backend = backend(config);
    backend.warmUp();
    warmUpRequests.clear();
    for (int i = 0; i < WARM_UP_CONNECTIONS; i++) {
      RecordedRequest received = server.takeRequest(10, TimeUnit.SECONDS);
      assertNotNull("a warm-up request never reached the server", received);
      warmUpRequests.add(received);
    }
    long deadline = System.currentTimeMillis() + 10_000;
    while (backend.idlePooledConnectionCount() < WARM_UP_CONNECTIONS
        && System.currentTimeMillis() < deadline) {
      Thread.sleep(10);
    }
    return backend;
  }

  @Test
  public void warmUpOpensOneConnectionPerWarmUpSlotAgainstTheKeyEndpoint() throws Exception {
    OpenRouterTtsBackend backend = warmedBackend(keyedConfig());

    assertEquals(
        "warm-up opens a connection per slot",
        WARM_UP_CONNECTIONS,
        backend.pooledConnectionCount());
    for (RecordedRequest warmUp : warmUpRequests) {
      assertEquals(
          "warm-up hits the key endpoint, never the billable one", "/api/v1/key", warmUp.getPath());
      assertEquals("GET", warmUp.getMethod());
      assertEquals("Bearer sk-or-abc", warmUp.getHeader("Authorization"));
      assertEquals("each warm-up call opens its own connection", 0, warmUp.getSequenceNumber());
    }
  }

  @Test
  public void warmedConnectionIsReusedByTheNextSpokenLine() throws Exception {
    OpenRouterTtsBackend backend = warmedBackend(keyedConfig());
    enqueuePcm((short) 0, (short) 16384, (short) -16384, (short) 0);

    assertNotNull("the warmed backend still synthesizes normally", backend.synthesize(req()));

    RecordedRequest speech = server.takeRequest();
    assertEquals("/api/v1/audio/speech", speech.getPath());
    assertTrue(
        "the spoken line reuses a warmed connection instead of handshaking",
        speech.getSequenceNumber() > 0);
  }

  @Test
  public void warmUpWithoutAnApiKeyIssuesNoRequest() {
    OpenRouterTtsBackend backend = backend(new MutableTestConfig());

    backend.warmUp();

    assertEquals("an unavailable backend is never warmed", 0, server.getRequestCount());
  }

  @Test
  public void warmUpIsANoOpWhileTheConnectionPoolIsAlreadyWarm() throws Exception {
    OpenRouterTtsBackend backend = warmedBackend(keyedConfig());

    backend.warmUp();

    assertEquals(
        "re-warming a warm pool spends nothing", WARM_UP_CONNECTIONS, server.getRequestCount());
  }

  @Test
  public void aVoicedLineCountsOnceAgainstTheCharactersActuallySent() throws Exception {
    enqueuePcm((short) 1, (short) 2);
    SpendTracker spend = new SpendTracker();
    OpenRouterTtsBackend backend = backend(keyedConfig());
    backend.setSpendTracker(spend);

    assertNotNull(backend.synthesize(req()));

    JsonObject sent = sentBody();

    SpendTracker.ProviderSpend recorded = spend.snapshot().get(0);
    assertEquals(VoicedDialogueConfig.TtsProvider.OPENROUTER, recorded.provider());
    assertEquals(1, recorded.voicedLines());
    assertEquals(0, recorded.prefetchedLines());
    assertEquals(
        "the counted characters are the input the endpoint bills on",
        sent.get("input").getAsString().length(),
        recorded.speechCharacters());
  }

  @Test
  public void aPrefetchedLineCountsAsWarmingRatherThanAsAVoicedLine() {
    enqueuePcm((short) 1, (short) 2);
    SpendTracker spend = new SpendTracker();
    OpenRouterTtsBackend backend = backend(keyedConfig());
    backend.setSpendTracker(spend);

    backend.synthesize(req().asPrefetch());

    SpendTracker.ProviderSpend recorded = spend.snapshot().get(0);
    assertEquals(0, recorded.voicedLines());
    assertEquals(1, recorded.prefetchedLines());
    assertTrue("warming still costs characters", recorded.speechCharacters() > 0);
  }

  @Test
  public void aStreamedLineCountsOnceWhenTheFirstAudioArrives() {
    enqueuePcm((short) 1, (short) 2, (short) 3, (short) 4);
    SpendTracker spend = new SpendTracker();
    OpenRouterTtsBackend backend = backend(keyedConfig());
    backend.setSpendTracker(spend);

    backend.synthesizeStreaming(req(), (samples, rate) -> {});

    SpendTracker.ProviderSpend recorded = spend.snapshot().get(0);
    assertEquals("a streamed line is one billable line", 1, recorded.voicedLines());
  }

  @Test
  public void aFailedLineThatReturnsNoAudioCostsNothing() {
    server.enqueue(new MockResponse().setResponseCode(HTTP_UNAUTHORIZED).setBody("bad key"));
    SpendTracker spend = new SpendTracker();
    OpenRouterTtsBackend backend = backend(keyedConfig());
    backend.setSpendTracker(spend);

    assertNull(backend.synthesize(req()));

    assertTrue("a rejected line never reaches the readout", spend.snapshot().isEmpty());
  }

  @Test
  public void aLineNeverSentForWantOfAKeyCostsNothing() {
    SpendTracker spend = new SpendTracker();
    OpenRouterTtsBackend backend = backend(new MutableTestConfig());
    backend.setSpendTracker(spend);

    assertNull(backend.synthesize(req()));

    assertTrue(spend.snapshot().isEmpty());
  }

  @Test
  public void theTranslationHopIsCountedInItsOwnBucket() {
    MutableTestConfig config = keyedConfig();
    config.language = VoicedDialogueConfig.SpokenLanguage.FRENCH;
    enqueueChat("Bonjour");
    enqueuePcm((short) 1, (short) 2);
    SpendTracker spend = new SpendTracker();
    OpenRouterTtsBackend backend = backend(config);
    backend.setSpendTracker(spend);

    assertNotNull(backend.synthesize(req()));

    SpendTracker.ProviderSpend recorded = spend.snapshot().get(0);
    assertEquals("one translation call", 1, recorded.translationCalls());
    assertEquals(
        "translation bills on the source line",
        "Hello & welcome".length(),
        recorded.translationCharacters());
    assertEquals("the spoken line is still counted once", 1, recorded.voicedLines());
  }
}

package com.grahambartley.runelite.voiced.dialogue.speech;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import org.junit.Test;

public class CloudSynthTraceTest {

  @Test
  public void successCarriesAttemptTimingAndSize() {
    String line = CloudSynthTrace.success(1, 2, 412, 83, 51200, "gen-abc");
    assertTrue(line, line.startsWith("[TTS cloud] synth ok"));
    assertTrue(line, line.contains("attempt=1/2"));
    assertTrue(line, line.contains("elapsedMs=412"));
    assertTrue(line, line.contains("inputLen=83"));
    assertTrue(line, line.contains("bytes=51200"));
    assertTrue(line, line.contains("genId=gen-abc"));
  }

  @Test
  public void retryRecordsReasonAttemptAndElapsed() {
    String line = CloudSynthTrace.retry("empty-body", 1, 2, 120);
    assertTrue(line, line.startsWith("[TTS cloud] synth retry"));
    assertTrue(line, line.contains("reason=empty-body"));
    assertTrue(line, line.contains("attempt=1/2"));
    assertTrue(line, line.contains("elapsedMs=120"));
  }

  @Test
  public void httpFailureCarriesEveryField() {
    String line =
        CloudSynthTrace.failure(
            "non-2xx", 1, 2, 95, 83, 429, "application/json", "gen-abc", 42, "Too Many Requests");
    assertTrue(line, line.startsWith("[TTS cloud] synth fail"));
    assertTrue(line, line.contains("reason=non-2xx"));
    assertTrue(line, line.contains("attempt=1/2"));
    assertTrue(line, line.contains("elapsedMs=95"));
    assertTrue(line, line.contains("inputLen=83"));
    assertTrue(line, line.contains("http=429"));
    assertTrue(line, line.contains("contentType=application/json"));
    assertTrue(line, line.contains("genId=gen-abc"));
    assertTrue(line, line.contains("bytes=42"));
    assertTrue(line, line.contains("detail=Too Many Requests"));
  }

  @Test
  public void networkFailureCollapsesAbsentHttpFieldsToDash() {
    String line = CloudSynthTrace.failure("network", 2, 2, 2000, 83, 0, "", "", 0, "timeout");
    assertTrue(line, line.contains("reason=network"));
    assertTrue(line, line.contains("http=-"));
    assertTrue(line, line.contains("contentType=-"));
    assertTrue(line, line.contains("genId=-"));
    assertTrue(line, line.contains("detail=timeout"));
  }

  @Test
  public void traceNeverLeaksDialogueText() {
    String dialogue = "Greetings adventurer, the king needs your help.";
    String success = CloudSynthTrace.success(1, 2, 10, dialogue.length(), 100, "g");
    String failure =
        CloudSynthTrace.failure(
            "truncated", 2, 2, 10, dialogue.length(), 200, "audio/pcm", "g", 5, "OK");
    assertFalse(success, success.contains(dialogue));
    assertFalse(failure, failure.contains(dialogue));
  }
}

package com.grahambartley.runelite.voiced.dialogue.speech;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;

import com.grahambartley.runelite.voiced.dialogue.VoicedDialogueConfig;
import com.grahambartley.runelite.voiced.dialogue.profile.Emotion;
import com.grahambartley.runelite.voiced.dialogue.profile.VoiceSpec;
import com.grahambartley.runelite.voiced.dialogue.speaker.NpcGender;
import com.grahambartley.runelite.voiced.dialogue.speaker.NpcRace;
import junitparams.JUnitParamsRunner;
import junitparams.Parameters;
import org.junit.Test;
import org.junit.runner.RunWith;

@RunWith(JUnitParamsRunner.class)
public class CloudTtsTextTest {

  @Test
  @Parameters(method = "needsTranslationCases")
  public void needsTranslationTreatsBlankAndEnglishAsNoTranslation(
      String language, boolean expected) {
    assertEquals(expected, CloudTtsText.needsTranslation(language));
  }

  private Object[] needsTranslationCases() {
    return new Object[] {
      new Object[] {"English", false},
      new Object[] {"  english  ", false},
      new Object[] {"", false},
      new Object[] {null, false},
      new Object[] {"French", true},
    };
  }

  @Test
  @Parameters(method = "combineLanguageCases")
  public void combineLanguageAppendsTheQuirkOnlyWhenSet(
      String language, VoicedDialogueConfig.SpeakingStyle style, String expected) {
    assertEquals(expected, CloudTtsText.combineLanguage(language, style));
  }

  private Object[] combineLanguageCases() {
    return new Object[] {
      new Object[] {"English", VoicedDialogueConfig.SpeakingStyle.NONE, "English"},
      new Object[] {"English", VoicedDialogueConfig.SpeakingStyle.GEN_Z, "English Gen Z slang"},
      new Object[] {"French", VoicedDialogueConfig.SpeakingStyle.PIRATE, "French pirate speak"},
      new Object[] {"  ", VoicedDialogueConfig.SpeakingStyle.GEN_Z, "English Gen Z slang"},
      new Object[] {
        "English", VoicedDialogueConfig.SpeakingStyle.UK_SLANG, "English with London Roadman Slang"
      },
      new Object[] {
        "English", VoicedDialogueConfig.SpeakingStyle.IRISH_SLANG, "English with Dublin Slang"
      },
      new Object[] {
        "English", VoicedDialogueConfig.SpeakingStyle.RHYMING, "English as rhyming verse"
      },
      new Object[] {
        "French", VoicedDialogueConfig.SpeakingStyle.SURFER, "French with laid-back surfer slang"
      },
    };
  }

  @Test
  public void narrationTakesNeitherSpeakingStyleButKeepsTheSpokenLanguage() {
    MutableTestConfig config = new MutableTestConfig();
    config.language = VoicedDialogueConfig.SpokenLanguage.FRENCH;
    config.playerQuirk = VoicedDialogueConfig.SpeakingStyle.PIRATE;
    config.npcQuirk = VoicedDialogueConfig.SpeakingStyle.GEN_Z;

    assertEquals(
        "narration is the game's own voice, so no character register is layered on",
        "French",
        CloudTtsText.effectiveSpokenLanguage(config, narrationRequest()));
  }

  @Test
  @Parameters(method = "speakerClassStyleCases")
  public void eachSpeakerClassPicksItsOwnStyle(SynthesisRequest request, String expected) {
    MutableTestConfig config = new MutableTestConfig();
    config.playerQuirk = VoicedDialogueConfig.SpeakingStyle.PIRATE;
    config.npcQuirk = VoicedDialogueConfig.SpeakingStyle.GEN_Z;

    assertEquals(expected, CloudTtsText.effectiveSpokenLanguage(config, request));
  }

  private Object[] speakerClassStyleCases() {
    return new Object[] {
      new Object[] {characterRequest(true), "English pirate speak"},
      new Object[] {characterRequest(false), "English Gen Z slang"},
      new Object[] {narrationRequest(), "English"},
    };
  }

  private static SynthesisRequest narrationRequest() {
    return new SynthesisRequest(
        "You find a key.",
        VoiceSpec.NARRATOR,
        Emotion.NEUTRAL,
        TestFixtures.TROLL_PROFILE,
        false,
        false);
  }

  private static SynthesisRequest characterRequest(boolean player) {
    VoiceSpec voice =
        player ? VoiceSpec.player(NpcGender.MALE) : VoiceSpec.npc(NpcRace.HUMAN, NpcGender.FEMALE);
    return new SynthesisRequest(
        "Hello.", voice, Emotion.NEUTRAL, TestFixtures.TROLL_PROFILE, false, player);
  }

  @Test
  public void translatorSystemPromptIsStablePerLanguageAndNamesTheTarget() {
    assertEquals(
        "the same target yields a byte-identical prompt so the model's cache hits",
        CloudTtsText.translatorSystemPrompt("French"),
        CloudTtsText.translatorSystemPrompt("French"));
    assertNotEquals(
        CloudTtsText.translatorSystemPrompt("French"),
        CloudTtsText.translatorSystemPrompt("German"));
    assertTrue(CloudTtsText.translatorSystemPrompt("French").contains("French"));
  }
}

package com.grahambartley.runelite.voiced.dialogue.speech;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertSame;

import com.grahambartley.runelite.voiced.dialogue.VoicedDialogueConfig;
import com.grahambartley.runelite.voiced.dialogue.audio.Pcm;
import com.grahambartley.runelite.voiced.dialogue.profile.Emotion;
import com.grahambartley.runelite.voiced.dialogue.profile.VoiceSpec;
import com.grahambartley.runelite.voiced.dialogue.speaker.NpcGender;
import com.grahambartley.runelite.voiced.dialogue.speaker.NpcRace;
import java.util.EnumSet;
import org.junit.Test;

public class BackendProviderTest {

  private static final class StubBackend implements SynthesisBackend {
    private final String id;
    private final boolean available;
    private final EnumSet<Emotion> emotions;
    Emotion lastEmotion;
    int synthCalls;
    int warmCalls;
    int closeCalls;
    int rateLimitClears;

    StubBackend(String id, boolean available, EnumSet<Emotion> emotions) {
      this.id = id;
      this.available = available;
      this.emotions = emotions;
    }

    @Override
    public String id() {
      return id;
    }

    @Override
    public void clearRateLimit() {
      rateLimitClears++;
    }

    @Override
    public boolean isAvailable() {
      return available;
    }

    @Override
    public EnumSet<Emotion> supportedEmotions() {
      return emotions;
    }

    @Override
    public Pcm synthesize(SynthesisRequest request) {
      synthCalls++;
      lastEmotion = request.emotion();
      return new Pcm(new float[] {0f}, 24_000);
    }

    @Override
    public void warmUp() {
      warmCalls++;
    }

    @Override
    public void close() {
      closeCalls++;
    }
  }

  private static SynthesisRequest req(Emotion emotion) {
    return new SynthesisRequest(
        "hi",
        VoiceSpec.npc(NpcRace.HUMAN, NpcGender.MALE),
        emotion,
        TestFixtures.TROLL_PROFILE,
        false,
        false);
  }

  @Test
  public void activeReturnsTheProvidedBackend() {
    StubBackend cloud = new StubBackend("cloud-openrouter", true, EnumSet.allOf(Emotion.class));
    BackendProvider provider = new BackendProvider(cloud);
    assertSame(cloud, provider.active());
  }

  @Test
  public void warmUpActiveWarmsTheBackend() {
    StubBackend cloud = new StubBackend("cloud-openrouter", true, EnumSet.allOf(Emotion.class));
    BackendProvider provider = new BackendProvider(cloud);

    provider.warmUpActive();

    assertEquals(1, cloud.warmCalls);
  }

  @Test
  public void unsupportedEmotionDowngradesToNeutralBeforeSynthesis() {
    StubBackend backend = new StubBackend("cloud-openrouter", true, EnumSet.of(Emotion.NEUTRAL));
    BackendProvider provider = new BackendProvider(backend);

    provider.synthesizeWith(provider.active(), req(Emotion.ANGRY));

    assertEquals("backend never sees an unsupported emotion", Emotion.NEUTRAL, backend.lastEmotion);
    assertEquals(1, backend.synthCalls);
  }

  @Test
  public void supportedEmotionIsPassedThroughUnchanged() {
    StubBackend cloud = new StubBackend("cloud-openrouter", true, EnumSet.allOf(Emotion.class));
    BackendProvider provider = new BackendProvider(cloud);

    provider.synthesizeWith(provider.active(), req(Emotion.ANGRY));

    assertEquals("a supported emotion is preserved", Emotion.ANGRY, cloud.lastEmotion);
  }

  @Test
  public void cloudFullEmotionSetIsNotDowngraded() {
    StubBackend cloud = new StubBackend("cloud-openrouter", true, EnumSet.allOf(Emotion.class));
    BackendProvider provider = new BackendProvider(cloud);

    provider.synthesizeWith(provider.active(), req(Emotion.SCARED));

    assertEquals("Cloud supports the full set, so no downgrade", Emotion.SCARED, cloud.lastEmotion);
  }

  @Test
  public void activeFollowsTheConfiguredProviderLive() {
    StubBackend openRouter =
        new StubBackend("cloud-openrouter", true, EnumSet.allOf(Emotion.class));
    StubBackend aiStudio =
        new StubBackend("cloud-google-ai-studio", true, EnumSet.allOf(Emotion.class));
    VoicedDialogueConfig.TtsProvider[] selected = {VoicedDialogueConfig.TtsProvider.OPENROUTER};
    BackendProvider provider = new BackendProvider(openRouter, aiStudio, () -> selected[0]);

    assertSame(openRouter, provider.active());
    selected[0] = VoicedDialogueConfig.TtsProvider.GOOGLE_AI_STUDIO;
    assertSame("provider switch takes effect with no restart", aiStudio, provider.active());
  }

  @Test
  public void warmUpActiveWarmsOnlyTheSelectedBackend() {
    StubBackend openRouter =
        new StubBackend("cloud-openrouter", true, EnumSet.allOf(Emotion.class));
    StubBackend aiStudio =
        new StubBackend("cloud-google-ai-studio", true, EnumSet.allOf(Emotion.class));
    BackendProvider provider =
        new BackendProvider(
            openRouter, aiStudio, () -> VoicedDialogueConfig.TtsProvider.GOOGLE_AI_STUDIO);

    provider.warmUpActive();

    assertEquals(0, openRouter.warmCalls);
    assertEquals(1, aiStudio.warmCalls);
  }

  @Test
  public void closeReleasesBothProviderBackends() {
    StubBackend openRouter =
        new StubBackend("cloud-openrouter", true, EnumSet.allOf(Emotion.class));
    StubBackend aiStudio =
        new StubBackend("cloud-google-ai-studio", true, EnumSet.allOf(Emotion.class));
    BackendProvider provider =
        new BackendProvider(
            openRouter, aiStudio, () -> VoicedDialogueConfig.TtsProvider.OPENROUTER);

    provider.close();

    assertEquals(1, openRouter.closeCalls);
    assertEquals(1, aiStudio.closeCalls);
  }

  @Test
  public void closeReleasesASingleFixedBackendOnce() {
    StubBackend cloud = new StubBackend("cloud-openrouter", true, EnumSet.allOf(Emotion.class));
    BackendProvider provider = new BackendProvider(cloud);

    provider.close();

    assertEquals(1, cloud.closeCalls);
  }

  @Test
  public void clearingRateLimitsReachesBothBackends() {
    StubBackend openRouter = new StubBackend("or", true, EnumSet.allOf(Emotion.class));
    StubBackend aiStudio = new StubBackend("ai", true, EnumSet.allOf(Emotion.class));
    BackendProvider provider =
        new BackendProvider(
            openRouter, aiStudio, () -> VoicedDialogueConfig.TtsProvider.GOOGLE_AI_STUDIO);

    provider.clearRateLimits();

    assertEquals(
        "a changed key invalidates the idle backend's window too", 1, aiStudio.rateLimitClears);
    assertEquals(1, openRouter.rateLimitClears);
  }
}

