package com.grahambartley.runelite.voiced.dialogue.speech.spend;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import com.grahambartley.runelite.voiced.dialogue.VoicedDialogueConfig.TtsProvider;
import com.grahambartley.runelite.voiced.dialogue.speech.spend.SpendTracker.ProviderSpend;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import org.junit.Test;

public class SpendTrackerTest {

  @Test
  public void anUnusedProviderIsAbsentFromTheSnapshot() {
    SpendTracker tracker = new SpendTracker();

    assertTrue("nothing recorded -> nothing to report", tracker.snapshot().isEmpty());

    tracker.recordSpeech(TtsProvider.OPENROUTER, 100, false);

    List<ProviderSpend> snapshot = tracker.snapshot();
    assertEquals("only the provider actually used is reported", 1, snapshot.size());
    assertEquals(TtsProvider.OPENROUTER, snapshot.get(0).provider());
  }

  @Test
  public void voicedAndPrefetchedLinesLandInSeparateBuckets() {
    SpendTracker tracker = new SpendTracker();

    tracker.recordSpeech(TtsProvider.OPENROUTER, 40, false);
    tracker.recordSpeech(TtsProvider.OPENROUTER, 60, false);
    tracker.recordSpeech(TtsProvider.OPENROUTER, 25, true);

    ProviderSpend spend = only(tracker);
    assertEquals("two lines the player heard", 2, spend.voicedLines());
    assertEquals("one speculative warm-up", 1, spend.prefetchedLines());
    assertEquals(
        "characters bill the same either way, so they share one total",
        125,
        spend.speechCharacters());
  }

  @Test
  public void translationIsItsOwnBucketAndNeverCountsAsAVoicedLine() {
    SpendTracker tracker = new SpendTracker();

    tracker.recordTranslation(TtsProvider.OPENROUTER, 80);
    tracker.recordSpeech(TtsProvider.OPENROUTER, 95, false);

    ProviderSpend spend = only(tracker);
    assertEquals(1, spend.translationCalls());
    assertEquals(80, spend.translationCharacters());
    assertEquals("the translation hop is not a voiced line", 1, spend.voicedLines());
    assertEquals(
        "translation characters stay out of the speech total", 95, spend.speechCharacters());
  }

  @Test
  public void providersAreCountedIndependentlyAndReportedInDeclarationOrder() {
    SpendTracker tracker = new SpendTracker();

    tracker.recordSpeech(TtsProvider.GOOGLE_AI_STUDIO, 30, false);
    tracker.recordSpeech(TtsProvider.OPENROUTER, 70, true);
    tracker.recordTranslation(TtsProvider.GOOGLE_AI_STUDIO, 10);

    List<ProviderSpend> snapshot = tracker.snapshot();
    assertEquals(2, snapshot.size());
    assertEquals(
        "declaration order, so a switched provider does not reshuffle the readout",
        TtsProvider.OPENROUTER,
        snapshot.get(0).provider());
    assertEquals(TtsProvider.GOOGLE_AI_STUDIO, snapshot.get(1).provider());

    assertEquals(0, snapshot.get(0).voicedLines());
    assertEquals(1, snapshot.get(0).prefetchedLines());
    assertEquals(0, snapshot.get(0).translationCalls());

    assertEquals(1, snapshot.get(1).voicedLines());
    assertEquals(1, snapshot.get(1).translationCalls());
  }

  @Test
  public void negativeCharacterCountsCannotDragTotalsBelowZero() {
    SpendTracker tracker = new SpendTracker();

    tracker.recordSpeech(TtsProvider.OPENROUTER, -50, false);
    tracker.recordTranslation(TtsProvider.OPENROUTER, -10);

    ProviderSpend spend = only(tracker);
    assertEquals(0, spend.speechCharacters());
    assertEquals(0, spend.translationCharacters());
    assertEquals("the call still happened, so it is still counted", 1, spend.voicedLines());
  }

  @Test
  public void reportedTokenCountsAccumulateAlongsideTheLineCounts() {
    SpendTracker tracker = new SpendTracker();

    tracker.recordSpeech(TtsProvider.GOOGLE_AI_STUDIO, 100, false, 1_700, 42);
    tracker.recordSpeech(TtsProvider.GOOGLE_AI_STUDIO, 60, true, 900, 30);

    ProviderSpend spend = only(tracker);
    assertEquals(2_600, spend.audioTokens());
    assertEquals(72, spend.speechPromptTokens());
    assertEquals("warming's tokens count too, they were still metered", 1, spend.prefetchedLines());
  }

  @Test
  public void theTranslationHopsTokensStayApartFromTheSpeechCallsTokens() {
    SpendTracker tracker = new SpendTracker();

    tracker.recordSpeech(TtsProvider.GOOGLE_AI_STUDIO, 100, false, 1_700, 42);
    tracker.recordTranslation(TtsProvider.GOOGLE_AI_STUDIO, 80, 90, 75);

    ProviderSpend spend = only(tracker);
    assertEquals(
        "the hop runs on a cheaper model, so its tokens cannot be pooled",
        1_700,
        spend.audioTokens());
    assertEquals(42, spend.speechPromptTokens());
    assertEquals(90, spend.translationInputTokens());
    assertEquals(75, spend.translationOutputTokens());
    assertEquals(1, spend.translationCalls());
  }

  @Test
  public void aProviderThatReportsNoTokensLeavesThoseTotalsAtZero() {
    SpendTracker tracker = new SpendTracker();

    tracker.recordSpeech(TtsProvider.OPENROUTER, 100, false);

    ProviderSpend spend = only(tracker);
    assertEquals(0, spend.audioTokens());
    assertEquals(0, spend.speechPromptTokens());
    assertEquals("the line is still counted", 1, spend.voicedLines());
  }

  @Test
  public void negativeTokenCountsCannotDragTotalsBelowZero() {
    SpendTracker tracker = new SpendTracker();

    tracker.recordSpeech(TtsProvider.GOOGLE_AI_STUDIO, 100, false, -900, -30);

    ProviderSpend spend = only(tracker);
    assertEquals(0, spend.audioTokens());
    assertEquals(0, spend.speechPromptTokens());
  }

  @Test
  public void concurrentRecordingLosesNoCalls() throws Exception {
    SpendTracker tracker = new SpendTracker();
    int threads = 8;
    int perThread = 250;
    ExecutorService pool = Executors.newFixedThreadPool(threads);
    CountDownLatch start = new CountDownLatch(1);
    CountDownLatch done = new CountDownLatch(threads);
    for (int i = 0; i < threads; i++) {
      boolean prefetch = i % 2 == 0;
      pool.execute(
          () -> {
            try {
              start.await();
              for (int n = 0; n < perThread; n++) {
                tracker.recordSpeech(TtsProvider.OPENROUTER, 10, prefetch);
              }
            } catch (InterruptedException e) {
              Thread.currentThread().interrupt();
            } finally {
              done.countDown();
            }
          });
    }
    start.countDown();
    assertTrue("workers finished", done.await(10, TimeUnit.SECONDS));
    pool.shutdownNow();

    ProviderSpend spend = only(tracker);
    assertEquals(threads / 2 * perThread, spend.voicedLines());
    assertEquals(threads / 2 * perThread, spend.prefetchedLines());
    assertEquals(threads * perThread * 10, spend.speechCharacters());
  }

  private static ProviderSpend only(SpendTracker tracker) {
    List<ProviderSpend> snapshot = new ArrayList<>(tracker.snapshot());
    assertEquals("exactly one provider was used", 1, snapshot.size());
    return snapshot.get(0);
  }
}

package com.grahambartley.runelite.voiced.dialogue.speech.spend;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import com.grahambartley.runelite.voiced.dialogue.VoicedDialogueConfig.TtsProvider;
import com.grahambartley.runelite.voiced.dialogue.speech.spend.SpendTracker.ProviderSpend;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import org.junit.Test;

public class SpendReportTest {

  private static ProviderSpend openRouter(long voiced, long prefetched, long characters) {
    return new ProviderSpend(
        TtsProvider.OPENROUTER, voiced, prefetched, characters, 0, 0, 0, 0, 0, 0);
  }

  private static ProviderSpend aiStudio(long voiced, long audioTokens, long promptTokens) {
    return new ProviderSpend(
        TtsProvider.GOOGLE_AI_STUDIO, voiced, 0, 400, 0, 0, audioTokens, promptTokens, 0, 0);
  }

  private static ProviderSpend aiStudioTranslated(
      long audioTokens, long promptTokens, long translationIn, long translationOut) {
    return new ProviderSpend(
        TtsProvider.GOOGLE_AI_STUDIO,
        4,
        0,
        400,
        2,
        310,
        audioTokens,
        promptTokens,
        translationIn,
        translationOut);
  }

  private static String only(List<String> lines) {
    assertEquals(1, lines.size());
    return lines.get(0);
  }

  @Test
  public void matchesTheCommandRegardlessOfCaseAndSurroundingSpace() {
    assertTrue(SpendReport.matches("voicedspend"));
    assertTrue(SpendReport.matches("VoicedSpend"));
    assertTrue(SpendReport.matches("  voicedspend  "));
  }

  @Test
  public void ignoresEveryOtherCommand() {
    assertFalse(SpendReport.matches(null));
    assertFalse(SpendReport.matches(""));
    assertFalse(SpendReport.matches("voiced"));
    assertFalse(SpendReport.matches("voicedspends"));
    assertFalse(SpendReport.matches("::voicedspend"));
  }

  @Test
  public void anUntouchedSessionReportsThatNothingWasSpent() {
    String line = only(SpendReport.lines(Collections.emptyList(), null));
    assertTrue(line, line.contains("Nothing has been voiced this session"));
  }

  @Test
  public void nullSnapshotIsTreatedAsAnUntouchedSession() {
    assertEquals(1, SpendReport.lines(null, 0.5).size());
  }

  @Test
  public void openRouterQuotesTheBilledFigureRatherThanAnEstimate() {
    String line =
        only(SpendReport.lines(Collections.singletonList(openRouter(12, 3, 4_821)), 0.1187));

    assertTrue(line, line.startsWith("OpenRouter this session: "));
    assertTrue(line, line.contains("12 lines voiced"));
    assertTrue(line, line.contains("3 prefetched"));
    assertTrue("thousands are grouped: " + line, line.contains("4,821 characters sent"));
    assertTrue("the provider's own figure is quoted: " + line, line.contains("$0.1187"));
    assertTrue("and named as billed, not modelled: " + line, line.contains("billed by OpenRouter"));
    assertFalse("nothing about it is an estimate: " + line, line.toLowerCase().contains("estimat"));
  }

  @Test
  public void openRouterSaysSoWhenTheBalanceCannotBeRead() {
    String line = only(SpendReport.lines(Collections.singletonList(openRouter(4, 0, 900)), null));

    assertTrue("the counts still stand: " + line, line.contains("4 lines voiced"));
    assertTrue("the gap is stated plainly: " + line, line.contains("could not be read"));
    assertFalse(
        "an unreadable balance must never be papered over with a guess: " + line,
        line.contains("$"));
  }

  @Test
  public void aiStudioReportsMeasuredTokensAndLabelsTheConversionAnEstimate() {
    String line =
        only(SpendReport.lines(Collections.singletonList(aiStudio(12, 18_204, 1_208)), null));

    assertTrue(line, line.startsWith("Google AI Studio this session: "));
    assertTrue("thousands are grouped: " + line, line.contains("18,204 audio tokens"));
    assertTrue(line, line.contains("1,208 text tokens"));
    assertTrue("the dollar figure is labelled: " + line, line.contains("Estimated $"));
    assertTrue("and its provenance stated: " + line, line.contains("tokens measured"));
  }

  @Test
  public void aiStudioWithoutTokenCountsReportsCostUnknownRatherThanZero() {
    String line = only(SpendReport.lines(Collections.singletonList(aiStudio(3, 0, 0)), null));

    assertTrue(line, line.contains("3 lines voiced"));
    assertTrue("a missing meter is stated, not costed: " + line, line.contains("cost is unknown"));
    assertFalse("no dollar figure is invented: " + line, line.contains("$"));
  }

  @Test
  public void eachProviderGetsItsOwnLineInDeclarationOrder() {
    List<String> lines =
        SpendReport.lines(Arrays.asList(openRouter(12, 3, 4_821), aiStudio(5, 9_000, 600)), 0.1187);

    assertEquals("one chat line per provider used", 2, lines.size());
    assertTrue(lines.get(0), lines.get(0).startsWith("OpenRouter this session: "));
    assertTrue(lines.get(1), lines.get(1).startsWith("Google AI Studio this session: "));
  }

  @Test
  public void theTranslationBucketAppearsOnlyWhenTranslationHappened() {
    String without =
        only(SpendReport.lines(Collections.singletonList(openRouter(2, 0, 200)), 0.01));
    assertFalse(
        "an English session mentions no translation: " + without, without.contains("translation"));

    ProviderSpend translated =
        new ProviderSpend(TtsProvider.OPENROUTER, 2, 0, 200, 2, 310, 0, 0, 0, 0);
    String with = only(SpendReport.lines(Collections.singletonList(translated), 0.01));
    assertTrue(with, with.contains("2 translation calls"));
    assertTrue(with, with.contains("310 characters"));
  }

  @Test
  public void aiStudioPricesTheTranslationHopOnTopOfTheSpeechCalls() {
    String line =
        only(
            SpendReport.lines(
                Collections.singletonList(aiStudioTranslated(9_000, 600, 800, 700)), null));

    assertTrue(
        "the hop is sized in the tokens it metered: " + line,
        line.contains("2 translation calls (1,500 tokens)"));

    double speechOnly = SpendPricing.estimateSpeechUsd(9_000, 600);
    double withHop = speechOnly + SpendPricing.estimateTranslationUsd(800, 700);
    assertTrue(
        "a translated session must not be costed as if the hop were free", withHop > speechOnly);
    assertTrue(
        "the quoted figure includes the hop: " + line,
        line.contains(String.format(java.util.Locale.US, "$%.4f", withHop)));
  }

  @Test
  public void anEnglishAiStudioSessionQuotesSpeechAlone() {
    String line =
        only(SpendReport.lines(Collections.singletonList(aiStudio(12, 18_204, 1_208)), null));

    assertFalse("no hop ran, so none is mentioned: " + line, line.contains("translation"));
    assertTrue(
        line,
        line.contains(
            String.format(
                java.util.Locale.US, "$%.4f", SpendPricing.estimateSpeechUsd(18_204, 1_208))));
  }

  @Test
  public void aSessionOfPureCacheHitsReadsAsZeroSpend() {
    String line = only(SpendReport.lines(Collections.singletonList(openRouter(0, 0, 0)), 0.0));

    assertTrue(line, line.contains("0 lines voiced"));
    assertTrue(line, line.contains("0 characters sent"));
    assertTrue("a free session reads as free: " + line, line.contains("$0.0000"));
  }

  @Test
  public void aTinyButRealCostIsNotRoundedAwayToNothing() {
    String line = only(SpendReport.lines(Collections.singletonList(openRouter(1, 0, 40)), 0.00002));

    assertTrue(
        "a fraction of a cent still reads as spent: " + line, line.contains("under $0.0001"));
  }
}

package com.grahambartley.runelite.voiced.dialogue.speech.spend;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import org.junit.Test;

public class SpendPricingTest {

  private static final double TOLERANCE = 1e-12;

  @Test
  public void speechBillsAudioAndTextAtTheirOwnPublishedRates() {
    double expected =
        20_000 * SpendPricing.AUDIO_USD_PER_TOKEN + 1_500 * SpendPricing.SPEECH_TEXT_USD_PER_TOKEN;

    assertEquals(expected, SpendPricing.estimateSpeechUsd(20_000, 1_500), TOLERANCE);
  }

  @Test
  public void translationBillsInputAndOutputAtTheirOwnPublishedRates() {
    double expected =
        800 * SpendPricing.TRANSLATION_INPUT_USD_PER_TOKEN
            + 600 * SpendPricing.TRANSLATION_OUTPUT_USD_PER_TOKEN;

    assertEquals(expected, SpendPricing.estimateTranslationUsd(800, 600), TOLERANCE);
  }

  @Test
  public void audioOutputDominatesTheCostOfALine() {
    assertTrue(
        "audio output bills far above text input, so a line's cost tracks how long it speaks",
        SpendPricing.AUDIO_USD_PER_TOKEN > SpendPricing.SPEECH_TEXT_USD_PER_TOKEN * 10);
  }

  @Test
  public void theTranslationHopIsFarCheaperThanSpeechButNotFree() {
    assertTrue(
        "the hop must never dominate the estimate",
        SpendPricing.TRANSLATION_OUTPUT_USD_PER_TOKEN * 10 < SpendPricing.AUDIO_USD_PER_TOKEN);
    assertTrue(
        "cheap is not free, so a translated session is still costed for it",
        SpendPricing.estimateTranslationUsd(800, 600) > 0);
  }

  @Test
  public void aTypicalLineLandsInTheRightOrderOfMagnitude() {
    double usd = SpendPricing.estimateSpeechUsd(170, 40);

    assertTrue("a single line costs fractions of a cent: " + usd, usd > 0.0005 && usd < 0.005);
  }

  @Test
  public void anUntouchedSessionEstimatesNothing() {
    assertEquals(0.0, SpendPricing.estimateSpeechUsd(0, 0), TOLERANCE);
    assertEquals(0.0, SpendPricing.estimateTranslationUsd(0, 0), TOLERANCE);
  }

  @Test
  public void negativeTokenCountsCannotProduceACredit() {
    assertEquals(0.0, SpendPricing.estimateSpeechUsd(-500, -500), TOLERANCE);
    assertEquals(0.0, SpendPricing.estimateTranslationUsd(-500, -500), TOLERANCE);
  }
}

package com.grahambartley.runelite.voiced.dialogue;

import static org.junit.Assert.assertEquals;
