            .getMethod("playerAccent")
            .getAnnotation(ConfigItem.class)
            .keyName());
    assertEquals(
        "playerPersona",
        VoicedDialogueConfig.class
            .getMethod("playerPersona")
            .getAnnotation(ConfigItem.class)
            .keyName());
    assertEquals(
        "playerPace",
        VoicedDialogueConfig.class
            .getMethod("playerPace")
            .getAnnotation(ConfigItem.class)
            .keyName());
  }

  @Test
  public void yourDeliveryPaceIsLabelledApartFromTheSpeakingPaceSpeedDial() throws Exception {
    ConfigItem direction =
        VoicedDialogueConfig.class.getMethod("playerPace").getAnnotation(ConfigItem.class);
    ConfigItem speed =
        VoicedDialogueConfig.class.getMethod("speakingPace").getAnnotation(ConfigItem.class);
    assertEquals("Your Delivery Pace", direction.name());
    assertEquals("Speaking Pace", speed.name());
  }
}

package com.grahambartley.runelite.voiced.dialogue.audio;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import org.junit.Test;

public class CaveEchoTest {

  private static int delaySamples(int rate) {
    return Math.max(1, Math.round(CaveEcho.DELAY_MS * rate / 1000f));
  }

  @Test
  public void impulseDecaysAcrossSuccessiveTaps() {
    int rate = 24_000;
    int d = delaySamples(rate);
    float[] in = new float[] {1f};
    Pcm out = CaveEcho.apply(new Pcm(in, rate));
    float[] s = out.getSamples();

    float firstTap = Math.abs(s[d]);
    float secondTap = Math.abs(s[2 * d]);
    assertTrue("first echo tap should be audible", firstTap > 0f);
    assertTrue("echo should decay: second tap quieter than first", secondTap < firstTap);
  }

  @Test
  public void silenceInSilenceOut() {
    Pcm out = CaveEcho.apply(new Pcm(new float[256], 24_000));
    for (float v : out.getSamples()) {
      assertEquals(0f, v, 0f);
    }
  }

  @Test
  public void outputLengthIsInputPlusTail() {
    int rate = 24_000;
    int d = delaySamples(rate);
    int hops = (int) Math.ceil(Math.log(CaveEcho.TAIL_FLOOR) / Math.log(CaveEcho.FEEDBACK));
    int tail = Math.min(hops * d, CaveEcho.MAX_TAIL_MS * rate / 1000);
    float[] in = new float[100];
    Pcm out = CaveEcho.apply(new Pcm(in, rate));
    assertEquals(in.length + tail, out.getSamples().length);
  }

  @Test
  public void everyOutputSampleIsWithinUnitRange() {
    float[] in = new float[2048];
    for (int i = 0; i < in.length; i++) {
      in[i] = i % 2 == 0 ? 1f : -1f;
    }
    Pcm out = CaveEcho.apply(new Pcm(in, 24_000));
    for (float v : out.getSamples()) {
      assertTrue("sample out of range: " + v, v >= -1f && v <= 1f);
    }
  }

  @Test
  public void inputArrayIsNotMutated() {
    float[] in = new float[] {0.5f, -0.5f, 0.25f};
    float[] copy = in.clone();
    CaveEcho.apply(new Pcm(in, 24_000));
    assertEquals(copy.length, in.length);
    for (int i = 0; i < in.length; i++) {
      assertEquals(copy[i], in[i], 0f);
    }
  }

  @Test
  public void delayScalesWithSampleRate() {
    for (int rate : new int[] {24_000, 48_000}) {
      int d = delaySamples(rate);
      float[] s = CaveEcho.apply(new Pcm(new float[] {1f}, rate)).getSamples();
      assertTrue("a tap should land at the rate-scaled delay for " + rate, Math.abs(s[d]) > 0f);
    }
  }
}

package com.grahambartley.runelite.voiced.dialogue.audio;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.util.Arrays;
import org.junit.Test;

public class PcmCompletenessTest {

  private static final int RATE = 24_000;

  private static Pcm clip(int speechSamples, int trailingSilenceSamples) {
    float[] s = new float[speechSamples + trailingSilenceSamples];
    Arrays.fill(s, 0, speechSamples, 0.5f);
    return new Pcm(s, RATE);
  }

  @Test
  public void aLineThatReleasesIntoTrailingSilenceIsComplete() {
    assertFalse(PcmCompleteness.isTruncated(clip(48_000, 4_800), 1.0));
  }

  @Test
  public void aLineThatEndsMidSignalIsTruncated() {
    assertTrue(PcmCompleteness.isTruncated(clip(48_000, 0), 1.0));
  }

  @Test
  public void aLineWithTooLittleTrailingSilenceIsTruncated() {
    assertTrue(PcmCompleteness.isTruncated(clip(48_000, 960), 1.0));
  }

  @Test
  public void aClipTooShortToJudgeIsLeftAlone() {
    assertFalse(PcmCompleteness.isTruncated(clip(2_400, 0), 1.0));
  }

  @Test
  public void emptyAudioIsNotFlagged() {
    assertFalse(PcmCompleteness.isTruncated(new Pcm(new float[0], RATE), 1.0));
  }

  @Test
  public void nonPositiveRateIsNotFlagged() {
    assertFalse(PcmCompleteness.isTruncated(new Pcm(new float[48_000], 0), 1.0));
  }

  @Test
  public void aFastLineIsNotFlaggedWhenItsTrailingSilenceScalesWithPace() {
    assertTrue(
        "short trailing silence is a cut at default pace",
        PcmCompleteness.isTruncated(clip(48_000, 1_500), 1.0));
    assertFalse(
        "the same buffer is complete once the window is scaled for 2x pace",
        PcmCompleteness.isTruncated(clip(48_000, 1_500), 2.0));
  }

  @Test
  public void aSlowLineRequiresProportionallyMoreTrailingSilence() {
    assertFalse(
        "200 ms of quiet is a clean ending at default pace",
        PcmCompleteness.isTruncated(clip(48_000, 4_800), 1.0));
    assertTrue(
        "the same buffer is short of the pace-scaled window at 0.5x",
        PcmCompleteness.isTruncated(clip(48_000, 4_800), 0.5));
  }

  @Test
  public void aNonPositiveSpeedRatioFallsBackToDefaultPace() {
    assertTrue(PcmCompleteness.isTruncated(clip(48_000, 1_500), 0.0));
    assertFalse(PcmCompleteness.isTruncated(clip(48_000, 4_800), -1.0));
  }
}

