    float[] f = RawPcmDecoder.decode(TestPcm.raw(samples), 24_000).getSamples();
    assertEquals(0f, f[0], 1e-6);
    assertEquals(0.5f, f[1], 1e-3);
    assertEquals(-0.5f, f[2], 1e-3);
    assertEquals(-1.0f, f[3], 1e-6);
